arent; background-clip: padding-box; }\n        ::-webkit-scrollbar-track { background: transparent; }\n        code { font-family: ui-monospace, \"SF Mono\", Menlo, monospace; font-size: .88em; background: var(--soft); padding: 1px 5px; border-radius: 5px; }\n        @keyframes popIn { from { opacity: 0; transform: scale(.96) translateY(6px); } }\n        @keyframes msgIn { from { opacity: 0; transform: translateY(4px); } }\n\n        /* ---------- auth ---------- */\n        #auth-screen {\n            position: fixed; inset: 0; z-index: 100; display: flex; align-items: center; justify-content: center;\n            background: radial-gradient(ellipse at 50% 0%, color-mix(in srgb, var(--accent, #fff) 10%, transparent), transparent 60%), var(--bg, #0c0c0c);\n        }\n        .auth-card {\n            width: min(380px, 92vw); padding: 30px; border-radius: 22px;\n            background: var(--panel); border: 1px solid var(--line);\n            box-shadow: 0 30px 80px -20px rgba(0,0,0,.6); animation: popIn .35s cubic-bezier(.2,.9,.3,1.2);\n        }\n        .auth-card h1 { font-size: 22px; font-weight: 600; color: var(--bright-text, #fff); text-align: center; letter-spacing: -.02em; }\n        .auth-card h1 span { color: var(--accent, #fff); }\n        .auth-sub { font-size: 13px; color: var(--muted); text-align: center; margin: 6px 0 22px; }\n        .auth-card input {\n            width: 100%; padding: 12px 14px; margin-bottom: 10px; font-size: 14px;\n            background: var(--bg, #0c0c0c); color: var(--bright-text, #fff);\n            border: 1px solid var(--line); border-radius: 12px; outline: none; transition: border-color .15s, box-shadow .15s;\n        }\n        .auth-card input:focus { border-color: color-mix(in srgb, var(--accent, #fff) 60%, transparent); box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent, #fff) 15%, transparent); }\n        .btn-primary {\n            width: 100%; padding: 12px; margin-top: 4px; border: none; border-radius: 12px;\n            background: var(--accent, #fff); color: #000; font-weight: 600; font-size: 14.5px; transition: filter .15s, transform .15s;\n        }\n        .btn-primary:hover { filter: brightness(1.08); }\n        .btn-primary:active { transform: scale(.98); }\n        .btn-primary:disabled { opacity: .5; }\n        .auth-switch { margin-top: 16px; text-align: center; font-size: 13px; color: var(--muted); }\n        .auth-switch a { color: var(--accent, #fff); cursor: pointer; text-decoration: none; }\n        .tabs { display: flex; gap: 4px; margin-bottom: 18px; background: var(--bg, #0c0c0c); padding: 4px; border-radius: 12px; border: 1px solid var(--line); }\n        .tabs button { flex: 1; padding: 8px; border: none; border-radius: 9px; background: transparent; color: var(--muted); font-weight: 500; transition: background .15s, color .15s; }\n        .tabs button.active { background: var(--soft); color: var(--bright-text, #fff); }\n        #auth-error { color: var(--danger); font-size: 13px; min-height: 18px; margin-bottom: 8px; text-align: center; }\n\n        /* ---------- layout: three floating panels ---------- */\n        #app { display: none; height: 100vh; padding: 8px; gap: 8px; }\n        #app.active { display: flex; }\n        .sidebar, .main, .members { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); }\n        .sidebar { width: 248px; flex-shrink: 0; display: flex; flex-direction: column; overflow: hidden; }\n        .side-header { height: 54px; flex-shrink: 0; padding: 0 10px 0 16px; display: flex; align-items: center; gap: 2px; }\n        .side-header .brand { flex: 1; font-size: 16px; font-weight: 600; color: var(--bright-text, #fff); letter-spacing: -.01em; }\n        .side-header .brand span { color: var(--accent, #fff); }\n        .icon-btn {\n            width: 32px; height: 32px; display: inline-flex; align-items: center; justify-content: center;\n            background: none; border: none; color: var(--muted); border-radius: 9px; transition: background .15s, color .15s;\n        }\n        .icon-btn:hover { background: var(--hover); color: var(--bright-text, #fff); }\n        .icon-btn svg { width: 17px; height: 17px; }\n\n        .channels { flex: 1; overflow-y: auto; padding: 4px 8px 12px; }\n        .cat-label {\n            display: flex; align-items: center; justify-content: space-between;\n            font-size: 11px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase;\n            color: var(--muted); padding: 14px 10px 6px;\n        }\n        .chan {\n            display: flex; align-items: center; gap: 8px; height: 34px; padding: 0 10px; margin: 1px 0;\n            border-radius: 9px; color: var(--muted); font-size: 14px; cursor: pointer; transition: background .12s, color .12s;\n            white-space: nowrap; overflow: hidden;\n        }\n        .chan:hover { background: var(--hover); color: var(--text, #c2c2c2); }\n        .chan.active { background: var(--soft); color: var(--bright-text, #fff); font-weight: 500; }\n        .chan.locked::after { content: \"\ud83d\udd12\"; font-size: 10px; margin-left: auto; opacity: .5; }\n        .chan .hash { width: 16px; text-align: center; opacity: .55; font-weight: 500; }\n        .chan.has-unread { color: var(--bright-text, #fff); font-weight: 600; }\n        .chan.has-unread .dm-avatar { box-shadow: 0 0 0 2px var(--panel), 0 0 0 4px var(--accent, #fff); }\n        .unread-badge {\n            margin-left: auto; flex-shrink: 0; min-width: 18px; height: 18px; padding: 0 5px; border-radius: 999px;\n            background: var(--danger); color: #fff; font-size: 11px; font-weight: 700; line-height: 18px; text-align: center;\n        }\n        .dm-friend-tag { font-size: 10.5px; font-weight: 600; background: var(--soft); border-radius: 6px; padding: 2px 6px; overflow: hidden; text-overflow: ellipsis; }\n        #ping-badge {\n            position: fixed; top: 18px; right: 18px; z-index: 300; min-width: 22px; height: 22px; padding: 0 7px;\n            border-radius: 999px; background: var(--danger); color: #fff; font-size: 12px; font-weight: 700;\n            line-height: 22px; text-align: center; cursor: pointer; box-shadow: 0 4px 14px rgba(242,85,90,.4);\n        }\n        .dm-avatar {\n            width: 22px; height: 22px; border-radius: 50%; flex-shrink: 0; overflow: hidden;\n            display: inline-flex; align-items: center; justify-content: center; font-size: 12px;\n        }\n\n        .me-bar { margin: 8px; padding: 8px; border-radius: 12px; display: flex; align-items: center; gap: 10px; background: var(--hover); }\n        .me-bar .avatar-sm { width: 34px; height: 34px; font-size: 16px; }\n        .me-info { flex: 1; min-width: 0; }\n        .me-name { font-size: 13.5px; font-weight: 600; color: var(--bright-text, #fff); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n        .me-mochis { font-size: 11.5px; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n\n        /* ---------- main column ---------- */\n        .main { flex: 1; display: flex; flex-direction: column; min-width: 0; overflow: hidden; }\n        .main-header { height: 54px; flex-shrink: 0; padding: 0 20px; border-bottom: 1px solid var(--line); display: flex; align-items: center; gap: 8px; min-width: 0; }\n        .main-header .hash-big { color: var(--muted); font-size: 19px; font-weight: 500; }\n        .main-header .title { color: var(--bright-text, #fff); font-weight: 600; font-size: 15px; white-space: nowrap; }\n        .main-header .topic { font-size: 12.5px; color: var(--muted); margin-left: 6px; padding-left: 12px; border-left: 1px solid var(--line);\n                              white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n        .main-header .topic:empty { display: none; }\n\n        #messages { flex: 1; overflow-y: auto; overflow-x: hidden; padding: 12px 0 8px; display: flex; flex-direction: column; }\n        #messages > :first-child { margin-top: auto; }\n\n        /* one message. grouped = same author as the one above, so no avatar/name */\n        .msg {\n            position: relative; display: grid; grid-template-columns: 40px minmax(0, 1fr); column-gap: 14px;\n            padding: 3px 20px; margin-top: 14px; transition: background .1s; animation: msgIn .18s ease-out;\n        }\n        .msg:first-child { margin-top: 0; }\n        .msg:hover { background: var(--hover); }\n        .msg.grouped { margin-top: 0; padding-top: 1px; padding-bottom: 1px; }\n        .msg.grouped .msg-head, .msg.grouped .msg-gutter .avatar-sm { display: none; }\n        .msg-gutter { display: flex; justify-content: center; }\n        .msg-stamp { display: none; font-size: 10px; color: var(--muted); line-height: 22px; white-space: nowrap; }\n        .msg.grouped:hover .msg-stamp { display: block; }\n        .avatar-sm {\n            width: 40px; height: 40px; border-radius: 50%; flex-shrink: 0; overflow: hidden;\n            display: flex; align-items: center; justify-content: center; font-size: 19px; cursor: pointer; position: relative;\n        }\n        .msg-gutter .avatar-sm { margin-top: 2px; }\n        .msg-body { min-width: 0; }\n        .msg-head { display: flex; align-items: center; gap: 7px; min-height: 22px; }\n        .msg-author { font-weight: 600; font-size: 14.5px; color: var(--bright-text, #fff); cursor: pointer; }\n        .msg-author:hover { text-decoration: underline; }\n        .msg-time { font-size: 11.5px; color: var(--muted); }\n        .msg-head .role-member { display: none; }\n        .msg-content { font-size: 14.5px; line-height: 1.5; color: var(--text, #c2c2c2); overflow-wrap: anywhere; white-space: pre-wrap; }\n        .msg.edited .msg-content:not(.editing)::after { content: \" (edited)\"; font-size: 11px; color: var(--muted); }\n        .msg-content b { color: var(--bright-text, #fff); }\n\n        .role-badge {\n            display: inline-flex; align-items: center; height: 18px; padding: 0 7px; border-radius: 6px;\n            font-size: 10.5px; font-weight: 600; letter-spacing: .02em; white-space: nowrap;\n            --rc: var(--muted); color: var(--rc); background: color-mix(in srgb, var(--rc) 15%, transparent);\n        }\n        .role-founder { --rc: #f0b232; }\n        .role-admin { --rc: #f2555a; }\n        .role-mod { --rc: #3ecf8e; }\n        .role-bot { --rc: #ff6b9d; text-transform: uppercase; }\n\n        .msg-actions {\n            position: absolute; top: -16px; right: 16px; z-index: 2; display: none; gap: 1px; padding: 3px;\n            background: var(--bg-2, #131313); border: 1px solid var(--line); border-radius: 10px;\n            box-shadow: 0 6px 18px rgba(0,0,0,.35);\n        }\n        .msg:hover .msg-actions { display: flex; }\n        .msg-actions button { width: 28px; height: 26px; background: none; border: none; border-radius: 7px; font-size: 14px; }\n        .msg-actions button:hover { background: var(--soft); }\n\n        .edit-box {\n            width: 100%; min-height: 44px; resize: vertical; margin-top: 2px; padding: 9px 12px; font-size: 14.5px;\n            background: var(--bg, #0c0c0c); color: var(--bright-text, #fff);\n            border: 1px solid color-mix(in srgb, var(--accent, #fff) 50%, transparent); border-radius: 10px; outline: none;\n        }\n        .edit-actions { display: flex; gap: 10px; margin-top: 6px; font-size: 12px; }\n        .edit-actions button { background: none; border: none; color: var(--accent, #fff); font-weight: 600; }\n\n        .reactions { display: flex; flex-wrap: wrap; gap: 4px; }\n        .reactions:not(:empty) { margin-top: 5px; }\n        .reaction {\n            display: inline-flex; align-items: center; gap: 5px; height: 26px; padding: 0 9px; border-radius: 999px;\n            background: var(--hover); border: 1px solid var(--line); font-size: 13px; cursor: pointer; transition: background .12s;\n        }\n        .reaction:hover { background: var(--soft); }\n        .reaction.mine { border-color: color-mix(in srgb, var(--accent, #fff) 55%, transparent); background: color-mix(in srgb, var(--accent, #fff) 12%, transparent); }\n        .emoji-picker {\n            position: fixed; z-index: 300; width: 320px; max-height: 280px; overflow-y: auto; padding: 8px;\n            background: var(--bg-2, #131313); border: 1px solid var(--line); border-radius: 14px;\n            box-shadow: 0 16px 40px rgba(0,0,0,.5); display: grid; grid-template-columns: repeat(8, 1fr); gap: 2px;\n            animation: popIn .15s ease-out;\n        }\n        .emoji-picker span { font-size: 19px; text-align: center; cursor: pointer; border-radius: 8px; padding: 4px 0; }\n        .emoji-picker span:hover { background: var(--soft); }\n\n        .mention { color: var(--accent, #fff); background: color-mix(in srgb, var(--accent, #fff) 14%, transparent); padding: 0 4px; border-radius: 5px; font-weight: 500; cursor: pointer; }\n        .mention.ping { background: #f0b23226; color: #f0b232; cursor: default; }\n        .msg-img { display: block; max-width: min(380px, 100%); max-height: 300px; border-radius: 12px; margin-top: 6px; border: 1px solid var(--line); cursor: zoom-in; }\n        .bot-msg .msg-content, .bot-msg .bj-actions { max-width: 560px; }\n        .bot-msg .msg-content {\n            margin-top: 3px; padding: 10px 14px; border-radius: 4px 14px 14px 14px;\n            background: color-mix(in srgb, #ff6b9d 7%, var(--bg-2, #131313)); border: 1px solid color-mix(in srgb, #ff6b9d 22%, transparent);\n        }\n\n        .msg-quote {\n            display: flex; align-items: center; gap: 7px; margin: 0 0 4px; padding: 3px 10px;\n            border-left: 2px solid var(--soft); border-radius: 0 8px 8px 0; font-size: 12.5px; cursor: pointer; max-width: fit-content;\n            color: var(--muted); transition: background .12s;\n        }\n        .msg-quote:hover { background: var(--hover); }\n        .msg-quote.pending { cursor: default; }\n        .msg-quote .quote-author { font-weight: 600; color: var(--text, #c2c2c2); flex-shrink: 0; }\n        .msg-quote .quote-text { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 360px; }\n\n        .msg-link { color: var(--accent, #fff); text-decoration: none; }\n        .msg-link:hover { text-decoration: underline; }\n        .msg-embed {\n            display: block; color: inherit; text-decoration: none; margin-top: 6px; max-width: 420px;\n            background: var(--bg-2, #131313); border: 1px solid var(--line); border-radius: 12px; overflow: hidden; transition: border-color .15s;\n        }\n        .msg-embed:hover { border-color: var(--soft); }\n        .embed-img-wrap { max-height: 220px; overflow: hidden; }\n        .embed-img { width: 100%; object-fit: cover; display: block; }\n        .embed-body { padding: 10px 12px; }\n        .embed-publisher { display: flex; align-items: center; gap: 6px; font-size: 11px; color: var(--muted); margin-bottom: 4px; }\n        .embed-favicon { width: 14px; height: 14px; border-radius: 3px; object-fit: cover; display: inline-flex; align-items: center; justify-content: center; font-size: 11px; }\n        .embed-title { color: var(--bright-text, #fff); font-size: 14px; font-weight: 600; line-height: 1.3; }\n        .embed-desc { font-size: 12.5px; color: var(--muted); margin-top: 3px; line-height: 1.4; }\n        .embed-url { font-size: 11px; color: var(--muted); margin-top: 5px; opacity: .7; }\n\n        /* game buttons (blackjack, quests, battles) */\n        .bj-actions { display: flex; gap: 6px; margin-top: 8px; flex-wrap: wrap; }\n        .bj-btn {\n            height: 34px; padding: 0 14px; border-radius: 10px; font-size: 13.5px; font-weight: 600;\n            border: 1px solid color-mix(in srgb, var(--c) 35%, transparent); background: color-mix(in srgb, var(--c) 14%, transparent); color: var(--c);\n            transition: background .15s, transform .1s;\n        }\n        .bj-btn:hover:not(:disabled) { background: color-mix(in srgb, var(--c) 24%, transparent); }\n        .bj-btn:active:not(:disabled) { transform: scale(.97); }\n        .bj-btn.hit { --c: #3ecf8e; } .bj-btn.stand { --c: #f2555a; } .bj-btn.dbl { --c: #f0b232; } .bj-btn.fold { --c: #8b93ff; }\n        .bj-btn:disabled { cursor: not-allowed; opacity: .45; }\n\n        /* ---------- composer ---------- */\n        .typing-bar { display: flex; align-items: center; gap: 8px; height: 22px; padding: 0 22px; font-size: 12px; color: var(--muted); opacity: 0; transition: opacity .2s; }\n        .typing-bar.show { opacity: 1; }\n        .typing-avatars { display: flex; }\n        .avatar-xs { width: 16px; height: 16px; border-radius: 50%; margin-right: -4px; display: inline-flex; align-items: center; justify-content: center; font-size: 9px; overflow: hidden; box-shadow: 0 0 0 2px var(--panel); }\n        .typing-text { display: inline-flex; align-items: center; gap: 4px; margin-left: 4px; }\n        .typing-name { color: var(--text, #c2c2c2); font-weight: 600; cursor: pointer; }\n        .dots { display: inline-flex; gap: 3px; margin-left: 3px; }\n        .dots i { display: block; width: 4px; height: 4px; border-radius: 50%; background: var(--muted); font-size: 0; animation: blink 1.4s infinite ease-in-out; }\n        .dots i:nth-child(2) { animation-delay: .2s; } .dots i:nth-child(3) { animation-delay: .4s; }\n        @keyframes blink { 0%,80%,100% { opacity: .3; transform: translateY(0); } 40% { opacity: 1; transform: translateY(-2px); } }\n\n        .input-area { flex-shrink: 0; padding: 0 16px 16px; position: relative; }\n        .input-row {\n            display: flex; align-items: center; gap: 6px; padding: 6px 6px 6px 8px;\n            background: var(--bg, #0c0c0c); border: 1px solid var(--line); border-radius: 14px; transition: border-color .15s, box-shadow .15s;\n        }\n        .input-row:focus-within { border-color: color-mix(in srgb, var(--accent, #fff) 45%, transparent); box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent, #fff) 10%, transparent); }\n        .input-row input { flex: 1; min-width: 0; height: 32px; background: none; border: none; outline: none; color: var(--bright-text, #fff); font-size: 14.5px; }\n        .input-row input::placeholder { color: var(--muted); }\n        #image-input { display: none; }\n        .attach-btn, .send-btn { width: 32px; height: 32px; flex-shrink: 0; display: inline-flex; align-items: center; justify-content: center; border: none; border-radius: 9px; }\n        .attach-btn { background: none; color: var(--muted); }\n        .attach-btn:hover { background: var(--hover); color: var(--bright-text, #fff); }\n        .send-btn { background: var(--accent, #fff); color: #000; transition: filter .15s, transform .1s; }\n        .send-btn:hover { filter: brightness(1.08); } .send-btn:active { transform: scale(.94); }\n        .attach-btn svg, .send-btn svg { width: 17px; height: 17px; }\n        .locked-note { text-align: center; font-size: 13px; color: var(--muted); padding: 12px; background: var(--hover); border-radius: 12px; }\n\n        .cmd-menu {\n            position: absolute; bottom: calc(100% + 6px); left: 16px; right: 16px; z-index: 5; display: none;\n            background: var(--bg-2, #131313); border: 1px solid var(--line); border-radius: 14px; padding: 4px;\n            overflow-y: auto; max-height: 260px; box-shadow: 0 -10px 30px rgba(0,0,0,.35);\n        }\n        .cmd-menu.open { display: block; }\n        .cmd-hint { font-size: 11px; color: var(--muted); padding: 6px 10px 4px; }\n        .cmd-item { display: flex; align-items: center; gap: 10px; padding: 7px 10px; border-radius: 9px; cursor: pointer; }\n        .cmd-item.selected { background: var(--soft); }\n        .ac-avatar, .ac-hash { width: 22px; height: 22px; border-radius: 50%; flex-shrink: 0; overflow: hidden; display: inline-flex; align-items: center; justify-content: center; font-size: 12px; font-weight: 600; }\n        .ac-hash { background: var(--soft); border-radius: 6px; }\n        .cmd-name { color: var(--bright-text, #fff); font-weight: 600; font-size: 13.5px; white-space: nowrap; }\n        .cmd-args { color: var(--muted); font-size: 12.5px; white-space: nowrap; }\n        .cmd-desc { color: var(--muted); font-size: 12.5px; margin-left: auto; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n\n        .reply-banner {\n            display: none; align-items: center; gap: 10px; padding: 7px 8px 7px 12px; margin-bottom: 6px;\n            background: var(--hover); border-radius: 10px; font-size: 12.5px;\n        }\n        .reply-banner.open { display: flex; }\n        .reply-banner .rb-text { flex: 1; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n        .reply-banner b { color: var(--bright-text, #fff); }\n        .reply-banner .rb-cancel { width: 22px; height: 22px; flex-shrink: 0; border: none; border-radius: 6px; background: none; color: var(--muted); font-size: 11px; }\n        .reply-banner .rb-cancel:hover { background: var(--soft); color: var(--bright-text, #fff); }\n\n        /* ---------- members ---------- */\n        .members { width: 232px; flex-shrink: 0; overflow-y: auto; padding: 8px; }\n        .member-group { font-size: 11px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; color: var(--muted); padding: 14px 8px 6px; }\n        .member-group:first-child { padding-top: 8px; }\n        .member { display: flex; align-items: center; gap: 10px; padding: 5px 8px; border-radius: 9px; cursor: pointer; transition: background .12s; }\n        .member:hover { background: var(--hover); }\n        .member .avatar-sm { width: 30px; height: 30px; font-size: 14px; overflow: visible; }\n        .member .avatar-sm img { border-radius: 50%; }\n        .member .m-name { font-size: 13.5px; color: var(--text, #c2c2c2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n        .presence { position: absolute; bottom: -1px; right: -1px; width: 11px; height: 11px; border-radius: 50%; border: 2.5px solid var(--panel); }\n        .presence.on { background: #3ecf8e; } .presence.off { background: #6b6b6b; } .presence.dnd { background: var(--danger); }\n        .presence-row { display: flex; gap: 6px; }\n        .presence-row .action-btn { flex: 1; padding: 9px 4px; font-size: 12.5px; }\n\n        /* ---------- modals ---------- */\n        .modal-bg { position: fixed; inset: 0; z-index: 200; display: none; align-items: center; justify-content: center; background: rgba(0,0,0,.55); backdrop-filter: blur(4px); }\n        .modal-bg.open { display: flex; }\n        .modal {\n            width: min(420px, 92vw); max-height: 86vh; overflow-y: auto; padding: 22px;\n            background: var(--bg-2, #131313); border: 1px solid var(--line); border-radius: 20px;\n            box-shadow: 0 30px 80px -20px rgba(0,0,0,.7); animation: popIn .22s cubic-bezier(.2,.9,.3,1.2);\n        }\n        .modal h2 { color: var(--bright-text, #fff); font-size: 17px; font-weight: 600; margin-bottom: 14px; }\n        .modal label { display: block; font-size: 12px; font-weight: 500; color: var(--muted); margin-bottom: 6px; }\n        .modal textarea, .modal input:not([type=file]) {\n            width: 100%; background: var(--bg, #0c0c0c); color: var(--bright-text, #fff);\n            border: 1px solid var(--line); border-radius: 10px; padding: 10px 12px; outline: none; font-size: 14px;\n        }\n        .modal textarea { min-height: 80px; resize: vertical; }\n        .modal textarea:focus, .modal input:focus { border-color: color-mix(in srgb, var(--accent, #fff) 50%, transparent); }\n        .profile-banner { height: 120px; margin: -22px -22px 0; border-radius: 20px 20px 0 0; overflow: hidden; }\n        .profile-banner + .profile-hero { margin-top: -30px; }\n        .profile-hero { display: flex; align-items: flex-end; gap: 14px; margin-bottom: 14px; }\n        .profile-hero .avatar-lg {\n            width: 76px; height: 76px; border-radius: 50%; font-size: 36px; flex-shrink: 0; overflow: hidden;\n            display: flex; align-items: center; justify-content: center; box-shadow: 0 0 0 5px var(--bg-2, #131313);\n        }\n        .profile-name { font-size: 19px; font-weight: 600; color: var(--bright-text, #fff); margin-bottom: 4px; }\n        .activity-card { margin: 0 0 14px; padding: 12px; border-radius: 14px; background: var(--hover); }\n        .activity-label { font-size: 11px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; color: var(--muted-text, #8a8a8a); margin-bottom: 10px; }\n        .activity-body { display: flex; align-items: center; gap: 12px; }\n        .activity-cover { position: relative; width: 64px; height: 64px; flex-shrink: 0; border-radius: 12px; overflow: hidden; display: flex; align-items: center; justify-content: center; font-size: 28px; background: var(--bg-3, #1c1c1c); }\n        .activity-cover img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; z-index: 1; }\n        .activity-info { min-width: 0; }\n        .activity-name { font-size: 14.5px; font-weight: 600; color: var(--bright-text, #fff); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n        .activity-sub { font-size: 12.5px; color: var(--text, #c2c2c2); margin-top: 2px; }\n        .activity-live { display: flex; align-items: center; gap: 6px; font-size: 12px; color: var(--muted-text, #8a8a8a); margin-top: 4px; }\n        .activity-live i { width: 7px; height: 7px; border-radius: 50%; background: #3ba55d; box-shadow: 0 0 0 0 rgba(59,165,93,.6); animation: activity-pulse 2s infinite; }\n        @keyframes activity-pulse { 70% { box-shadow: 0 0 0 6px rgba(59,165,93,0); } 100% { box-shadow: 0 0 0 0 rgba(59,165,93,0); } }\n        .m-activity { font-size: 11px; color: var(--muted-text, #8a8a8a); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n        .m-activity b { font-weight: 600; color: var(--text, #c2c2c2); }\n        .profile-pls { margin: 0 0 14px; padding: 12px; border-radius: 14px; background: var(--hover); }\n        .profile-pl { display: flex; align-items: center; gap: 10px; padding: 6px; margin: 0 -6px; border-radius: 10px; color: inherit; text-decoration: none; }\n        .profile-pl:hover { background: var(--bg-3, #1c1c1c); }\n        .profile-pl-cover { position: relative; width: 40px; height: 40px; flex-shrink: 0; border-radius: 8px; overflow: hidden; display: flex; align-items: center; justify-content: center; font-size: 18px; background: var(--bg-3, #1c1c1c); }\n        .profile-pl-cover img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; z-index: 1; }\n        .profile-pl-info { min-width: 0; display: flex; flex-direction: column; }\n        .profile-pl-info b { font-size: 13.5px; font-weight: 600; color: var(--bright-text, #fff); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n        .profile-pl-info small { font-size: 12px; color: var(--muted-text, #8a8a8a); }\n        .profile-bio { font-size: 14px; color: var(--text, #c2c2c2); margin: 4px 0 14px; line-height: 1.5; }\n        .profile-stats { display: flex; gap: 6px; margin-bottom: 16px; flex-wrap: wrap; }\n        .stat-chip { background: var(--hover); border-radius: 9px; padding: 6px 10px; font-size: 12.5px; }\n        .stat-chip b { color: var(--bright-text, #fff); }\n        .modal-actions { display: flex; flex-direction: column; gap: 6px; }\n        .action-btn {\n            padding: 10px; border: none; border-radius: 10px; font-weight: 600; font-size: 13.5px;\n            background: var(--soft); color: var(--bright-text, #fff); transition: filter .15s, background .15s;\n        }\n        .action-btn:hover { filter: brightness(1.15); }\n        .action-btn.accent { background: var(--accent, #fff); color: #000; }\n        .action-btn.danger { background: color-mix(in srgb, var(--danger) 14%, transparent); color: var(--danger); }\n        .action-btn.ghost { background: transparent; color: var(--muted); }\n        .action-btn:disabled { opacity: .45; cursor: not-allowed; filter: none; }\n        .mod-row, .role-picker { margin-top: 8px; padding-top: 12px; border-top: 1px solid var(--line); }\n        .mod-row { display: flex; align-items: center; gap: 6px; }\n        .mod-row .mod-label { font-size: 12px; color: var(--muted); margin-right: 2px; }\n        .mod-row .action-btn { flex: 1; font-size: 12px; padding: 7px 8px; }\n        .rp-label { font-size: 12px; color: var(--muted); margin-bottom: 8px; }\n        .rp-chips { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 8px; }\n        .rp-chip { padding: 2px; border: 1px solid transparent; border-radius: 8px; background: none; transition: border-color .12s; }\n        .rp-chip:hover { border-color: var(--soft); }\n        .rp-chip.on { border-color: var(--bright-text, #fff); }\n        .rp-chip .role-badge { height: 22px; padding: 0 9px; font-size: 11.5px; cursor: pointer; }\n        .rp-new { display: flex; gap: 6px; }\n        .rp-new input { flex: 1; min-width: 0; padding: 8px 11px !important; font-size: 13px !important; }\n        .rp-new .action-btn { padding: 8px 14px; }\n\n        .avatar-grid { display: grid; grid-template-columns: repeat(8, 1fr); gap: 6px; margin-bottom: 16px; }\n        .avatar-opt { aspect-ratio: 1; display: flex; align-items: center; justify-content: center; font-size: 20px; border-radius: 10px; border: 2px solid transparent; background: var(--hover); cursor: pointer; }\n        .avatar-opt.selected { border-color: var(--accent, #fff); }\n        .color-row { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 16px; }\n        .color-opt { width: 28px; height: 28px; border-radius: 50%; cursor: pointer; box-shadow: inset 0 0 0 1px rgba(255,255,255,.15); }\n        .color-opt.selected { box-shadow: 0 0 0 2px var(--bg-2, #131313), 0 0 0 4px var(--bright-text, #fff); }\n        #toast {\n            position: fixed; bottom: 24px; left: 50%; z-index: 300; transform: translateX(-50%) translateY(90px);\n            background: var(--bg-2, #131313); border: 1px solid var(--line); color: var(--bright-text, #fff);\n            padding: 10px 18px; border-radius: 12px; font-size: 13.5px; box-shadow: 0 12px 30px rgba(0,0,0,.45);\n            transition: transform .3s cubic-bezier(.2,.9,.3,1.2); max-width: 90vw;\n        }\n        #toast.show { transform: translateX(-50%) translateY(0); }\n        #toast .toast-btn { margin-left: 12px; padding: 5px 12px; border-radius: 8px; border: 0; cursor: pointer; font: inherit; font-weight: 600; background: var(--accent, #7c5cff); color: #fff; }\n\n        #profile-modal-bg { overflow: hidden; }\n        .fx-particle { position: fixed; top: -28px; z-index: 9999; pointer-events: none; animation: fx-fall linear forwards; }\n        @keyframes fx-fall { from { transform: translateY(-30px) rotate(0deg); } to { transform: translateY(calc(100vh + 40px)) rotate(340deg); } }\n\n        .banner-upload { display: flex; flex-direction: column; gap: 6px; margin-bottom: 6px; }\n        .banner-preview { height: 84px; border-radius: 10px; overflow: hidden; border: 1px solid var(--line); background: var(--hover); display: flex; align-items: center; justify-content: center; }\n        .banner-preview img { width: 100%; height: 100%; object-fit: cover; display: block; }\n        .banner-empty { font-size: 12px; color: var(--muted); }\n\n        @media (max-width: 1000px) { .members { display: none; } }\n        @media (max-width: 680px) {\n            #app { padding: 0; gap: 0; }\n            .sidebar { width: 72px; border-radius: 0; }\n            .main { border-radius: 0; border-width: 0 0 0 1px; }\n            .side-header .brand, .cat-label, .chan > :not(.hash):not(.dm-avatar):not(.unread-badge), .me-info { display: none; }\n            .side-header { flex-direction: column; height: auto; padding: 10px 0; }\n            .chan { justify-content: center; padding: 0; font-size: 0; }\n            .chan .hash { font-size: 14px; }\n            .me-bar { justify-content: center; flex-wrap: wrap; }\n            .msg { padding-left: 12px; padding-right: 12px; }\n        }\n    <\/style>\n<\/head>\n\n<body>\n    <div id=\"auth-screen\">\n        <div class=\"auth-card\">\n            <h1>mochii <span>chat<\/span><\/h1>\n            <p class=\"auth-sub\">sign in to start chatting<\/p>\n            <div class=\"tabs\">\n                <button id=\"tab-login\" class=\"active\" onclick=\"switchTab('login')\">log in<\/button>\n                <button id=\"tab-signup\" onclick=\"switchTab('signup')\">sign up<\/button>\n            <\/div>\n            <div id=\"auth-error\"><\/div>\n            <input id=\"auth-username\" placeholder=\"username\" maxlength=\"20\" autocomplete=\"username\" />\n            <input id=\"auth-password\" type=\"password\" placeholder=\"password\" autocomplete=\"current-password\" />\n            <button class=\"btn-primary\" id=\"auth-submit\" onclick=\"submitAuth()\">log in<\/button>\n            <p class=\"auth-switch\"><span id=\"auth-switch-text\">new here?<\/span> <a id=\"auth-switch-link\" onclick=\"switchTab('signup')\">create an account<\/a><\/p>\n        <\/div>\n    <\/div>\n\n\n    <div id=\"app\">\n        <div class=\"sidebar\">\n            <div class=\"side-header\">\n                <div class=\"brand\"><span>chat<\/span><\/div>\n                <button class=\"icon-btn\" title=\"settings\" onclick=\"openSettings()\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"3\"/><path d=\"M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 1 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06A1.65 1.65 0 0 0 4.68 15a1.65 1.65 0 0 0-1.51-1H3a2 2 0 1 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06A1.65 1.65 0 0 0 9 4.68a1.65 1.65 0 0 0 1-1.51V3a2 2 0 1 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06A1.65 1.65 0 0 0 19.4 9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 1 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z\"/><\/svg><\/button>\n            <\/div>\n            <div class=\"channels\" id=\"channel-list\"><\/div>\n            <div class=\"me-bar\">\n                <div class=\"avatar-sm me-avatar\" id=\"me-avatar\" style=\"cursor:pointer\" onclick=\"openSettings()\"><\/div>\n                <div class=\"me-info\">\n                    <div class=\"me-name\" id=\"me-name\"><\/div>\n                    <div class=\"me-mochis\" id=\"me-mochis\">\ud83c\udf61 0 mochis<\/div>\n                <\/div>\n                <button class=\"icon-btn\" title=\"log out\" onclick=\"logout()\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4\"/><path d=\"m16 17 5-5-5-5\"/><path d=\"M21 12H9\"/><\/svg><\/button>\n            <\/div>\n        <\/div>\n\n        <div class=\"main\">\n            <div class=\"main-header\">\n                <span class=\"hash-big\" id=\"header-icon\">#<\/span>\n                <span class=\"title\" id=\"header-title\">general<\/span>\n                <span class=\"topic\" id=\"header-topic\"><\/span>\n            <\/div>\n            <div id=\"messages\"><\/div>\n            <div class=\"typing-bar\" id=\"typing-bar\"><\/div>\n            <div class=\"input-area\" id=\"input-area\">\n                <div class=\"reply-banner\" id=\"reply-banner\"><\/div>\n                <div class=\"cmd-menu\" id=\"cmd-menu\"><\/div>\n                <div class=\"input-row\">\n                    <button class=\"attach-btn\" title=\"Send an image\" onclick=\"document.getElementById('image-input').click()\"><\/button>\n                    <input id=\"message-input\" placeholder=\"message #general\"\n                           oninput=\"updateCmdMenu();typingPing()\" onkeydown=\"inputKeydown(event)\" />\n                    <input type=\"file\" id=\"image-input\" accept=\"image/*\" onchange=\"sendImage(this)\" />\n                <\/div>\n            <\/div>\n        <\/div>\n\n        <div class=\"members\" id=\"members\"><\/div>\n    <\/div>\n\n    <div class=\"modal-bg\" id=\"profile-modal-bg\" onclick=\"if(event.target===this)closeModal('profile-modal-bg')\">\n        <div class=\"modal\" id=\"profile-modal\"><\/div>\n    <\/div>\n\n\n    <div class=\"modal-bg\" id=\"settings-modal-bg\" onclick=\"if(event.target===this)closeModal('settings-modal-bg')\">\n        <div class=\"modal\" id=\"settings-modal\"><\/div>\n    <\/div>\n\n    <div id=\"ping-badge\" style=\"display:none\" onclick=\"clearPings()\" title=\"times you've been pinged - click to clear\"><\/div>\n    <div id=\"toast\"><\/div>\n\n    <script>/* p/js/chatroom/app.js */\n\"use strict\";\n\nconst sb = supabase.createClient(SUPABASE_URL, SUPABASE_ANON_KEY);\n\nconst state = {\n    me: null,               // my profile row\n    profiles: new Map(),    // id -> profile (all users)\n    channels: [],\n    dms: [],                // {dmId, other: profile}\n    view: null,             // {type:'channel', channel} | {type:'dm', dmId, other}\n    msgsChannel: null,\n    msgsDm: null,\n    authMode: \"login\",\n    friendState: {},        // otherUserId -> 'none'|'pending_out'|'pending_in'|'friends'|'blocked'\n    reactions: new Map(),   // messageId -> [{emoji, user_id}]\n    msgCache: new Map(),    // messageId -> message (for rendering quoted replies)\n    replyTo: null,          // messageId being replied to\n    typing: new Map(),      // userId -> expiry timestamp (typing indicator)\n    unreadDms: new Map(),   // dmId -> unread message count\n    pingCount: 0,           // how many times i've been @-pinged\n    friendRequests: new Set(), // user ids with an inbound pending request\n};\n\nconst $ = (id) => {\n    const el = document.getElementById(id);\n    if (!el) {\n        console.warn(`Element with id \"${id}\" not found`);\n        return null;\n    }\n    return el;\n};\nconst CAT_LABELS = { chat: \"chat\", gambling: \"gambling\", important: \"important\", dm: \"direct messages\" };\nconst AVATAR_EMOJIS = [\"\ud83d\udc31\",\"\ud83d\udc36\"];\nconst AVATAR_COLORS = [\"#ffffff\",\"#7c5cff\",\"#000000\",\"#ff6b9d\",\"#43b581\",\"#f0b232\",\"#4aa8ff\",\"#ff6b6b\",\"#00c2a8\",\"#e67e22\"];\n\nfunction esc(s) {\n    return String(s ?? \"\").replace(/[&<>\"']/g, c => ({ \"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\",\"'\":\"&#39;\" }[c]));\n}\nfunction safeHref(url) {\n    try { const u = new URL(url); return /^https?:$/.test(u.protocol) ? u.href : \"\"; } catch { return \"\"; }\n}\nfunction parseAvatar(a) {\n    a = String(a || \"\");\n    // full URLs or root-relative paths (e.g. \"/assets/img/bot.png\") = image avatars\n    if (a.startsWith(\"http\") || a.startsWith(\"/\")) return { image: true, url: a };\n    const [emoji, color] = a.split(\"|\");\n    return { emoji: emoji || \"\ud83d\udc31\", color: /^#[0-9a-f]{3,8}$/i.test(color || \"\") ? color : \"#7c5cff\" };\n}\nfunction avatarInner(a) {\n    if (a.image) return `<img src=\"${esc(a.url)}\" style=\"width:100%;height:100%;object-fit:cover;border-radius:50%\" loading=\"lazy\">`;\n    return esc(a.emoji);\n}\nfunction avatarHTML(p, cls = \"avatar-sm\") {\n    const a = parseAvatar(p?.avatar);\n    return `<div class=\"${cls}\" style=\"background:${a.color || \"#7c5cff\"}\" onclick=\"openProfile('${p?.id || \"\"}')\">${avatarInner(a)}<\/div>`;\n}\nfunction toast(msg, opts = {}) {\n    const t = $(\"toast\");\n    if (!t) return;\n    t.textContent = msg;\n    if (opts.action) { // optional button, e.g. { label, fn }\n        const b = document.createElement(\"button\");\n        b.className = \"toast-btn\"; b.textContent = opts.action.label;\n        b.onclick = () => { t.classList.remove(\"show\"); opts.action.fn(); };\n        t.appendChild(b);\n    }\n    t.classList.add(\"show\");\n    clearTimeout(t._h);\n    t._h = setTimeout(() => t.classList.remove(\"show\"), opts.ms || 2500);\n}\nfunction timeStr(ts) {\n    return new Date(ts).toLocaleTimeString([], { hour: \"2-digit\", minute: \"2-digit\" });\n}\n// roles: founder > admin > mod > everyone else (member + custom roles). set_role() in\n// supabase/roles.sql enforces the same ranks server-side\nconst STAFF_ROLES = [\"founder\", \"admin\", \"mod\"];\nconst roleRank = (r) => ({ founder: 3, admin: 2, mod: 1 })[r] || 0;\nconst isStaffRole = (r) => STAFF_ROLES.includes(r);\nfunction isMod() { return !!state.me && isStaffRole(state.me.role); }\n// custom roles can have spaces etc, so they share one class and get a colour from their name\nfunction roleBadge(role, isBot) {\n    if (isBot) return `<span class=\"role-badge role-bot\">bot<\/span>`;\n    role = String(role || \"member\");\n    if (isStaffRole(role) || role === \"member\") return `<span class=\"role-badge role-${role}\">${esc(role)}<\/span>`;\n    let h = 0; for (const c of role) h = (h * 31 + c.codePointAt(0)) % 360;\n    return `<span class=\"role-badge role-custom\" style=\"--rc:hsl(${h} 70% 65%)\">${esc(role)}<\/span>`;\n}\n\n// ---------- IMAGE COMPRESSION ----------\n// downscale + re-encode before upload so storage egress (billed on every\n// download, not just upload) stays small. gifs are skipped since drawing to\n// canvas would flatten them to a single frame and kill the animation.\nfunction compressImage(file, maxDim = 1600, quality = 0.78) {\n    return new Promise((resolve) => {\n        if (!file.type.startsWith(\"image/\") || file.type === \"image/gif\") return resolve(file);\n        const url = URL.createObjectURL(file);\n        const img = new Image();\n        img.onload = () => {\n            URL.revokeObjectURL(url);\n            let { width, height } = img;\n            if (width > maxDim || height > maxDim) {\n                const scale = maxDim / Math.max(width, height);\n                width = Math.round(width * scale);\n                height = Math.round(height * scale);\n            }\n            const canvas = document.createElement(\"canvas\");\n            canvas.width = width;\n            canvas.height = height;\n            canvas.getContext(\"2d\").drawImage(img, 0, 0, width, height);\n            canvas.toBlob((blob) => {\n                // keep the original if compression somehow made it bigger\n                // (already-tiny or already-optimized images)\n                if (!blob || blob.size >= file.size) return resolve(file);\n                resolve(new File([blob], file.name.replace(/\\.\\w+$/, \"\") + \".jpg\", { type: \"image/jpeg\" }));\n            }, \"image/jpeg\", quality);\n        };\n        img.onerror = () => resolve(file); // corrupt/unsupported \u2014 just upload as-is\n        img.src = url;\n    });\n}\n\n// ---------- XP ----------\n// xp goes up 1 per message sent (server-side trigger, see schema.sql), so\n// it can't be faked client-side.\n//\n// leveling uses an escalating curve rather than a flat xp-per-level: level 2\n// costs XP_STEP, level 3 costs 2x that, level 4 costs 3x, etc, so early\n// levels come quick but it grinds the higher you go. tune XP_STEP to make\n// the whole curve faster/slower without changing its shape.\nconst XP_STEP = 25;\nfunction xpInfo(xp) {\n    xp = xp || 0;\n    let level = 1, need = XP_STEP, remaining = xp;\n    while (remaining >= need) {\n        remaining -= need;\n        level++;\n        need += XP_STEP;\n    }\n    return { xp, level, into: remaining, need };\n}\n\n// heartbeat fires every HEARTBEAT_MS, and a user counts as online if their\n// last_seen is within ONLINE_WINDOW_MS. window was only 3x the heartbeat\n// interval, so a single missed beat (tab throttled in background, brief\n// network hiccup) flipped someone to \"offline\" for everyone. wider window\n// + faster heartbeat fixes the flicker.\nconst HEARTBEAT_MS = 20000;\nconst ONLINE_WINDOW_MS = 100000;\n\n// \"playing x\" / \"listening to x\" comes from mochii (the games page and the music player), which refreshes\n// activity_at every minute while it's on. anything older than the window means it was closed\nconst ACTIVITY_WINDOW_MS = 180000;\nfunction activityOf(p) {\n    if (!p?.activity || !p.activity_at || (p.presence || \"online\") === \"offline\") return null;\n    if (Date.now() - new Date(p.activity_at).getTime() > ACTIVITY_WINDOW_MS) return null;\n    return { kind: p.activity_kind === \"music\" ? \"music\" : \"game\", name: p.activity, detail: p.activity_detail || \"\", cover: /^https:\\/\\//.test(p.activity_cover || \"\") ? p.activity_cover : \"\", since: p.activity_since ? new Date(p.activity_since).getTime() : 0 };\n}\n// \"12:34 elapsed\", like discord. any .activity-elapsed on screen is ticked once a second\nfunction elapsedText(since) {\n    const s = Math.max(0, Math.floor((Date.now() - since) / 1000)), pad = n => String(n).padStart(2, \"0\");\n    return (s >= 3600 ? Math.floor(s / 3600) + \":\" + pad(Math.floor(s / 60) % 60) : Math.floor(s / 60)) + \":\" + pad(s % 60) + \" elapsed\";\n}\nsetInterval(() => document.querySelectorAll(\".activity-elapsed[data-since]\").forEach(el => { el.textContent = elapsedText(+el.dataset.since); }), 1000);\n// discord style activity card for the profile modal\nfunction activityCardHTML(p) {\n    const act = activityOf(p);\n    if (!act) return \"\";\n    const music = act.kind === \"music\";\n    return `<div class=\"activity-card\">\n        <div class=\"activity-label\">${music ? \"listening to music\" : \"playing a game\"}<\/div>\n        <div class=\"activity-body\">\n            <div class=\"activity-cover\">${act.cover ? `<img src=\"${esc(act.cover)}\" alt=\"\" referrerpolicy=\"no-referrer\" onerror=\"this.remove()\">` : \"\"}<span>${music ? \"\ud83c\udfb5\" : \"\ud83c\udfae\"}<\/span><\/div>\n            <div class=\"activity-info\">\n                <div class=\"activity-name\">${esc(act.name)}<\/div>\n                <div class=\"activity-sub\">${music ? (act.detail ? \"by \" + esc(act.detail) + \" \u00b7 \" : \"\") + \"on mochii music\" : \"on mochii games\"}<\/div>\n                <div class=\"activity-live\"><i><\/i>${act.since ? `<span class=\"activity-elapsed\" data-since=\"${act.since}\">${elapsedText(act.since)}<\/span>` : music ? \"listening now\" : \"playing now\"}<\/div>\n            <\/div>\n        <\/div>\n    <\/div>`;\n}\n\n// ---------- AUTH ----------\nfunction switchTab(mode) {\n    state.authMode = mode;\n    const tabLogin = $(\"tab-login\");\n    if (tabLogin) tabLogin.classList.toggle(\"active\", mode === \"login\");\n    const tabSignup = $(\"tab-signup\");\n    if (tabSignup) tabSignup.classList.toggle(\"active\", mode === \"signup\");\n    const authSubmit = $(\"auth-submit\");\n    if (authSubmit) authSubmit.textContent = mode === \"login\" ? \"log in\" : \"sign up\";\n    const authSwitchText = $(\"auth-switch-text\");\n    if (authSwitchText) authSwitchText.textContent = mode === \"login\" ? \"New here?\" : \"Already have an account?\";\n    const authSwitchLink = $(\"auth-switch-link\");\n    if (authSwitchLink) {\n        authSwitchLink.textContent = mode === \"login\" ? \"Create an account\" : \"Log in\";\n        authSwitchLink.onclick = () => switchTab(mode === \"login\" ? \"signup\" : \"login\");\n    }\n    const authError = $(\"auth-error\");\n    if (authError) authError.textContent = \"\";\n}\n\nasync function submitAuth() {\n    const usernameInput = $(\"auth-username\");\n    const passwordInput = $(\"auth-password\");\n    const err = $(\"auth-error\");\n    const submitBtn = $(\"auth-submit\");\n\n    if (!usernameInput || !passwordInput || !err || !submitBtn) return;\n\n    const username = usernameInput.value.trim().toLowerCase();\n    const password = passwordInput.value;\n    if (!/^[a-z0-9_]{3,20}$/.test(username)) { err.textContent = \"Username must be 3\u201320 chars: a-z, 0-9, _\"; return; }\n    if (password.length < 6) { err.textContent = \"Password must be at least 6 characters.\"; return; }\n    err.textContent = \"\";\n    submitBtn.disabled = true;\n    try {\n        const email = `${username}@mochii.chat`;\n        let session = null, error = null;\n        if (state.authMode === \"signup\") {\n            ({ data: { session }, error } = await sb.auth.signUp({ email, password }));\n            if (error) throw error;\n        } else {\n            ({ data: { session }, error } = await sb.auth.signInWithPassword({ email, password }));\n            if (error) throw error;\n        }\n        if (!session) {\n            // only happens if \"Confirm email\" is still enabled in the Supabase dashboard\n            err.textContent = \"Check Supabase settings: turn OFF 'Confirm email' (Auth -> Providers -> Email), then try again.\";\n            return;\n        }\n        // logged in \u2014 enter app immediately\n        await loadMe();\n        await enterApp();\n    } catch (e) {\n        const m = e.message || \"\";\n        err.textContent =\n            m.includes(\"Invalid login\") ? \"Wrong username or password.\" :\n            m.includes(\"already registered\") ? \"That username is taken.\" :\n            m.includes(\"rate limit\") ? \"Too many attempts \u2014 wait a minute and try again.\" :\n            m.includes(\"at least 6\") ? \"Password must be at least 6 characters.\" :\n            m;\n    } finally {\n        if (submitBtn) submitBtn.disabled = false;\n    }\n}\n\nasync function loadMe() {\n    try {\n        const { data: { user } } = await sb.auth.getUser();\n        if (!user) return false;\n        let { data: p } = await sb.from(\"profiles\").select(\"*\").eq(\"id\", user.id).single();\n        if (!p) { // trigger may lag a moment on fresh signup\n            await new Promise(r => setTimeout(r, 800));\n            ({ data: p } = await sb.from(\"profiles\").select(\"*\").eq(\"id\", user.id).single());\n        }\n        state.me = p || null;\n        return !!p;\n    } catch (error) {\n        console.error(\"Failed to load user profile:\", error);\n        toast(\"Failed to load profile: \" + error.message);\n        return false;\n    }\n}\n\nasync function logout() {\n    try {\n        await sb.auth.signOut();\n    } catch (error) {\n        console.error(\"Logout failed:\", error);\n        // We still want to reload the page to clear local state\n    }\n    location.reload();\n}\n\n// ---------- PRESENCE HEARTBEAT ----------\nasync function heartbeat() {\n    if (!state.me) return;\n    // appearing offline = stop the heartbeat so others see you as offline\n    if ((state.me.presence || \"online\") === \"offline\") return;\n    try {\n        await sb.from(\"profiles\").update({ last_seen: new Date().toISOString() }).eq(\"id\", state.me.id);\n    } catch (error) {\n        console.error(\"Heartbeat failed:\", error);\n    }\n}\n\n// ---------- PRESENCE STATUS ----------\nasync function setPresence(val) {\n    try {\n        state.me.presence = val;\n        const { error } = await sb.from(\"profiles\").update({ presence: val }).eq(\"id\", state.me.id);\n        if (error) return toast(\"couldn't update status: \" + error.message);\n        if (val !== \"offline\") await heartbeat();\n        renderMembers();\n        toast(val === \"offline\" ? \"\ud83d\udc41\ufe0f you now appear offline\" : val === \"dnd\" ? \"\ud83d\udd34 do not disturb\" : \"\ud83d\udfe2 online\");\n        const settingsModalBg = $(\"settings-modal-bg\");\n        if (settingsModalBg && settingsModalBg.classList.contains(\"open\")) openSettings();\n    } catch (error) {\n        console.error(\"Set presence failed:\", error);\n        toast(\"couldn't update status: \" + error.message);\n    }\n}\n\n// ---------- BOOT ----------\n(async function boot() {\n    if (!SUPABASE_URL.startsWith(\"https://\") || SUPABASE_ANON_KEY.startsWith(\"YOUR-\")) {\n        const authSub = document.querySelector(\".auth-sub\");\n        if (authSub) {\n            authSub.innerHTML =\n                \"Setup needed: paste your Supabase URL + anon key into<br><b>assets/js/chatroom/config.js<\/b>, then run <b>supabase/schema.sql<\/b>.\";\n        }\n    }\n    if (await loadMe()) await enterApp();\n\n    sb.auth.onAuthStateChange(async (evt) => {\n        // the main site shares this login, so signing out there signs out here too\n        if (evt === \"SIGNED_OUT\" && appEntered) return location.reload();\n        if (evt === \"SIGNED_IN\" && !(await loadMe())) return;\n        const appEl = $(\"app\");\n        if (state.me && appEl && !appEl.classList.contains(\"active\")) await enterApp();\n    });\n})();\n\n// ---------- APP ENTRY ----------\nlet msgSubChannel = null, msgSubDm = null;\nlet lastPollAt = null;\nlet appEntered = false;\n\nasync function enterApp() {\n    if (appEntered) return;\n    appEntered = true;\n    const authScreen = $(\"auth-screen\");\n    const appEl = $(\"app\");\n    if (authScreen) authScreen.style.display = \"none\";\n    if (appEl) appEl.classList.add(\"active\");\n\n    await Promise.all([loadChannels(), loadProfiles(), loadDMs()]);\n    renderSidebar();\n    renderMeBar();\n    renderMembers();\n    startRealtime();\n\n    await heartbeat();\n    setInterval(heartbeat, HEARTBEAT_MS);\n    setInterval(() => { loadProfiles().then(renderMembers); }, HEARTBEAT_MS);\n    setInterval(pollMessages, 250);\n    // background tabs get their intervals throttled by the browser, so a\n    // beat can be missed for way longer than HEARTBEAT_MS \u2014 catch up the\n    // instant the tab is visible again instead of waiting on the timer\n    document.addEventListener(\"visibilitychange\", () => { if (!document.hidden) heartbeat(); });\n\n    const gen = state.channels.find(c => c.name === \"general\") || state.channels[0];\n    if (gen) openChannel(gen);\n}\n\nasync function loadProfiles() {\n    try {\n        const { data } = await sb.from(\"profiles\").select(\"*\");\n        state.profiles.clear();\n        for (const p of data || []) {\n            state.profiles.set(p.id, p);\n            // keep our own view of `me` (effect/banner/balance) in sync with realtime updates\n            if (state.me && p.id === state.me.id) state.me = p;\n        }\n    } catch (error) {\n        console.error(\"Failed to load profiles:\", error);\n        toast(\"Failed to load profiles: \" + error.message);\n    }\n}\n\nasync function loadChannels() {\n    try {\n        const { data } = await sb.from(\"channels\").select(\"*\").order(\"position\");\n        state.channels = data || [];\n    } catch (error) {\n        console.error(\"Failed to load channels:\", error);\n        toast(\"Failed to load channels: \" + error.message);\n    }\n}\n\nasync function loadDMs() {\n    try {\n        if (!state.me) return;\n        const { data } = await sb.from(\"dms\").select(\"*\")\n            .or(`user_a.eq.${state.me.id},user_b.eq.${state.me.id}`);\n        state.dms = [];\n        for (const d of data || []) {\n            const otherId = d.user_a === state.me.id ? d.user_b : d.user_a;\n            const { data: op } = await sb.from(\"profiles\").select(\"*\").eq(\"id\", otherId).maybeSingle();\n            if (op) state.dms.push({ dmId: d.id, other: op });\n        }\n    } catch (error) {\n        console.error(\"Failed to load DMs:\", error);\n        toast(\"Failed to load DMs: \" + error.message);\n    }\n}\n\nasync function getOrCreateDm(otherId) {\n    if (!state.me) return null;\n    try {\n        const [a, b] = [state.me.id, otherId].sort();\n        let { data: dm } = await sb.from(\"dms\").select(\"*\").eq(\"user_a\", a).eq(\"user_b\", b).maybeSingle();\n        if (!dm) {\n            ({ data: dm } = await sb.from(\"dms\").insert({ user_a: a, user_b: b }).select().single());\n        }\n        return dm;\n    } catch (error) {\n        console.error(\"Failed to get or create DM:\", error);\n        toast(\"Failed to get or create DM: \" + error.message);\n        return null;\n    }\n}\n\n// ---------- SIDEBAR ----------\nfunction renderSidebar() {\n    const list = $(\"channel-list\");\n    if (!list) return;\n    let html = \"\";\n    for (const cat of [...new Set(state.channels.map(c => c.category))]) {\n        html += `<div class=\"cat-label\"><span>${esc(CAT_LABELS[cat] || cat)}<\/span><\/div>`;\n        for (const ch of state.channels.filter(c => c.category === cat)) {\n            html += `<div class=\"chan ${ch.locked ? \"locked\" : \"\"} ${state.view?.type === \"channel\" && state.view.channel.id === ch.id ? \"active\" : \"\"}\"\n                        onclick=\"openChannelById('${ch.id}')\">\n                        <span class=\"hash\">#<\/span>${esc(ch.name)}<\/div>`;\n        }\n    }\n    html += `<div class=\"cat-label\"><span>${CAT_LABELS.dm}<\/span><\/div>`;\n    if (!state.dms.length) html += `<div style=\"font-size:12.5px;opacity:.4;padding:4px 10px;\">no dms yet \u2014 click a member<\/div>`;\n    for (const d of state.dms) {\n        const a = parseAvatar(d.other?.avatar);\n        const unread = state.unreadDms.get(d.dmId) || 0;\n        const hasReq = state.friendRequests.has(d.other.id);\n        html += `<div class=\"chan ${unread > 0 ? \"has-unread\" : \"\"} ${state.view?.type === \"dm\" && state.view.dmId === d.dmId ? \"active\" : \"\"}\"\n                    onclick=\"openDm('${d.other.id}')\">\n                    <span class=\"dm-avatar\" style=\"background:${a.color || \"#7c5cff\"}\">${avatarInner(a)}<\/span>\n                    ${esc(d.other.username)}${hasReq ? ` <span class=\"dm-friend-tag\">\ud83d\udc4b wants to be friends<\/span>` : \"\"}\n                    ${unread > 0 ? `<span class=\"unread-badge\">${unread > 9 ? \"9+\" : unread}<\/span>` : \"\"}<\/div>`;\n    }\n    list.innerHTML = html;\n}\n\nfunction openChannelById(id) { openChannel(state.channels.find(c => c.id === id)); }\n\nfunction renderMeBar() {\n    const a = parseAvatar(state.me.avatar);\n    const meAvatar = $(\"me-avatar\");\n    if (meAvatar) {\n        meAvatar.outerHTML =\n            `<div class=\"avatar-sm me-avatar\" id=\"me-avatar\" style=\"cursor:pointer;background:${a.color || \"#7c5cff\"}\" onclick=\"openSettings()\">${avatarInner(a)}<\/div>`;\n    }\n    const meName = $(\"me-name\");\n    if (meName) meName.textContent = state.me.username;\n    const meMochis = $(\"me-mochis\");\n    if (meMochis) meMochis.textContent = `\ud83c\udf61 ${state.me.balance} mochis \u00b7 lvl ${xpInfo(state.me.xp).level}`;\n}\n\n// ---------- OPENING VIEWS ----------\nfunction setHeader(icon, title, topic) {\n    const headerIcon = $(\"header-icon\");\n    if (headerIcon) headerIcon.textContent = icon;\n    const headerTitle = $(\"header-title\");\n    if (headerTitle) headerTitle.textContent = title;\n    const headerTopic = $(\"header-topic\");\n    if (headerTopic) headerTopic.textContent = topic || \"\";\n}\n\nfunction canPostHere() {\n    if (!state.view) return false;\n    if (state.view.type === \"dm\") return true;\n    if (state.view.channel.locked) return isMod();\n    return true;\n}\n\nasync function openChannel(ch) {\n    if (!ch) return;\n    state.view = { type: \"channel\", channel: ch };\n    state.replyTo = null;\n    renderSidebar();\n    setHeader(\"#\", ch.name,\n        ch.category === \"gambling\" ? \"commands: /daily /beg /work /fish /crime /quest /coinflip /gamble /blackjack /battle /pay /steal /hug /rich\"\n        : ch.locked ? \"only staff can post here\" : \"\");\n    updateInputLock(ch.name);\n    await loadMessages();\n}\n\nasync function openDm(otherId) {\n    let dmRec = state.dms.find(d => d.other.id === otherId);\n    if (!dmRec) {\n        const dm = await getOrCreateDm(otherId);\n        const other = state.profiles.get(otherId);\n        if (!dm || !other) return toast(\"couldn't open that dm.\");\n        dmRec = { dmId: dm.id, other };\n        state.dms.push(dmRec);\n    }\n    state.view = { type: \"dm\", dmId: dmRec.dmId, other: dmRec.other };\n    state.replyTo = null;\n    clearDmUnread(dmRec.dmId);\n    renderSidebar();\n    setHeader(\"@\", dmRec.other.username, \"direct message\");\n    updateInputLock(dmRec.other.username);\n    await loadMessages();\n}\n\nfunction updateInputLock(name) {\n    if (canPostHere()) {\n        const inputArea = $(\"input-area\");\n        if (inputArea) {\n            inputArea.innerHTML = `\n            <div class=\"reply-banner\" id=\"reply-banner\"><\/div>\n            <div class=\"cmd-menu\" id=\"cmd-menu\"><\/div>\n            <div class=\"input-row\">\n                <button class=\"attach-btn\" title=\"send an image\" onclick=\"document.getElementById('image-input')?.click()\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"3\"/><circle cx=\"9\" cy=\"9\" r=\"2\"/><path d=\"m21 15-3.09-3.09a2 2 0 0 0-2.82 0L6 21\"/><\/svg><\/button>\n                <input id=\"message-input\" placeholder=\"${esc(`message ${state.view.type === \"channel\" ? \"#\" : \"@\"}${name}`)}\"\n                       oninput=\"updateCmdMenu();typingPing()\" onkeydown=\"inputKeydown(event)\" />\n                <input type=\"file\" id=\"image-input\" accept=\"image/*\" onchange=\"sendImage(this)\" />\n                <button class=\"send-btn\" title=\"send\" onmousedown=\"event.preventDefault()\" onclick=\"sendCurrent()\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 19V5\"/><path d=\"m5 12 7-7 7 7\"/><\/svg><\/button>\n            <\/div>`;\n            renderReplyBanner();\n        }\n    } else {\n        const inputArea = $(\"input-area\");\n        if (inputArea) {\n            inputArea.innerHTML = `<div class=\"locked-note\">\ud83d\udd12 only staff can post in this channel.<\/div>`;\n        }\n    }\n}\n\n// ---------- SLASH COMMAND AUTOCOMPLETE ----------\nconst COMMANDS = [\n    { name: \"/daily\",    params: [],            desc: \"claim your daily mochis (streak bonus)\" },\n    { name: \"/balance\",  params: [],            desc: \"check your mochis balance\" },\n    { name: \"/rich\",     params: [],            desc: \"mochis leaderboard\" },\n    { name: \"/beg\",      params: [],            desc: \"beg strangers for mochis (45s cooldown)\" },\n    { name: \"/work\",     params: [],            desc: \"do a job for mochis (3min cooldown)\" },\n    { name: \"/fish\",     params: [],            desc: \"go fishing for mochis (60s cooldown)\" },\n    { name: \"/crime\",    params: [],            desc: \"risk it for a bigger payout (90s cooldown)\" },\n    { name: \"/quest\",    params: [],            desc: \"fight a monster for mochis (attack/flee), 5min cooldown\" },\n    { name: \"/coinflip\", params: [\"amount\"],     desc: \"double or nothing\" },\n    { name: \"/gamble\",   params: [\"amount\"],     desc: \"roll the dice, up to 3x\" },\n    { name: \"/blackjack\",params: [\"amount\"],     desc: \"play blackjack vs mochiiBot (hit/stand)\" },\n    { name: \"/pay\",      params: [\"@user\", \"amount\"], desc: \"send mochis to someone\" },\n    { name: \"/steal\",    params: [\"@user\"],        desc: \"try to steal mochis (40% success, 2min cooldown)\" },\n    { name: \"/hug\",      params: [\"@user\"],        desc: \"hug someone \ud83e\udec2\" },\n    { name: \"/battle\",   params: [\"@user\", \"amount\"], desc: \"wagered duel, optional style: clash|highroll|rps|tug \u2014 both must ready up\" },\n    { name: \"/role\",     params: [\"@user\", \"role\"], desc: \"give someone a role (staff only)\", staff: true },\n];\nconst GAMBLING_CMDS = [\"coinflip\", \"gamble\", \"blackjack\", \"battle\", \"pay\"];\nconst KNOWN_CMDS = [...GAMBLING_CMDS, \"beg\", \"work\", \"fish\", \"crime\", \"quest\", \"daily\", \"balance\", \"rich\", \"hug\", \"steal\"];\n// short aliases -> full command names (shown in autocomplete, normalized before sending)\nconst COMMAND_ALIASES = { d: \"daily\", b: \"balance\", bal: \"balance\", lb: \"rich\", top: \"rich\", bg: \"beg\", w: \"work\", f: \"fish\", c: \"crime\", q: \"quest\", cf: \"coinflip\", g: \"gamble\", bj: \"blackjack\", p: \"pay\", s: \"steal\", h: \"hug\", bt: \"battle\" };\nconst cmdArgs = (c) => c.params.map(x => ` [${x}]`).join(\"\");\nconst PLACEHOLDER = /\\[[^\\]\\s][^\\]]*\\]/g;\n// select the next [placeholder] at/after pos (wraps); returns false if there are none\nfunction selectPlaceholder(input, pos = 0) {\n    for (const from of [pos, 0]) {\n        PLACEHOLDER.lastIndex = from;\n        const m = PLACEHOLDER.exec(input.value);\n        if (m) { input.setSelectionRange(m.index, m.index + m[0].length); return true; }\n    }\n    return false;\n}\n// discord-style: every [param] of a command must be filled in before it can be sent\nfunction validateCommand(text) {\n    const [c0, ...args] = text.slice(1).trim().split(/\\s+/);\n    const cmd = \"/\" + (COMMAND_ALIASES[c0.toLowerCase()] || c0.toLowerCase());\n    const c = COMMANDS.find(x => x.name === cmd);\n    if (!c) return null;\n    for (let i = 0; i < c.params.length; i++) {\n        const p = c.params[i], v = i === c.params.length - 1 && p === \"role\" ? args.slice(i).join(\" \") : args[i];\n        if (!v || /^\\[.*\\]$/.test(v)) return `fill in [${p}] to use ${cmd}`;\n        if (p === \"amount\" && !/^\\d+$/.test(v)) return \"[amount] needs to be a whole number\";\n        if (p === \"@user\" && !/^@[a-z0-9_]{3,20}$/i.test(v)) return \"[@user] needs to be an @mention\";\n    }\n    return null;\n}\nlet acIndex = 0;\n\n// figure out what (if anything) we're autocompleting: /commands, @people, #channels\nfunction acMatches() {\n    const input = $(\"message-input\");\n    if (!input) return null;\n    const val = input.value || \"\";\n\n    // slash commands \u2014 start of message, bot commands are channel-only\n    if (val.startsWith(\"/\") && !val.includes(\" \")) {\n        if (state.view?.type !== \"channel\") return null;\n        const q = val.toLowerCase();\n        return {\n            hint: \"commands \u2022 \u2191\u2193 to browse \u2022 tab/enter to complete\",\n            from: 0, to: val.length,\n            items: COMMANDS.filter(c => (c.name.startsWith(q) || Object.keys(COMMAND_ALIASES).some(a => COMMAND_ALIASES[a] === c.name.slice(1) && \"/\" + a === q)) && (!c.staff || isMod())).map(c => ({\n                insert: c.name + cmdArgs(c), label: c.name, sub: cmdArgs(c).trim(), desc: c.desc,\n                avatarHTML: \"\",\n            })),\n        };\n    }\n\n    // @mention or #channel at the word currently being typed\n    const caret = input.selectionStart ?? val.length;\n    const m = val.slice(0, caret).match(/(^|\\s)([@#])([a-z0-9_]*)$/i);\n    if (!m) return null;\n    const sig = m[2], q = m[3].toLowerCase();\n    const from = m.index + m[1].length, to = caret;\n\n    if (sig === \"@\") {\n        const isOn = (p) => (p.presence || \"online\") !== \"offline\" &&\n            Date.now() - new Date(p.last_seen).getTime() < ONLINE_WINDOW_MS;\n        const users = [...state.profiles.values()]\n            .filter(p => p.username.toLowerCase() !== \"mochiibot\" && p.username.toLowerCase().startsWith(q))\n            .sort((a, b) => (isOn(b) - isOn(a)) || a.username.localeCompare(b.username));\n        return {\n            hint: \"members \u2022 \u2191\u2193 to browse \u2022 tab/enter to ping\",\n            from, to,\n            items: users.map(p => {\n                const av = parseAvatar(p.avatar);\n                return {\n                    insert: `@${p.username} `, label: p.username, sub: \"\", desc: p.role,\n                    avatarHTML: `<span class=\"ac-avatar\" style=\"background:${av.color || \"#7c5cff\"}\">${avatarInner(av)}<\/span>`,\n                };\n            }),\n        };\n    }\n\n    // #\n    const chans = state.channels.filter(c => c.name.toLowerCase().startsWith(q));\n    return {\n        hint: \"channels \u2022 \u2191\u2193 to browse \u2022 tab/enter to complete\",\n        from, to,\n        items: chans.map(c => ({\n            insert: `#${c.name} `, label: c.name, sub: \"\", desc: c.category,\n            avatarHTML: `<span class=\"ac-hash\">#<\/span>`,\n        })),\n    };\n}\n\n// store matches so the click / keydown handlers agree on what's listed\nlet acCurrent = null;\n\nfunction updateCmdMenu() {\n    const menu = $(\"cmd-menu\");\n    if (!menu) return;\n    const ac = acMatches();\n    acCurrent = ac;\n    if (!ac || !ac.items.length) { menu.classList.remove(\"open\"); menu.innerHTML = \"\"; return; }\n    if (acIndex >= ac.items.length) acIndex = 0;\n    menu.innerHTML =\n        `<div class=\"cmd-hint\">${ac.hint}<\/div>` +\n        ac.items.map((it, i) => `\n            <div class=\"cmd-item ${i === acIndex ? \"selected\" : \"\"}\"\n                 onmousedown=\"event.preventDefault();completeAutocomplete(${i})\">\n                ${it.avatarHTML}\n                <span class=\"cmd-name\">${esc(it.label)}<\/span>\n                ${it.sub ? `<span class=\"cmd-args\">${esc(it.sub)}<\/span>` : \"\"}\n                <span class=\"cmd-desc\">${esc(it.desc)}<\/span>\n            <\/div>`).join(\"\");\n    menu.classList.add(\"open\");\n    menu.querySelector(\".selected\")?.scrollIntoView({ block: \"nearest\" });\n}\n\nfunction completeAutocomplete(i) {\n    const input = $(\"message-input\");\n    const it = acCurrent?.items?.[i];\n    if (!input || !it || !acCurrent) return;\n    const rest = input.value.slice(acCurrent.to);\n    const ins = rest.startsWith(\" \") ? it.insert.trimEnd() : it.insert; // don't double the space before a [placeholder]\n    input.value = input.value.slice(0, acCurrent.from) + ins + rest;\n    closeCmdMenu();\n    input.focus();\n    const end = acCurrent.from + ins.length;\n    // jump onto the next unfilled [placeholder], else park the caret after what we inserted\n    if (!selectPlaceholder(input, ins.startsWith(\"/\") ? 0 : end)) input.setSelectionRange(end, end);\n}\n\nfunction closeCmdMenu() {\n    const cmdMenu = $(\"cmd-menu\");\n    if (cmdMenu) cmdMenu.classList.remove(\"open\");\n}\n\nconst input_hasPlaceholder = (el) => el.value.startsWith(\"/\") && /\\[[^\\]\\s][^\\]]*\\]/.test(el.value);\nfunction inputKeydown(e) {\n    const menu = $(\"cmd-menu\");\n    const open = menu && menu.classList.contains(\"open\");\n    if (!open) {\n        if (e.key === \"Tab\" && input_hasPlaceholder(e.target)) { e.preventDefault(); selectPlaceholder(e.target, e.target.selectionEnd); }\n        else if (e.key === \"Enter\") sendCurrent();\n        else if (e.key === \"Escape\" && state.replyTo) cancelReply();\n        return;\n    }\n    // keep the list fresh in case it changed since the last input event\n    updateCmdMenu();\n    if (!menu || !menu.classList.contains(\"open\")) return;\n    const items = menu ? [...menu.querySelectorAll(\".cmd-item\")] : [];\n    if (e.key === \"ArrowDown\" || e.key === \"ArrowUp\") {\n        e.preventDefault();\n        const dir = e.key === \"ArrowDown\" ? 1 : -1;\n        acIndex = (acIndex + dir + items.length) % items.length;\n        items.forEach((el, i) => el.classList.toggle(\"selected\", i === acIndex));\n        items[acIndex]?.scrollIntoView({ block: \"nearest\" });\n    } else if (e.key === \"Tab\" || e.key === \"Enter\") {\n        e.preventDefault();\n        completeAutocomplete(acIndex);\n        // an argless slash command fires immediately (old \"/\" behaviour) \u2014\n        // only when it truly takes no arguments (empty sub), otherwise this\n        // sent the literal placeholder text (e.g. \"/coinflip <amount>\")\n        const it = acCurrent?.items?.[acIndex] || acCurrent?.items?.[0];\n        if (e.key === \"Enter\" && it && it.insert.startsWith(\"/\") && !it.sub) sendCurrent();\n    } else if (e.key === \"Escape\") {\n        e.preventDefault();\n        closeCmdMenu();\n    }\n}\n\n// ---------- MESSAGES ----------\nconst BOT_PROFILE = { username: \"mochiiBot\", avatar: \"\ud83c\udf61|#ff6b9d\", role: \"member\" };\nconst EMOJI_PICKER = (() => {\n    const str = \"\u2764\ufe0f\ud83d\ude02\ud83d\ude2d\ud83d\ude2d\ud83d\udc80\ud83d\udd25\ud83d\udcaf\ud83d\udc4d\ud83d\udc4e\ud83d\ude2d\ud83e\udd7a\ud83d\ude0d\ud83e\udd70\ud83d\ude0e\ud83d\ude2d\ud83e\udd23\ud83e\udd14\ud83d\ude10\ud83d\ude11\ud83d\ude21\ud83d\ude31\ud83d\ude2d\ud83d\ude05\ud83d\ude0a\ud83d\ude4f\ud83d\udc4f\ud83d\ude4c\ud83d\udc4c\u270c\ufe0f\ud83e\udd1e\ud83e\udd1f\ud83e\udd19\ud83d\udcaa\ud83d\udc4b\ud83d\udc4a\ud83d\udc40\u2b50\ud83c\udf89\u2705\u274c\u2757\u2753\ud83d\udc95\ud83d\udc96\ud83d\udc97\ud83d\udc94\ud83e\udde1\ud83d\udc9b\ud83d\udc9a\ud83d\udc99\ud83d\udc9c\ud83d\udda4\ud83e\udd0d\ud83e\udd0e\ud83d\ude34\ud83e\udd2f\ud83d\ude0f\ud83d\ude44\ud83d\ude2c\ud83e\udee1\ud83e\udd1d\";\n    const parts = typeof Intl !== \"undefined\" && Intl.Segmenter\n        ? [...new Intl.Segmenter().segment(str)].map(x => x.segment)\n        : str.match(/\\p{Extended_Pictographic}\\uFE0F?/gu) || [];\n    return [...new Set(parts)];\n})();\n\nfunction viewKind() { return state.view?.type === \"dm\" ? \"dm\" : \"channel\"; }\n\nfunction renderMsg(m) {\n    const author = m.author_id ? (state.profiles.get(m.author_id) || BOT_PROFILE) : BOT_PROFILE;\n    const isBot = author === BOT_PROFILE || (author.username || \"\").toLowerCase() === \"mochiibot\";\n    const mine = m.author_id === state.me?.id;\n\n    // game messages (blackjack, quest, battle) link via a generic\n    // game_kind/game_id pair on the row itself, and get edited in place as\n    // the game progresses \u2014 no more separate message per round\n    const rawContent = m.content || \"\";\n    let gameHTML = \"\";\n    if (isBot && m.game_id) {\n        const gid = m.game_id;\n        if (m.game_kind === \"blackjack\") {\n            gameHTML = `<div class=\"bj-actions\" data-game=\"${gid}\">\n                <button class=\"bj-btn hit\" onclick=\"bjMove('hit','${gid}')\">\ud83c\udccf hit<\/button>\n                <button class=\"bj-btn stand\" onclick=\"bjMove('stand','${gid}')\">\u270b stand<\/button>\n            <\/div>`;\n        } else if (m.game_kind === \"quest\") {\n            gameHTML = `<div class=\"bj-actions\" data-game=\"${gid}\">\n                <button class=\"bj-btn hit\" onclick=\"questMove('attack','${gid}')\">\u2694\ufe0f attack<\/button>\n                <button class=\"bj-btn stand\" onclick=\"questMove('flee','${gid}')\">\ud83c\udfc3 flee<\/button>\n            <\/div>`;\n        } else if (m.game_kind === \"battle_pending\") {\n            gameHTML = `<div class=\"bj-actions\" data-game=\"${gid}\">\n                <button class=\"bj-btn hit\" onclick=\"battleMove('accept','${gid}')\">\u2705 accept<\/button>\n                <button class=\"bj-btn fold\" onclick=\"battleMove('decline','${gid}')\">\ud83c\udff3\ufe0f decline<\/button>\n            <\/div>`;\n        } else if (m.game_kind === \"battle_ready\") {\n            gameHTML = `<div class=\"bj-actions\" data-game=\"${gid}\">\n                <button class=\"bj-btn hit\" onclick=\"battleMove('ready','${gid}')\">\u2705 ready<\/button>\n                <button class=\"bj-btn fold\" onclick=\"battleMove('decline','${gid}')\">\ud83c\udff3\ufe0f decline<\/button>\n            <\/div>`;\n        } else if (m.game_kind === \"battle_tug\") {\n            gameHTML = `<div class=\"bj-actions\" data-game=\"${gid}\">\n                <button class=\"bj-btn hit\" onclick=\"battlePull('${gid}')\">\ud83e\udea2 pull!<\/button>\n            <\/div>`;\n        }\n    }\n    const content = formatContent(rawContent, author);\n    const imgUrl = safeHref(m.image_url);\n    const img = imgUrl ? `<a href=\"${esc(imgUrl)}\" target=\"_blank\" rel=\"noopener noreferrer\"><img class=\"msg-img\" src=\"${esc(imgUrl)}\" loading=\"lazy\"><\/a>` : \"\";\n    const quote = renderQuote(m.reply_to);\n\n    // link embed (open graph)\n    let embedHTML = \"\";\n    const embedUrl = extractEmbedUrl(m);\n    if (embedUrl && !isBot) {\n        if (!state.embeds.has(m.id)) state.embeds.set(m.id, { url: embedUrl, data: null });\n        embedHTML = `<div id=\"embed-${m.id}\">${embedCardHTML(m.id)}<\/div>`;\n        setTimeout(() => ensureEmbed(m.id, embedUrl), 0);\n    }\n\n    return `<div class=\"msg ${isBot ? \"bot-msg\" : \"\"} ${m.edited_at ? \"edited\" : \"\"}\" data-mid=\"${m.id}\" data-author=\"${m.author_id || \"bot\"}\" data-ts=\"${new Date(m.created_at).getTime()}\"${m.reply_to ? ' data-reply=\"1\"' : \"\"}${m.local ? ' data-local=\"1\"' : \"\"}>\n        <div class=\"msg-gutter\">${avatarHTML(author)}<span class=\"msg-stamp\">${timeStr(m.created_at)}<\/span><\/div>\n        <div class=\"msg-body\">\n            <div class=\"msg-head\">\n                <span class=\"msg-author\" onclick=\"${isBot ? \"\" : `openProfile('${author.id}')`}\">${esc(author.username)}<\/span>\n                ${roleBadge(author.role, isBot)}\n                <span class=\"msg-time\">${timeStr(m.created_at)}<\/span>\n            <\/div>\n            ${quote}\n            ${content ? `<div class=\"msg-content\">${content}<\/div>` : \"\"}\n            ${gameHTML}\n            ${img}\n            ${embedHTML}\n            <div class=\"reactions\" id=\"reactions-${m.id}\"><\/div>\n        <\/div>\n        <div class=\"msg-actions\">\n            <button title=\"add reaction\" onclick=\"openEmojiPicker(event, '${m.id}')\">\ud83d\ude00<\/button>\n            <button title=\"reply\" onclick=\"startReply('${m.id}')\">\u21a9\ufe0f<\/button>\n            ${mine && !isBot ? `<button title=\"edit message\" onclick=\"startEdit('${m.id}')\">\u270f\ufe0f<\/button>` : \"\"}\n            ${!isBot && (mine || (viewKind() === \"channel\" && isStaff())) ? `<button title=\"${mine ? \"delete message\" : \"delete message (mod)\"}\" onclick=\"deleteMsg('${m.id}')\">\ud83d\uddd1\ufe0f<\/button>` : \"\"}\n        <\/div>\n    <\/div>`;\n}\n\n// ---------- GROUPING ----------\n// back-to-back messages from the same person (within 5 min, not replies) drop\n// their avatar and name. it's a class on the dom, so re-run it after any add/remove/edit\nconst GROUP_MS = 5 * 60 * 1000;\nfunction regroup() {\n    let prev = null;\n    for (const el of document.querySelectorAll(\"#messages > .msg\")) {\n        const d = el.dataset;\n        el.classList.toggle(\"grouped\", !!prev && !d.reply && d.author === prev.dataset.author && d.ts - prev.dataset.ts < GROUP_MS);\n        prev = el;\n    }\n}\n\n// ---------- REPLIES ----------\nfunction quotedPreview(m) {\n    if (!m) return \"\";\n    if (m.image_url && !m.content) return \"\ud83d\uddbc\ufe0f image\";\n    return (m.content || \"\").slice(0, 120);\n}\n\nfunction renderQuote(replyId) {\n    if (!replyId) return \"\";\n    ensureQuote(replyId);\n    const q = state.msgCache.get(replyId);\n    if (!q) {\n        return `<div class=\"msg-quote pending\" data-quote=\"${replyId}\"><span class=\"quote-bar\"><\/span><i>loading reply\u2026<\/i><\/div>`;\n    }\n    const qa = q.author_id ? (state.profiles.get(q.author_id) || BOT_PROFILE) : BOT_PROFILE;\n    return `<div class=\"msg-quote\" data-quote=\"${replyId}\" onclick=\"jumpToMsg('${replyId}')\">\n        <span class=\"quote-author\" data-quote-author=\"${replyId}\">${esc(qa.username)}<\/span>\n        <span class=\"quote-text\">${esc(quotedPreview(q))}<\/span>\n    <\/div>`;\n}\n\nasync function ensureQuote(mid) {\n    if (!mid || state.msgCache.has(mid)) return;\n    state.msgCache.set(mid, null); // reserve so we don't fetch twice\n    const table = viewKind() === \"dm\" ? \"dm_messages\" : \"messages\";\n    const { data } = await sb.from(table).select(\"id, author_id, content, image_url\").eq(\"id\", mid).maybeSingle();\n    if (!data) { state.msgCache.delete(mid); return; }\n    state.msgCache.set(data.id, data);\n    const qa = data.author_id ? (state.profiles.get(data.author_id) || BOT_PROFILE) : BOT_PROFILE;\n    document.querySelectorAll(`.msg-quote[data-quote=\"${mid}\"]`).forEach(el => {\n        el.classList.remove(\"pending\");\n        el.onclick = () => jumpToMsg(mid);\n        el.innerHTML = `<span class=\"quote-author\">${esc(qa.username)}<\/span><span class=\"quote-text\">${esc(quotedPreview(data))}<\/span>`;\n    });\n}\n\nasync function hydrateReplies(rows) {\n    const need = [...new Set(rows.map(m => m.reply_to).filter(Boolean))].filter(id => !state.msgCache.has(id));\n    if (!need.length) return;\n    const table = viewKind() === \"dm\" ? \"dm_messages\" : \"messages\";\n    for (let i = 0; i < need.length; i += 50) {\n        const chunk = need.slice(i, i + 50);\n        const { data } = await sb.from(table).select(\"id, author_id, content, image_url\").in(\"id\", chunk);\n        for (const m of data || []) state.msgCache.set(m.id, m);\n    }\n}\n\nfunction jumpToMsg(mid) {\n    const el = document.querySelector(`[data-mid=\"${mid}\"]`);\n    if (!el) return toast(\"that message isn't loaded anymore.\");\n    el.scrollIntoView({ behavior: \"smooth\", block: \"center\" });\n    el.style.transition = \"background .2s\";\n    el.style.background = \"rgba(255,255,255,.07)\";\n    setTimeout(() => { el.style.background = \"\"; }, 1200);\n}\n\nfunction startReply(mid) {\n    state.replyTo = mid;\n    renderReplyBanner();\n    $(\"message-input\")?.focus();\n}\n\nfunction cancelReply() {\n    state.replyTo = null;\n    renderReplyBanner();\n}\n\nfunction renderReplyBanner() {\n    const banner = $(\"reply-banner\");\n    if (!banner) return;\n    if (!state.replyTo) { banner.classList.remove(\"open\"); banner.innerHTML = \"\"; return; }\n    const m = state.msgCache.get(state.replyTo);\n    const who = m\n        ? ((m.author_id ? state.profiles.get(m.author_id) : BOT_PROFILE) || BOT_PROFILE).username\n        : \"message\";\n    banner.innerHTML = `<span class=\"rb-text\">\u21a9\ufe0f replying to <b>${esc(who)}<\/b> \u2014 ${esc(quotedPreview(m) || \"\")}<\/span>\n        <button class=\"rb-cancel\" title=\"Cancel reply\" onclick=\"cancelReply()\">\u2715<\/button>`;\n    banner.classList.add(\"open\");\n}\n\nfunction renderReactions(mid) {\n    const box = document.getElementById(`reactions-${mid}`);\n    if (!box) return;\n    const list = state.reactions.get(mid) || [];\n    const byEmoji = new Map();\n    for (const r of list) {\n        if (!byEmoji.has(r.emoji)) byEmoji.set(r.emoji, []);\n        byEmoji.get(r.emoji).push(r.user_id);\n    }\n    box.innerHTML = [...byEmoji.entries()].map(([emoji, uids]) => `\n        <span class=\"reaction ${uids.includes(state.me.id) ? \"mine\" : \"\"}\"\n              onclick=\"toggleReaction('${mid}', ${esc(JSON.stringify(emoji))})\"\n              title=\"${uids.map(id => esc(state.profiles.get(id)?.username || \"?\")).join(\", \")}\">\n              ${esc(emoji)} ${uids.length}<\/span>`).join(\"\");\n}\n\nfunction renderAllReactions() {\n    for (const mid of state.reactions.keys()) renderReactions(mid);\n}\n\nfunction formatContent(text, author) {\n    let out = esc(text)\n        .replace(/\\*\\*(.+?)\\*\\*/g, \"<b>$1<\/b>\")\n        .replace(/`(.+?)`/g, \"<code>$1<\/code>\");\n    // @here / @everyone \u2014 rendered as ping only when sender is staff\n    if (author && isStaffRole(author.role)) {\n        out = out.replace(/@(here|everyone)/g, '<span class=\"mention ping\">@$1<\/span>');\n    }\n    // @username mentions -> clickable profile links\n    out = out.replace(/@([a-z0-9_]{3,20})/gi, (match, name) => {\n        const n = name.toLowerCase();\n        if (n === \"here\" || n === \"everyone\") return match;\n        const target = [...state.profiles.values()].find(p => p.username.toLowerCase() === n);\n        return target ? `<span class=\"mention\" onclick=\"openProfile('${target.id}')\">@${target.username}<\/span>` : match;\n    });\n    // #channel mentions -> clickable links that open the channel\n    out = out.replace(/(^|[\\s(])#([a-z0-9_-]+)/gi, (match, pre, name) => {\n        const target = state.channels.find(c => c.name.toLowerCase() === name.toLowerCase());\n        return target ? `${pre}<span class=\"mention\" onclick=\"openChannelById('${target.id}')\">#${esc(target.name)}<\/span>` : match;\n    });\n    // bare URLs -> clickable links\n    out = out.replace(/(^|[\\s(])((?:https?:\\/\\/)[^\\s<)]+)/gi,\n        (m, pre, url) => {\n            const raw = url.replace(/&(amp|lt|gt|quot|#39);/g, (_, e) => ({ amp: \"&\", lt: \"<\", gt: \">\", quot: '\"', \"#39\": \"'\" }[e]));\n            return `${pre}<a class=\"msg-link\" href=\"${esc(raw)}\" target=\"_blank\" rel=\"noopener noreferrer\">${esc(raw.length > 60 ? raw.slice(0, 57) + \"\u2026\" : raw)}<\/a>`;\n        });\n    return out;\n}\n\n// ---------- LINK EMBEDS (open graph) ----------\nstate.embeds = new Map();   // messageId -> {url, data|null, failed}\nconst EMBED_URL_RE = /(?:https?:\\/\\/)[^\\s<>\"]+/i;\n\nfunction extractEmbedUrl(m) {\n    if (!m.content) return null;\n    const match = m.content.match(EMBED_URL_RE);\n    if (!match) return null;\n    // ignore obvious media/image urls that already get special treatment\n    try {\n        const u = new URL(match[0]);\n        if (/\\.(png|jpe?g|gif|webp|svg|mp4|webm)$/i.test(u.pathname)) return null;\n        return u.href;\n    } catch { return null; }\n}\n\nfunction embedCardHTML(mid) {\n    const e = state.embeds.get(mid);\n    if (!e || !e.data) return \"\";\n    const d = e.data;\n    const img = d.image ? `<img class=\"embed-img\" src=\"${esc(d.image)}\" loading=\"lazy\" onerror=\"this.remove()\">` : \"\";\n    const favicon = d.logo\n        ? `<img class=\"embed-favicon\" src=\"${esc(d.logo)}\" onerror=\"this.style.display='none'\">`\n        : `<span class=\"embed-favicon\">\ud83c\udf10<\/span>`;\n    return `<a class=\"msg-embed\" href=\"${esc(safeHref(e.url))}\" target=\"_blank\" rel=\"noopener noreferrer\">\n        ${img ? `<div class=\"embed-img-wrap\">${img}<\/div>` : \"\"}\n        <div class=\"embed-body\">\n            <div class=\"embed-publisher\">${favicon}<span>${esc(d.publisher || hostOf(e.url))}<\/span><\/div>\n            ${d.title ? `<div class=\"embed-title\">${esc(d.title)}<\/div>` : \"\"}\n            ${d.description ? `<div class=\"embed-desc\">${esc(d.description.length > 200 ? d.description.slice(0, 197) + \"\u2026\" : d.description)}<\/div>` : \"\"}\n            <div class=\"embed-url\">${esc(hostOf(e.url))}<\/div>\n        <\/div>\n    <\/a>`;\n}\n\nfunction hostOf(url) { try { return new URL(url).hostname.replace(/^www\\./, \"\"); } catch { return url; } }\n\nfunction ensureEmbed(mid, url) {\n    if (!url || !state.embeds.has(mid)) return;\n    const e = state.embeds.get(mid);\n    if (e.loading || e.done) return;\n    e.loading = true;\n    fetch(`https://api.microlink.io/?url=${encodeURIComponent(url)}`)\n        .then(r => r.json())\n        .then(res => {\n            const d = res?.data;\n            e.data = d && (d.title || d.description) ? {\n                title: d.title,\n                description: d.description,\n                image: d.image?.url || null,\n                logo: d.logo?.url || null,\n                publisher: d.publisher || null,\n            } : null;\n        })\n        .catch(() => { e.data = null; })\n        .finally(() => {\n            e.done = true;\n            const slot = document.getElementById(`embed-${mid}`);\n            if (slot) slot.outerHTML = embedCardHTML(mid);\n        });\n}\n\n// ---------- EMOJI PICKER ----------\nfunction openEmojiPicker(ev, mid) {\n    closeEmojiPicker();\n    const pick = document.createElement(\"div\");\n    pick.className = \"emoji-picker\";\n    pick.id = \"emoji-picker\";\n    pick.innerHTML = EMOJI_PICKER.map(e => `<span onclick=\"toggleReaction('${mid}', ${esc(JSON.stringify(e))})\">${e}<\/span>`).join(\"\");\n    document.body.appendChild(pick);\n    const r = ev.target.getBoundingClientRect();\n    const pw = 320, ph = Math.min(280, window.innerHeight - 20);\n    pick.style.left = Math.min(Math.max(8, r.left - pw + 30), window.innerWidth - pw - 8) + \"px\";\n    pick.style.top = (r.bottom + ph > window.innerHeight ? r.top - ph - 6 : r.bottom + 6) + \"px\";\n    setTimeout(() => document.addEventListener(\"click\", pickerOutside), 0);\n}\nfunction pickerOutside(ev) {\n    if (!document.getElementById(\"emoji-picker\")?.contains(ev.target)) closeEmojiPicker();\n}\nfunction closeEmojiPicker() {\n    document.getElementById(\"emoji-picker\")?.remove();\n    document.removeEventListener(\"click\", pickerOutside);\n}\n\nasync function toggleReaction(mid, emoji) {\n    closeEmojiPicker();\n    const kind = viewKind();\n    const mine = (state.reactions.get(mid) || []).find(r => r.user_id === state.me.id && r.emoji === emoji);\n    if (mine) {\n        const { error } = await sb.from(\"reactions\").delete()\n            .eq(\"message_id\", mid).eq(\"user_id\", state.me.id).eq(\"emoji\", emoji);\n        if (error) return toast(error.message);\n        state.reactions.set(mid, state.reactions.get(mid).filter(r => r !== mine));\n    } else {\n        const { error } = await sb.from(\"reactions\")\n            .insert({ message_id: mid, kind, user_id: state.me.id, emoji });\n        if (error) return toast(error.message);\n        if (!state.reactions.has(mid)) state.reactions.set(mid, []);\n        state.reactions.get(mid).push({ emoji, user_id: state.me.id });\n    }\n    renderReactions(mid);\n}\n\n// ---------- EDIT / DELETE ----------\nlet editingMid = null;\n\nfunction startEdit(mid) {\n    if (editingMid) return;\n    editingMid = mid;\n    const contentEl = document.querySelector(`[data-mid=\"${mid}\"] .msg-content`);\n    if (!contentEl) { editingMid = null; return; }\n    const original = contentEl.textContent;\n    contentEl.classList.add(\"editing\");\n    contentEl.innerHTML = `\n        <textarea class=\"edit-box\" id=\"edit-box\">${esc(original)}<\/textarea>\n        <div class=\"edit-actions\">\n            <button onclick=\"saveEdit()\">save<\/button>\n            <button onclick=\"cancelEdit()\" style=\"opacity:.6\">cancel<\/button>\n            <span style=\"opacity:.4;align-self:center\">enter to save \u2022 escape to cancel<\/span>\n        <\/div>`;\n    const ta = document.getElementById(\"edit-box\");\n    ta.focus();\n    ta.setSelectionRange(ta.value.length, ta.value.length);\n    ta.onkeydown = (e) => {\n        if (e.key === \"Escape\") cancelEdit();\n        if (e.key === \"Enter\" && !e.shiftKey) { e.preventDefault(); saveEdit(); }\n    };\n}\n\nasync function cancelEdit() {\n    if (!editingMid) return;\n    editingMid = null;\n    await loadMessages(); // re-render from db\n}\n\nasync function saveEdit() {\n    const text = document.getElementById(\"edit-box\")?.value.trim();\n    const mid = editingMid;\n    if (!mid || !text) return cancelEdit();\n    editingMid = null;\n    const table = viewKind() === \"dm\" ? \"dm_messages\" : \"messages\";\n    const { data, error } = await sb.from(table)\n        .update({ content: text, edited_at: new Date().toISOString() })\n        .eq(\"id\", mid).select().single();\n    if (error) return toast(error.message);\n    document.querySelector(`[data-mid=\"${mid}\"]`).outerHTML = renderMsg(data);\n    renderReactions(mid);\n    regroup();\n}\n\nasync function deleteMsg(mid) {\n    if (!confirm(\"delete this message?\")) return;\n    const table = viewKind() === \"dm\" ? \"dm_messages\" : \"messages\";\n    const { error } = await sb.from(table).delete().eq(\"id\", mid);\n    if (error) return toast(error.message.replace(/^./, c => c.toLowerCase()));\n    document.querySelector(`[data-mid=\"${mid}\"]`)?.remove();\n    state.reactions.delete(mid);\n    regroup();\n}\n\n// ---------- MODERATION ----------\nfunction isStaff() { return isMod(); }\n\nasync function modMute(userId, minutes) {\n    const { error } = await sb.rpc(\"mod_mute\", { p_user: userId, p_minutes: minutes });\n    if (error) return toast(error.message.replace(/^./, c => c.toLowerCase()));\n    toast(`muted for ${minutes} min`);\n    closeModal(\"profile-modal-bg\");\n}\n\nasync function modUnmute(userId) {\n    const { error } = await sb.rpc(\"mod_unmute\", { p_user: userId });\n    if (error) return toast(error.message.replace(/^./, c => c.toLowerCase()));\n    toast(\"unmuted\");\n}\n\nasync function loadMessages() {\n    try {\n        const box = $(\"messages\");\n        if (!box) return;\n        box.innerHTML = \"\";\n        // NOTE: don't removeChannel here! msgSubChannel is a global subscription\n        // (\"chatroom-all\") started once in startRealtime(); tearing it down on\n        // every channel switch killed live updates for the rest of the session.\n\n        let rows = [];\n        if (state.view.type === \"channel\") {\n            // channels are capped server-side at 35 messages (see schema.sql's\n            // trim_channel_messages trigger), so there's never more than that to fetch\n            ({ data: rows } = await sb.from(\"messages\").select(\"*\")\n                .eq(\"channel_id\", state.view.channel.id).order(\"created_at\").limit(35));\n        } else {\n            ({ data: rows } = await sb.from(\"dm_messages\").select(\"*\")\n                .eq(\"dm_id\", state.view.dmId).order(\"created_at\").limit(200));\n        }\n        box.innerHTML = (rows || []).map(m => renderMsg(m)).join(\"\");\n        regroup();\n        box.scrollTop = box.scrollHeight;\n        state.msgCache = new Map();\n        for (const m of rows || []) state.msgCache.set(m.id, m);\n        await hydrateReplies(rows || []);\n        document.querySelectorAll(\".msg-quote.pending\").forEach(el => renderQuoteInto(el.dataset.quote, el));\n        state.reactions = new Map();\n        await loadReactions();\n        // pollMessages() only needs to look for rows newer than whatever we just\n        // rendered \u2014 otherwise every poll tick would re-fetch the whole history.\n        lastPollAt = (rows && rows.length) ? rows[rows.length - 1].created_at : new Date().toISOString();\n    } catch (error) {\n        console.error(\"Failed to load messages:\", error);\n        toast(\"Failed to load messages: \" + error.message);\n    }\n}\n\n// ---------- MESSAGE POLLING (fallback for when realtime doesn't deliver) ----------\n// postgres_changes over the realtime websocket is what's *supposed* to push\n// new messages in instantly, but on some projects/networks that socket never\n// actually delivers (commonly: Realtime not switched on for the table in the\n// Supabase dashboard, or a proxy that kills long-lived websockets) and\n// messages only appear after a manual page refresh. This is a belt-and-braces\n// poll: it asks for anything newer than the last row we've already rendered\n// and feeds it through the exact same appendMessage() path realtime uses, so\n// it's a no-op (deduped by data-mid) if realtime is in fact delivering fine.\nlet polling = false;\nasync function pollMessages() {\n    if (polling) return;\n    polling = true;\n    try { await pollOnce(); } finally { polling = false; }\n}\nasync function pollOnce() {\n    const view = state.view;\n    if (!view || (view.type !== \"channel\" && view.type !== \"dm\")) return;\n    const since = lastPollAt || new Date(0).toISOString();\n    let rows = [];\n    try {\n        if (state.view.type === \"channel\") {\n            ({ data: rows } = await sb.from(\"messages\").select(\"*\")\n                .eq(\"channel_id\", state.view.channel.id).gt(\"created_at\", since).order(\"created_at\"));\n        } else {\n            ({ data: rows } = await sb.from(\"dm_messages\").select(\"*\")\n                .eq(\"dm_id\", state.view.dmId).gt(\"created_at\", since).order(\"created_at\"));\n        }\n    } catch {\n        return; // network hiccup \u2014 just try again next tick\n    }\n    if (state.view !== view) return;\n    for (const m of rows || []) {\n        lastPollAt = m.created_at;\n        appendMessage(m);\n    }\n\n    // channels are capped server-side at 35 messages (oldest gets trimmed on\n    // insert) \u2014 reconcile any rows that vanished the same way we reconcile\n    // new ones, since a DELETE needs the same \"realtime might not deliver\"\n    // safety net an INSERT does. cheap id-only fetch, channels only (no cap\n    // on DMs).\n    if (state.view.type === \"channel\") {\n        try {\n            const { data: idRows } = await sb.from(\"messages\").select(\"id\")\n                .eq(\"channel_id\", state.view.channel.id).order(\"created_at\", { ascending: false }).limit(35);\n            if (state.view !== view || !idRows) return;\n            const liveIds = new Set(idRows.map(r => r.id));\n            document.querySelectorAll(\"#messages [data-mid]\").forEach(el => {\n                if (!el.dataset.local && !liveIds.has(el.dataset.mid)) {\n                    el.remove();\n                    state.msgCache.delete(el.dataset.mid);\n                    state.reactions.delete(el.dataset.mid);\n                }\n            });\n            regroup();\n        } catch {\n            // ignore \u2014 next tick will retry\n        }\n    }\n}\n\nfunction renderQuoteInto(mid, el) {\n    const q = state.msgCache.get(mid);\n    if (!q) { el.remove(); return; }\n    const qa = q.author_id ? (state.profiles.get(q.author_id) || BOT_PROFILE) : BOT_PROFILE;\n    el.classList.remove(\"pending\");\n    el.onclick = () => jumpToMsg(mid);\n    el.innerHTML = `<span class=\"quote-author\">${esc(qa.username)}<\/span><span class=\"quote-text\">${esc(quotedPreview(q))}<\/span>`;\n}\n\nasync function loadReactions() {\n    try {\n        const mids = [...document.querySelectorAll(\".msg\")].map(el => el.dataset.mid);\n        if (!mids.length) return;\n        for (let i = 0; i < mids.length; i += 50) {\n            const { data } = await sb.from(\"reactions\").select(\"*\")\n                .eq(\"kind\", viewKind()).in(\"message_id\", mids.slice(i, i + 50));\n            for (const r of data || []) {\n                if (!state.reactions.has(r.message_id)) state.reactions.set(r.message_id, []);\n                state.reactions.get(r.message_id).push({ emoji: r.emoji, user_id: r.user_id });\n            }\n        }\n        renderAllReactions();\n    } catch (error) {\n        console.error(\"Failed to load reactions:\", error);\n    }\n}\n\n// ---------- NOTIFICATIONS ----------\nfunction notifyIncoming(m) {\n    if (!state.me || m.author_id === state.me.id || state.me.presence === \"dnd\") return;\n\n    const author = state.profiles.get(m.author_id);\n    const name = author?.username || \"someone\";\n    const isDm = !!m.dm_id;\n\n    if (isDm) {\n        const known = state.dms.find(d => d.dmId === m.dm_id);\n        const viewingThis = state.view?.type === \"dm\" && state.view.dmId === m.dm_id;\n\n        if (!viewingThis) {\n            state.unreadDms.set(m.dm_id, (state.unreadDms.get(m.dm_id) || 0) + 1);\n        }\n\n        if (!known) {\n            loadProfiles().then(loadDMs).then(renderSidebar);\n        } else {\n            renderSidebar();\n        }\n\n        toast(`\ud83d\udcac ${name}: ${String(m.content || \"\ud83d\udcce image\").slice(0, 60)}`);\n        return;\n    }\n\n    const mentioned = typeof m.content === \"string\" &&\n        new RegExp(`@${state.me.username}\\\\b`, \"i\").test(m.content);\n\n    const staffPing = mentioned || (\n        author && isStaffRole(author.role) &&\n        /@(here|everyone)\\b/i.test(m.content)\n    );\n\n    if (staffPing) {\n        state.pingCount++;\n        renderPingBadge();\n        toast(`\ud83d\udd14 ${name} pinged you!`);\n    }\n}\n\nfunction renderPingBadge() {\n    const b = $(\"ping-badge\");\n    if (!b) return;\n    b.textContent = state.pingCount > 99 ? \"99+\" : String(state.pingCount);\n    b.style.display = state.pingCount > 0 ? \"flex\" : \"none\";\n    document.title = state.pingCount > 0 ? `(${state.pingCount}) mochii` : \"mochii\";\n}\nfunction clearPings() {\n    state.pingCount = 0;\n    renderPingBadge();\n}\nfunction clearDmUnread(dmId) {\n    if (state.unreadDms.delete(dmId)) renderSidebar();\n}\n\nfunction appendMessage(m) {\n    // dedupe: realtime may deliver a message we already appended optimistically\n    if (document.querySelector(`[data-mid=\"${m.id}\"]`)) return;\n    const active =\n        (state.view?.type === \"channel\" && m.channel_id === state.view.channel.id) ||\n        (state.view?.type === \"dm\" && m.dm_id === state.view.dmId);\n    refreshBalance();\n    notifyIncoming(m);\n    if (!active) return;\n    state.msgCache.set(m.id, m); // cache so replies to it can render\n    const box = $(\"messages\");\n    const nearBottom = box.scrollHeight - box.scrollTop - box.clientHeight < 160;\n    box.insertAdjacentHTML(\"beforeend\", renderMsg(m));\n    regroup();\n    if (nearBottom) box.scrollTop = box.scrollHeight;\n}\n\nfunction updateMessageInPlace(m) {\n    const el = document.querySelector(`[data-mid=\"${m.id}\"]`);\n    if (!el) return; // not currently rendered (different view, or scrolled out of the 35-cap) \u2014 nothing to do\n    state.msgCache.set(m.id, m);\n    el.outerHTML = renderMsg(m);\n    renderReactions(m.id);\n    regroup();\n}\n\nasync function refreshBalance() {\n    try {\n        const { data } = await sb.from(\"profiles\").select(\"balance\").eq(\"id\", state.me.id).single();\n        if (data && data.balance !== state.me.balance) {\n            state.me.balance = data.balance;\n            const meMochis = $(\"me-mochis\");\n            if (meMochis) meMochis.textContent = `\ud83c\udf61 ${state.me.balance} mochis \u00b7 lvl ${xpInfo(state.me.xp).level}`;\n        }\n    } catch (error) {\n        console.error(\"Failed to refresh balance:\", error);\n    }\n}\n\n// ---------- SENDING ----------\nasync function sendCurrent() {\n    try {\n        const input = $(\"message-input\");\n        const text = input.value.trim();\n        if (!text || !state.view) return;\n        if (text.startsWith(\"/\")) { const bad = validateCommand(text); if (bad) { toast(bad); selectPlaceholder(input); return; } }\n        input.value = \"\";\n        closeCmdMenu();\n\n        if (/^\\/role(\\s|$)/i.test(text)) { await roleCommand(text); return; }\n        if (text.startsWith(\"/\")) { await handleCommand(text); return; }\n\n        let finalText = text;\n        if (!isMod()) finalText = finalText.replace(/@(here|everyone)\\b/gi, \"@user\");\n\n        if (state.view.type === \"channel\") {\n            const { data, error } = await sb.from(\"messages\").insert({\n                channel_id: state.view.channel.id, author_id: state.me.id, content: finalText,\n                reply_to: state.replyTo\n            }).select().single();\n            if (error) toast(error.message.includes(\"row-level\") ? \"\ud83d\udd12 you can't post here.\" : error.message);\n            else appendMessage(data); // show instantly\n        } else {\n            const { data, error } = await sb.from(\"dm_messages\").insert({\n                dm_id: state.view.dmId, author_id: state.me.id, content: finalText,\n                reply_to: state.replyTo\n            }).select().single();\n            if (error) toast(error.message.includes(\"row-level\") ? \"you can't message this user.\" : error.message);\n            else appendMessage(data);\n        }\n        cancelReply();\n    } catch (error) {\n        console.error(\"Failed to send message:\", error);\n        toast(\"Failed to send message: \" + error.message);\n    }\n}\n\nasync function sendImage(fileInput) {\n    try {\n        const file = fileInput.files[0];\n        fileInput.value = \"\";\n        if (!file || !state.view) return;\n        if (file.size > 5 * 1024 * 1024) return toast(\"image too big (max 5mb).\");\n        if (!canPostHere()) return toast(\"\ud83d\udd12 you can't post here.\");\n\n        toast(\"uploading image\u2026\");\n        const upload = await compressImage(file, 1600, 0.78);\n        const path = `${state.me.id}/${Date.now()}_${file.name.replace(/[^\\w.\\-]/g, \"_\")}`;\n        const { error: upErr } = await sb.storage.from(\"chat-images\").upload(path, upload, { cacheControl: \"31536000\" }); // path is timestamped/immutable, so cache it for a year \u2014 this is what actually cuts cached egress, since browsers stop re-fetching what they already have\n        if (upErr) return toast(\"upload failed: \" + upErr.message);\n        const { data: { publicUrl } } = sb.storage.from(\"chat-images\").getPublicUrl(path);\n\n        if (state.view.type === \"channel\") {\n            const { data, error } = await sb.from(\"messages\").insert({\n                channel_id: state.view.channel.id, author_id: state.me.id, image_url: publicUrl,\n                reply_to: state.replyTo\n            }).select().single();\n            if (error) toast(error.message.includes(\"row-level\") ? \"\ud83d\udd12 you can't post here.\" : error.message);\n            else appendMessage(data);\n        } else {\n            const { data, error } = await sb.from(\"dm_messages\").insert({\n                dm_id: state.view.dmId, author_id: state.me.id, image_url: publicUrl,\n                reply_to: state.replyTo\n            }).select().single();\n            if (error) toast(error.message.includes(\"row-level\") ? \"\ud83d\udd12 you can't post here.\" : error.message);\n            else appendMessage(data);\n        }\n        cancelReply();\n    } catch (error) {\n        console.error(\"Failed to send image:\", error);\n        toast(\"Failed to send image: \" + error.message);\n    }\n}\n\n// ---------- MOCHII BOT COMMANDS ----------\nasync function handleCommand(raw) {\n    try {\n        const [cmd0, ...args] = raw.slice(1).split(/\\s+/);\n        const cmd = COMMAND_ALIASES[cmd0.toLowerCase()] || cmd0.toLowerCase();\n        if (cmd !== cmd0) raw = \"/\" + [cmd, ...args].join(\" \").trim(); // show the full command in chat\n\n        // unknown commands: don't send, just say so\n        if (!KNOWN_CMDS.includes(cmd)) return toast(`unknown command /${cmd0}! type / to see the list`, { ms: 4000 });\n\n        // gambling commands only work in gambling channels: don't send, offer a jump to the casino\n        if (GAMBLING_CMDS.includes(cmd) && (state.view?.type !== \"channel\" || state.view.channel.category !== \"gambling\")) {\n            const casino = state.channels.find(c => c.category === \"gambling\" && c.name === \"casino\") || state.channels.find(c => c.category === \"gambling\");\n            return toast(\"you need to be in a gambling channel to use that!\", { ms: 8000, action: casino && { label: \"go to #\" + casino.name, fn: async () => {\n                await openChannel(casino);\n                const i = $(\"message-input\"); if (i) { i.value = raw; i.focus(); }\n            } } });\n        }\n        if (state.view?.type !== \"channel\") { toast(\"Bot commands work in channels (try #casino).\"); return; }\n        const chId = state.view.channel.id;\n        const amountArg = args.find(a => /^\\d+$/.test(a));\n        const amount = amountArg ? parseInt(amountArg, 10) : null;\n        const payTarget = args.find(a => a.startsWith(\"@\"))?.slice(1);\n        const styleArg = args.find(a => !a.startsWith(\"@\") && !/^\\d+$/.test(a));\n\n        // post the command itself into the chat\u2026\n        const { data: sent, error: sendErr } = await sb.from(\"messages\").insert({\n            channel_id: chId, author_id: state.me.id, content: raw\n        }).select().single();\n        if (sendErr) return toast(sendErr.message.includes(\"row-level\") ? \"\ud83d\udd12 you can't post here.\" : sendErr.message);\n        appendMessage(sent); // realtime will dedupe\n\n        // \u2026and let mochiiBot reply to it\n        const botProfile = [...state.profiles.values()].find(p => p.username.toLowerCase() === \"mochiibot\");\n        const botSay = (content) => appendMessage({\n            id: crypto.randomUUID(), channel_id: chId, created_at: new Date().toISOString(),\n            author_id: botProfile?.id ?? null, reply_to: sent.id, content, local: true\n        });\n\n        const rpcMap = {\n            daily: () => sb.rpc(\"cmd_daily\", { p_channel: chId }),\n            beg: () => sb.rpc(\"cmd_beg\", { p_channel: chId }),\n            work: () => sb.rpc(\"cmd_work\", { p_channel: chId }),\n            fish: () => sb.rpc(\"cmd_fish\", { p_channel: chId }),\n            crime: () => sb.rpc(\"cmd_crime\", { p_channel: chId }),\n            quest: () => sb.rpc(\"cmd_quest\", { p_channel: chId }),\n            coinflip: () => sb.rpc(\"cmd_coinflip\", { p_channel: chId, p_amount: amount || 10 }),\n            gamble: () => sb.rpc(\"cmd_gamble\", { p_channel: chId, p_amount: amount || 0 }),\n            pay: () => sb.rpc(\"cmd_pay\", { p_channel: chId, p_to: payTarget, p_amount: amount || 0 }),\n            rich: () => sb.rpc(\"cmd_rich\", { p_channel: chId }),\n            blackjack: () => sb.rpc(\"cmd_blackjack\", { p_channel: chId, p_amount: amount || 10 }),\n            hug: () => sb.rpc(\"cmd_hug\", { p_channel: chId, p_to: payTarget }),\n            steal: () => sb.rpc(\"cmd_steal\", { p_channel: chId, p_to: payTarget }),\n            battle: () => sb.rpc(\"cmd_battle\", { p_channel: chId, p_to: payTarget, p_amount: amount || 0, p_style: styleArg || \"clash\" }),\n            balance: () => botSay(`\ud83c\udf61 **${state.me.username}** has **${state.me.balance} mochis**.`),\n        };\n\n        const fn = rpcMap[cmd];\n        if (!fn) {\n            botSay(\"unknown command! try `/daily` `/beg` `/work` `/fish` `/crime` `/quest` `/coinflip <amt>` `/gamble <amt>` `/blackjack <amt>` `/battle @user <amt> [style]` `/pay @user <amt>` `/steal @user` `/hug @user` `/rich` `/balance`\");\n            return;\n        }\n        // run the command and surface any server-side error\n        const { error } = await fn();\n        if (error) {\n            console.error(\"[mochiiBot] command failed:\", cmd, error);\n            toast(error.message.includes(\"Could not find the function\")\n                ? \"\u26a0\ufe0f bot is missing its server functions \u2014 ask an admin to re-run supabase/schema.sql.\"\n                : `\u26a0\ufe0f /${cmd} failed: ${error.message}`);\n        } else {\n            refreshBalance();\n        }\n    } catch (error) {\n        console.error(\"Failed to handle command:\", error);\n        toast(\"Failed to handle command: \" + error.message);\n    }\n}\n\n// ---------- BLACKJACK BUTTONS ----------\nasync function bjMove(move, gameId) {\n    try {\n        const rpcName = { hit: \"cmd_bj_hit\", stand: \"cmd_bj_stand\" }[move];\n        const { error } = await sb.rpc(rpcName, { p_game: gameId });\n        if (error) return toast(`\u26a0\ufe0f ${error.message}`);\n        // the server edits the same message in place, but disable immediately\n        // for instant feedback while that update is in flight\n        document.querySelectorAll(`[data-game=\"${gameId}\"]`).forEach(box => {\n            box.querySelectorAll(\"button\").forEach(b => { b.disabled = true; b.style.opacity = \".4\"; });\n        });\n        refreshBalance();\n    } catch (error) {\n        console.error(\"Blackjack move failed:\", error);\n        toast(`\u26a0\ufe0f Blackjack move failed: ${error.message}`);\n    }\n}\n\n// ---------- QUEST BUTTONS ----------\nasync function questMove(move, questId) {\n    try {\n        const rpcName = { attack: \"cmd_quest_attack\", flee: \"cmd_quest_flee\" }[move];\n        const { error } = await sb.rpc(rpcName, { p_quest: questId });\n        if (error) return toast(`\u26a0\ufe0f ${error.message}`);\n        document.querySelectorAll(`[data-game=\"${questId}\"]`).forEach(box => {\n            box.querySelectorAll(\"button\").forEach(b => { b.disabled = true; b.style.opacity = \".4\"; });\n        });\n        refreshBalance();\n    } catch (error) {\n        console.error(\"Quest move failed:\", error);\n        toast(`\u26a0\ufe0f Quest move failed: ${error.message}`);\n    }\n}\n\n// ---------- BATTLE BUTTONS ----------\nasync function battleMove(move, gameId) {\n    try {\n        const rpcName = { accept: \"cmd_battle_accept\", decline: \"cmd_battle_decline\", ready: \"cmd_battle_ready\" }[move];\n        const { error } = await sb.rpc(rpcName, { p_game: gameId });\n        if (error) return toast(`\u26a0\ufe0f ${error.message}`);\n        document.querySelectorAll(`[data-game=\"${gameId}\"]`).forEach(box => {\n            box.querySelectorAll(\"button\").forEach(b => { b.disabled = true; b.style.opacity = \".4\"; });\n        });\n        refreshBalance();\n    } catch (error) {\n        console.error(\"Battle move failed:\", error);\n        toast(`\u26a0\ufe0f Battle move failed: ${error.message}`);\n    }\n}\n\nasync function battlePull(gameId) {\n    try {\n        const { error } = await sb.rpc(\"cmd_battle_pull\", { p_game: gameId });\n        if (error) return toast(`\u26a0\ufe0f ${error.message}`);\n        refreshBalance();\n        // no disable here \u2014 tug of war is meant to be mashed by both sides\n        // until someone wins, unlike the one-shot game types above\n    } catch (error) {\n        console.error(\"Pull failed:\", error);\n        toast(`\u26a0\ufe0f Pull failed: ${error.message}`);\n    }\n}\n\n// ---------- MEMBERS LIST ----------\nfunction renderMembers() {\n    const box = $(\"members\");\n    const users = [...state.profiles.values()].filter(p => p.username.toLowerCase() !== \"mochiibot\");\n    const isOn = (p) => (p.presence || \"online\") !== \"offline\" &&\n        Date.now() - new Date(p.last_seen).getTime() < ONLINE_WINDOW_MS;\n    const dotClass = (p) => (p.presence === \"dnd\" && isOn(p)) ? \"dnd\" : (isOn(p) ? \"on\" : \"off\");\n\n    // staff roles first, in order; custom roles get their own group but only\n    // while online \u2014 offline custom-role users fall into the offline group;\n    // plain members are grouped by online status\n    const STAFF_ORDER = STAFF_ROLES;\n    const customRoles = [...new Set(\n        users.map(p => p.role).filter(r => r !== \"member\" && !STAFF_ORDER.includes(r))\n    )];\n    const groups = [];\n    for (const r of STAFF_ORDER) groups.push([r, users.filter(p => p.role === r)]);\n    for (const r of customRoles) groups.push([r, users.filter(p => p.role === r && isOn(p))]);\n    groups.push([\"online\", users.filter(p => p.role === \"member\" && isOn(p))]);\n    groups.push([\"offline\", users.filter(p => !isStaffRole(p.role) && !isOn(p))]);\n\n    let html = \"\";\n    for (const [g, list] of groups) {\n        if (!list.length) continue;\n        html += `<div class=\"member-group\">${esc(g)} - ${list.length}<\/div>`;\n        for (const p of list) {\n            const a = parseAvatar(p.avatar), act = activityOf(p);\n            html += `<div class=\"member\" onclick=\"openProfile('${p.id}')\">\n                <div class=\"avatar-sm\" style=\"background:${a.color || \"#7c5cff\"}\">${avatarInner(a)}<span class=\"presence ${dotClass(p)}\"><\/span><\/div>\n                <div style=\"min-width:0;overflow:hidden\">\n                    <div class=\"m-name\">${esc(p.username)}<\/div>\n                    ${act ? `<div class=\"m-activity\">${act.kind === \"music\" ? \"listening to\" : \"playing\"} <b>${esc(act.name)}<\/b><\/div>`\n                        : p.status_text ? `<div style=\"font-size:11px;opacity:.5;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;\">${esc(p.status_text)}<\/div>` : \"\"}\n                <\/div>\n            <\/div>`;\n        }\n    }\n    box.innerHTML = html;\n}\n\n// ---------- TYPING INDICATOR ----------\nlet typingLastSent = 0;\nfunction typingPing() {\n    if (!state.view || state.view.type !== \"channel\" || !msgSubChannel) return;\n    const now = Date.now();\n    if (now - typingLastSent < 1500) return;\n    typingLastSent = now;\n    msgSubChannel.send({ type: \"broadcast\", event: \"typing\", payload: { u: state.me.id } });\n}\n\nlet typingTicker = null;\nfunction startTypingTicker() {\n    if (!typingTicker) {\n        typingTicker = setInterval(() => {\n            if (!state.typing.size) return;\n            let dirty = false;\n            for (const [uid, exp] of state.typing)\n                if (Date.now() > exp) { state.typing.delete(uid); dirty = true; }\n            if (dirty) renderTyping();\n        }, 700);\n    }\n}\n\nfunction renderTyping() {\n    const bar = $(\"typing-bar\");\n    if (!bar) return;\n    const users = [...state.typing.keys()]\n        .map(uid => state.profiles.get(uid))\n        .filter(Boolean).slice(0, 4);\n    if (!users.length) {\n        bar.classList.remove(\"show\");\n        bar.innerHTML = \"\";\n        return;\n    }\n    const names = users.map(p => `<span class=\"typing-name\" onclick=\"openProfile('${p.id}')\">${esc(p.username)}<\/span>`);\n    const avatars = users.map(p => {\n        const a = parseAvatar(p.avatar);\n        return `<div class=\"avatar-xs\" style=\"background:${a.color || \"#7c5cff\"}\">${avatarInner(a)}<\/div>`;\n    }).join(\"\");\n    // Fix for older browsers that don't support Array.prototype.at\n    const lastName = names.length > 0 ? names[names.length - 1] : \"\";\n    const text = names.length === 1 ? `${names[0]} is typing` : `${names.slice(0, -1).join(\", \")} and ${lastName} are typing`;\n    bar.innerHTML = `<div class=\"typing-avatars\">${avatars}<\/div><span class=\"typing-text\">${text}<span class=\"dots\"><i>.<\/i><i>.<\/i><i>.<\/i><\/span><\/span>`;\n    bar.classList.add(\"show\");\n}\n\n// ---------- REALTIME ----------\nfunction startRealtime() {\n    msgSubChannel = sb.channel(\"chatroom-all\")\n        .on(\"postgres_changes\", { event: \"INSERT\", schema: \"public\", table: \"messages\" },\n            (payload) => appendMessage(payload.new))\n        .on(\"postgres_changes\", { event: \"INSERT\", schema: \"public\", table: \"dm_messages\" },\n            (payload) => appendMessage(payload.new))\n        .on(\"postgres_changes\", { event: \"UPDATE\", schema: \"public\", table: \"messages\" },\n            // covers both user message edits and game messages (blackjack/\n            // quest/battle) being edited in place by the server as the game\n            // progresses \u2014 previously only the editor's own client patched\n            // the dom, so nobody else ever saw a game update after the first\n            (payload) => updateMessageInPlace(payload.new))\n        .on(\"postgres_changes\", { event: \"UPDATE\", schema: \"public\", table: \"dm_messages\" },\n            (payload) => updateMessageInPlace(payload.new))\n        .on(\"postgres_changes\", { event: \"DELETE\", schema: \"public\", table: \"messages\" },\n            // covers messages trimmed by the 35-per-channel cap (see schema.sql's\n            // trim_channel_messages trigger) as well as manual deletes from other\n            // clients/tabs; pollMessages() reconciles the same thing if this\n            // socket event doesn't arrive\n            (payload) => {\n                const mid = payload.old?.id;\n                if (!mid) return;\n                document.querySelector(`[data-mid=\"${mid}\"]`)?.remove();\n                state.msgCache.delete(mid);\n                state.reactions.delete(mid);\n                regroup();\n            })\n        .on(\"postgres_changes\", { event: \"*\", schema: \"public\", table: \"profiles\" },\n            () => { loadProfiles().then(renderMembers); refreshBalance(); })\n        .on(\"postgres_changes\", { event: \"*\", schema: \"public\", table: \"reactions\" },\n            (payload) => {\n                const row = payload.new?.message_id ? payload.new : (payload.old || {});\n                const mid = row.message_id;\n                if (!mid) return;\n                let list = state.reactions.get(mid) || [];\n                if (payload.eventType === \"INSERT\") {\n                    if (!list.some(x => x.user_id === row.user_id && x.emoji === row.emoji)) {\n                        state.reactions.set(mid, [...list, { emoji: row.emoji, user_id: row.user_id }]);\n                    }\n                } else {\n                    state.reactions.set(mid, list.filter(x => !(x.user_id === (row.user_id || \"\") && x.emoji === row.emoji)));\n                }\n                renderReactions(mid);\n            })\n        .on(\"postgres_changes\", { event: \"INSERT\", schema: \"public\", table: \"friendships\" },\n            async (payload) => {\n                const f = payload.new;\n                if (f.addressee !== state.me.id) return;\n                state.friendRequests.add(f.requester);\n                await loadProfiles();\n                renderSidebar();\n                const who = state.profiles.get(f.requester)?.username || \"someone\";\n                toast(`\ud83d\udc4b ${who} sent you a friend request! open their profile to accept.`);\n            })\n        .on(\"broadcast\", { event: \"typing\" }, ({ payload }) => {\n            if (!payload?.u || payload.u === state.me.id) return;\n            state.typing.set(payload.u, Date.now() + 4000);\n            renderTyping();\n        })\n        .subscribe();\n    startTypingTicker();\n}\n\n// ---------- PROFILE MODAL ----------\nasync function openProfile(userId) {\n    try {\n        if (!userId) return;\n        const { data: p } = await sb.from(\"profiles\").select(\"*\").eq(\"id\", userId).single();\n        if (!p) return;\n        state.profiles.set(p.id, p);\n        const isBot = p.username.toLowerCase() === \"mochiibot\";\n\n        // friend / block state (the bot is neither friend-able nor block-able)\n        let fs = \"none\";\n        if (!isBot && p.id !== state.me.id) {\n            const { data: fr } = await sb.from(\"friendships\").select(\"*\")\n                .or(`requester.eq.${state.me.id},addressee.eq.${state.me.id}`)\n                .or(`requester.eq.${p.id},addressee.eq.${p.id}`);\n            for (const f of fr || []) {\n                if ((f.requester === p.id && f.addressee === state.me.id)) fs = f.status === \"accepted\" ? \"friends\" : \"pending_in\";\n                else if ((f.requester === state.me.id && f.addressee === p.id)) fs = f.status === \"accepted\" ? \"friends\" : \"pending_out\";\n            }\n            const { data: bl } = await sb.from(\"blocks\").select(\"*\")\n                .eq(\"blocker\", state.me.id).eq(\"blocked\", p.id).maybeSingle();\n            if (bl) fs = \"blocked\";\n        }\n        state.friendState[p.id] = fs;\n\n        const a = parseAvatar(p.avatar);\n        const me = p.id === state.me.id;\n        const iStaff = isMod();\n        const theyStaff = isStaffRole(p.role);\n        let actions = \"\";\n        if (isBot) {\n            actions = `<div class=\"locked-note\">\ud83e\udd16 mochiiBot runs on commands \u2014 try <b>/daily<\/b> or <b>/work<\/b> in a channel.<\/div>`;\n        } else if (me) {\n            actions = `<button class=\"action-btn accent\" onclick=\"closeModal('profile-modal-bg');openSettings()\">edit my profile<\/button>`;\n        } else {\n            const btn = {\n                none: `<button class=\"action-btn accent\" onclick=\"addFriend('${p.id}')\">add friend<\/button>`,\n                pending_out: `<button class=\"action-btn\" disabled>request sent<\/button>`,\n                pending_in: `<button class=\"action-btn accent\" onclick=\"acceptFriend('${p.id}')\">accept friend request<\/button>`,\n                friends: `<button class=\"action-btn\" disabled>friends<\/button>\n                      <button class=\"action-btn danger\" onclick=\"removeFriend('${p.id}')\">remove friend<\/button>`,\n                blocked: `<button class=\"action-btn\" onclick=\"unblock('${p.id}')\">unblock<\/button>`,\n            }[fs];\n            actions = `\n                ${btn}\n                <button class=\"action-btn accent\" onclick=\"dmFromProfile('${p.id}')\">send message<\/button>\n                ${fs === \"blocked\" ? \"\" : `<button class=\"action-btn danger\" onclick=\"blockUser('${p.id}')\">block<\/button>`}\n                ${iStaff && !theyStaff ? `<div class=\"mod-row\">\n                    <span class=\"mod-label\">muted?<\/span>\n                    <button class=\"action-btn danger\" onclick=\"modMute('${p.id}',10)\">10 min<\/button>\n                    <button class=\"action-btn danger\" onclick=\"modMute('${p.id}',60)\">1 hour<\/button>\n                    <button class=\"action-btn\" onclick=\"modUnmute('${p.id}')\">unmute<\/button>\n                <\/div>` : \"\"}\n                ${roleRank(p.role) < roleRank(state.me.role) ? rolePickerHTML(p) : \"\"}`;\n        }\n\n        const showBanner = bannerHTML(p);\n        $(\"profile-modal\").innerHTML = `\n            ${showBanner ? `<div class=\"profile-banner\">${showBanner}<\/div>` : \"\"}\n            <div class=\"profile-hero\">\n                <div class=\"avatar-lg\" style=\"background:${a.color || \"#7c5cff\"}\">${avatarInner(a)}<\/div>\n                <div>\n                    <div class=\"profile-name\">${esc(p.username)}<\/div>\n                    ${roleBadge(p.role, isBot)}\n                    ${p.status_text && !isBot ? `<div style=\"font-size:13px;opacity:.75;font-style:italic;margin-top:4px;\">\ud83d\udcac ${esc(p.status_text)}<\/div>` : \"\"}\n                <\/div>\n            <\/div>\n            ${isBot ? \"\" : activityCardHTML(p)}\n            <div id=\"profile-playlists\"><\/div>\n            ${p.bio && !isBot ? `<div class=\"profile-bio\">${esc(p.bio)}<\/div>` : \"\"}\n            ${isBot ? \"\" : `<div class=\"profile-stats\">\n                <div class=\"stat-chip\">\ud83c\udf61 <b>${p.balance}<\/b> mochis<\/div>\n                <div class=\"stat-chip\">\ud83d\udd25 <b>${p.streak}<\/b> day streak<\/div>\n                <div class=\"stat-chip\">\u2b50 lvl <b>${xpInfo(p.xp).level}<\/b> <span style=\"opacity:.6\">(${p.xp} xp)<\/span><\/div>\n            <\/div>`}\n            <div class=\"modal-actions\">${actions}<\/div>`;\n        $(\"profile-modal-bg\").classList.add(\"open\");\n        if (!isBot && EFFECT_EMOJI[p.effect]) spawnEffect(EFFECT_EMOJI[p.effect]);\n        if (!isBot) loadProfilePlaylists(p.id);\n    } catch (error) {\n        console.error(\"Failed to open profile:\", error);\n        toast(\"Failed to load profile: \" + error.message);\n    }\n}\n\n// inside mochii the chat is a nested same origin frame, so it can hand the playlist straight to the music page\nfunction openMochiiPlaylist(id) {\n    try { if (window.top !== window && typeof window.top.openMusicRoute === \"function\") { closeModal(\"profile-modal-bg\"); window.top.openMusicRoute(\"pl/\" + id); return false; } } catch {}\n    return true;\n}\n// public playlists from mochii music. each one opens the shared playlist link on mochii\nasync function loadProfilePlaylists(userId) {\n    const { data } = await sb.from(\"playlists\").select(\"id,name,tracks\").eq(\"owner\", userId).eq(\"visibility\", \"public\").order(\"updated_at\", { ascending: false }).limit(6);\n    const box = $(\"profile-playlists\");\n    if (!box || !data || !data.length) return;\n    box.innerHTML = `<div class=\"profile-pls\"><div class=\"activity-label\">playlists<\/div>${data.map(pl => {\n        const t = Array.isArray(pl.tracks) ? pl.tracks : [], cover = t[0] && /^https:\\/\\//.test(t[0].cover || \"\") ? t[0].cover : \"\";\n        return `<a class=\"profile-pl\" href=\"${esc(location.origin + \"/#music/pl/\" + pl.id)}\" target=\"_blank\" rel=\"noopener\" onclick=\"return openMochiiPlaylist('${pl.id}')\">\n            <span class=\"profile-pl-cover\">${cover ? `<img src=\"${esc(cover)}\" alt=\"\" referrerpolicy=\"no-referrer\" onerror=\"this.remove()\">` : \"\"}<span>\ud83c\udfb5<\/span><\/span>\n            <span class=\"profile-pl-info\"><b>${esc(pl.name)}<\/b><small>${t.length} song${t.length === 1 ? \"\" : \"s\"}<\/small><\/span><\/a>`;\n    }).join(\"\")}<\/div>`;\n}\n\n// ---------- ROLES ----------\n// staff can hand out any role ranked below their own (and custom ones), to anyone ranked below them\nfunction rolePickerHTML(p) {\n    const mine = roleRank(state.me.role);\n    const custom = [...new Set([...state.profiles.values()].map(x => x.role).filter(r => r && !isStaffRole(r) && r !== \"member\"))].sort();\n    const opts = [...[\"admin\", \"mod\"].filter(r => roleRank(r) < mine), \"member\", ...custom];\n    return `<div class=\"role-picker\">\n        <div class=\"rp-label\">role<\/div>\n        <div class=\"rp-chips\">${opts.map(r => `<button class=\"rp-chip ${r === p.role ? \"on\" : \"\"}\" onclick=\"setRole('${p.id}', ${esc(JSON.stringify(r))})\">${roleBadge(r)}<\/button>`).join(\"\")}<\/div>\n        <div class=\"rp-new\">\n            <input id=\"rp-input\" maxlength=\"20\" placeholder=\"new custom role\u2026\" onkeydown=\"if(event.key==='Enter')setRole('${p.id}', this.value)\">\n            <button class=\"action-btn\" onclick=\"setRole('${p.id}', document.getElementById('rp-input').value)\">give<\/button>\n        <\/div>\n    <\/div>`;\n}\n\nasync function setRole(userId, role, reopen = true) {\n    role = String(role || \"\").trim();\n    if (!role) return toast(\"type a role name first\");\n    const { error } = await sb.rpc(\"set_role\", { p_user: userId, p_role: role });\n    if (error) return toast(error.message.replace(/^./, c => c.toLowerCase()));\n    await loadProfiles();\n    const p = state.profiles.get(userId);\n    toast(`${p?.username || \"they\"} ${p ? \"is\" : \"are\"} now ${p?.role || role}`);\n    // swap the badge on their messages that are already on screen\n    document.querySelectorAll(`#messages .msg[data-author=\"${userId}\"] .role-badge`).forEach(b => { b.outerHTML = roleBadge(p?.role); });\n    renderMembers();\n    if (reopen && $(\"profile-modal-bg\")?.classList.contains(\"open\")) openProfile(userId);\n}\n\n// /role @user <role name>, works anywhere and never posts to the chat\nasync function roleCommand(text) {\n    const m = text.match(/^\\/role\\s+@?([a-z0-9_]{3,20})\\s+(.+)$/i);\n    if (!m) return toast(\"usage: /role @user <role>\");\n    const target = [...state.profiles.values()].find(p => p.username.toLowerCase() === m[1].toLowerCase());\n    if (!target) return toast(`no user called ${m[1]}`);\n    await setRole(target.id, m[2], false);\n}\n\n// ---------- PROFILE EFFECTS & STORE ----------\nconst EFFECT_EMOJI = {\n    cherry_blossom: [\"\ud83c\udf38\", \"\ud83c\udf38\", \"\ud83d\udcae\"],\n    autumn_leaves: [\"\ud83c\udf42\", \"\ud83c\udf41\", \"\ud83c\udf43\"],\n    sparkles: [\"\u2728\", \"\u2b50\", \"\ud83d\udcab\"],\n    hearts: [\"\ud83d\udc95\", \"\ud83d\udc97\", \"\u2764\ufe0f\"],\n    snowfall: [\"\u2744\ufe0f\", \"\ud83c\udf28\ufe0f\", \"\u2745\"],\n    confetti: [\"\ud83c\udf89\", \"\ud83c\udf8a\", \"\ud83e\udd73\"],\n    stars: [\"\u2b50\", \"\ud83c\udf1f\", \"\u2729\"],\n    butterflies: [\"\ud83e\udd8b\", \"\ud83d\udc1b\", \"\ud83c\udf38\"],\n};\n// legacy gradient banners kept so previously-bought ones still render;\n// new banners are user-uploaded images stored on profiles.banner as a URL\nconst BANNERS = {\n    \"banner:sunset\": \"linear-gradient(135deg,#ff9a56,#ff5e62,#b24592)\",\n    \"banner:synthwave\": \"linear-gradient(135deg,#2b1055,#7597de 60%,#ff6ec7)\",\n    \"banner:ocean\": \"linear-gradient(135deg,#0f2027,#203a43,#2c5364)\",\n    \"banner:forest\": \"linear-gradient(135deg,#134e5e,#3a6186,#71b280)\",\n    \"banner:mochi\": \"linear-gradient(135deg,#ffdde1,#ff9a9e,#fad0c4)\",\n    \"banner:royal\": \"linear-gradient(135deg,#bf953f,#fcf6ba,#aa771c)\",\n};\nfunction bannerHTML(p) {\n    const b = String(p?.banner || \"\");\n    if (!b) return \"\";\n    if (b.startsWith(\"http\") || b.startsWith(\"/\"))\n        return `<img src=\"${esc(b)}\" style=\"width:100%;height:100%;object-fit:cover;display:block\" loading=\"lazy\">`;\n    if (BANNERS[b]) return `<div style=\"width:100%;height:100%;background:${BANNERS[b]}\"><\/div>`;\n    return \"\";\n}\nlet effectTimer = null;\nfunction spawnEffect(emojis) {\n    stopEffect();\n    const bg = $(\"profile-modal-bg\");\n    const spawn = () => {\n        if (!bg.classList.contains(\"open\")) return stopEffect();\n        const el = document.createElement(\"span\");\n        el.className = \"fx-particle\";\n        el.textContent = emojis[Math.floor(Math.random() * emojis.length)];\n        el.style.left = Math.random() * 90 + 5 + \"%\";\n        el.style.fontSize = 14 + Math.random() * 16 + \"px\";\n        el.style.animationDuration = 2.4 + Math.random() * 2 + \"s\";\n        el.style.opacity = 0.55 + Math.random() * 0.45;\n        bg.appendChild(el);\n        setTimeout(() => el.remove(), 4600);\n    };\n    for (let i = 0; i < 10; i++) setTimeout(spawn, i * 180);\n    effectTimer = setInterval(spawn, 320);\n}\nfunction stopEffect() {\n    clearInterval(effectTimer); effectTimer = null;\n    document.querySelectorAll(\".fx-particle\").forEach(el => el.remove());\n}\n\nasync function uploadBanner(input) {\n    try {\n        const file = input.files[0];\n        input.value = \"\";\n        if (!file) return;\n        if (file.size > 5 * 1024 * 1024) return toast(\"banner too big (max 5mb).\");\n        toast(\"uploading banner\u2026\");\n        const upload = await compressImage(file, 900, 0.78);\n        const path = `banners/${state.me.id}/${Date.now()}`;\n        const { error: upErr } = await sb.storage.from(\"chat-images\").upload(path, upload, { cacheControl: \"31536000\" }); // path is timestamped/immutable, so cache it for a year \u2014 this is what actually cuts cached egress, since browsers stop re-fetching what they already have\n        if (upErr) return toast(\"upload failed: \" + upErr.message);\n        const { data: { publicUrl } } = sb.storage.from(\"chat-images\").getPublicUrl(path);\n        const { error } = await sb.from(\"profiles\").update({ banner: publicUrl }).eq(\"id\", state.me.id);\n        if (error) return toast(\"couldn't set banner: \" + error.message);\n        state.me.banner = publicUrl;\n        state.profiles.set(state.me.id, { ...state.profiles.get(state.me.id), banner: publicUrl });\n        toast(\"banner equipped! \ud83d\uddbc\ufe0f\");\n        refreshBalance();\n        openSettings();\n    } catch (error) {\n        console.error(\"Failed to upload banner:\", error);\n        toast(\"Failed to upload banner: \" + error.message);\n    }\n}\n\nasync function unequipBanner() {\n    try {\n        const { error } = await sb.from(\"profiles\").update({ banner: \"\" }).eq(\"id\", state.me.id);\n        if (error) return toast(error.message);\n        state.me.banner = \"\";\n        state.profiles.set(state.me.id, { ...state.profiles.get(state.me.id), banner: \"\" });\n        toast(\"banner removed.\");\n        openSettings();\n    } catch (error) {\n        console.error(\"Failed to unequip banner:\", error);\n        toast(\"Failed to unequip banner: \" + error.message);\n    }\n}\n\nfunction closeModal(id) {\n    $(id).classList.remove(\"open\");\n    if (id === \"profile-modal-bg\") stopEffect();\n}\n\nasync function addFriend(id) {\n    try {\n        const { error } = await sb.from(\"friendships\")\n            .insert({ requester: state.me.id, addressee: id, status: \"pending\" });\n        toast(error ? \"couldnt send request. :(\" : \"friend request sent!\");\n        openProfile(id);\n    } catch (error) {\n        console.error(\"Failed to send friend request:\", error);\n        toast(\"Failed to send friend request: \" + error.message);\n    }\n}\n\nasync function acceptFriend(id) {\n    try {\n        await sb.from(\"friendships\")\n            .update({ status: \"accepted\" })\n            .eq(\"requester\", id).eq(\"addressee\", state.me.id);\n        state.friendRequests.delete(id);\n        renderSidebar();\n        toast(\"you are now friends!\");\n        openProfile(id);\n    } catch (error) {\n        console.error(\"Failed to accept friend request:\", error);\n        toast(\"Failed to accept friend request: \" + error.message);\n    }\n}\n\nasync function removeFriend(id) {\n    try {\n        const { error } = await sb.from(\"friendships\").delete()\n            .or(`and(requester.eq.${state.me.id},addressee.eq.${id}),and(requester.eq.${id},addressee.eq.${state.me.id})`);\n        if (error) return toast(\"couldn't remove friend: \" + error.message);\n        toast(\"friend removed.\");\n        openProfile(id);\n    } catch (error) {\n        console.error(\"Failed to remove friend:\", error);\n        toast(\"Failed to remove friend: \" + error.message);\n    }\n}\n\nasync function blockUser(id) {\n    try {\n        await sb.from(\"blocks\").insert({ blocker: state.me.id, blocked: id });\n        toast(\"user blocked.\");\n        openProfile(id);\n    } catch (error) {\n        console.error(\"Failed to block user:\", error);\n        toast(\"Failed to block user: \" + error.message);\n    }\n}\n\nasync function unblock(id) {\n    await sb.from(\"blocks\").delete().eq(\"blocker\", state.me.id).eq(\"blocked\", id);\n    toast(\"user unblocked.\");\n    openProfile(id);\n}\n\nasync function dmFromProfile(id) {\n    // the bot can't be dmed\n    const target = state.profiles.get(id) || state.dms.find(d => d.other.id === id)?.other;\n    if (target?.username?.toLowerCase() === \"mochiibot\") return toast(\"\ud83e\udd16 you can't dm mochiiBot \u2014 use its commands in a channel!\");\n    closeModal(\"profile-modal-bg\");\n    openDm(id);\n}\n\n// ---------- SETTINGS / AVATAR MAKER ----------\nlet draftAvatar = { emoji: \"\ud83d\udc31\", color: \"#fbfafd\" }; // or { image: true, url }\n\nfunction openSettings() {\n    const parsed = parseAvatar(state.me.avatar);\n    draftAvatar = parsed.image ? { ...parsed } : { emoji: parsed.emoji, color: parsed.color };\n\n    $(\"settings-modal\").innerHTML = `\n        <h2>customize your profile<\/h2>\n        <div class=\"profile-hero\">\n            <div class=\"avatar-lg\" id=\"draft-avatar\" style=\"background:${draftAvatar.color || \"#7c5cff\"}\">${avatarInner(draftAvatar)}<\/div>\n            <div class=\"me-name\">${esc(state.me.username)} ${roleBadge(state.me.role)}<\/div>\n        <\/div>\n        <label>upload a photo (or pick an emoji below)<\/label>\n        <input type=\"file\" id=\"pfp-input\" accept=\"image/*\" style=\"display:none\" onchange=\"uploadPfp(this)\">\n        <button class=\"action-btn\" onclick=\"document.getElementById('pfp-input').click()\">upload profile photo<\/button>\n        <br><br>\n        <label>pick an emoji avatar<\/label>\n        <div class=\"avatar-grid\" id=\"avatar-grid\"><\/div>\n        <label>pick a color<\/label>\n        <div class=\"color-row\" id=\"color-row\"><\/div>\n        <label>bio<\/label>\n        <textarea id=\"bio-input\" maxlength=\"200\" placeholder=\"tell everyone about yourself\u2026\">${esc(state.me.bio)}<\/textarea>\n        <label>status <span style=\"opacity:.6;font-weight:400\">shown on your profile and in the members list<\/span><\/label>\n        <input id=\"status-input\" maxlength=\"60\" placeholder=\"what are you up to?\"\n               value=\"${esc(state.me.status_text || \"\")}\"\n               style=\"width:100%;padding:10px 12px;background:var(--bg,#0c0c0c);color:var(--bright-text,#fff);border:1px solid var(--border-3,#e0e0e030);border-radius:10px;outline:none;font-size:14px;\">\n        <br><br>\n        <label>presence<\/label>\n        <div class=\"presence-row\">\n            <button class=\"action-btn ${(state.me.presence || \"online\") === \"online\" ? \"accent\" : \"\"}\" onclick=\"setPresence('online')\">\ud83d\udfe2 online<\/button>\n            <button class=\"action-btn ${state.me.presence === \"dnd\" ? \"accent\" : \"\"}\" onclick=\"setPresence('dnd')\">\ud83d\udd34 dnd<\/button>\n            <button class=\"action-btn ${state.me.presence === \"offline\" ? \"accent\" : \"\"}\" onclick=\"setPresence('offline')\">\u26ab appear offline<\/button>\n        <\/div>\n        <br>\n        <label>custom banner <span style=\"opacity:.6;font-weight:400\">shown at the top of your profile<\/span><\/label>\n        <div class=\"banner-upload\">\n            <div class=\"banner-preview\" id=\"banner-preview\">\n                ${String(state.me.banner || \"\") ? (bannerHTML(state.me) || \"\") : `<span class=\"banner-empty\">no banner yet<\/span>`}\n            <\/div>\n            <input type=\"file\" id=\"banner-input\" accept=\"image/*\" style=\"display:none\"\n                   onchange=\"uploadBanner(this)\">\n            <button class=\"action-btn accent\" onclick=\"document.getElementById('banner-input').click()\">\n                ${state.me.banner ? \"replace banner image\" : \"upload a banner image\"}\n            <\/button>\n            ${state.me.banner ? `<button class=\"action-btn ghost\" onclick=\"unequipBanner()\">remove banner<\/button>` : \"\"}\n        <\/div>\n        <br><br>\n        <button class=\"action-btn accent\" onclick=\"saveProfile()\">save profile<\/button>`;\n\n    renderAvatarGrid();\n    $(\"settings-modal-bg\").classList.add(\"open\");\n}\n\nasync function uploadPfp(input) {\n    const file = input.files[0];\n    input.value = \"\";\n    if (!file) return;\n    if (file.size > 3 * 1024 * 1024) return toast(\"photo too big (max 3mb).\");\n    toast(\"uploading\u2026\");\n    const upload = await compressImage(file, 256, 0.8);\n    const path = `pfps/${state.me.id}/${Date.now()}`;\n    const { error: upErr } = await sb.storage.from(\"chat-images\").upload(path, upload, { cacheControl: \"31536000\" }); // path is timestamped/immutable, so cache it for a year \u2014 this is what actually cuts cached egress, since browsers stop re-fetching what they already have\n    if (upErr) return toast(\"upload failed: \" + upErr.message);\n    const { data: { publicUrl } } = sb.storage.from(\"chat-images\").getPublicUrl(path);\n    draftAvatar = { image: true, url: publicUrl };\n    syncDraft();\n}\n\nfunction renderAvatarGrid() {\n    $(\"avatar-grid\").innerHTML = AVATAR_EMOJIS.map(e =>\n        `<div class=\"avatar-opt ${!draftAvatar.image && e === draftAvatar.emoji ? \"selected\" : \"\"}\"\n              onclick=\"pickEmoji('${e}')\">${e}<\/div>`).join(\"\");\n    $(\"color-row\").innerHTML = AVATAR_COLORS.map(c =>\n        `<div class=\"color-opt ${c === draftAvatar.color ? \"selected\" : \"\"}\" style=\"background:${c}\"\n              onclick=\"pickColor('${c}')\"><\/div>`).join(\"\");\n}\n\nfunction pickEmoji(e) { draftAvatar = { emoji: e, color: draftAvatar.color || \"#7c5cff\" }; syncDraft(); }\nfunction pickColor(c) { draftAvatar.color = c; syncDraft(); }\nfunction syncDraft() {\n    $(\"draft-avatar\").style.background = draftAvatar.color || \"#7c5cff\";\n    $(\"draft-avatar\").innerHTML = avatarInner(draftAvatar);\n    renderAvatarGrid();\n}\n\nasync function saveProfile() {\n    const bio = $(\"bio-input\").value.trim();\n    const status_text = $(\"status-input\").value.trim();\n    const avatarStr = draftAvatar.image ? draftAvatar.url : `${draftAvatar.emoji}|${draftAvatar.color}`;\n    const { error } = await sb.from(\"profiles\")\n        .update({ avatar: avatarStr, bio, status_text })\n        .eq(\"id\", state.me.id);\n    if (error) return toast(\"save failed: \" + error.message);\n    state.me.avatar = avatarStr;\n    state.me.bio = bio;\n    state.me.status_text = status_text;\n    closeModal(\"settings-modal-bg\");\n    renderMeBar();\n    loadProfiles().then(() => { renderMembers(); loadMessages(); });\n    toast(\"profile saved!\");\n}\n<\/script>\n<\/body>\n\n<\/html>";
window.__legalHtml="<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>mochii terms of service<\/title>\n<link href=\"https://fonts.googleapis.com/css2?family=Geist:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>:root{--bg:#f6f5f2;--card:#fff;--text:#1d1c1a;--muted:#6b6862;--line:#e4e1da;--accent:#c4702a}\n@media (prefers-color-scheme:dark){:root{--bg:#121212;--card:#1b1b1b;--text:#ecebe8;--muted:#9a978f;--line:#2c2c2c;--accent:#e89a52}}\n*{box-sizing:border-box}\nbody{margin:0;background:var(--bg);color:var(--text);font:15px/1.65 \"Geist\",-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif}\nmain{max-width:720px;margin:0 auto;padding:48px 16px 80px}\nh1{font-size:28px;font-weight:600;margin:0 0 4px}\nh2{font-size:17px;font-weight:600;margin:32px 0 6px}\n.date,.foot{color:var(--muted);font-size:13px}\n.foot{margin-top:40px;padding-top:16px;border-top:1px solid var(--line)}\na{color:var(--accent)}\nul{padding-left:20px}\n\nmain:not(:target){display:none} body:not(:has(main:target)) #terms{display:block}<\/style><\/head>\n<body><main id=\"terms\">\n<h1>terms of service<\/h1>\n<div class=\"date\">last updated october 15, 2026<\/div>\n\n<p>by using mochii you agree to these terms. if you don't agree, don't use it.<\/p>\n\n<h2>what mochii is<\/h2>\n<p>mochii is a free web proxy browser with games, music, chat and an ai assistant. it's provided as is, with no guarantees that it works, stays online, or keeps your data forever.<\/p>\n\n<h2>your responsibility<\/h2>\n<p>you're responsible for how you use mochii. follow the laws where you live and the rules of any network you're on, including school or work policies. mochii doesn't give you permission to get around rules that apply to you.<\/p>\n\n<h2>don't use mochii to<\/h2>\n<ul>\n<li>break the law, or access, share or store illegal content.<\/li>\n<li>harass, threaten, impersonate or dox anyone.<\/li>\n<li>post spam, malware, or sexual content involving minors.<\/li>\n<li>attack, overload or scrape mochii, its wisp servers, or other sites.<\/li>\n<li>get around limits like the ai daily limit, for example with lots of accounts.<\/li>\n<\/ul>\n\n<h2>accounts and chat<\/h2>\n<p>keep your password safe; you're responsible for what happens on your account. you own what you post, but you let us store and show it so the chat works. we can remove content or suspend accounts that break these terms, without notice.<\/p>\n\n<h2>ai<\/h2>\n<p>ai replies can be wrong, made up, or inappropriate. don't rely on them for medical, legal, financial or other important decisions. usage is limited per day.<\/p>\n\n<h2>third party content<\/h2>\n<p>sites you visit through the proxy, games, and music from youtube or soundcloud belong to their owners and follow their own terms. we aren't responsible for them.<\/p>\n\n<h2>liability<\/h2>\n<p>to the extent the law allows, mochii and its makers aren't liable for any damages from using or not being able to use the service, including lost data.<\/p>\n\n<h2>changes<\/h2>\n<p>we can change these terms or the service at any time. we'll update the date at the top when we do.<\/p>\n\n<h2>contact<\/h2>\n<p>questions or reports? reach us on <a href=\"https://discord.gg/cmzz7cRqaH\" target=\"_blank\" rel=\"noopener\">discord<\/a>.<\/p>\n\n<div class=\"foot\">questions? find us on <a href=\"https://discord.gg/cmzz7cRqaH\" target=\"_blank\" rel=\"noopener\">discord<\/a>. see also the <a href=\"#privacy\">privacy policy<\/a>.<\/div>\n<\/main><main id=\"privacy\">\n<h1>privacy policy<\/h1>\n<div class=\"date\">last updated october 15, 2026<\/div>\n\n<p>this explains what mochii collects, where it goes, and what you can do about it. short version: most things stay in your browser, accounts store a little on our database, and we don't sell anything to anyone.<\/p>\n\n<h2>stuff that stays in your browser<\/h2>\n<p>settings, themes, wallpapers, tabs, proxy server choice, custom wisp servers, music recents, ad block stats and similar data are saved in your browser's local storage. we never see it. clearing your site data deletes it.<\/p>\n\n<h2>accounts<\/h2>\n<p>accounts are optional and shared with mochii chat. when you make one we store:<\/p>\n<ul>\n<li>your username and a hashed password (handled by supabase auth). we don't ask for a real email.<\/li>\n<li>your public profile: username, avatar and anything else you put on it. <b>profiles are readable by everyone<\/b>, so don't put private info there.<\/li>\n<li>site settings and search history you choose to sync. only your account can read these.<\/li>\n<li>chat messages and images you post in mochii chat, which other users can see.<\/li>\n<\/ul>\n\n<h2>ai<\/h2>\n<p>messages you send on the ai page go through our relay to groq, which generates the reply. we don't keep your conversations. to enforce the daily limit we store token counts per account and per network. the network is stored as a one-way hash of your ip address, never the raw ip.<\/p>\n\n<h2>browsing through the proxy<\/h2>\n<p>sites you visit are fetched through a wisp server, which may be run by us or a third party you pick. those servers carry your traffic and could see it, especially for sites without https. we don't log the pages you visit. the sites themselves get whatever you send them, same as normal browsing.<\/p>\n\n<h2>third parties<\/h2>\n<ul>\n<li><b>supabase<\/b> stores account, chat and usage data.<\/li>\n<li><b>vercel<\/b> hosts the site and may keep standard request logs.<\/li>\n<li><b>groq<\/b> processes ai messages.<\/li>\n<li><b>youtube and soundcloud<\/b> serve music played in mochii music, under their own policies.<\/li>\n<li><b>google fonts<\/b> serves fonts.<\/li>\n<\/ul>\n<p>we don't run ads, analytics or tracking pixels.<\/p>\n\n<h2>kids<\/h2>\n<p>mochii isn't meant for children under 13. if you're under 13, don't make an account. if you think a child made one, message us on <a href=\"https://discord.gg/cmzz7cRqaH\" target=\"_blank\" rel=\"noopener\">discord<\/a> and we'll delete it.<\/p>\n\n<h2>your choices<\/h2>\n<p>you can edit your profile, clear your search history, or ask us on <a href=\"https://discord.gg/cmzz7cRqaH\" target=\"_blank\" rel=\"noopener\">discord<\/a> to delete your account and the data tied to it. clear your browser's site data to remove everything stored locally.<\/p>\n\n<h2>changes<\/h2>\n<p>if this policy changes, we'll update the date at the top. continuing to use mochii means you accept the new version.<\/p>\n\n<div class=\"foot\">questions? find us on <a href=\"https://discord.gg/cmzz7cRqaH\" target=\"_blank\" rel=\"noopener\">discord<\/a>. see also the <a href=\"#terms\">terms of service<\/a>.<\/div>\n<\/main>\n<script>const t={\"terms\": \"mochii terms of service\", \"privacy\": \"mochii privacy policy\"},s=()=>document.title=t[location.hash.slice(1)]||t.terms;s();addEventListener(\"hashchange\",()=>{s();scrollTo(0,0)});<\/script>\n<\/body><\/html>";</script>
