  <style>/* /p/css/app/base.css */
/* reset, keyframes and the classes toggled by settings */

* { box-sizing:border-box; margin:0; padding:0; }
html, body { width:100%; height:100%; overflow:hidden; }
body {
  background:var(--bg-body);
  color:var(--text-primary);
  font-family:var(--font);
  font-weight:var(--font-weight,400);
  text-transform:lowercase;
  -webkit-font-smoothing:antialiased;
}
button, input, select { font:inherit; text-transform:lowercase; }
button, a { -webkit-tap-highlight-color:transparent; }
::selection { background:var(--accent); color:var(--bg-body); }
::-webkit-scrollbar { width:3px; height:3px; }
::-webkit-scrollbar-track { background:transparent; }
::-webkit-scrollbar-thumb { background:#4e4e4e; border-radius:999px; }
::-webkit-scrollbar-thumb:hover { background:#707070; }
* { scrollbar-width:thin; scrollbar-color:#4e4e4e transparent; }

@keyframes spin { to { transform:rotate(360deg); } }
@keyframes fade-in { from { opacity:0; transform:translateY(7px); } to { opacity:1; transform:none; } }
@keyframes modal-in { from { opacity:0; transform:translate(-50%,-50%) scale(.94); } to { opacity:1; transform:translate(-50%,-50%) scale(1); } }
@keyframes modal-out { from { opacity:1; transform:translate(-50%,-50%) scale(1); } to { opacity:0; transform:translate(-50%,-50%) scale(.94); } }
@keyframes skeleton { to { transform:translateX(-100%); } }
@keyframes modal-pop { from { opacity:0; transform:scale(.94); } to { opacity:1; transform:none; } }
@keyframes soft-rise { from { opacity:0; transform:translateY(12px) scale(.985); } to { opacity:1; transform:none; } }
@keyframes soft-pop { 0% { opacity:0; transform:scale(.92); } 70% { opacity:1; transform:scale(1.025); } 100% { transform:scale(1); } }
@keyframes chrome-in { from { opacity:0; transform:translateY(-10px); filter:blur(5px); } to { opacity:1; transform:none; filter:none; } }
@keyframes page-in { from { opacity:0; transform:scale(.992); } to { opacity:1; transform:scale(1); } }
@keyframes glow-drift { 0%,100% { transform:translate3d(-2%,0,0) scale(1); opacity:.32; } 50% { transform:translate3d(2%,1%,0) scale(1.06); opacity:.48; } }
@keyframes shimmer { from { background-position:200% 0; } to { background-position:-200% 0; } }
@keyframes button-bounce { 0% { transform:scale(1); } 45% { transform:scale(.94); } 100% { transform:scale(1); } }
@media (prefers-reduced-motion:reduce) {
  *, *::before, *::after { scroll-behavior:auto!important; transition-duration:.001ms!important; animation-duration:.001ms!important; animation-iteration-count:1!important; }
}

:root { --motion-fast:.12s; --motion-med:.22s; --motion-slow:.38s; --hover-scale:1.035; --radius-mult:1; }
html.motion-subtle { --motion-fast:.08s; --motion-med:.15s; --motion-slow:.24s; --hover-scale:1.02; }
html.motion-off { --motion-fast:.001s; --motion-med:.001s; --motion-slow:.001s; --hover-scale:1; }
html.motion-off *, html.motion-off *::before, html.motion-off *::after { animation:none!important; transition:none!important; scroll-behavior:auto!important; }
html.grid-off .iframe-container { background:var(--bg-body); }
html.glow-on .iframe-container::before { content:""; position:absolute; inset:-22%; pointer-events:none; z-index:0; background:radial-gradient(circle at 50% 44%, var(--accent-soft), transparent 42%); filter:blur(34px); animation:glow-drift 9s ease-in-out infinite; opacity:.8; }
html.glow-on .iframe-container iframe, html.glow-on .iframe-container > .message-container, html.glow-on .iframe-container > .loading-bar-container { z-index:1; }
html.compact-ui .tab { height:24px; }
html.compact-ui .main-nav { min-height:50px; padding:6px 8px; }
html.no-hover .tab:hover, html.no-hover .pill:hover, html.no-hover .proxy-action:hover, html.no-hover .chrome-icon:hover { transform:none; }

</style>
  <style>/* /p/css/app/browser.css */
/* browser chrome: tabs, address bar, page frame, loading states */

#proxy-content { width:100%; height:100%; display:flex; overflow:hidden; }
#proxy-app { width:100%; height:100%; display:flex; min-width:0; overflow:hidden; }
.browser-container { width:100%; height:100%; display:flex; overflow:hidden; background:var(--bg-body); }

.build-and-discord {
  position: fixed;
  bottom: 6px;
  right: 6px;
  font-size: 8px;
  opacity: 0.5;
}

a {
  color: inherit;
}

.new-tab-btn {
  border:0; color:var(--text-muted); background:transparent; width:28px; height:28px; flex:0 0 28px;
  border-radius:50%; display:flex; align-items:center; justify-content:center; cursor:pointer;
  transition:background-color var(--motion-fast), color var(--motion-fast);
}
.new-tab-btn:hover { background:var(--accent-soft); color:var(--text-white); }
.tabbar {
  display:flex; align-items:center; gap:6px; padding:5px 8px;
  background:var(--surface-0); border-bottom:1px solid var(--border-subtle); z-index:14;
}
.tabs-container { display:flex; flex-direction:row; gap:3px; flex:1; min-width:0; overflow-x:auto; overflow-y:hidden; }
.tabs-container::-webkit-scrollbar { display:none; }
.tab {
  position:relative; flex:1 1 0; min-width:90px; max-width:240px; height:28px;
  display:flex; align-items:center; justify-content:center; gap:7px; padding:0 28px;
  border-radius:8px; color:var(--text-muted); background:transparent;
  cursor:pointer; user-select:none; overflow:hidden;
  transition:background-color var(--motion-fast), color var(--motion-fast);
}
.tab:hover { background:var(--accent-soft); color:var(--text-white); }
.tab.active { background:var(--surface-5); color:var(--text-white); }
.tab.drag-over { outline:1px solid var(--accent); }
.tab-favicon { width:14px; height:14px; flex:0 0 14px; border-radius:3px; object-fit:contain; }
.tab-title { min-width:0; overflow:hidden; white-space:nowrap; text-overflow:ellipsis; font-size:12px; }
.tab-close {
  position:absolute; left:5px; top:50%; transform:translateY(-50%);
  opacity:0; width:18px; height:18px; display:flex; align-items:center; justify-content:center;
  border-radius:50%; color:var(--text-muted); font-size:14px; line-height:1;
  transition:opacity var(--motion-fast), background-color var(--motion-fast), color var(--motion-fast);
}
.tab:hover .tab-close, .tab.active .tab-close { opacity:.7; }
.tab-close:hover { opacity:1!important; color:var(--text-white); background:var(--accent-soft); }
.tab-spinner { width:12px; height:12px; border:2px solid var(--border-faint); border-top-color:var(--accent); border-radius:50%; animation:spin .8s linear infinite; flex:0 0 12px; }

.content-area { flex:1; min-width:0; min-height:0; display:flex; flex-direction:column; overflow:hidden; background:var(--bg-body); }
.main-nav {
  min-height:56px;
  padding:8px 10px;
  display:flex;
  align-items:center;
  gap:8px;
  background:var(--surface-0);
  border-bottom:1px solid var(--border-subtle);
  z-index:15;
}
.nav-controls, .window-controls { display:flex; align-items:center; gap:4px; flex:0 0 auto; }
.chrome-icon {
  width:32px;
  height:32px;
  flex:0 0 32px;
  border:1px solid transparent;
  border-radius:9px;
  background:transparent;
  color:var(--text-muted);
  display:flex;
  align-items:center;
  justify-content:center;
  cursor:pointer;
  text-decoration:none;
  font-size:14px;
  transition:background var(--motion-fast), border-color var(--motion-fast), color var(--motion-fast), transform var(--motion-fast);
}
.chrome-icon:hover {
  background:var(--surface-3);
  border-color:var(--border-subtle);
  color:var(--text-primary);
  transform:scale(var(--hover-scale));
}
.chrome-icon:active {
  background:var(--surface-4);
  transform:scale(.96);
}
.chrome-icon.disabled {
  opacity:.25;
  pointer-events:none;
  transform:none;
}
.chrome-icon svg, .new-tab-btn svg, .proxy-action svg { width:17px; height:17px; }
.omnibox { flex:1; min-width:0; display:flex; align-items:center; justify-content:center; gap:8px; }
.omnibox-input-wrap {
  flex:0 1 700px;
  min-width:0;
  position:relative;
  display:flex;
  align-items:center;
}
.omnibox input {
  width:100%;
  height:36px;
  border:1px solid transparent;
  outline:none;
  border-radius:14px;
  background:var(--input-search);
  color:var(--text-secondary);
  padding:0 15px 0 40px;
  font-size:12px;
  caret-color:var(--accent);text-transform:none;
  transition:background-color .1s, border-color .1s, color .1s;
}
.omnibox input:hover { background:rgba(255,255,255,.045); }
.omnibox input:focus { background:rgba(255,255,255,.055); border-color:var(--border-faint); color:var(--text-primary); box-shadow:0 0 0 3px var(--accent-soft); }
.omnibox input::placeholder { color:var(--text-muted); opacity:.65; font-weight:300; }
.omnibox-icon { position:absolute; left:10px; width:22px; height:22px; border-radius:50%; display:flex; align-items:center; justify-content:center; color:var(--text-muted); z-index:2; pointer-events:none; }
.omnibox-icon svg { width:17px; height:17px; }
/* the music player next to the url bar: same height, fill and radius as the url bar */
.nav-music { flex:0 1 300px; min-width:200px; height:36px; display:flex; align-items:center; gap:2px; padding:0 5px 0 4px; border:1px solid var(--border-subtle); border-radius:14px; background:var(--input-search); }
.nm-now { flex:1; min-width:0; height:28px; display:flex; align-items:center; gap:10px; padding:0 8px; border:0; border-radius:10px; background:transparent; color:var(--text-muted); font:inherit; font-size:12px; text-align:left; cursor:pointer; transition:background var(--motion-fast), color var(--motion-fast); }
.nm-now:hover { background:var(--accent-soft); color:var(--text-primary); }
.nm-now svg { flex:0 0 auto; width:16px; height:16px; }
.nav-music.playing .nm-now svg { color:var(--accent); }
.nm-now span { min-width:0; overflow:hidden; white-space:nowrap; text-overflow:ellipsis; color:var(--text-secondary); text-transform:none; }
.nav-music:not(.has-track) .nm-now span { color:var(--text-muted); text-transform:lowercase; }
.nm-btn { width:28px; height:28px; flex:0 0 28px; display:flex; align-items:center; justify-content:center; border:0; border-radius:9px; background:transparent; color:var(--text-muted); cursor:pointer; transition:background var(--motion-fast), color var(--motion-fast); }
.nm-btn:hover { background:var(--accent-soft); color:var(--text-white); }
.nm-btn svg { width:15px; height:15px; }
.nm-btn > span { display:flex; }
.nm-btn .i-pause, .nav-music.playing .nm-btn .i-play { display:none; }
.nav-music.playing .nm-btn .i-pause { display:flex; }
.nav-music:not(.has-track) .nm-btn { opacity:.4; pointer-events:none; }
.nm-now:focus-visible, .nm-btn:focus-visible { outline:2px solid var(--accent); outline-offset:-2px; }
@media (max-width:1000px) { .nav-music { flex-basis:170px; } }
@media (max-width:760px) { .nav-music .nm-now span { display:none; } .nav-music { flex:0 0 auto; min-width:0; } }
@media (max-width:560px) { .nav-music { display:none; } }
.proxy-actions { display:flex; align-items:center; gap:4px; }
.proxy-action {
  width:30px; height:30px; border:0; border-radius:50%; background:transparent; color:var(--text-muted);
  display:flex; align-items:center; justify-content:center; cursor:pointer; transition:var(--motion-fast);
}
.proxy-action:hover { background:var(--accent-soft); color:var(--text-white); transform:scale(1.05); }

.iframe-container {
  position:relative;
  flex:1;
  min-height:0;
  width:calc(100% - 10px);
  height:100%;
  margin:0 5px 5px;
  border-radius:var(--radius-frame);
  overflow:hidden;
  background:
    radial-gradient(circle at 50% 50%, rgba(255,255,255,.02), transparent 55%),
    linear-gradient(var(--bg-grid) 1px, transparent 1px),
    linear-gradient(90deg, var(--bg-grid) 1px, transparent 1px),
    var(--bg-body);
  background-size:100% 100%,20px 20px,20px 20px,auto;
  border:1px solid var(--border-medium);
}
.iframe-container iframe {
  position:absolute; inset:0; width:100%; height:100%; border:0; display:block; background:transparent;
  transition:filter .18s var(--motion), opacity .18s var(--motion);
}
.iframe-container iframe.hidden { display:none; }
.iframe-container iframe.loading { filter:blur(10px); opacity:.82; }
.browser-container.browsing-mode .main-nav { animation:chrome-in var(--motion-med) var(--motion) both; }
.browser-container.browsing-mode .tabbar { animation:chrome-in var(--motion-med) var(--motion) both; }
.iframe-container iframe:not(.hidden) { animation:page-in var(--motion-med) var(--motion) both; }

.browser-container.landing-mode .tabbar,
.browser-container.landing-mode .main-nav { display:none !important; }
.browser-container.landing-mode .content-area { flex:1 1 100%; }
.browser-container.landing-mode .content-area { width:100%; }
.browser-container.landing-mode .iframe-container {
  width:100%; height:100%; margin:0; border:0; border-radius:0;
}
.page-loading { position:absolute; inset:0; z-index:20; display:none; flex-direction:column; align-items:center; justify-content:center; gap:12px; color:var(--text-muted); font-size:12px; }
.page-loading .spinner { margin:0; }
.loading-bar-container { position:absolute; top:0; left:0; right:0; height:2px; z-index:25; pointer-events:none; }
.loading-bar { width:0; height:100%; background:var(--accent); opacity:0; transition:width .2s, opacity .15s; }

.message-container {
  position:absolute; inset:0; z-index:40; display:flex; align-items:center; justify-content:center;
  background:rgba(0,0,0,.78); backdrop-filter:blur(4px); -webkit-backdrop-filter:blur(4px);
}
.message-content {
  width:min(410px, calc(100% - 32px)); padding:26px 28px; border:1px solid var(--border-faint);
  border-radius:var(--radius-dialog); background:var(--surface-2); text-align:center; animation:fade-in .18s ease;
}
.message-content h1 { color:var(--text-primary); font-size:16px; font-weight:500; margin-bottom:8px; }
.message-content p { color:var(--text-muted); font-size:12px; line-height:1.7; word-break:break-word; }
.spinner { width:26px; height:26px; margin:0 auto 16px; border:2px solid var(--border-faint); border-top-color:var(--accent); border-radius:50%; animation:spin .8s linear infinite; }
.message-button {
  margin-top:16px; padding:9px 14px; border:0; border-radius:var(--radius-control); background:var(--surface-4);
  color:var(--text-secondary); cursor:pointer; font-size:12px; transition:.1s;
}
.message-button:hover { background:var(--surface-hover); color:var(--text-white); transform:scale(1.03); }
@media (max-width:760px) {
  .window-controls .proxy-action:nth-last-child(2) { display:none; }
}
@media (max-width:560px) {
  .main-nav { padding:7px; }
  .omnibox { margin:0 4px; }
}

</style>
  <style>/* /p/css/app/account.css */
/* account forms and the first-run setup wizard */

.acct-note { color:var(--text-muted); font-size:12px; margin-bottom:12px; }
.acct-field { display:block; width:100%; height:40px; padding:0 14px; margin-bottom:8px; border:1px solid var(--border-subtle); border-radius:11px; outline:none; background:var(--surface-3); color:var(--text-primary); font:inherit; font-size:13px; text-transform:none; }
.acct-field:focus { border-color:var(--border-faint); box-shadow:0 0 0 3px var(--accent-soft); }
textarea.acct-field { height:84px; padding:10px 14px; resize:none; line-height:1.5; }
.acct-actions { display:flex; gap:8px; margin-top:4px; }
.acct-card { width:min(320px,100%); }
.acct-card .acct-actions .btn { width:100%; justify-content:center; }
.acct-switch { display:block; margin:14px auto 0; padding:4px 8px; border:0; background:none; color:var(--text-muted); font-size:12px; cursor:pointer; transition:color .12s; }
.acct-switch:hover { color:var(--text-white); }
.acct-switch:focus-visible { outline:2px solid var(--accent); outline-offset:2px; border-radius:6px; }
#account-body.acct-centered { flex:1; display:flex; align-items:center; justify-content:center; min-height:320px; }
.settings-pane[data-settings-pane="account"]:not(.hidden) { display:flex; flex-direction:column; min-height:100%; }
.wizard-card { width:min(540px,100%); max-height:100%; display:flex; flex-direction:column; gap:14px; padding:30px; overflow:auto; background:var(--surface-1); border:1px solid var(--border-faint); border-radius:22px; box-shadow:0 30px 90px rgba(0,0,0,.5); }
.wizard-card h2 { font-size:20px; font-weight:500; color:var(--text-white); }
.wizard-sub { color:var(--text-muted); font-size:13px; margin-top:-8px; }
.wizard-dots { display:flex; gap:6px; }
.wizard-dot { width:22px; height:3px; border-radius:2px; background:var(--border-subtle); }
.wizard-dot.on { background:var(--accent); }
.wizard-body { min-height:200px; display:flex; flex-direction:column; justify-content:center; }
.wizard-body .theme-list { display:flex; flex-wrap:wrap; gap:8px; }
.wizard-bgs { display:grid; grid-template-columns:repeat(3,1fr); gap:8px; max-height:260px; overflow:auto; }
.wizard-bg { position:relative; aspect-ratio:16/10; border-radius:12px; border:1px solid var(--border-subtle); background-color:var(--surface-4); background-size:cover; background-position:center; color:var(--text-white); font-size:12px; display:flex; align-items:flex-end; padding:8px; text-align:left; }
.wizard-bg.active { border-color:var(--accent); box-shadow:0 0 0 2px var(--accent-soft); }
.wizard-bg span { position:relative; padding:2px 7px; border-radius:7px; background:rgba(0,0,0,.55); }
.wizard-bg svg { position:absolute; inset:0; width:100%; height:100%; color:var(--accent); }
.wizard-actions { display:flex; gap:8px; justify-content:flex-end; margin-top:6px; }
.wizard-actions .grow { margin-right:auto; }
.acct-msg { min-height:16px; margin-top:10px; color:var(--text-muted); font-size:12px; }
.acct-avatar-row { display:flex; align-items:center; gap:14px; margin-bottom:12px; }
.acct-avatar { width:64px; height:64px; flex:0 0 64px; display:flex; align-items:center; justify-content:center; border-radius:50%; overflow:hidden; background:var(--surface-4); border:1px solid var(--border-subtle); color:var(--text-white); font-size:24px; }
.acct-avatar img { width:100%; height:100%; object-fit:cover; display:block; }
.acct-avatar-actions { display:flex; gap:8px; flex-wrap:wrap; }
.acct-legal { margin-top:10px; text-align:center; color:var(--text-muted); font-size:11px; } .acct-legal a { color:inherit; text-decoration:underline; } .acct-legal a:hover { color:var(--text-white); }

</style>
  <style>/* /p/css/app/extensions.css */
/* extensions: toolbar, popups and menus, the settings pane, side panel and option dialogs */

.extension-toolbar{display:none;align-items:center;gap:4px;flex:0 0 auto}
.extension-toolbar.visible{display:flex}
.extension-toolbar button{position:relative;width:30px;height:30px;border:1px solid var(--border-subtle);border-radius:9px;background:var(--surface-2);color:var(--text-secondary);display:flex;align-items:center;justify-content:center;cursor:pointer;transition:background var(--motion-fast),border-color var(--motion-fast),color var(--motion-fast),transform var(--motion-fast);font-size:11px;font-weight:500;padding:0}
.extension-toolbar button:hover{background:var(--surface-4);border-color:var(--border-faint);color:var(--text-white);transform:scale(var(--hover-scale))}
.extension-toolbar button.dim img{filter:grayscale(1);opacity:.5}
.extension-toolbar img{width:18px;height:18px;object-fit:contain}
.ext-badge{position:absolute;right:-4px;bottom:-4px;min-width:14px;height:14px;padding:0 3px;border-radius:7px;background:#5f6368;color:#fff;font-size:8.5px;font-weight:600;line-height:14px;text-align:center;pointer-events:none;box-shadow:0 0 0 2px var(--bg-body)}

.ext-icon{width:36px;height:36px;flex:0 0 36px;border-radius:10px;background:var(--surface-4);display:flex;align-items:center;justify-content:center;overflow:hidden;color:var(--text-primary);font-size:14px;font-weight:500}
.ext-icon img{width:100%;height:100%;object-fit:contain}
.ext-icon.sm{width:20px;height:20px;flex:0 0 20px;border-radius:5px;font-size:10px;background:transparent}

/* popups, the extensions menu and context menus */
.ext-popup{position:fixed;z-index:10002;background:var(--surface-1);border:1px solid var(--border-faint);border-radius:14px;box-shadow:0 18px 60px rgba(0,0,0,.45);overflow:hidden;animation:modal-pop .12s var(--motion)}
.ext-popup-frame{background:#fff;border-radius:10px}
.ext-popup-frame iframe{display:block;border:0;background:#fff;max-width:800px;max-height:600px}
.ext-menu{width:280px;padding:6px}
.ext-menu-title{padding:8px 10px 6px;color:var(--text-muted);font-size:12px}
.ext-menu-row{display:flex;align-items:center;gap:2px;border-radius:9px}
.ext-menu-row:hover{background:var(--surface-3)}
.ext-menu-main{flex:1;min-width:0;display:flex;align-items:center;gap:10px;padding:8px 10px;border:0;background:transparent;color:var(--text-primary);font-size:13px;text-align:left;cursor:pointer}
.ext-menu-main span:last-child{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ext-menu-pin{width:30px;height:30px;flex:0 0 30px;border:0;border-radius:8px;background:transparent;color:var(--text-faint);cursor:pointer;display:flex;align-items:center;justify-content:center}
.ext-menu-pin:hover,.ext-menu-pin.active{color:var(--text-white)}
.ext-menu-manage{width:100%;margin-top:4px;padding:9px 10px;border:0;border-top:1px solid var(--border-subtle);background:transparent;color:var(--text-secondary);font-size:12px;text-align:left;cursor:pointer;border-radius:0 0 8px 8px}
.ext-menu-manage:hover{color:var(--text-white)}
.ext-ctx{min-width:200px;max-width:320px;padding:5px;border-radius:11px}
.ext-ctx-head{padding:6px 10px 3px;color:var(--text-faint);font-size:11px}
.ext-ctx-item{display:block;width:100%;padding:7px 12px;border:0;border-radius:7px;background:transparent;color:var(--text-primary);font-size:12.5px;text-align:left;cursor:pointer;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ext-ctx-item:hover:not(:disabled){background:var(--surface-3)}
.ext-ctx-item:disabled{color:var(--text-faint);cursor:default}
.ext-ctx-gap{display:inline-block;width:14px}
.ext-ctx-sep{height:1px;margin:4px 6px;background:var(--border-subtle)}

/* settings pane */
.ext-lead{margin-top:6px;color:var(--text-faint);font-size:12px;line-height:1.5}
.ext-row{display:flex;align-items:center;gap:12px;padding:12px 0;border-bottom:1px solid var(--border-subtle)}
.ext-row:last-child{border-bottom:0}
.ext-row.off .ext-icon{filter:grayscale(1);opacity:.55}
.ext-store-info{min-width:0;flex:1}
.ext-name{color:var(--text-primary);font-size:13px;font-weight:500;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ext-meta{margin-top:2px;color:var(--text-faint);font-size:11px}
.ext-desc{margin-top:4px;color:var(--text-muted);font-size:11.5px;line-height:1.45;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.ext-err{margin-top:4px;color:#e88;font-size:11px;line-height:1.4;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ext-row-actions{display:flex;align-items:center;gap:6px;flex:0 0 auto;flex-wrap:wrap;justify-content:flex-end}
.ext-row-actions .btn{height:30px;padding:0 11px}
.ext-row-actions .switch{cursor:pointer}
.ext-pin.active{color:var(--text-white);border-color:var(--border-faint)}
.ext-search input{width:100%;height:40px;margin-top:8px;padding:0 14px;border:1px solid var(--border-subtle);border-radius:12px;outline:none;background:var(--surface-3);color:var(--text-primary);font-size:13px}
.ext-search input:focus-visible{outline:2px solid var(--accent);outline-offset:1px}
.ext-chips{display:flex;flex-wrap:wrap;gap:6px;margin:10px 0 4px}
.ext-chip{height:28px;padding:0 11px;border:1px solid var(--border-subtle);border-radius:999px;background:transparent;color:var(--text-muted);font-size:12px;cursor:pointer}
.ext-chip:hover{color:var(--text-white);border-color:var(--border-faint)}
.ext-chip.active{background:var(--accent-active);color:var(--text-white);border-color:transparent}
.ext-market-head{display:flex;align-items:center;justify-content:space-between;gap:10px;margin:10px 0 2px;color:var(--text-faint);font-size:12px}
.ext-store-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:8px;margin-top:10px}
.ext-store-card{display:flex;align-items:flex-start;gap:11px;padding:12px;border:1px solid var(--border-subtle);border-radius:var(--radius-item);background:var(--surface-2);min-width:0}
.ext-store-card:hover{background:var(--surface-3)}
.ext-store-action{flex:0 0 auto}
.ext-store-action .btn{height:30px;padding:0 12px}
.ext-store-action .btn:disabled{opacity:.7;cursor:default}
.ext-empty{padding:12px 0 4px;color:var(--text-faint);font-size:12px}

/* options and extension pages opened as a tab */
.extension-surface-modal{position:fixed;inset:0;z-index:10000;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,.72);backdrop-filter:blur(7px);-webkit-backdrop-filter:blur(7px)}
.extension-surface-modal.hidden{display:none}
.extension-surface-card{width:min(1000px,calc(100% - 30px));height:min(760px,calc(100% - 30px));display:flex;flex-direction:column;background:var(--bg-body);border:1px solid var(--border-faint);border-radius:var(--radius-dialog);overflow:hidden;box-shadow:0 30px 90px rgba(0,0,0,.45)}
.extension-surface-header{position:relative;height:48px;display:flex;align-items:center;padding:0 52px 0 16px;border-bottom:1px solid var(--border-subtle);font-size:13px;color:var(--text-primary);flex:0 0 48px}
.extension-surface-header .close-btn{top:8px;right:8px}
.extension-surface-body{flex:1;min-height:0}
.extension-surface-body iframe{width:100%;height:100%;border:0;background:#fff;display:block}

/* side panel */
.ext-side{position:fixed;top:0;right:0;bottom:0;z-index:9990;width:min(400px,100%);display:flex;flex-direction:column;background:var(--surface-1);border-left:1px solid var(--border-faint);box-shadow:-20px 0 60px rgba(0,0,0,.35);animation:ext-side-in .16s var(--motion)}
@keyframes ext-side-in{from{transform:translateX(30px);opacity:0}}
.ext-side-head{position:relative;display:flex;align-items:center;gap:9px;height:46px;padding:0 48px 0 14px;border-bottom:1px solid var(--border-subtle);color:var(--text-primary);font-size:13px}
.ext-side-head .close-btn{top:7px;right:7px}
.ext-side iframe{flex:1;width:100%;border:0;background:#fff}

/* notices */
#ext-toasts{position:fixed;right:16px;bottom:16px;z-index:10003;display:flex;flex-direction:column;gap:8px;max-width:min(360px,calc(100% - 32px))}
.ext-toast{display:flex;align-items:flex-start;gap:10px;padding:12px 12px 12px 14px;background:var(--surface-1);border:1px solid var(--border-faint);border-radius:14px;box-shadow:0 14px 40px rgba(0,0,0,.4);color:var(--text-secondary);font-size:12.5px;line-height:1.45;animation:modal-pop .14s var(--motion);cursor:default}
.ext-toast-text{flex:1;min-width:0;display:flex;flex-direction:column;gap:2px}
.ext-toast-text b{color:var(--text-white);font-weight:500}
.ext-toast-text .btn{align-self:flex-start;height:28px;margin-top:6px}
.ext-toast-x{border:0;background:transparent;color:var(--text-faint);font-size:18px;line-height:1;cursor:pointer;padding:0 2px}
.ext-toast-x:hover{color:var(--text-white)}

/* background pages and offscreen documents */
#ext-hosts{position:fixed;width:0;height:0;overflow:hidden;left:-9999px;top:0;pointer-events:none}
.ext-host-frame{width:400px;height:300px;border:0}

@media (max-width:640px){
  .ext-row{flex-wrap:wrap}
  .ext-row-actions{width:100%;justify-content:flex-start}
  .ext-store-grid{grid-template-columns:1fr}
}

</style>
  <style>/* /p/css/app/settings.css */
/* settings modal */

.wisp-settings-modal { position:fixed; inset:0; z-index:9999; display:flex; align-items:center; justify-content:center; padding:16px; background:rgba(0,0,0,.7); backdrop-filter:blur(8px); -webkit-backdrop-filter:blur(8px); animation:fade-in .12s ease; }
.wisp-settings-modal.hidden { display:none; }
.settings-card { width:min(800px,100%); height:min(580px,100%); display:flex; overflow:hidden; background:var(--surface-1); border:1px solid var(--border-faint); border-radius:22px; box-shadow:0 30px 90px rgba(0,0,0,.5); animation:modal-pop .14s var(--motion); }
.settings-nav { width:200px; flex:0 0 200px; display:flex; flex-direction:column; gap:2px; padding:24px 12px 16px; background:var(--surface-0); border-right:1px solid var(--border-subtle); }
.settings-nav h2 { padding:0 10px 18px; font-size:16px; font-weight:500; color:var(--text-white); }
.settings-nav-item { width:100%; height:40px; display:flex; align-items:center; gap:11px; padding:0 10px; border:0; border-radius:11px; background:transparent; color:var(--text-muted); font-size:13px; text-align:left; cursor:pointer; transition:background .12s, color .12s; }
.settings-nav-item:hover { background:var(--accent-soft); color:var(--text-primary); }
.settings-nav-item.active { background:var(--accent-active); color:var(--text-white); }
.settings-nav-icon { width:18px; height:18px; flex:0 0 18px; display:flex; }
.settings-nav-note { margin-top:auto; padding:0 10px; color:var(--text-faint); font-size:11px; }
.settings-main { position:relative; flex:1; min-width:0; display:flex; flex-direction:column; }
.close-btn { position:absolute; top:16px; right:16px; z-index:2; width:32px; height:32px; border:0; border-radius:10px; background:transparent; color:var(--text-muted); display:flex; align-items:center; justify-content:center; font-size:20px; line-height:1; cursor:pointer; transition:background .12s, color .12s; }
.close-btn:hover { background:var(--accent-soft); color:var(--text-white); }
.settings-panels { flex:1; min-height:0; overflow:auto; padding:26px 34px 34px; }
.settings-pane.hidden { display:none; }
.settings-pane-title { margin-bottom:4px; font-size:20px; font-weight:500; color:var(--text-white); }
.group { margin-top:28px; }
.group-title { display:flex; align-items:center; justify-content:space-between; gap:12px; margin-bottom:2px; color:var(--text-muted); font-size:12px; }
.row { width:100%; display:flex; align-items:center; justify-content:space-between; gap:18px; padding:14px 0; border:0; border-bottom:1px solid var(--border-subtle); background:transparent; color:inherit; text-align:left; }
.row:last-child { border-bottom:0; }
.row-text { min-width:0; }
.row-text b { display:block; font-size:13px; font-weight:500; color:var(--text-primary); }
.row-text small { display:block; margin-top:3px; color:var(--text-faint); font-size:12px; font-weight:300; line-height:1.45; }
button.row { cursor:pointer; }
.btn { height:34px; padding:0 14px; border:1px solid var(--border-subtle); border-radius:11px; background:var(--surface-3); color:var(--text-secondary); font-size:12px; cursor:pointer; transition:background .12s, color .12s, border-color .12s; white-space:nowrap; }
.btn:hover { background:var(--surface-hover); border-color:var(--border-faint); color:var(--text-white); }
.btn.primary { background:var(--accent); border-color:transparent; color:var(--bg-body); }
.btn.primary:hover { filter:brightness(1.1); background:var(--accent); color:var(--bg-body); }
.btn:focus-visible, .settings-nav-item:focus-visible, .close-btn:focus-visible, .seg button:focus-visible, .wisp-option:focus-visible, .theme-swatch:focus-visible, .wallpaper-card:focus-visible { outline:2px solid var(--accent); outline-offset:2px; }
.switch { flex:0 0 auto; width:38px; height:22px; padding:3px; border-radius:999px; background:var(--surface-5); border:1px solid var(--border-faint); transition:background .15s, border-color .15s; }
.switch i { display:block; width:14px; height:14px; border-radius:50%; background:var(--text-faint); transition:transform .15s, background .15s; }
.setting-toggle.active .switch, .switch.active { background:var(--accent); border-color:var(--accent); }
.setting-toggle.active .switch i, .switch.active i { transform:translateX(16px); background:var(--bg-body); }
.seg { display:flex; flex:0 0 auto; padding:3px; border-radius:12px; background:var(--surface-3); border:1px solid var(--border-subtle); }
.seg button { padding:6px 14px; border:0; border-radius:9px; background:transparent; color:var(--text-muted); font-size:12px; cursor:pointer; transition:background .12s, color .12s; }
.seg button:hover { color:var(--text-primary); }
.seg button.active { background:var(--surface-5); color:var(--text-white); }
.select-row select { min-width:140px; height:34px; padding:0 10px; border:1px solid var(--border-subtle); border-radius:11px; outline:none; background:var(--surface-3); color:var(--text-secondary); font-size:12px; }
.select-row select:focus-visible { outline:2px solid var(--accent); outline-offset:2px; }
.server-list { display:flex; flex-direction:column; gap:2px; margin-top:8px; }
.wisp-option { display:flex; align-items:center; justify-content:space-between; gap:14px; padding:10px 12px; border-radius:12px; cursor:pointer; transition:background .12s; }
.wisp-option:hover { background:var(--surface-3); }
.wisp-option.active { background:var(--accent-soft); }
.wisp-main { min-width:0; display:flex; align-items:center; gap:12px; }
.radio { width:14px; height:14px; flex:0 0 14px; border-radius:50%; box-shadow:inset 0 0 0 1.5px var(--text-faint); transition:box-shadow .12s; }
.wisp-option.active .radio { box-shadow:inset 0 0 0 4px var(--accent); }
.wisp-text { min-width:0; }
.wisp-option-name { color:var(--text-primary); font-size:13px; font-weight:500; }
.wisp-option-url { margin-top:2px; color:var(--text-faint); font-size:11px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; text-transform:none; }
.server-status { display:flex; align-items:center; gap:8px; flex:0 0 auto; }
.ping-text { color:var(--text-faint); font-size:11px; }
.status-indicator { width:7px; height:7px; border-radius:50%; background:var(--text-faint); }
.status-indicator.status-success { background:#61ff8a; }
.status-indicator.status-error { background:#ff6666; }
.delete-wisp-btn { width:24px; height:24px; border:0; border-radius:8px; background:transparent; color:var(--text-faint); display:flex; align-items:center; justify-content:center; font-size:16px; cursor:pointer; transition:background .12s, color .12s; }
.delete-wisp-btn:hover { background:rgba(255,80,80,.14); color:#ff6666; }
.wisp-toggle { display:flex; align-items:center; justify-content:space-between; gap:18px; margin-top:6px; padding:14px 12px 4px; border-top:1px solid var(--border-subtle); cursor:pointer; }
.custom-input-group { display:flex; gap:8px; margin-top:12px; }
.custom-input-group input { flex:1; min-width:0; height:38px; padding:0 14px; border:1px solid var(--border-subtle); border-radius:11px; outline:none; background:var(--surface-3); color:var(--text-primary); font-size:13px; text-transform:none; }
.custom-input-group input:focus { border-color:var(--border-faint); box-shadow:0 0 0 3px var(--accent-soft); }
.custom-input-group input.invalid { border-color:#ff6666; }
.custom-input-group .btn { height:38px; }
.theme-list { display:flex; flex-wrap:wrap; gap:8px; margin-top:14px; }
.theme-swatch { height:34px; display:flex; align-items:center; gap:8px; padding:0 14px 0 10px; border:1px solid var(--border-subtle); border-radius:999px; background:var(--surface-3); color:var(--text-secondary); font-size:12px; cursor:pointer; transition:background .12s, border-color .12s, color .12s; }
.theme-swatch:hover { background:var(--surface-5); }
.theme-swatch.active { border-color:var(--accent); color:var(--text-white); }
.theme-dot { width:14px; height:14px; flex:0 0 14px; border-radius:50%; border:1px solid rgba(255,255,255,.18); }
.wallpaper-grid { display:grid; grid-template-columns:repeat(auto-fill,minmax(120px,1fr)); gap:10px; margin-top:12px; }
.wallpaper-card { padding:0; border:0; background:transparent; text-align:left; cursor:pointer; color:var(--text-muted); font-size:12px; }
.wallpaper-card img { display:block; width:100%; aspect-ratio:16/10; object-fit:cover; border-radius:12px; background:var(--surface-4); outline:2px solid transparent; outline-offset:2px; transition:outline-color .12s; }
.wallpaper-card:hover img { outline-color:var(--border-faint); }
.wallpaper-card.active img { outline-color:var(--accent); }
.wallpaper-card.active { color:var(--text-white); }
.wallpaper-card-name { display:block; margin-top:7px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.wallpaper-empty { padding:12px 0 0; color:var(--text-faint); font-size:12px; }
.background-btn.remove { display:none; }
.background-btn.remove.visible { display:inline-flex; align-items:center; }
.background-actions { display:flex; align-items:center; gap:8px; }
.about-logo { font-size:26px; font-weight:500; color:var(--text-white); }
.about-line { margin-top:8px; color:var(--text-muted); font-size:13px; line-height:1.6; }
.about-links { display:flex; gap:8px; margin-top:20px; }
.about-links a { display:inline-flex; align-items:center; height:34px; padding:0 14px; border:1px solid var(--border-subtle); border-radius:11px; background:var(--surface-3); color:var(--text-secondary); font-size:12px; text-decoration:none; transition:background .12s, color .12s; }
.about-links a:hover { background:var(--surface-hover); color:var(--text-white); }
@media (max-width:640px) {
  .settings-card { flex-direction:column; }
  .settings-nav { width:100%; flex:0 0 auto; flex-direction:row; align-items:center; gap:4px; padding:12px 56px 10px 12px; border-right:0; border-bottom:1px solid var(--border-subtle); overflow-x:auto; }
  .settings-nav h2, .settings-nav-note { display:none; }
  .settings-nav-item { width:auto; flex:0 0 auto; padding:0 12px; }
  .settings-panels { padding:20px 20px 28px; }
  .row { flex-wrap:wrap; }
}

/* blocked ads and trackers */
.block-stats { padding:10px 0 4px; }
.block-tiles { display:grid; grid-template-columns:repeat(3,1fr); gap:8px; }
.block-tile { padding:12px 14px; border:1px solid var(--border-subtle); border-radius:13px; background:var(--surface-2); }
.block-tile b { display:block; font-size:20px; font-weight:400; color:var(--text-white); font-variant-numeric:tabular-nums; letter-spacing:-.02em; }
.block-tile small { display:block; margin-top:2px; color:var(--text-faint); font-size:11.5px; }
.block-since { margin:8px 2px 0; color:var(--text-faint); font-size:11.5px; }
.block-hosts { margin-top:10px; display:flex; flex-direction:column; gap:2px; }
.block-host { display:flex; justify-content:space-between; gap:12px; padding:5px 2px; font-size:12px; color:var(--text-secondary); }
.block-host span:first-child { min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.block-host span:last-child { color:var(--text-faint); font-variant-numeric:tabular-nums; }

</style>
  <style>/* /p/css/app/palette.css */
/* command palette (ctrl/cmd+k) */

.palette { position:fixed; inset:0; z-index:10001; display:flex; justify-content:center; align-items:flex-start; padding:min(16vh,140px) 16px 16px; background:rgba(0,0,0,.55); backdrop-filter:blur(6px); -webkit-backdrop-filter:blur(6px); animation:palette-fade .14s ease; }
.palette.hidden { display:none; }
.palette-card { width:min(600px,100%); max-height:min(520px,100%); display:flex; flex-direction:column; overflow:hidden; background:var(--surface-2); background:color-mix(in srgb,var(--surface-2) 92%,transparent); border:1px solid var(--border-faint); border-radius:var(--radius-dialog); box-shadow:0 30px 80px -10px rgba(0,0,0,.7),0 0 0 1px rgba(0,0,0,.4),inset 0 1px 0 rgba(255,255,255,.04); backdrop-filter:blur(20px); -webkit-backdrop-filter:blur(20px); animation:palette-in .18s var(--motion); }
.palette-search { display:flex; align-items:center; gap:12px; padding:0 16px 0 18px; height:58px; flex:0 0 58px; border-bottom:1px solid var(--border-subtle); color:var(--text-muted); }
.palette-search input { flex:1; min-width:0; height:100%; border:0; outline:none; background:none; color:var(--text-white); font-size:15px; text-transform:none; caret-color:var(--accent); }
.palette-search input::placeholder { color:var(--text-faint); text-transform:lowercase; }
.palette kbd { display:inline-flex; align-items:center; justify-content:center; min-width:20px; height:20px; padding:0 6px; border:1px solid var(--border-faint); border-bottom-width:2px; border-radius:6px; background:var(--surface-4); color:var(--text-muted); font:inherit; font-size:10.5px; line-height:1; }
.palette-list { flex:1; overflow-y:auto; padding:6px 8px 8px; overscroll-behavior:contain; }
.palette-group { padding:12px 10px 6px; color:var(--text-faint); font-size:11px; letter-spacing:.04em; }
.palette-item { display:flex; align-items:center; gap:12px; height:42px; padding:0 10px; border-radius:var(--radius-item); color:var(--text-secondary); font-size:13.5px; cursor:pointer; scroll-margin:8px; }
.palette-item.active { background:var(--accent-soft); color:var(--text-white); box-shadow:inset 2px 0 0 var(--accent); }
.palette-icon { width:28px; height:28px; flex:0 0 28px; display:flex; align-items:center; justify-content:center; border-radius:8px; background:var(--surface-4); border:1px solid var(--border-subtle); color:var(--text-muted); }
.palette-item.active .palette-icon { color:var(--text-white); border-color:var(--border-faint); }
.palette-icon img { width:16px; height:16px; border-radius:3px; object-fit:contain; }
.palette-dot { width:12px; height:12px; border-radius:50%; box-shadow:0 0 0 2px var(--surface-2),0 0 0 3px var(--border-faint); }
.palette-label { flex:1; min-width:0; overflow:hidden; white-space:nowrap; text-overflow:ellipsis; }
.palette-hint { flex:0 0 auto; max-width:40%; overflow:hidden; white-space:nowrap; text-overflow:ellipsis; color:var(--text-faint); font-size:11.5px; }
.palette-hint.current { padding:2px 8px; border-radius:999px; background:var(--accent-soft); color:var(--accent); }
.palette-empty { padding:36px 0; text-align:center; color:var(--text-faint); font-size:13px; }
.palette-foot { display:flex; align-items:center; gap:14px; padding:9px 16px; border-top:1px solid var(--border-subtle); color:var(--text-faint); font-size:11px; }
.palette-foot span { display:flex; align-items:center; gap:4px; }
.palette-foot .grow { flex:1; }
@keyframes palette-fade { from { opacity:0; } to { opacity:1; } }
@keyframes palette-in { from { opacity:0; transform:translateY(-8px) scale(.98); } to { opacity:1; transform:none; } }
@media (max-width:560px) { .palette { padding-top:12px; } .palette-foot { display:none; } }

</style>
  <style>/* /p/css/app/tour.css */
/* first-run guided tour */

.tour { position:fixed; inset:0; z-index:10002; }
.tour-hole { position:absolute; border-radius:16px; box-shadow:0 0 0 2px var(--accent-active), 0 0 0 200vmax rgba(0,0,0,.72); pointer-events:none; transition:left var(--motion-slow) var(--motion), top var(--motion-slow) var(--motion), width var(--motion-slow) var(--motion), height var(--motion-slow) var(--motion), border-radius var(--motion-slow) var(--motion); }
.tour-card { position:absolute; width:min(340px, calc(100% - 32px)); padding:20px 20px 16px; background:var(--surface-1); border:1px solid var(--border-faint); border-radius:18px; box-shadow:0 24px 70px rgba(0,0,0,.55); transition:left var(--motion-slow) var(--motion), top var(--motion-slow) var(--motion); }
.tour-card.in { animation:soft-rise var(--motion-med) var(--motion) both; }
.tour-count { color:var(--text-faint); font-size:11px; margin-bottom:8px; }
.tour-card h2 { font-size:16px; font-weight:500; color:var(--text-white); margin-bottom:6px; }
.tour-card p { color:var(--text-muted); font-size:13px; line-height:1.6; }
.tour-actions { display:flex; gap:8px; margin-top:18px; }
.tour-skip { margin-right:auto; background:transparent; border-color:transparent; color:var(--text-faint); padding:0 6px; }
.tour-skip:hover { background:transparent; border-color:transparent; color:var(--text-primary); }

</style>
</head>
<body>
  <section id="proxy-content">
    <div id="proxy-app"></div>
  </section>

  <div class="wisp-settings-modal hidden" id="wisp-settings-modal">
    <div class="settings-card" role="dialog" aria-modal="true" aria-labelledby="settings-title">
      <aside class="settings-nav" aria-label="settings sections">
        <h2 id="settings-title">settings</h2>
        <button class="settings-nav-item active" data-settings-section="preferences"><span class="settings-nav-icon"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><path d="M4 7h9M17 7h3M4 17h3M11 17h9"/><circle cx="15" cy="7" r="2"/><circle cx="9" cy="17" r="2"/></svg></span><span>general</span></button>
        <button class="settings-nav-item" data-settings-section="appearance"><span class="settings-nav-icon"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="4"/><path d="M12 3v2M12 19v2M3 12h2M19 12h2M5.6 5.6 7 7M17 17l1.4 1.4M5.6 18.4 7 17M17 7l1.4-1.4"/></svg></span><span>appearance</span></button>
        <button class="settings-nav-item" data-settings-section="extensions"><span class="settings-nav-icon"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><path d="M10 4a2 2 0 1 1 4 0v2h4v4h-1.5a2 2 0 1 0 0 4H18v4h-4v-1.5a2 2 0 1 0-4 0V18H6v-4h1.5a2 2 0 1 0 0-4H6V6h4z"/></svg></span><span>extensions</span></button>
        <button class="settings-nav-item" data-settings-section="account"><span class="settings-nav-icon"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="8" r="4"/><path d="M4 20c1.5-3.5 4.5-5 8-5s6.5 1.5 8 5"/></svg></span><span>account</span></button>
        <button class="settings-nav-item" data-settings-section="about"><span class="settings-nav-icon"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M12 11v5M12 8h.01"/></svg></span><span>about</span></button>
        <div class="settings-nav-note" id="settings-save-status">changes save automatically</div>
      </aside>

      <div class="settings-main">
        <button class="close-btn" id="close-wisp-modal" aria-label="close settings">&times;</button>
        <div class="settings-panels">
          <section class="settings-pane" data-settings-pane="preferences">
            <div class="settings-pane-title">general</div>

            <div class="group">
              <div class="group-title">browser</div>
              <div class="row"><div class="row-text"><b>animations</b><small>how much the interface moves</small></div>
                <div class="seg" role="group" aria-label="animations">
                  <button type="button" data-setting-select="motion" data-value="full">full</button>
                  <button type="button" data-setting-select="motion" data-value="subtle">subtle</button>
                  <button type="button" data-setting-select="motion" data-value="off">off</button>
                </div></div>
              <button type="button" class="row setting-toggle" data-setting-toggle="grid"><span class="row-text"><b>grid background</b><small>show the faint grid behind pages</small></span><span class="switch"><i></i></span></button>
              <button type="button" class="row setting-toggle" data-setting-toggle="compact"><span class="row-text"><b>compact toolbar</b><small>tighter tabs and address bar</small></span><span class="switch"><i></i></span></button>
            </div>

            <div class="group">
              <div class="group-title">search</div>
              <div class="row select-row"><div class="row-text"><b>search engine</b><small>used when you type plain text</small></div>
                <select id="search-engine-setting" aria-label="search engine">
                  <option value="duckduckgo">duckduckgo</option>
                  <option value="google">google</option>
                  <option value="bing">bing</option>
                  <option value="brave">brave</option>
                </select></div>
              <div class="row select-row"><div class="row-text"><b>proxy</b><small>switching reloads mochii</small></div>
                <select id="proxy-setting" aria-label="proxy">
                  <option value="scramjet">scramjet</option>
                  <option value="ultraviolet">ultraviolet</option>
                </select></div>
              <div class="row select-row"><div class="row-text"><b>transport</b><small>epoxy is encrypted, libcurl is the fallback. switching reloads mochii</small></div>
                <select id="transport-setting" aria-label="transport">
                  <option value="epoxy">epoxy</option>
                  <option value="libcurl">libcurl</option>
                </select></div>
              <div class="row"><div class="row-text"><b>search history</b><small>recent searches shown in suggestions</small></div>
                <button class="btn" id="clear-history" type="button">clear</button></div>
            </div>

            <div class="group">
              <div class="group-title"><span>blocked</span><button class="btn" id="reset-block-stats" type="button">reset</button></div>
              <div class="block-stats" id="block-stats"></div>
              <button type="button" class="row setting-toggle" data-setting-toggle="blockStats"><span class="row-text"><b>show on home</b><small>the ads and trackers count under your bookmarks</small></span><span class="switch"><i></i></span></button>
            </div>

            <div class="group">
              <div class="group-title">proxy server</div>
              <div class="server-list" id="server-list"></div>
              <div class="custom-input-group">
                <input type="text" id="custom-wisp-input" placeholder="wss://your-server.com/api/" spellcheck="false" aria-label="custom server url">
                <button class="btn primary" id="save-custom-wisp" type="button">add server</button>
              </div>
            </div>

            <div class="group">
              <div class="row"><div class="row-text"><b>reset to defaults</b><small>restores preferences, theme and wallpaper. proxy servers are kept.</small></div>
                <button class="btn" id="reset-settings" type="button">reset</button></div>
            </div>
          </section>

          <section class="settings-pane hidden" data-settings-pane="appearance">
            <div class="settings-pane-title">appearance</div>

            <div class="group">
              <div class="group-title"><span>theme</span><span id="settings-theme-name">default</span></div>
              <div class="theme-list" id="theme-list"></div>
            </div>

            <div class="group">
              <div class="group-title">font</div>
              <div class="row select-row"><div class="row-text"><b>site font</b><small>does not change the websites you browse</small></div>
                <select id="font-setting" aria-label="site font"></select></div>
            </div>

            <div class="group">
              <div class="group-title"><span>wallpaper</span><button class="btn" id="wallpaper-refresh-btn" type="button">refresh</button></div>
              <div class="wallpaper-grid" id="wallpaper-grid"></div>
              <div class="row">
                <div class="row-text"><b>your own image</b><small id="background-name">no background selected</small></div>
                <div class="background-actions">
                  <button class="btn background-btn remove" id="background-remove-btn" type="button">remove</button>
                  <button class="btn background-btn" id="background-upload-btn" type="button">upload</button>
                </div>
                <input id="background-file-input" type="file" accept="image/*" hidden>
              </div>
            </div>
          </section>

          <section class="settings-pane hidden" data-settings-pane="extensions">
            <div class="settings-pane-title">extensions</div>
            <p class="ext-lead">real chrome extensions, straight from the chrome web store. they run inside mochii with their own background, popups and content scripts.</p>

            <div class="group">
              <div class="group-title">installed</div>
              <div id="ext-installed"></div>
            </div>

            <div class="group">
              <div class="group-title">marketplace</div>
              <div class="ext-search"><input type="text" id="ext-market-search" placeholder="search the chrome web store, or paste a store link" spellcheck="false" autocomplete="off" aria-label="search extensions"></div>
              <div class="ext-chips" id="ext-market-cats"></div>
              <div id="ext-market"></div>
            </div>

            <div class="group">
              <div class="group-title">developer</div>
              <div class="row"><div class="row-text"><b>load unpacked</b><small>a .zip or .crx package, or a folder with a manifest.json</small></div>
                <div class="background-actions">
                  <button class="btn" id="extension-upload-zip" type="button">zip / crx</button>
                  <button class="btn" id="extension-upload-folder" type="button">folder</button>
                </div>
                <input id="extension-zip-input" type="file" accept=".zip,.crx,application/zip" hidden>
                <input id="extension-folder-input" type="file" webkitdirectory hidden>
              </div>
            </div>
          </section>

          <section class="settings-pane hidden" data-settings-pane="account">
            <div class="settings-pane-title">account</div>
            <div id="account-body"></div>
            <div class="group">
              <div class="group-title">activity</div>
              <button type="button" class="row setting-toggle" data-setting-toggle="shareActivity"><span class="row-text"><b>show what i'm playing</b><small>puts the game or song you have on your chat profile, like "playing flappy bird" or "listening to blinding lights". needs an account</small></span><span class="switch"><i></i></span></button>
            </div>
          </section>

          <section class="settings-pane hidden" data-settings-pane="about">
            <div class="settings-pane-title">about</div>
            <div class="group">
              <div class="about-logo">mochii</div>
              <p class="about-line">cool web pr0xy, developed by atmoss.</p>
              <p class="about-line">please join the discord!!</p>
              <div class="about-links">
                <a href="https://github.com/atmo1lost" target="_blank" rel="noopener">github</a>
                <a href="https://discord.gg/cmzz7cRqaH" target="_blank" rel="noopener">discord</a>
              </div>
            </div>
            <div class="group">
              <div class="row"><div class="row-text"><b>tour</b><small>a quick walkthrough of where everything is</small></div>
                <button class="btn" id="replay-tour" type="button">take the tour</button></div>
            </div>
          </section>
        </div>
      </div>
    </div>
  </div>

  <div class="extension-surface-modal hidden" id="extension-surface-modal">
    <div class="extension-surface-card" role="dialog" aria-modal="true" aria-labelledby="extension-surface-title">
      <div class="extension-surface-header"><span id="extension-surface-title">extension</span><button class="close-btn" id="extension-surface-close" type="button" aria-label="close">&times;</button></div>
      <div class="extension-surface-body" id="extension-surface-body"></div>
    </div>
  </div>

