  <script>/* p/js/app/utils.js */
// small helpers shared by every other file

const getBasePath = () => {
  const p = __loc.pathname.replace(/[^/]*$/, '');
  return p.endsWith('/') ? p : p + '/';
};
function escapeHtml(value) {
  return String(value).replace(/[&<>'"]/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[ch]));
}

</script>
