    background:color-mix(in srgb,var(--surface-5) 96%,transparent);border:1px solid var(--border-faint);box-shadow:0 0 0 3px color-mix(in srgb,var(--bg-body) 60%,transparent),0 18px 36px -14px rgba(0,0,0,.75)}
  .rail-music.open .rm-pop{display:flex;animation:soft-rise .2s var(--motion) both}
  .rm-now{flex:1;min-width:0;display:flex;align-items:center;gap:10px;height:34px;padding:0 6px;border-radius:10px;text-align:left;transition:background .12s}
