  .card .nm{position:absolute;left:0;right:0;bottom:0;padding:26px 10px 9px;font-size:12px;color:#fff;
    background:linear-gradient(transparent,rgba(0,0,0,.85));white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
  .games-grid{grid-template-columns:repeat(auto-fill,minmax(150px,1fr))}
  .games-grid .card{aspect-ratio:1/1}
  @media (max-width:720px){:root{--bar-h:48px}.acct-pill{top:calc(14px + var(--bar-h) + 10px)}.rail{gap:2px;padding:0 6px;max-width:calc(100% - 24px)}.rail-nav,.rail-foot{gap:2px}.rail-btn{width:38px;height:38px}.rail-btn::after{display:none}.scroll{padding:16px 16px 24px}}
  @media (max-width:560px){.games-grid{grid-template-columns:repeat(auto-fill,minmax(120px,1fr))}}
`;

function baseScript(cfg) {
  const post = m => { if (window.parent !== window) window.parent.postMessage(m, '*'); };
  window.nav = url => post({ type: 'navigate', url });
  window.openTab = url => post({ type: 'gl_open_tab', url });
  window.pick = a => a[Math.floor(Math.random() * a.length)];
  window.bmLoad = () => {
    try { return JSON.parse(localStorage.getItem('gl_shortcuts') || 'null') || cfg.bookmarks; }
    catch { return cfg.bookmarks; }
  };
  window.bmSave = list => { try { localStorage.setItem('gl_shortcuts', JSON.stringify(list)); } catch {} };
  window.favicon = url => {
    try { return 'https://www.google.com/s2/favicons?domain=' + encodeURIComponent(new URL(url).hostname) + '&sz=64'; }
    catch { return ''; }
  };
  document.addEventListener('click', e => {
    const p = e.target.closest('button[data-page]');
    if (p) { e.preventDefault(); if (p.dataset.page !== document.body.dataset.view) post({ type: 'gl_page', page: p.dataset.page }); return; }
    if (e.target.closest('[data-settings]')) post({ type: 'gl_settings' });
    if (e.target.closest('[data-account]')) post({ type: 'gl_settings', section: 'account' });
    if (e.target.closest('[data-discord]')) post({ type: 'gl_discord' });
    // the music tab under the bar: opens a small player, the song opens the music page
    const rm = e.target.closest('.rail-music'), rmOpen = document.querySelector('.rail-music.open');
    if (rmOpen && !rm) { rmOpen.classList.remove('open'); rmOpen.querySelector('.rm-tab').setAttribute('aria-expanded', 'false'); }
    if (rm) {
      const b = e.target.closest('[data-rm]');
      if (b) post({ type: 'gl_music', cmd: b.dataset.rm });
      else if (e.target.closest('.rm-tab')) { const o = rm.classList.toggle('open'); e.target.closest('.rm-tab').setAttribute('aria-expanded', String(o)); }
      else if (e.target.closest('.rm-now')) { rm.classList.remove('open'); post(rm.classList.contains('has-track') ? { type: 'gl_page', page: 'music', route: 'now' } : { type: 'gl_page', page: 'music' }); }
      return;
    }
    if (e.target.closest('[data-rail-toggle]')) { const min = document.body.classList.toggle('rail-min'); if (!document.body.dataset.railTemp) try { localStorage.setItem('mochiiRailMin', min ? '1' : '0'); } catch {} }
  });
  document.querySelectorAll('.searchbar').forEach(sb => {
    const input = sb.querySelector('input');
    if (!input) return;
    const sync = () => sb.classList.toggle('has-value', !!input.value);
    input.addEventListener('input', sync);
    sync();
    const clear = sb.querySelector('[data-clear]');
    if (clear) clear.addEventListener('click', () => { input.value = ''; sync(); input.dispatchEvent(new Event('input', { bubbles: true })); input.focus(); });
  });
  document.addEventListener('keydown', e => {
    if (e.key === 'Escape') { const rm = document.querySelector('.rail-music.open'); if (rm) rm.classList.remove('open'); }
    if ((e.ctrlKey || e.metaKey) && !e.altKey && !e.shiftKey && e.key.toLowerCase() === 'k') { e.preventDefault(); post({ type: 'gl_palette' }); return; }
    if (e.key !== '/' || e.ctrlKey || e.metaKey || e.altKey) return;
    if (/^(input|textarea|select)$/i.test(document.activeElement?.tagName || '')) return;
    const input = document.querySelector('.searchbar input');
    if (input) { e.preventDefault(); input.focus(); }
  });
  const ADAPTIVE_HOME_VARS = [
    '--text-primary','--text-secondary','--text-muted','--text-faint','--text-white',
    '--border-subtle','--border-faint','--accent','--accent-soft','--accent-active',
    '--surface-3','--surface-5','--surface-hover','--search-inset','--search-inset-focus','--on-accent'
  ];
  let baseThemeVars = {};

  function rememberBaseThemeVars(vars) {
    if (!vars || typeof vars !== 'object') return;
    for (const key of ADAPTIVE_HOME_VARS) {
      if (vars[key]) baseThemeVars[key] = vars[key];
    }
  }

  function restoreBaseThemeVars() {
    const r=document.documentElement;
    for (const key of ADAPTIVE_HOME_VARS) {
      if (baseThemeVars[key]) r.style.setProperty(key, baseThemeVars[key]);
      else r.style.removeProperty(key);
    }
    document.body.classList.remove('home-wallpaper-light','home-wallpaper-medium');
  }

  let bgToken = 0;
  function applyAdaptiveContrast(value) {
    const token = ++bgToken;
    if (document.body.dataset.view !== 'home') return;
    const v = String(value || '');
    if (!v) { restoreBaseThemeVars(); return; }

    const img = new Image();
    img.onload = () => {
      // a newer background was picked while this one loaded (e.g. settings sync on login), drop it
      if (token !== bgToken) return;
      try {
        const size=32, canvas=document.createElement('canvas');
        canvas.width=size; canvas.height=size;
        const ctx=canvas.getContext('2d',{willReadFrequently:true});
        ctx.drawImage(img,0,0,size,size);
        const pixels=ctx.getImageData(0,0,size,size).data;
        let lum=0, count=0;
        for(let i=0;i<pixels.length;i+=4){
          const r=pixels[i]/255, g=pixels[i+1]/255, b=pixels[i+2]/255;
          const rl=r<=.04045?r/12.92:Math.pow((r+.055)/1.055,2.4);
          const gl=g<=.04045?g/12.92:Math.pow((g+.055)/1.055,2.4);
          const bl=b<=.04045?b/12.92:Math.pow((b+.055)/1.055,2.4);
          lum += .2126*rl + .7152*gl + .0722*bl;
          count++;
        }
        const luminance=count ? lum/count : .18;
        const light=luminance>.56;
        const medium=luminance>.38 && !light;
        const r=document.documentElement;

        document.body.classList.toggle('home-wallpaper-light',light);
        document.body.classList.toggle('home-wallpaper-medium',medium);

        if(light){
          const set=(k,val)=>r.style.setProperty(k,val);
          set('--text-primary','#101010');
          set('--text-secondary','#202020');
          set('--text-muted','#363636');
          set('--text-faint','#505050');
          set('--text-white','#0a0a0a');
          set('--border-subtle','rgba(0,0,0,.12)');
          set('--border-faint','rgba(0,0,0,.20)');
          set('--accent','#101010');
          set('--on-accent','#fafafa');
          set('--accent-soft','rgba(0,0,0,.08)');
          set('--accent-active','rgba(0,0,0,.12)');
          set('--surface-3','rgba(255,255,255,.76)');
          set('--surface-5','rgba(255,255,255,.88)');
          set('--surface-hover','rgba(255,255,255,.94)');
          set('--search-inset','rgba(255,255,255,.80)');
          set('--search-inset-focus','rgba(255,255,255,.92)');
        }else{
          restoreBaseThemeVars();
          document.body.classList.toggle('home-wallpaper-light',light);
          document.body.classList.toggle('home-wallpaper-medium',medium);
        }

        const overlay = light ? .48 : medium ? .38 : .28;
        document.body.style.backgroundImage=`linear-gradient(rgba(0,0,0,${overlay}),rgba(0,0,0,${overlay})),url("${v.replace(/"/g, '\\"')}")`;
      } catch {
        document.body.style.backgroundImage=`linear-gradient(rgba(0,0,0,.28),rgba(0,0,0,.28)),url("${v.replace(/"/g, '\\"')}")`;
      }
    };
    img.src=v;
  }

  let bg3d = null;
  function setBg3d(on) {
    if (!bg3d) {
      bg3d = document.createElement('canvas');
      bg3d.style.cssText = 'position:fixed;inset:0;width:100%;height:100%;z-index:-1;pointer-events:none';
      document.body.insertBefore(bg3d, document.body.firstChild);
      const ctx = bg3d.getContext('2d');
      const still = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const rings = 9, segs = 28;
      let t = 0, last = 0;
      const draw = now => {
        requestAnimationFrame(draw);
        if (bg3d.style.display === 'none' || document.hidden || now - last < 33) return;
        last = now;
        const w = bg3d.width = innerWidth, h = bg3d.height = innerHeight;
        ctx.clearRect(0, 0, w, h);
        const accent = getComputedStyle(document.documentElement).getPropertyValue('--accent').trim() || '#ffffff';
        const r = Math.min(w, h) * 0.46, cx = w * 0.5, cy = h * 0.52, cam = r * 4.2;
        const ay = t, ax = 0.45;
        const pt = (i, j) => {
          const lat = (i / rings) * Math.PI - Math.PI / 2, lon = (j / segs) * Math.PI * 2;
          let x = Math.cos(lat) * Math.cos(lon), y = Math.sin(lat), z = Math.cos(lat) * Math.sin(lon);
          const x1 = x * Math.cos(ay) - z * Math.sin(ay), z1 = x * Math.sin(ay) + z * Math.cos(ay);
          const y2 = y * Math.cos(ax) - z1 * Math.sin(ax), z2 = y * Math.sin(ax) + z1 * Math.cos(ax);
          const k = cam / (cam + z2 * r);
          return [cx + x1 * r * k, cy + y2 * r * k, z2];
        };
        ctx.lineWidth = 1;
        ctx.strokeStyle = accent;
        for (let i = 1; i < rings; i++) {
          ctx.beginPath();
          for (let j = 0; j <= segs; j++) { const q = pt(i, j % segs); j ? ctx.lineTo(q[0], q[1]) : ctx.moveTo(q[0], q[1]); }
          ctx.globalAlpha = 0.07;
          ctx.stroke();
        }
        for (let j = 0; j < segs; j += 2) {
          ctx.beginPath();
          for (let i = 0; i <= rings; i++) { const q = pt(i, j); i ? ctx.lineTo(q[0], q[1]) : ctx.moveTo(q[0], q[1]); }
          ctx.globalAlpha = 0.07;
          ctx.stroke();
        }
        ctx.globalAlpha = 1;
        if (!still) t += 0.0026;
      };
      requestAnimationFrame(draw);
    }
    bg3d.style.display = on ? 'block' : 'none';
  }

  function applyCustomBackground(value) {
    const v = String(value || '');
    setBg3d(!v);
    document.body.classList.toggle('has-wallpaper', !!v);
    if (!v) {
      document.body.style.backgroundImage = '';
      document.body.style.backgroundSize = '';
      document.body.style.backgroundPosition = '';
      document.body.style.backgroundRepeat = '';
      document.body.style.backgroundAttachment = '';
      applyAdaptiveContrast('');
      return;
    }
    document.body.style.backgroundSize = 'cover';
    document.body.style.backgroundPosition = 'center';
    document.body.style.backgroundRepeat = 'no-repeat';
    document.body.style.backgroundAttachment = 'fixed';
    applyAdaptiveContrast(v);
  }

  const initialStyle = getComputedStyle(document.documentElement);
  const initialVars = {};
  ADAPTIVE_HOME_VARS.forEach(key => { initialVars[key] = initialStyle.getPropertyValue(key).trim(); });
  rememberBaseThemeVars(initialVars);
  try { applyCustomBackground(localStorage.getItem('mochiiBackground') || ''); } catch {}
  window.addEventListener('message', e => {
    if (!e.data) return;
    if (e.data.type === 'GHOSTLINK_NT_THEME') {
      rememberBaseThemeVars(e.data.vars || {});
      const r = document.documentElement;
      for (const [k, v] of Object.entries(e.data.vars || {})) if (v) r.style.setProperty(k, v);
      applyAdaptiveContrast(localStorage.getItem('mochiiBackground') || '');
    }
    if (e.data.type === 'GHOSTLINK_NT_BACKGROUND') applyCustomBackground(e.data.background || '');
    if (e.data.type === 'GHOSTLINK_NT_ACCOUNT') {
      const pill = document.querySelector('.acct-pill'); if (!pill) return;
      const a = e.data.account, pic = pill.querySelector('.acct-pill-pic');
      pill.hidden = !a; if (!a) return;
      pill.querySelector('.acct-pill-name').textContent = a.name || 'account';
      pill.setAttribute('aria-label', 'account: ' + (a.name || 'account'));
      pic.textContent = ''; pic.style.background = a.color || '';
      if (a.image) { const img = document.createElement('img'); img.src = a.image; img.alt = ''; pic.appendChild(img); }
      else pic.textContent = a.emoji || (a.name || '?').charAt(0);
    }
    if (e.data.type === 'GHOSTLINK_NT_MUSIC') {
      const rm = document.querySelector('.rail-music'); if (!rm) return;
      const s = e.data.state || {}, t = s.track;
      rm.classList.toggle('has-track', !!t); rm.classList.toggle('playing', !!(t && s.playing));
      rm.querySelector('.rm-txt b').textContent = t ? t.title : 'nothing playing';
      rm.querySelector('.rm-txt small').textContent = !t ? 'open music' : s.loading ? 'loading...' : s.error ? s.error : t.artist || '';
      const img = rm.querySelector('.rm-cov img'), cover = (t && t.cover) || '';
      if (img.dataset.src !== cover) {
        img.dataset.src = cover; img.hidden = !cover; if (cover) img.src = cover; else img.removeAttribute('src');
        // covers that the network blocks come through the proxy instead
        img.onerror = () => { if (img.dataset.tried === img.dataset.src) { img.hidden = true; return; } img.dataset.tried = img.dataset.src; post({ type: 'gl_music_api', id: 'rail', op: 'img', args: { url: img.dataset.src } }); };
      }
    }
    if (e.data.type === 'GHOSTLINK_MUSIC_API' && e.data.id === 'rail') { const img = document.querySelector('.rail-music .rm-cov img'); if (img && e.data.data) img.src = e.data.data; }
  });
  post({ type: 'GHOSTLINK_NT_READY' });
}

function pageShell(cfg, title, body, script, css = '') {
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>${title} | mochii!</title>${window.__fontHead || ''}<link rel="stylesheet" href="${FONT_LINK}"><style>${PAGE_CSS}${css}</style>
<script>(function(){var r=document.documentElement,t=${JSON.stringify(readThemeVars())};for(var k in t)if(t[k])r.style.setProperty(k,t[k]);})();<\/script>
</head><body data-view="${title}">${body}
<script>window.attachSuggest=${attachSuggest.toString()};<\/script>
<script>window.__CFG=${JSON.stringify(cfg)};(${baseScript.toString()})(window.__CFG);<\/script>
<script>(${script.toString()})(window.__CFG);<\/script></body></html>`;
}

// on chat and ai the bar can tuck away so the page gets the full height (state is shared, starts hidden).
// on games it tucks away only while a game is open (the page turns it on, and it isn't saved)
const RAIL_COLLAPSIBLE = ['chat', 'ai'], RAIL_TEMP = ['games'];
function topbar(active, cfg, brand) {
  const auto = RAIL_COLLAPSIBLE.includes(active), fold = auto || RAIL_TEMP.includes(active), chev = d => `<svg viewBox="0 0 24 24" width="${d ? 16 : 20}" height="${d ? 16 : 20}" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${d ? 'm6 9 6 6 6-6' : 'm18 15-6-6-6 6'}"/></svg>`;
  const item = (p, label) => `<button class="rail-btn${active === p ? ' on' : ''}" type="button" data-page="${p}" data-tip="${label}" aria-label="${label}"${active === p ? ' aria-current="page"' : ''}>${pgIcon(p, 20)}</button>`;
  return `<aside class="rail"><nav class="rail-nav" aria-label="pages">${item('home', 'home')}${item('games', 'games')}${item('music', 'music')}${item('chat', 'chat')}${cfg.noAi ? '' : item('ai', 'ai chat')}</nav><div class="rail-foot"><button class="rail-btn" type="button" data-discord data-tip="discord" aria-label="discord">${pgIcon('discord', 20)}</button><button class="rail-btn" type="button" data-settings data-tip="settings" aria-label="settings">${pgIcon('settings', 20)}</button>${fold ? `<button class="rail-btn" type="button" data-rail-toggle data-tip="hide bar" aria-label="hide bar">${chev(0)}</button>` : ''}</div><div class="rail-music"><button class="rm-tab" type="button" aria-label="music player" aria-expanded="false" title="music">${pgIcon('music', 13)}</button><div class="rm-pop" role="group" aria-label="now playing"><button class="rm-now" type="button"><span class="rm-cov">${pgIcon('music', 16)}<img alt="" hidden></span><span class="rm-txt"><b>nothing playing</b><small>open music</small></span></button><span class="rm-ctl"><button type="button" data-rm="prev" aria-label="previous">${pgIcon('prevo', 16)}</button><button type="button" data-rm="toggle" aria-label="play or pause"><span class="i-play">${pgIcon('playo', 16)}</span><span class="i-pause">${pgIcon('pauseo', 16)}</span></button><button type="button" data-rm="next" aria-label="next">${pgIcon('nexto', 16)}</button></span></div></div></aside>${fold ? `<button class="rail-tab" type="button" data-rail-toggle aria-label="show bar">${chev(1)}</button>${auto ? `<script>(function(b){b.classList.add('rail-collapsible');var v;try{v=localStorage.getItem('mochiiRailMin')}catch(e){}if(v!=='0')b.classList.add('rail-min')})(document.body)<\/script>` : ''}` : ''}<button class="acct-pill" type="button" data-account aria-label="account" hidden><span class="acct-pill-pic"></span><span class="acct-pill-name"></span></button>`;
}

</script>
  <script>/* p/js/app/pages/home.js */
// home page: clock, search bar and bookmark dock

function pageHome(cfg) {
  const css = `
    .center{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:var(--bar-space) 28px 24px;overflow:auto}
    @media (max-width:720px){.center{padding:var(--bar-space) 16px 24px}}
    .center>*{flex:0 0 auto;animation:soft-rise var(--motion-slow) var(--motion) both}
    .center > .home-time{animation-delay:.05s}
    .center > .home-search{animation-delay:.09s}
    .center > .bm{animation-delay:.14s}
    .home-time{
      color:var(--text-white);
      font-family:var(--font),'Lexend',sans-serif;
      font-size:clamp(64px,12vw,112px);
      line-height:.9;
      font-weight:300;
      letter-spacing:-.045em;
      font-variant-numeric:tabular-nums;
      text-shadow:0 0 22px color-mix(in srgb,var(--accent) 18%,transparent),0 4px 30px rgba(0,0,0,.25);
    }
    .home-time .colon{display:inline-block;opacity:.55;margin:0 .02em;animation:clock-tick 2s steps(1,end) infinite}
    @keyframes clock-tick{0%{opacity:.7}50%{opacity:.35}}
    .home-greet{margin:14px 0 30px;color:var(--text-primary);font-size:15px;letter-spacing:.01em;text-shadow:0 1px 3px rgba(0,0,0,.45),0 2px 16px rgba(0,0,0,.4)}
    .home-greet b{font-weight:500;color:var(--text-primary)}
    .home-greet span{color:var(--text-secondary);opacity:.8}
    body.home-wallpaper-light .home-greet{text-shadow:none}
    .center > .home-greet{animation-delay:.07s}
    .home-search{width:min(520px,100%)}
    .bm{width:min(560px,100%);margin-top:30px;padding-bottom:28px;display:flex;flex-direction:column;align-items:center;gap:14px}
    .dock{display:flex;flex-wrap:wrap;justify-content:center;gap:10px}
    .dock-item,.dock-add{position:relative;width:54px;height:54px;display:flex;align-items:center;justify-content:center;border-radius:18px;transition:background .12s,border-color .12s,transform .12s}
    .dock-item{background:var(--surface-3);border:1px solid var(--border-subtle);color:var(--text-secondary);font-size:16px;cursor:pointer}
    .dock-item:hover{background:var(--surface-5);border-color:var(--border-faint);transform:translateY(-3px)}
    .dock-item:focus-visible,.dock-add:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
    .dock-item img{width:26px;height:26px;object-fit:contain;border-radius:6px}
    .dock-item::after{content:attr(data-tip);position:absolute;top:calc(100% + 8px);left:50%;transform:translate(-50%,-3px);max-width:140px;padding:5px 9px;border-radius:8px;background:var(--surface-5);border:1px solid var(--border-faint);color:var(--text-white);font-size:11px;line-height:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;opacity:0;pointer-events:none;z-index:3;transition:opacity .12s,transform .12s}
    .dock-item:hover::after,.dock-item:focus-visible::after{opacity:1;transform:translate(-50%,0)}
    .dock-item .rm{position:absolute;top:-6px;right:-6px;width:20px;height:20px;display:none;align-items:center;justify-content:center;border-radius:50%;background:var(--surface-hover);border:1px solid var(--border-faint);color:var(--text-white);font-size:13px;line-height:1;z-index:4}
    .dock-item:hover .rm,.dock-item:focus-within .rm{display:flex}
    @media (hover:none){.dock-item .rm{display:flex}}
    @media (max-width:420px){.dock{gap:8px}.dock-item,.dock-add{width:48px;height:48px;border-radius:16px}.dock-item img{width:24px;height:24px}}
    .dock-add{border:1px dashed var(--border-faint);color:var(--text-faint);background:transparent;cursor:pointer}
    .dock-add:hover,.dock-add.on{border-color:var(--text-muted);color:var(--text-white);background:var(--accent-soft)}
    .add-form{display:none;gap:8px;width:100%}
    .add-form.open{display:flex}
    .add-form input{flex:1;min-width:0;height:40px;padding:0 14px;border-radius:13px;border:1px solid var(--border-subtle);background:var(--input);outline:none;font-size:13px;text-transform:none}
    .add-form input[name=label]{flex:0 1 130px}
    .add-form input:focus{border-color:var(--border-faint);box-shadow:0 0 0 3px var(--accent-soft)}
    .add-form button{height:40px;padding:0 18px;border-radius:13px;background:var(--accent);color:var(--on-accent);font-size:13px}
    .shield{display:none;align-items:center;gap:8px;margin-top:4px;padding:7px 13px 7px 11px;border-radius:999px;border:1px solid var(--border-subtle);background:var(--surface-3);color:var(--text-secondary);font-size:12px;cursor:pointer;transition:border-color .12s,color .12s}
    .shield.on{display:inline-flex}
    .shield:hover{background:var(--surface-5);border-color:var(--border-faint);color:var(--text-primary)}
    .shield svg{color:var(--accent);flex:0 0 auto}
    .shield b{font-weight:500;color:var(--text-white);font-variant-numeric:tabular-nums}
    .shield i{width:3px;height:3px;border-radius:50%;background:currentColor;opacity:.5}
    @media (max-width:560px){.add-form{flex-wrap:wrap}.add-form input[name=label]{flex:1 1 100%}.add-form input[name=url]{flex:1 1 0}}
  `;
  const body = `${topbar('home', cfg)}
    <main class="center">
      <div class="home-time" id="home-time" aria-label="current time"></div>
      <div class="home-greet" id="home-greet"></div>
      <form class="searchbar home-search" id="f"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round">${PG_ICONS.search}</svg>
        <input id="q" type="text" autocomplete="off" spellcheck="false" aria-label="search or url">
        <kbd class="sb-kbd" aria-hidden="true">/</kbd>
        <button class="sb-btn" type="submit" aria-label="search"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg></button></form>
      <section class="bm" aria-label="bookmarks">
        <div class="dock" id="bm"></div>
        <button class="shield" id="shield" type="button" aria-label="blocked ads and trackers"></button>
        <form class="add-form" id="add"><input name="label" placeholder="name" spellcheck="false" autocomplete="off" aria-label="bookmark name"><input name="url" placeholder="url" spellcheck="false" autocomplete="off" aria-label="bookmark url"><button type="submit">add</button></form>
      </section>
    </main>`;
  const script = function (cfg) {
    const q = document.getElementById('q');
    const clock = document.getElementById('home-time');

    const greet = document.getElementById('home-greet');
    let last = '';
    const updateClock = () => {
      const d = new Date(), h = d.getHours(), pad = n => String(n).padStart(2, '0');
      const key = `${h}:${d.getMinutes()}:${d.getDate()}`;
      if (key === last) return;
      last = key;
      clock.innerHTML = `${pad(h)}<span class="colon">:</span>${pad(d.getMinutes())}`;
      clock.setAttribute('aria-label', `${pad(h)}:${pad(d.getMinutes())}`);
      const part = h < 5 ? 'good night' : h < 12 ? 'good morning' : h < 18 ? 'good afternoon' : 'good evening';
      const date = d.toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long' }).toLowerCase();
      greet.innerHTML = `<b>${part}</b> <span>&middot; ${date}</span>`;
    };

    updateClock();
    setInterval(updateClock, 1000);

    q.placeholder = 'search or enter url';
    const sg = attachSuggest(q, v => nav(v));
    document.getElementById('f').addEventListener('submit', e => {
      e.preventDefault();
      sg.close();
      const v = q.value.trim();
      if (v) nav(v);
    });
    const grid = document.getElementById('bm');
    const form = document.getElementById('add');
    function render() {
      grid.innerHTML = '';
      bmLoad().forEach((b, i) => {
        const t = document.createElement('div');
        t.className = 'dock-item';
        t.setAttribute('role', 'link');
        t.tabIndex = 0;
        t.dataset.tip = b.label;
        t.setAttribute('aria-label', b.label);
        const im = document.createElement('img');
        im.alt = '';
        im.src = favicon(b.url);
        im.onerror = () => { im.remove(); t.insertBefore(document.createTextNode((b.label || '?')[0]), t.firstChild); };
        const rm = document.createElement('button');
        rm.className = 'rm';
        rm.type = 'button';
        rm.setAttribute('aria-label', 'remove ' + b.label);
        rm.textContent = '\u00d7';
        rm.onclick = e => { e.stopPropagation(); const l = bmLoad(); l.splice(i, 1); bmSave(l); render(); };
        t.append(im, rm);
        t.onclick = () => nav(b.url);
        t.onkeydown = e => { if (e.target === t && e.key === 'Enter') nav(b.url); };
        grid.appendChild(t);
      });
      const add = document.createElement('button');
      add.type = 'button';
      add.className = 'dock-add' + (form.classList.contains('open') ? ' on' : '');
      add.setAttribute('aria-label', 'add bookmark');
      add.innerHTML = '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round"><path d="M12 5v14M5 12h14"/></svg>';
      add.onclick = () => {
        const open = form.classList.toggle('open');
        add.classList.toggle('on', open);
        if (open) form.elements.url.focus(); else q.focus();
      };
      grid.appendChild(add);
    }
    form.addEventListener('keydown', e => {
      if (e.key === 'Escape') { form.classList.remove('open'); render(); q.focus(); }
    });
    form.addEventListener('submit', e => {
      e.preventDefault();
      const f = e.target;
      let url = f.url.value.trim();
      const label = f.label.value.trim();
      if (!url) return;
      if (!/^https?:\/\//i.test(url)) url = 'https://' + url;
      let host = label;
      try { host = label || new URL(url).hostname.replace(/^www\./, ''); } catch { return; }
      const l = bmLoad();
      l.push({ label: host, url });
      bmSave(l);
      f.reset();
      form.classList.remove('open');
      render();
    });
    render();

    // blocked ads and trackers. the totals are kept in localStorage by mochii, and the storage event fires here when they change
    const shield = document.getElementById('shield');
    const fmt = n => Number(n || 0).toLocaleString('en-GB');
    function renderShield() {
      let s = null, on = true;
      try { s = JSON.parse(localStorage.getItem('mochiiBlocked') || 'null'); on = localStorage.getItem('mochiiSetting:blockStats') !== 'false'; } catch {}
      shield.classList.toggle('on', on);
      if (!on) return;
      shield.innerHTML = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3 5 6v5c0 4.5 3 8.3 7 9.5 4-1.2 7-5 7-9.5V6l-7-3Z"/><path d="m9 12 2 2 4-4"/></svg><span><b>${fmt(s && s.ads)}</b> ads</span><i></i><span><b>${fmt(s && s.trackers)}</b> trackers blocked</span>`;
    }
    shield.onclick = () => { if (window.parent !== window) window.parent.postMessage({ type: 'gl_settings', section: 'preferences' }, '*'); };
    window.addEventListener('storage', e => { if (!e.key || e.key === 'mochiiBlocked' || e.key === 'mochiiSetting:blockStats') renderShield(); });
    renderShield();
    q.focus();
  };
  return pageShell(cfg, 'home', body, script, css);
}

</script>
  <script>/* p/js/app/pages/games.js */
// games page: gn-math + lumin catalogues and the in-page player

function pageGames(cfg) {
  const css = `
    .player{position:absolute;inset:var(--bar-space) 0 0 0;z-index:20;display:none;flex-direction:column;background:var(--bg-body);transition:top var(--motion-slow) var(--motion)}
    .player.open{display:flex}
    .p-loading{display:none;z-index:2;background:var(--bg-body);position:absolute;top:50px;right:0;bottom:0;left:0;flex-direction:column;align-items:center;justify-content:center;gap:12px;color:var(--text-muted);font-size:12px}
    .player.loading .p-loading{display:flex}
    .p-spin{width:22px;height:22px;border-radius:50%;border:2px solid var(--border-faint);border-top-color:var(--accent);animation:pspin .8s linear infinite}
    @keyframes pspin{to{transform:rotate(360deg)}}
    .p-bar{display:flex;align-items:center;gap:8px;padding:10px 14px;border-bottom:1px solid var(--border-subtle);background:var(--surface-0)}
    .p-title{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:13px;color:var(--text-secondary)}
    .fav{position:absolute;top:6px;right:6px;z-index:1;width:28px;height:28px;border-radius:9px;display:flex;align-items:center;justify-content:center;font-size:15px;line-height:1;background:rgba(0,0,0,.55);color:#fff;opacity:0;transition:opacity .12s,color .12s}
    .card:hover .fav,.fav.on,.fav:focus-visible{opacity:1}
    .fav.on{color:#ffd24a}
    .favtog{align-self:center;font-size:12px;padding:5px 12px;border-radius:99px;background:var(--surface-3);border:1px solid var(--border-subtle);color:var(--text-muted)}
    .favtog.on{color:#ffd24a;border-color:#ffd24a}
    .player iframe{flex:1;width:100%;border:0;background:#000}
  `;
  const body = `${topbar('games', cfg)}
    <div class="scroll" id="scroll"><div class="wrap">
      <div class="tools">
        <div class="searchbar"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round">${PG_ICONS.search}</svg>
          <input id="q" type="text" placeholder="search games" autocomplete="off" spellcheck="false" aria-label="search games">
          <kbd class="sb-kbd" aria-hidden="true">/</kbd>
          <button class="sb-btn" type="button" data-clear aria-label="clear search">${pgIcon('close', 16)}</button></div>
        <div class="status" id="status">loading games...</div>
        <button class="favtog" id="favtog" type="button">★ favourites</button>
      </div>
      <div class="grid games-grid" id="grid"></div>
      <div id="sentinel" style="height:1px"></div>
    </div></div>
    <div class="player" id="player">
      <div class="p-bar"><span class="p-title" id="ptitle"></span>
        <button class="icon-btn" id="pfull" title="fullscreen" aria-label="fullscreen">${pgIcon('full', 16)}</button>
        <button class="icon-btn" id="pclose" title="close" aria-label="close">${pgIcon('close', 16)}</button></div>
      <iframe id="pframe" sandbox="allow-scripts allow-same-origin allow-forms allow-modals allow-pointer-lock allow-downloads" allow="autoplay; fullscreen; pointer-lock; gamepad; clipboard-write" allowfullscreen></iframe>
      <div class="p-loading"><div class="p-spin"></div><span>loading game</span></div>
    </div>`;
  const script = async function (cfg) {
    const $ = id => document.getElementById(id);
    const grid = $('grid'), status = $('status'), q = $('q');
    const CHUNK = 90;
    let all = [], view = [], shown = 0, luminBoot = null;
    let loaded = false, dirty = false, filterTimer = null, playToken = 0;
    const seen = new Set();
    // favourites are stored by normalised name so they survive catalogue refreshes
    const FAV_KEY = 'mochiiGameFavs';
    let favs = new Set(), favOnly = false;
    try { favs = new Set(JSON.parse(localStorage.getItem(FAV_KEY)) || []); } catch {}
    const norm = s => String(s).toLowerCase().replace(/[^a-z0-9]/g, '');
    const saveFavs = () => { try { localStorage.setItem(FAV_KEY, JSON.stringify([...favs])); } catch {} };
    // the catalogue is cached, so the grid fills straight away and refreshes in the background.
    // until the fresh list lands, cached lumin icons can 404 (their tokens are signed) and fall back to the letter
    const CACHE_KEY = 'mochiiGames';
    let cache = null;
    try { cache = JSON.parse(localStorage.getItem(CACHE_KEY)); } catch {}
    if (!Array.isArray(cache?.gn) || !Array.isArray(cache?.lumin)) cache = null;
    const fresh = { gn: null, lumin: null };
    const live = list => { if (!cache) add(list); };

    function add(list) {
      for (const g of list) {
        const k = norm(g.name);
        if (!k || seen.has(k)) continue;
        seen.add(k);
        all.push(g);
        dirty = true;
      }
      if (!filterTimer) filterTimer = setTimeout(() => { filterTimer = null; applyFilter(true); }, 150);
    }

    function updateStatus() {
      status.textContent = view.length + (view.length === 1 ? ' game' : ' games') + (q.value.trim() ? ' found' : '') + (loaded ? '' : ' (loading...)');
    }

    function applyFilter(keep) {
      if (dirty) { all.sort((a, b) => a.name.localeCompare(b.name)); dirty = false; }
      const s = q.value.trim().toLowerCase();
      view = all.filter(g => (!s || g.name.toLowerCase().includes(s)) && (!favOnly || favs.has(norm(g.name))));
      if (favs.size && !favOnly) view = view.filter(g => favs.has(norm(g.name))).concat(view.filter(g => !favs.has(norm(g.name))));
      const target = keep ? Math.max(shown, CHUNK) : CHUNK;
      for (const c of grid.children) if (c._g) io.unobserve(c);
      grid.innerHTML = '';
      shown = 0;
      more(target);
      updateStatus();
      if (!view.length && loaded) grid.innerHTML = '<div class="empty">' + (favOnly && !q.value.trim() ? 'no favourites yet, star a game to add it' : 'no games found!!! report to discord') + '</div>';
    }

    const io = new IntersectionObserver(entries => {
      for (const e of entries) {
        if (!e.isIntersecting) continue;
        io.unobserve(e.target);
        loadImg(e.target);
      }
    }, { root: $('scroll'), rootMargin: '300px' });

    async function loadImg(card) {
      const g = card._g, img = card.querySelector('img');
      try {
        if (g.src === 'gn') img.src = g.cover;
        else { await bootLumin(); img.src = await Lumin.getImageUrl(g.token); }
      } catch { img.remove(); }
    }

    function more(limit = CHUNK) {
      const end = Math.min(shown + limit, view.length);
      for (; shown < end; shown++) {
        const g = view[shown];
        const c = document.createElement('div');
        c.className = 'card';
        c.setAttribute('role', 'button');
        c.tabIndex = 0;
        c._g = g;
        const ph = document.createElement('div');
        ph.className = 'ph';
        ph.textContent = g.name[0] || '?';
        const im = document.createElement('img');
        im.alt = '';
        im.loading = 'lazy';
        im.onerror = () => im.remove();
        const nm = document.createElement('div');
        nm.className = 'nm';
        nm.textContent = g.name;
        const fv = document.createElement('button');
        fv.type = 'button';
        fv.className = 'fav' + (favs.has(norm(g.name)) ? ' on' : '');
        fv.textContent = '★';
        fv.setAttribute('aria-label', 'favourite');
        fv.onclick = e => {
          e.stopPropagation();
          const k = norm(g.name);
          if (favs.has(k)) favs.delete(k); else favs.add(k);
          saveFavs();
          fv.classList.toggle('on', favs.has(k));
          if (favOnly && !favs.has(k)) applyFilter(true);
        };
        fv.onkeydown = e => e.stopPropagation();
        c.append(ph, im, nm, fv);
        c.onclick = () => play(g);
        c.onkeydown = e => { if (e.key === 'Enter') play(g); };
        grid.appendChild(c);
        io.observe(c);
      }
    }

    new IntersectionObserver(es => { if (es[0].isIntersecting && shown < view.length) more(); }, { root: $('scroll'), rootMargin: '600px' })
      .observe($('sentinel'));

    $('favtog').onclick = e => { favOnly = !favOnly; e.currentTarget.classList.toggle('on', favOnly); applyFilter(false); };
    let t;
    q.addEventListener('input', () => { clearTimeout(t); t = setTimeout(() => applyFilter(false), 120); });

    const player = $('player'), pframe = $('pframe');
    let playing = false, loadTimer = 0;
    // the topbar slides up while a game is open (the tab at the top brings it back) and returns when it closes
    function tuckBar(on) { const b = document.body; b.classList.toggle('rail-collapsible', on); b.classList.toggle('rail-min', on); if (on) b.dataset.railTemp = '1'; else delete b.dataset.railTemp; }
    function armLoad() { clearTimeout(loadTimer); loadTimer = setTimeout(() => player.classList.remove('loading'), 12000); }
    // tells mochii what's being played, so the chat profile can show it like a discord activity (null clears it)
    function activity(g, cover) { try { window.parent.postMessage({ type: 'gl_activity', game: g ? { name: g.name, cover: /^https:\/\//.test(cover || '') ? cover : '' } : null }, '*'); } catch {} }
    async function coverOf(g) { try { if (g.src === 'gn') return g.cover; await bootLumin(); return await Lumin.getImageUrl(g.token); } catch { return ''; } }
    window.addEventListener('pagehide', () => { if (playing) activity(null); });
    function closePlayer() { if (playing) activity(null); playToken++; playing = false; clearTimeout(loadTimer); player.classList.remove('open', 'loading'); tuckBar(false); pframe.removeAttribute('srcdoc'); pframe.src = 'about:blank'; }
    pframe.addEventListener('load', () => { if (playing) { clearTimeout(loadTimer); player.classList.remove('loading'); } });

    $('pclose').onclick = closePlayer;
    $('pfull').onclick = () => { (pframe.requestFullscreen || pframe.webkitRequestFullscreen || (() => {})).call(pframe); };
    document.addEventListener('keydown', e => { if (e.key === 'Escape' && player.classList.contains('open')) closePlayer(); });

    async function play(g) {
      const token = ++playToken;
      $('ptitle').textContent = g.name;
      coverOf(g).then(c => { if (token === playToken) activity(g, c); });
      try {
        if (g.src === 'gn') {
          playing = true;
          player.classList.add('open', 'loading'); tuckBar(true);
          // gn-math files carry an ad loader that reaches into window.parent, so they load cross origin
          // (never srcdoc, which would give them mochii's origin and let the ads into the app)
          pframe.removeAttribute('srcdoc');
          pframe.src = g.url.replace('{COVER_URL}', cfg.gn.cover).replace('{HTML_URL}', cfg.gn.html);
          armLoad();
        } else {
          playing = true;
          player.classList.add('open', 'loading'); tuckBar(true);
          await bootLumin();
          const { url } = await Lumin.getGameUrl(g.id);
          if (token !== playToken) return;
          pframe.removeAttribute('srcdoc');
          pframe.src = url;
          armLoad();
        }
      } catch (err) {
        if (token !== playToken) return;
        closePlayer();
        status.textContent = 'could not load ' + g.name;
      }
    }

    async function loadGn() {
      const zones = await (await fetch(cfg.gn.zones + '?t=' + Date.now())).json();
      const list = zones.slice(1).filter(z => z && z.name && z.url && !z.name.startsWith('[!]')).map(z => ({
        src: 'gn', id: z.id, name: z.name, url: z.url,
        cover: String(z.cover || '').replace('{COVER_URL}', cfg.gn.cover).replace('{HTML_URL}', cfg.gn.html)
      }));
      fresh.gn = list;
      live(list);
    }

    function bootLumin() {
      return luminBoot || (luminBoot = new Promise((res, rej) => {
        const s = document.createElement('script');
        s.src = cfg.luminScript;
        s.onload = res;
        s.onerror = () => rej(new Error('lumin script blocked'));
        document.head.appendChild(s);
      }).then(() => Lumin.init({ headless: true })));
    }

    async function loadLumin() {
      await bootLumin();
      const first = await Lumin.getGames({ page: 1, limit: 100 });
      const map = r => r.games.map(g => ({ src: 'lumin', id: g.id, name: g.name, token: g.image_token }));
      const lumin = map(first);
      live(lumin);
      for (let p = 2; p <= (first.pages || 1); p++) {
        const list = map(await Lumin.getGames({ page: p, limit: 100 }));
        lumin.push(...list);
        live(list);
      }
      fresh.lumin = lumin;
    }

    if (cache) { add(cache.gn.concat(cache.lumin)); loaded = true; clearTimeout(filterTimer); filterTimer = null; applyFilter(true); }
    const results = await Promise.allSettled([loadGn(), loadLumin()]);
    // a source that failed keeps its cached list
    const gn = fresh.gn || cache?.gn || [], lumin = fresh.lumin || cache?.lumin || [];
    if (cache) { all = []; seen.clear(); add(gn.concat(lumin)); }
    if (fresh.gn || fresh.lumin) try { localStorage.setItem(CACHE_KEY, JSON.stringify({ gn, lumin })); } catch {}
    loaded = true;
    clearTimeout(filterTimer); filterTimer = null;
    applyFilter(true);
    const failed = [];
    if (results[0].status === 'rejected' && !cache) failed.push('gn-math');
    if (results[1].status === 'rejected' && !cache) failed.push('lumin');
    if (failed.length) status.textContent += ' (' + failed.join(' + ') + ' failed to load)';
  };
  return pageShell(Object.assign({}, cfg, { gn: { zones: GN_ZONES_URL, cover: GN_COVER_URL, html: GN_HTML_URL }, luminScript: LUMIN_SCRIPT }), 'games', body, script, css);
}

</script>
  <script>/* p/js/app/pages/chat.js */
// chat page: wraps the chatroom in an iframe

function pageChat(cfg) {
  const css = `iframe{position:absolute;top:var(--bar-space);left:0;width:100%;height:calc(100% - var(--bar-space));border:0;background:var(--bg-body);transition:top var(--motion-slow) var(--motion),height var(--motion-slow) var(--motion)}`;
  const body = `${topbar('chat', cfg)}<iframe id="chat" title="chat" sandbox="allow-scripts allow-same-origin allow-forms allow-modals allow-pointer-lock allow-downloads" allow="autoplay; fullscreen; clipboard-write; microphone; camera"></iframe>`;
  const script = function (cfg) {
    const frame = document.getElementById('chat');
    // the chatroom has its own var names, so map mochii's theme onto them (same origin, so we can reach in)
    const MAP = { '--bg': '--bg-body', '--bg-1': '--surface-1', '--bg-2': '--surface-2', '--bg-3': '--surface-5', '--bg-5': '--surface-0',
      '--border-3': '--border-faint', '--bright-text': '--text-primary', '--text': '--text-secondary', '--muted-text': '--text-muted', '--accent': '--accent' };
    function syncTheme() {
      let r; try { r = frame.contentDocument && frame.contentDocument.documentElement; } catch {}
      if (!r) return;
      const cs = getComputedStyle(document.documentElement);
      for (const [to, from] of Object.entries(MAP)) { const v = cs.getPropertyValue(from).trim(); if (v) r.style.setProperty(to, v); else r.style.removeProperty(to); }
    }
    frame.addEventListener('load', syncTheme);
    window.addEventListener('message', e => { if (e.data && e.data.type === 'GHOSTLINK_NT_THEME') syncTheme(); });
    frame.src = cfg.chatUrl;
  };
  return pageShell(cfg, 'chat', body, script, css);
}

</script>

  <script>/* p/js/app/pages/music.js */
// music page: browse / search / library over youtube music + soundcloud, playlists, and the song view with lyrics.
// ui only: the player is in the parent (p/js/app/music.js), reached with gl_music and gl_music_api messages

function pageMusic(cfg) {
  const css = `
    .mu{--panel:color-mix(in srgb,var(--surface-2) 70%,var(--bg-body));position:absolute;inset:var(--bar-space) 0 0 0;display:grid;grid-template-columns:232px minmax(0,1fr);grid-template-rows:minmax(0,1fr) auto;gap:8px;padding:8px}
    .mu-side,.mu-main,.mu-bar{background:var(--panel);border:1px solid var(--border-faint);border-radius:16px}
    .mu-side{grid-area:1/1;display:flex;flex-direction:column;gap:2px;padding:12px 10px;overflow:auto;min-height:0}
    .mu-nav{display:flex;align-items:center;gap:11px;min-height:38px;padding:0 12px;border-radius:11px;color:var(--text-muted);font-size:13.5px;text-align:left;transition:background .12s,color .12s}
    .mu-nav:hover{background:var(--accent-soft);color:var(--text-primary)}
    .mu-nav.on{background:var(--accent-active);color:var(--text-white)}
    .mu-nav span{flex:1;min-width:0;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
    .mu-nav small{color:var(--text-faint);font-size:11px}
    .mu-sep{display:flex;align-items:center;justify-content:space-between;padding:16px 12px 6px;color:var(--text-faint);font-size:11px;letter-spacing:.02em}
    .mu-sep button{width:24px;height:24px;display:flex;align-items:center;justify-content:center;border-radius:8px;color:var(--text-muted)}
    .mu-sep button:hover{background:var(--accent-soft);color:var(--text-white)}
    .mu-note{padding:8px 12px;color:var(--text-faint);font-size:12px;line-height:1.5}
    .mu-note button{color:var(--text-secondary);text-decoration:underline;text-underline-offset:3px}
    .mu-main{grid-area:1/2;position:relative;overflow:auto;min-height:0;padding:22px 26px 30px}
    .mu-h1{font-size:24px;font-weight:500;color:var(--text-white);margin-bottom:4px}
    .mu-sub{color:var(--text-faint);font-size:12.5px;margin-bottom:18px}
    .mu-h2{display:flex;align-items:center;gap:8px;margin:26px 0 12px;font-size:15px;font-weight:500;color:var(--text-primary)}
    .mu-h2:first-child{margin-top:0}
    .src{display:inline-flex;align-items:center;gap:5px;font-size:10.5px;color:var(--text-faint);font-weight:400}
    .src::before{content:"";width:6px;height:6px;border-radius:50%;background:#ff4e45}
    .src.sc::before{background:#ff7a1a}
    .shelf{display:grid;grid-auto-flow:column;grid-auto-columns:154px;gap:14px;overflow-x:auto;padding-bottom:8px;scroll-snap-type:x proximity}
    .crd{display:flex;flex-direction:column;gap:7px;text-align:left;scroll-snap-align:start;min-width:0}
    .crd-img{position:relative;width:100%;aspect-ratio:1;border-radius:12px;overflow:hidden;background:var(--surface-3);border:1px solid var(--border-subtle)}
    .crd-img img{width:100%;height:100%;object-fit:cover;display:block;transition:transform .25s var(--motion)}
    .crd:hover .crd-img img{transform:scale(1.04)}
    .crd b{font-weight:450;font-size:13px;color:var(--text-primary);overflow:hidden;white-space:nowrap;text-overflow:ellipsis;text-transform:none}
    .shelf.artists{grid-auto-columns:132px}
    .crd.artist{align-items:center;text-align:center}
    .crd.artist .crd-img{border-radius:50%}
    .crd.artist b,.crd.artist small{max-width:100%}
    .crd small{font-size:11.5px;color:var(--text-faint);overflow:hidden;white-space:nowrap;text-overflow:ellipsis;margin-top:-4px;text-transform:none}
    .picks{display:grid;grid-template-columns:repeat(auto-fill,minmax(270px,1fr));gap:2px 12px}
    .tl{display:flex;flex-direction:column}
    .tr{display:grid;grid-template-columns:28px 44px minmax(0,1fr) auto 46px 32px;align-items:center;gap:12px;min-height:58px;padding:6px 8px;border-radius:12px;cursor:pointer;transition:background .12s}
    .picks .tr{grid-template-columns:44px minmax(0,1fr) 32px}
    .picks .tr-n,.picks .tr-src,.picks .tr-dur{display:none}
    .tr:hover{background:var(--accent-soft)}
    .tr.on{background:var(--accent-active)}
    .tr-n{color:var(--text-faint);font-size:12px;text-align:center}
    .tr.on .tr-n{color:var(--accent)}
    .tr-cov{width:44px;height:44px;border-radius:9px;overflow:hidden;background:var(--surface-3)}
    .tr-cov img{width:100%;height:100%;object-fit:cover;display:block}
    .tr-meta{min-width:0;display:flex;flex-direction:column;gap:2px;text-transform:none}
    .tr-meta b{font-weight:450;font-size:13.5px;color:var(--text-primary);overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
    .tr.on .tr-meta b{color:var(--text-white)}
    .tr-meta small{font-size:12px;color:var(--text-faint);overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
    .tr-dur{color:var(--text-faint);font-size:12px;text-align:right;font-variant-numeric:tabular-nums}
    .tag{margin-left:6px;padding:1px 6px;border-radius:6px;background:var(--surface-5);color:var(--text-muted);font-size:10px;vertical-align:1px}
    .tr-act{width:32px;height:32px;display:flex;align-items:center;justify-content:center;border-radius:9px;color:var(--text-faint);opacity:0;transition:opacity .12s,background .12s,color .12s}
    .tr:hover .tr-act,.tr-act:focus-visible{opacity:1}
    .tr-act:hover{background:var(--surface-hover);color:var(--text-white)}
    @media (hover:none){.tr-act{opacity:1}}
    .bars{display:inline-flex;align-items:flex-end;gap:2px;height:12px}
    .bars i{width:3px;height:100%;background:var(--accent);border-radius:1px;transform-origin:bottom;animation:bars .9s ease-in-out infinite}
    .bars i:nth-child(2){animation-delay:-.3s}.bars i:nth-child(3){animation-delay:-.6s}
    .paused .bars i{animation-play-state:paused}
    @keyframes bars{0%,100%{transform:scaleY(.3)}50%{transform:scaleY(1)}}
    .mu-search{display:flex;flex-direction:column;gap:12px;max-width:620px;margin-bottom:10px}
    .seg{display:inline-flex;gap:2px;padding:3px;border-radius:12px;background:var(--surface-3);border:1px solid var(--border-subtle);align-self:flex-start}
    .seg button{height:30px;padding:0 13px;border-radius:9px;color:var(--text-muted);font-size:12.5px;transition:background .12s,color .12s}
    .seg button:hover{color:var(--text-primary)}
    .seg button.on{background:var(--surface-hover);color:var(--text-white)}
    .hero{display:flex;align-items:flex-end;gap:24px;margin-bottom:22px}
    .hero-img{width:180px;height:180px;flex:0 0 180px;border-radius:16px;overflow:hidden;background:var(--surface-3);border:1px solid var(--border-subtle);box-shadow:0 20px 40px -18px rgba(0,0,0,.7);display:flex;align-items:center;justify-content:center;color:var(--text-faint)}
    .hero.artist .hero-img{border-radius:50%}
    .hero-img img{width:100%;height:100%;object-fit:cover;display:block}
    .hero-info{min-width:0;flex:1}
    .hero-kind{font-size:11px;color:var(--text-faint);margin-bottom:6px}
    .hero h1{font-size:30px;font-weight:500;color:var(--text-white);line-height:1.15;overflow-wrap:anywhere;text-transform:none}
    .hero p{color:var(--text-muted);font-size:13px;margin-top:6px;overflow-wrap:anywhere;text-transform:none}
    .hero-meta{color:var(--text-faint);font-size:12px;margin-top:8px}
    .acts{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin-bottom:18px}
    .btn{height:36px;display:inline-flex;align-items:center;gap:7px;padding:0 15px;border-radius:12px;background:var(--surface-3);border:1px solid var(--border-subtle);color:var(--text-secondary);font-size:13px;transition:background .12s,color .12s}
    .btn:hover{background:var(--surface-5);color:var(--text-white)}
    .btn.primary{background:var(--accent);border-color:transparent;color:var(--on-accent)}
    .btn.primary:hover{filter:brightness(.92)}
    .btn.round{width:46px;height:46px;padding:0;justify-content:center;border-radius:50%}
    .btn.danger:hover{color:#ff6b6b}
    .btn[disabled]{opacity:.45;pointer-events:none}
    .back{display:inline-flex;align-items:center;gap:6px;margin-bottom:14px;color:var(--text-faint);font-size:12.5px}
    .back:hover{color:var(--text-primary)}
    .form{display:flex;flex-direction:column;gap:10px;flex:1;min-width:0;max-width:520px}
    .form input,.form textarea{width:100%;padding:10px 12px;border-radius:11px;border:1px solid var(--border-subtle);background:var(--search-inset);color:var(--text-primary);font:inherit;font-size:13.5px;outline:none;text-transform:none;resize:vertical}
    .form input:focus,.form textarea:focus{border-color:var(--border-faint)}
    .form .hint{color:var(--text-faint);font-size:12px}
    .empty{padding:40px 0;text-align:center;color:var(--text-faint);font-size:13px}
    .spin{width:20px;height:20px;margin:40px auto;border-radius:50%;border:2px solid var(--border-faint);border-top-color:var(--accent);animation:spin .8s linear infinite}
    @keyframes spin{to{transform:rotate(360deg)}}
    .lgrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:16px}
    .mu-bar{grid-area:2/1/3/-1;position:relative;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.4fr) minmax(0,1fr);align-items:center;gap:16px;height:78px;padding:0 16px}
    .mu-bar.none .b-mid,.mu-bar.none .b-right{opacity:.4;pointer-events:none}
    .b-now{display:flex;align-items:center;gap:12px;min-width:0;text-align:left}
    .b-cov{width:50px;height:50px;flex:0 0 50px;border-radius:10px;overflow:hidden;background:var(--surface-3)}
    .b-cov img{width:100%;height:100%;object-fit:cover;display:block}
    .b-txt{min-width:0;display:flex;flex-direction:column;gap:3px;text-transform:none}
    .b-txt b{font-weight:450;font-size:13.5px;color:var(--text-primary);overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
    .b-txt small{font-size:12px;color:var(--text-faint);overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
    .b-mid{display:flex;flex-direction:column;align-items:center;gap:6px;min-width:0}
    .b-ctl{display:flex;align-items:center;gap:10px}
    .cb{position:relative;width:34px;height:34px;display:flex;align-items:center;justify-content:center;border-radius:50%;color:var(--text-muted);transition:background .12s,color .12s}
    .cb:hover{color:var(--text-white);background:var(--accent-soft)}
    .cb.on{color:var(--accent)}
    .cb.on::after{content:"";position:absolute;bottom:1px;left:50%;width:4px;height:4px;margin-left:-2px;border-radius:50%;background:var(--accent)}
    .cb[data-c=toggle]{width:40px;height:40px;background:var(--accent);color:var(--on-accent)}
    .cb[data-c=toggle]:hover{filter:brightness(.92);background:var(--accent);color:var(--on-accent)}
    .cb .one{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);font-size:8px;font-weight:600}
    .i-pause,.is-playing .i-play{display:none}
    .is-playing .i-pause{display:flex}
    .i-play{display:flex}
    .b-seek{display:flex;align-items:center;gap:10px;width:100%;color:var(--text-faint);font-size:11px;font-variant-numeric:tabular-nums}
    .b-seek span{min-width:34px}.b-seek span:last-child{text-align:right}
    .rng{-webkit-appearance:none;appearance:none;flex:1;height:14px;background:transparent;cursor:pointer;--p:0%}
    .rng::-webkit-slider-runnable-track{height:4px;border-radius:2px;background:linear-gradient(var(--text-secondary),var(--text-secondary)) 0/var(--p) 100% no-repeat,var(--surface-hover)}
    .rng::-moz-range-track{height:4px;border-radius:2px;background:linear-gradient(var(--text-secondary),var(--text-secondary)) 0/var(--p) 100% no-repeat,var(--surface-hover)}
    .rng::-webkit-slider-thumb{-webkit-appearance:none;width:12px;height:12px;margin-top:-4px;border-radius:50%;background:var(--text-white);opacity:0;transition:opacity .12s}
    .rng::-moz-range-thumb{width:12px;height:12px;border:0;border-radius:50%;background:var(--text-white);opacity:0}
    .rng:hover::-webkit-slider-thumb,.rng:focus-visible::-webkit-slider-thumb{opacity:1}
    .rng:hover::-moz-range-thumb{opacity:1}
    .b-right{display:flex;align-items:center;justify-content:flex-end;gap:4px}
    .b-right .rng{flex:0 1 100px;min-width:60px}
    .b-loading .b-txt small::before{content:"";display:inline-block;width:8px;height:8px;margin-right:6px;border-radius:50%;border:1.5px solid var(--border-faint);border-top-color:var(--accent);animation:spin .8s linear infinite;vertical-align:-1px}
    .song{grid-area:1/1/2/-1;position:relative;z-index:5;display:none;overflow:hidden;border-radius:16px;border:1px solid var(--border-faint);background:var(--bg-body)}
    .mu.song-open .song{display:block;animation:soft-rise .3s var(--motion) both}
    .song-bg{position:absolute;inset:-60px;background-size:cover;background-position:center;filter:blur(60px) saturate(1.4);opacity:.35;transform:scale(1.1)}
    .song-bg::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent,var(--bg-body))}
    .song-in{position:relative;height:100%;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.1fr);gap:40px;padding:34px 44px}
    .song-close{position:absolute;top:14px;left:14px;z-index:2}
    .song-left{display:flex;flex-direction:column;justify-content:center;align-items:center;gap:18px;min-height:0;text-align:center}
    .song-cov{width:min(100%,42vh,400px);aspect-ratio:1;border-radius:20px;overflow:hidden;background:var(--surface-3);box-shadow:0 30px 60px -20px rgba(0,0,0,.8)}
    .song-cov img{width:100%;height:100%;object-fit:cover;display:block}
    .song-t{font-size:26px;font-weight:500;color:var(--text-white);line-height:1.2;text-transform:none;overflow-wrap:anywhere}
    .song-a{font-size:15px;color:var(--text-muted);margin-top:4px;text-transform:none}
    .song-acts{display:flex;gap:8px}
    .lyr{position:relative;min-height:0;overflow:auto;padding:30vh 6px 30vh;scroll-behavior:smooth;-webkit-mask-image:linear-gradient(transparent,#000 18%,#000 82%,transparent);mask-image:linear-gradient(transparent,#000 18%,#000 82%,transparent)}
    .ly{display:block;width:100%;text-align:left;padding:7px 0;font-size:24px;font-weight:500;line-height:1.35;color:var(--text-faint);opacity:.55;text-transform:none;transition:color .3s,opacity .3s,transform .3s var(--motion);transform-origin:left center}
    .ly.done{opacity:.4}
    .ly.on{color:var(--text-white);opacity:1;transform:scale(1.03)}
    button.ly:hover{opacity:.9}
    .ly .w{color:transparent;-webkit-background-clip:text;background-clip:text;
      background-image:linear-gradient(90deg,var(--text-white) calc(var(--p,0%) - 8%),color-mix(in srgb,var(--text-white) 36%,transparent) var(--p,0%))}
    .ly .w.rh{filter:drop-shadow(0 0 0 transparent) drop-shadow(0 0 0 transparent);transition:filter .5s ease-out}
    .ly .w.rh.glow{filter:drop-shadow(0 0 5px color-mix(in srgb,var(--accent) 90%,transparent)) drop-shadow(0 0 14px color-mix(in srgb,var(--accent) 70%,transparent))}
    .ly-plain{white-space:pre-wrap;font-size:17px;line-height:1.7;color:var(--text-secondary);text-transform:none}
    .ly-msg{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;color:var(--text-faint);font-size:14px}
    .ly-src{margin-top:24px;font-size:11px;color:var(--text-faint)}
    .qp{position:absolute;right:8px;bottom:94px;z-index:20;width:min(380px,calc(100% - 16px));max-height:min(560px,calc(100% - 110px));display:none;flex-direction:column;background:var(--surface-4);background:color-mix(in srgb,var(--surface-5) 94%,transparent);border:1px solid var(--border-faint);border-radius:16px;box-shadow:0 24px 48px -16px rgba(0,0,0,.75);-webkit-backdrop-filter:blur(16px);backdrop-filter:blur(16px);overflow:hidden}
    .qp.open{display:flex;animation:soft-rise .22s var(--motion) both}
    .qp-h{display:flex;align-items:center;justify-content:space-between;padding:14px 16px 8px;font-size:13px;color:var(--text-primary)}
    .qp-l{overflow:auto;padding:0 6px 8px}
    .qp .tr{grid-template-columns:40px minmax(0,1fr) 32px;min-height:52px}
    .qp .tr-cov{width:40px;height:40px}
    .qp .tr-n,.qp .tr-src,.qp .tr-dur{display:none}
    .qp-lbl{padding:10px 10px 4px;font-size:11px;color:var(--text-faint)}
    .menu{position:fixed;z-index:60;min-width:200px;max-width:280px;max-height:340px;overflow:auto;padding:5px;background:var(--surface-5);border:1px solid var(--border-faint);border-radius:13px;box-shadow:0 18px 40px -12px rgba(0,0,0,.8);animation:soft-rise .16s var(--motion) both}
    .menu button{display:flex;align-items:center;gap:10px;width:100%;min-height:34px;padding:0 10px;border-radius:9px;color:var(--text-secondary);font-size:13px;text-align:left}
    .menu button:hover{background:var(--surface-hover);color:var(--text-white)}
    .menu button span{flex:1;min-width:0;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;text-transform:none}
    .menu hr{border:0;height:1px;background:var(--border-subtle);margin:4px 6px}
    .menu .mh{padding:6px 10px 4px;font-size:11px;color:var(--text-faint)}
    .toast{position:absolute;left:50%;bottom:98px;z-index:70;transform:translate(-50%,8px);padding:9px 16px;border-radius:12px;background:var(--surface-5);border:1px solid var(--border-faint);color:var(--text-primary);font-size:13px;opacity:0;pointer-events:none;transition:opacity .18s,transform .18s;white-space:nowrap;max-width:calc(100% - 32px);overflow:hidden;text-overflow:ellipsis}
    .toast.show{opacity:1;transform:translate(-50%,0)}
    @media (max-width:900px){.song-in{grid-template-columns:1fr;grid-template-rows:auto minmax(0,1fr);gap:16px;padding:56px 22px 16px}.song-left{flex-direction:row;justify-content:flex-start;text-align:left}.song-cov{width:96px;flex:0 0 96px;border-radius:14px}.song-t{font-size:19px}.song-acts{display:none}.lyr{padding:12vh 4px}.ly{font-size:19px}}
    @media (max-width:720px){
      .mu{grid-template-columns:minmax(0,1fr);grid-template-rows:auto minmax(0,1fr) auto;padding:6px;gap:6px}
      .mu-side{grid-area:1/1;flex-direction:row;overflow-x:auto;padding:5px;gap:4px;border-radius:14px}
      .mu-side .mu-sep,.mu-side .mu-note,.mu-side .mu-pl{display:none}
      .mu-nav{flex:0 0 auto;min-height:34px}
      .song{grid-area:1/1/3/-1}
      .mu-main{grid-area:2/1;padding:16px 14px 24px}
      .mu-bar{grid-area:3/1}
      .hero{flex-direction:column;align-items:flex-start;gap:14px}.hero-img{width:130px;height:130px;flex-basis:130px}.hero h1{font-size:23px}
      .tr{grid-template-columns:44px minmax(0,1fr) 32px;gap:10px}.tr-n,.tr-src,.tr-dur{display:none}
      .mu-bar{grid-template-columns:minmax(0,1fr) auto;height:66px;padding:0 10px;gap:8px}
      .b-mid{position:static}.b-seek{position:absolute;left:14px;right:14px;top:-1px;width:auto}.b-seek span{display:none}.b-seek .rng{height:6px}
      .b-ctl [data-c=shuffle],.b-ctl [data-c=repeat],.b-ctl [data-c=prev],.b-right{display:none}
      .b-cov{width:44px;height:44px;flex-basis:44px}
      .qp,.toast{bottom:80px}
    }
  `;
  const I = n => pgIcon(n, 18);
  const body = `${topbar('music', cfg)}
    <div class="mu" id="mu">
      <nav class="mu-side" id="side" aria-label="music">
        <button class="mu-nav" data-v="browse" type="button">${I('compass')}<span>browse</span></button>
        <button class="mu-nav" data-v="search" type="button">${I('search')}<span>search</span></button>
        <button class="mu-nav" data-v="library" type="button">${I('library')}<span>your library</span></button>
        <div class="mu-sep">recently played</div>
        <button class="mu-nav mu-pl" data-v="recent" type="button">${I('clock')}<span>recently played</span></button>
        <div class="mu-sep">playlists<button type="button" id="newpl" aria-label="new playlist" title="new playlist">${pgIcon('plus', 16)}</button></div>
        <div id="side-pls"></div>
      </nav>
      <main class="mu-main" id="main"></main>
      <section class="song" id="song" aria-label="now playing">
        <div class="song-bg" id="song-bg"></div>
        <button class="icon-btn song-close" id="song-close" type="button" aria-label="close" title="close">${pgIcon('close', 16)}</button>
        <div class="song-in">
          <div class="song-left">
            <div class="song-cov" id="song-cov"></div>
            <div><div class="song-t" id="song-t"></div><div class="song-a" id="song-a"></div></div>
            <div class="song-acts"><button class="btn" type="button" id="song-add">${pgIcon('plus', 16)} add to playlist</button><button class="btn" type="button" id="song-q">${pgIcon('queue', 16)} queue</button></div>
          </div>
          <div class="lyr" id="lyr"></div>
        </div>
      </section>
      <footer class="mu-bar none" id="bar">
        <button class="b-now" type="button" id="b-now" aria-label="open the song"><span class="b-cov" id="b-cov"></span><span class="b-txt"><b id="b-t">nothing playing</b><small id="b-a">pick a song to start</small></span></button>
        <div class="b-mid">
          <div class="b-ctl">
            <button class="cb" type="button" data-c="shuffle" aria-label="shuffle" title="shuffle">${pgIcon('shuffle', 17)}</button>
            <button class="cb" type="button" data-c="prev" aria-label="previous" title="previous">${pgIcon('prev', 17)}</button>
            <button class="cb" type="button" data-c="toggle" aria-label="play or pause" title="play / pause"><span class="i-play">${pgIcon('play', 18)}</span><span class="i-pause">${pgIcon('pause', 18)}</span></button>
            <button class="cb" type="button" data-c="next" aria-label="next" title="next">${pgIcon('next', 17)}</button>
            <button class="cb" type="button" data-c="repeat" aria-label="repeat" title="repeat">${pgIcon('repeat', 17)}<span class="one" hidden>1</span></button>
          </div>
          <div class="b-seek"><span id="b-cur">0:00</span><input class="rng" id="seek" type="range" min="0" max="1000" value="0" aria-label="seek"><span id="b-dur">0:00</span></div>
        </div>
        <div class="b-right">
          <button class="cb" type="button" id="b-lyr" aria-label="lyrics" title="lyrics">${pgIcon('lyrics', 17)}</button>
          <button class="cb" type="button" id="b-q" aria-label="queue" title="queue">${pgIcon('queue', 17)}</button>
          <button class="cb" type="button" id="b-mute" aria-label="mute" title="mute"><span class="i-vol">${pgIcon('volume', 17)}</span></button>
          <input class="rng" id="vol" type="range" min="0" max="100" value="100" aria-label="volume">
        </div>
      </footer>
      <div class="qp" id="qp" role="dialog" aria-label="queue"><div class="qp-h"><span>queue</span><button class="icon-btn" id="qp-x" type="button" aria-label="close">${pgIcon('close', 14)}</button></div><div class="qp-l" id="qp-l"></div></div>
      <div class="toast" id="toast" role="status"></div>
    </div>`;
  const icons = {}; ['more', 'play', 'shuffle', 'share', 'plus', 'back', 'search', 'close', 'music', 'queue', 'volume', 'mute'].forEach(n => { icons[n] = pgIcon(n, n === 'play' || n === 'shuffle' ? 18 : 16); });
  const script = function (cfg) {
    const $ = id => document.getElementById(id), IC = cfg.icons;
    const esc = s => String(s == null ? '' : s).replace(/[&<>'"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[c]));
    const post = m => { try { window.parent.postMessage(m, '*'); } catch {} };
    const cmd = (c, a) => post(Object.assign({ type: 'gl_music', cmd: c }, a || {}));
    let seq = 0; const wait = {};
    const api = (op, args) => new Promise((res, rej) => { const id = ++seq; wait[id] = { res, rej }; post({ type: 'gl_music_api', id, op, args }); setTimeout(() => { if (wait[id]) { delete wait[id]; rej(new Error('that took too long, try again')); } }, 45000); });
    const fmt = s => { s = Math.max(0, Math.floor(s || 0)); return Math.floor(s / 60) + ':' + String(s % 60).padStart(2, '0'); };
    const key = t => t ? t.src + ':' + t.id : '';
    const main = $('main'), mu = $('mu');
    let st = { track: null, playing: false, t: 0, at: Date.now(), dur: 0, queue: [], i: -1, vol: 1 };
    const now = () => st.playing ? Math.min(st.t + (Date.now() - st.at) / 1000, st.dur || 1e9) : st.t;
    let pls = { signedIn: false, lists: [] }, view = { v: 'browse' }, hist = [], lists = {}, lid = 0;
    let toastTimer = 0;
    function toast(t) { const el = $('toast'); el.textContent = t; el.classList.add('show'); clearTimeout(toastTimer); toastTimer = setTimeout(() => el.classList.remove('show'), 2400); }
    // covers load straight from youtube / soundcloud, and through the proxy if the network blocks them
    const img = (url, alt) => url ? `<img src="${esc(url)}" data-src="${esc(url)}" alt="${esc(alt || '')}" loading="lazy" referrerpolicy="no-referrer">` : '';
    document.addEventListener('error', e => {
      const el = e.target; if (!el || el.tagName !== 'IMG' || !el.dataset.src) return;
      if (el.dataset.p) { el.remove(); return; }
      el.dataset.p = '1'; api('img', { url: el.dataset.src }).then(u => { if (u) el.src = u; else el.remove(); }, () => el.remove());
    }, true);

    // ---------- track lists ----------
    function trackRows(tracks, opts) {
      opts = opts || {}; const id = ++lid; lists[id] = { tracks, opts };
      if (!tracks.length) return `<div class="empty">${esc(opts.empty || 'nothing here yet')}</div>`;
      const k = key(st.track);
      return `<div class="${opts.picks ? 'picks' : 'tl'}">` + tracks.map((t, i) => {
        const on = key(t) === k;
        return `<div class="tr${on ? ' on' : ''}${on && !st.playing ? ' paused' : ''}" role="button" tabindex="0" data-l="${id}" data-i="${i}" data-k="${esc(key(t))}">
          <span class="tr-n">${on ? '<span class="bars"><i></i><i></i><i></i></span>' : i + 1}</span>
          <span class="tr-cov">${img(t.cover)}</span>
          <span class="tr-meta"><b>${esc(t.title)}${t.preview ? '<span class="tag">preview</span>' : ''}</b><small>${esc(t.artist || 'unknown artist')}</small></span>
          <span class="tr-src"><span class="src${t.src === 'sc' ? ' sc' : ''}">${t.src === 'sc' ? 'soundcloud' : 'youtube'}</span></span>
          <span class="tr-dur">${t.dur ? fmt(t.dur) : ''}</span>
          <button class="tr-act" type="button" data-act="more" aria-label="more">${IC.more}</button></div>`;
      }).join('') + '</div>';
    }
    function markPlaying() {
      const k = key(st.track);
      document.querySelectorAll('.tr[data-k]').forEach(el => {
        const on = el.dataset.k === k, was = el.classList.contains('on');
        el.classList.toggle('on', on); el.classList.toggle('paused', on && !st.playing);
        if (on !== was) { const n = el.querySelector('.tr-n'); if (n) n.innerHTML = on ? '<span class="bars"><i></i><i></i><i></i></span>' : (+el.dataset.i + 1); }
      });
    }
    function playFrom(l, i, shuffle) {
      const L = lists[l]; if (!L) return;
      if (L.opts.queue) { cmd('jump', { i: +i }); return; }
      cmd('play', { list: L.tracks, i: +i || 0, shuffle });
      if (!shuffle) openSong();
    }

    // ---------- views ----------
    function go(v, push) {
      if (push !== false && view.v) hist.push(view);
      view = v; closeMenu(); render();
      main.scrollTop = 0;
    }
    function back() { view = hist.pop() || { v: 'browse' }; render(); }
    function setNav() { document.querySelectorAll('.mu-nav').forEach(b => b.classList.toggle('on', b.dataset.pl ? view.v === 'pl' && b.dataset.pl === view.id : b.dataset.v === view.v)); }
    const backBtn = () => hist.length ? `<button class="back" type="button" data-back>${IC.back} back</button>` : '';
    const loading = () => '<div class="spin"></div>';
    async function render() {
      setNav();
      const v = view, token = (render.t = (render.t || 0) + 1), live = () => token === render.t;
      if (v.v === 'browse') {
        main.innerHTML = `<div class="mu-h1">browse</div><div class="mu-sub">from youtube music and soundcloud</div>${loading()}`;
        try {
          const d = await api('browse'); if (!live()) return;
          const shelves = d.yt.concat(d.sc);
          const card = c => `<button class="crd${c.artist ? ' artist' : ''}" type="button" data-open="${esc(c.id)}"><span class="crd-img">${img(c.cover)}</span><b>${esc(c.title)}</b><small>${esc(c.sub)}</small></button>`;
          main.innerHTML = `<div class="mu-h1">browse</div><div class="mu-sub">from youtube music and soundcloud</div>` +
            (d.featured && d.featured.length ? `<div class="mu-h2">featured artists</div><div class="shelf artists">${d.featured.map(card).join('')}</div>` : '') + (shelves.length ? shelves.map(s => {
            const tracks = s.items.filter(x => x.kind === 'track').map(x => x.track), cards = s.items.filter(x => x.kind === 'list');
            return `<div class="mu-h2">${esc(s.title)} <span class="src${s.src === 'sc' ? ' sc' : ''}">${s.src === 'sc' ? 'soundcloud' : 'youtube music'}</span></div>` +
              (tracks.length ? trackRows(tracks.slice(0, 12), { picks: true }) : '') +
              (cards.length ? `<div class="shelf">${cards.map(card).join('')}</div>` : '');
          }).join('') : '<div class="empty">nothing to show right now</div>');
        } catch (e) { if (live()) main.innerHTML = `<div class="mu-h1">browse</div><div class="empty">${esc(e.message)}<br><br><button class="btn" type="button" data-retry>try again</button></div>`; }
      } else if (v.v === 'search') {
        main.innerHTML = `<div class="mu-search"><div class="searchbar">${IC.search}
          <input id="q" type="text" placeholder="songs, artists..." autocomplete="off" spellcheck="false" aria-label="search music" value="${esc(v.q || '')}"><button class="sb-btn" type="button" data-clear aria-label="clear search">${IC.close}</button></div>
          <div class="seg" id="srcseg">${[['all', 'everywhere'], ['yt', 'youtube music'], ['sc', 'soundcloud']].map(([k, l]) => `<button type="button" data-src="${k}" class="${(v.src || 'all') === k ? 'on' : ''}">${l}</button>`).join('')}</div></div><div id="res"></div>`;
        const q = $('q'), sb = q.parentElement, sync = () => sb.classList.toggle('has-value', !!q.value);
        sync(); if (!v.q) q.focus();
        let t; q.addEventListener('input', () => { sync(); clearTimeout(t); t = setTimeout(() => { view.q = q.value; runSearch(); }, 450); });
        q.addEventListener('keydown', e => { if (e.key === 'Enter') { clearTimeout(t); view.q = q.value; runSearch(); } });
        sb.querySelector('[data-clear]').onclick = () => { q.value = ''; sync(); view.q = ''; runSearch(); q.focus(); };
        $('srcseg').onclick = e => { const b = e.target.closest('[data-src]'); if (!b) return; view.src = b.dataset.src; $('srcseg').querySelectorAll('button').forEach(x => x.classList.toggle('on', x === b)); runSearch(); };
        runSearch();
      } else if (v.v === 'library') {
        main.innerHTML = `<div class="mu-h1">your library</div><div class="mu-sub">playlists and what you played lately</div>${loading()}`;
        await loadPls(); if (!live()) return;
        const recent = await api('recent').catch(() => []); if (!live()) return;
        main.innerHTML = `<div class="mu-h1">your library</div><div class="mu-sub">playlists and what you played lately</div>
          <div class="mu-h2">playlists</div>` + (pls.signedIn ? `<div class="lgrid">${pls.lists.map(p => `<button class="crd" type="button" data-pl="${p.id}"><span class="crd-img">${p.tracks[0] ? img(p.tracks[0].cover) : ''}</span><b>${esc(p.name)}</b><small>${p.tracks.length} songs · ${p.visibility}</small></button>`).join('')}<button class="crd" type="button" data-newpl><span class="crd-img" style="display:flex;align-items:center;justify-content:center;color:var(--text-faint)">${IC.plus}</span><b>new playlist</b></button></div>`
            : `<div class="mu-note"><button type="button" data-account>sign in</button> to make playlists and share them.</div>`) +
          `<div class="mu-h2">recently played</div>` + trackRows(recent.slice(0, 10), { empty: 'songs you play show up here' });
      } else if (v.v === 'recent') {
        const recent = await api('recent').catch(() => []); if (!live()) return;
        main.innerHTML = `${backBtn()}<div class="mu-h1">recently played</div><div class="mu-sub">the last ${recent.length} songs, kept on this device</div>
          <div class="acts"><button class="btn round primary" type="button" data-playall aria-label="play all">${IC.play}</button>${recent.length ? '<button class="btn" type="button" data-clearrecent>clear</button>' : ''}</div>` + trackRows(recent, { empty: 'songs you play show up here' });
      } else if (v.v === 'list') {
        main.innerHTML = backBtn() + loading();
        try {
          const d = await api('open', { id: v.id }); if (!live()) return;
          view.data = d;
          const artist = d.kind === 'artist';
          main.innerHTML = `${backBtn()}<div class="hero${artist ? ' artist' : ''}"><div class="hero-img">${img(d.cover)}</div><div class="hero-info"><div class="hero-kind">${artist ? 'artist' : v.id.startsWith('sc:') ? 'soundcloud' : 'youtube music'}</div><h1>${esc(d.title)}</h1><p>${esc(d.sub || '')}</p><div class="hero-meta">${d.tracks.length} songs</div></div></div>
            <div class="acts"><button class="btn round primary" type="button" data-playall aria-label="play">${IC.play}</button><button class="btn round" type="button" data-shuffleall aria-label="shuffle">${IC.shuffle}</button>${pls.signedIn && d.tracks.length ? '<button class="btn" type="button" data-copy>save as playlist</button>' : ''}</div>` + trackRows(d.tracks, { empty: 'no playable songs in here' });
        } catch (e) { if (live()) main.innerHTML = `${backBtn()}<div class="empty">${esc(e.message)}</div>`; }
      } else if (v.v === 'pl') {
        main.innerHTML = backBtn() + loading();
        try {
          const p = v.fresh || await api('pl.get', { id: v.id }); if (!live()) return;
          view.data = p; delete view.fresh;
          const vis = { public: 'public · on your chat profile', unlisted: 'unlisted · anyone with the link', private: 'private · only you' };
          const head = v.edit ? `<div class="hero"><div class="hero-img">${p.tracks[0] ? img(p.tracks[0].cover) : IC.music}</div><div class="form">
              <input id="pl-name" maxlength="80" placeholder="playlist name" value="${esc(p.name)}" aria-label="name">
              <textarea id="pl-desc" maxlength="300" rows="2" placeholder="description (optional)" aria-label="description">${esc(p.description)}</textarea>
              <div class="seg" id="pl-vis">${['public', 'unlisted', 'private'].map(k => `<button type="button" data-vis="${k}" class="${p.visibility === k ? 'on' : ''}">${k}</button>`).join('')}</div>
              <div class="hint" id="pl-hint">${vis[p.visibility]}</div>
              <div class="acts" style="margin:4px 0 0"><button class="btn primary" type="button" data-plsave>save</button><button class="btn" type="button" data-plcancel>cancel</button></div></div></div>`
            : `<div class="hero"><div class="hero-img">${p.tracks[0] ? img(p.tracks[0].cover) : IC.music}</div><div class="hero-info"><div class="hero-kind">${p.mine ? vis[p.visibility] : 'playlist by ' + esc(p.ownerName || 'someone')}</div><h1>${esc(p.name)}</h1>${p.description ? `<p>${esc(p.description)}</p>` : ''}<div class="hero-meta">${p.tracks.length} songs${p.tracks.length ? ' · ' + fmt(p.tracks.reduce((a, t) => a + (t.dur || 0), 0)).replace(/^(\d+):\d+$/, (m, a) => a >= 60 ? Math.floor(a / 60) + ' hr ' + (a % 60) + ' min' : a + ' min') : ''}</div></div></div>`;
          main.innerHTML = backBtn() + head + `<div class="acts"><button class="btn round primary" type="button" data-playall aria-label="play">${IC.play}</button><button class="btn round" type="button" data-shuffleall aria-label="shuffle">${IC.shuffle}</button>` +
            (p.mine ? (v.edit ? '' : `<button class="btn" type="button" data-pledit>edit</button><button class="btn" type="button" data-share${p.visibility === 'private' ? ' title="make it public or unlisted to share it"' : ''}>${IC.share} share</button><button class="btn danger" type="button" data-pldel>delete</button>`)
              : pls.signedIn ? '<button class="btn" type="button" data-copy>save a copy</button><button class="btn" type="button" data-share>' + IC.share + ' share</button>' : '<button class="btn" type="button" data-share>' + IC.share + ' share</button>') + '</div>' +
            trackRows(p.tracks, { pl: p.mine ? p.id : null, empty: p.mine ? 'add songs with the ••• button next to any song' : 'this playlist is empty' });
          if (v.edit) {
            const name = $('pl-name'); name.focus(); name.select();
            $('pl-vis').onclick = e => { const b = e.target.closest('[data-vis]'); if (!b) return; $('pl-vis').querySelectorAll('button').forEach(x => x.classList.toggle('on', x === b)); $('pl-hint').textContent = vis[b.dataset.vis]; };
            name.onkeydown = e => { if (e.key === 'Enter') main.querySelector('[data-plsave]').click(); };
          }
        } catch (e) { if (live()) main.innerHTML = `${backBtn()}<div class="empty">${esc(e.message)}</div>`; }
      }
    }
    async function runSearch() {
      const res = $('res'); if (!res) return;
      const q = (view.q || '').trim(), src = view.src || 'all', token = (runSearch.t = (runSearch.t || 0) + 1);
      if (!q) { res.innerHTML = '<div class="empty">search youtube music and soundcloud</div>'; return; }
      res.innerHTML = loading();
      try {
        const d = await api('search', { q, src }); if (token !== runSearch.t || !$('res')) return;
        let html = '';
        if (src !== 'sc') html += `<div class="mu-h2">songs <span class="src">youtube music</span></div>` + (d.ytFailed ? '<div class="empty">youtube music didn\'t answer</div>' : trackRows(d.yt, { empty: 'no songs found' }));
        if (src !== 'yt') html += `<div class="mu-h2">tracks <span class="src sc">soundcloud</span></div>` + (d.scFailed ? '<div class="empty">soundcloud didn\'t answer</div>' : trackRows(d.sc, { empty: 'no tracks found' }));
        res.innerHTML = html;
      } catch (e) { if (token === runSearch.t && $('res')) $('res').innerHTML = `<div class="empty">${esc(e.message)}</div>`; }
    }

    // ---------- playlists ----------
    async function loadPls() {
      try { pls = await api('pl.mine'); } catch { pls = { signedIn: pls.signedIn, lists: pls.lists }; }
      $('side-pls').innerHTML = pls.signedIn ? (pls.lists.length ? pls.lists.map(p => `<button class="mu-nav mu-pl" type="button" data-v="pl" data-pl="${p.id}"><span>${esc(p.name)}</span><small>${p.tracks.length}</small></button>`).join('') : '<div class="mu-note">no playlists yet</div>')
        : '<div class="mu-note"><button type="button" data-account>sign in</button> to make playlists</div>';
      $('newpl').hidden = !pls.signedIn;
      setNav();
    }
    async function newPlaylist(tracks, name, description) {
      if (!pls.signedIn) { toast('sign in to make playlists'); return; }
      try {
        const p = await api('pl.save', { pl: { name: name || 'new playlist', description: description || '', tracks: tracks || [] } });
        await loadPls(); go({ v: 'pl', id: p.id, fresh: p, edit: !tracks || !tracks.length });
        if (tracks && tracks.length) toast('saved to your library');
      } catch (e) { toast(e.message); }
    }
    async function addTo(id, track) {
      try { const p = await api('pl.add', { id, track }); toast('added to ' + p.name); loadPls(); if (view.v === 'pl' && view.id === id) { view.fresh = p; render(); } }
      catch (e) { toast(e.message); }
    }
    async function share(p) {
      if (p.mine && p.visibility === 'private') { toast('make it public or unlisted to share it'); return; }
      const url = await api('share', { id: p.id });
      try { await navigator.clipboard.writeText(url); toast('link copied'); }
      catch { window.prompt('copy the link', url); }
    }

    // ---------- menus ----------
    let menuEl = null;
    function closeMenu() { if (menuEl) { menuEl.remove(); menuEl = null; } }
    function openMenu(anchor, items) {
      closeMenu();
      const m = menuEl = document.createElement('div'); m.className = 'menu'; m.setAttribute('role', 'menu');
      items.forEach(it => {
        if (it === '-') { m.appendChild(document.createElement('hr')); return; }
        if (it.head) { const h = document.createElement('div'); h.className = 'mh'; h.textContent = it.head; m.appendChild(h); return; }
        const b = document.createElement('button'); b.type = 'button'; b.setAttribute('role', 'menuitem');
        const s = document.createElement('span'); s.textContent = it.label; b.appendChild(s);
        b.onclick = e => { e.stopPropagation(); if (!it.keep) closeMenu(); it.fn(); };
        m.appendChild(b);
      });
      document.body.appendChild(m);
      const r = anchor.getBoundingClientRect(), w = m.offsetWidth, h = m.offsetHeight;
      m.style.left = Math.max(8, Math.min(r.right - w, innerWidth - w - 8)) + 'px';
      m.style.top = (r.bottom + h + 8 > innerHeight ? Math.max(8, r.top - h - 4) : r.bottom + 4) + 'px';
      const first = m.querySelector('button'); if (first) first.focus();
    }
    function trackMenu(anchor, t, opts) {
      const items = [];
      if (opts && opts.queueIndex != null) items.push({ label: 'remove from queue', fn: () => cmd('unqueue', { i: opts.queueIndex }) });
      else items.push({ label: 'play next', fn: () => { cmd('queue', { track: t, next: true }); toast('playing next'); } }, { label: 'add to queue', fn: () => { cmd('queue', { track: t }); toast('added to queue'); } });
      items.push({ label: 'add to playlist', keep: true, fn: () => playlistMenu(anchor, t) });
      if (opts && opts.pl) items.push('-', { label: 'remove from this playlist', fn: async () => {
        const p = view.data; if (!p) return;
        try { const np = await api('pl.save', { pl: { id: p.id, tracks: p.tracks.filter((_, i) => i !== opts.index) } }); view.fresh = np; render(); loadPls(); toast('removed'); } catch (e) { toast(e.message); }
      } });
      openMenu(anchor, items);
    }
    function playlistMenu(anchor, t) {
      if (!pls.signedIn) { closeMenu(); toast('sign in to make playlists'); return; }
      openMenu(anchor, [{ head: 'add to playlist' }, ...pls.lists.map(p => ({ label: p.name, fn: () => addTo(p.id, t) })), '-', { label: '+ new playlist', fn: () => newPlaylist([t], t.title) }]);
    }

    // ---------- clicks ----------
    document.addEventListener('click', e => {
      if (menuEl && !menuEl.contains(e.target)) closeMenu();
      if (!e.target.closest('#qp') && !e.target.closest('#b-q') && !e.target.closest('.menu')) $('qp').classList.remove('open');
    }, true);
    mu.addEventListener('click', e => {
      const T = e.target;
      const act = T.closest('[data-act=more]');
      if (act) { const row = act.closest('.tr'), L = lists[row.dataset.l], i = +row.dataset.i; if (L) trackMenu(act, L.tracks[i], { pl: L.opts.pl, index: i, queueIndex: L.opts.queue ? i : null }); return; }
      const row = T.closest('.tr[data-l]'); if (row) { playFrom(row.dataset.l, row.dataset.i); return; }
      const nav = T.closest('.mu-nav'); if (nav) { hist = []; go(nav.dataset.pl ? { v: 'pl', id: nav.dataset.pl } : { v: nav.dataset.v }, false); return; }
      if (T.closest('[data-back]')) return back();
      if (T.closest('[data-retry]')) return render();
      const open = T.closest('[data-open]'); if (open) return go({ v: 'list', id: open.dataset.open });
      const pl = T.closest('[data-pl]'); if (pl && !pl.classList.contains('mu-nav')) return go({ v: 'pl', id: pl.dataset.pl });
      if (T.closest('[data-newpl]') || T.closest('#newpl')) return newPlaylist();
      const firstRow = main.querySelector('.tl .tr[data-l]') || main.querySelector('.tr[data-l]'), first = firstRow && firstRow.dataset.l;
      if (T.closest('[data-playall]')) { if (first && lists[first].tracks.length) playFrom(first, 0); return; }
      if (T.closest('[data-shuffleall]')) { if (first && lists[first].tracks.length) playFrom(first, 0, true); return; }
      if (T.closest('[data-clearrecent]')) { api('clearRecent').then(render); return; }
      const d = view.data;
      if (T.closest('[data-copy]') && d) return newPlaylist(d.tracks, view.v === 'pl' ? d.name : d.title, view.v === 'pl' ? d.description : '');
      if (T.closest('[data-share]') && d) return share(d);
      if (T.closest('[data-pledit]')) { view.edit = true; view.fresh = d; render(); return; }
      if (T.closest('[data-plcancel]')) { view.edit = false; view.fresh = d; render(); return; }
      if (T.closest('[data-plsave]') && d) {
        const vis = (main.querySelector('#pl-vis .on') || {}).dataset;
        api('pl.save', { pl: { id: d.id, name: $('pl-name').value, description: $('pl-desc').value, visibility: vis ? vis.vis : d.visibility } })
          .then(p => { view.edit = false; view.fresh = p; render(); loadPls(); toast('saved'); }, err => toast(err.message));
        return;
      }
      const del = T.closest('[data-pldel]');
      if (del && d) {
        if (!del.dataset.sure) { del.dataset.sure = '1'; del.textContent = 'sure? click again'; setTimeout(() => { if (del.isConnected) { delete del.dataset.sure; del.textContent = 'delete'; } }, 3000); return; }
        api('pl.delete', { id: d.id }).then(() => { toast('playlist deleted'); hist = []; loadPls(); go({ v: 'library' }, false); }, err => toast(err.message));
      }
    });
    mu.addEventListener('keydown', e => { if (e.key === 'Enter' && e.target.classList && e.target.classList.contains('tr')) playFrom(e.target.dataset.l, e.target.dataset.i); });
    document.addEventListener('keydown', e => {
      if (e.key === 'Escape') { if (menuEl) return closeMenu(); if ($('qp').classList.contains('open')) return $('qp').classList.remove('open'); if (mu.classList.contains('song-open')) return closeSong(); }
      if (/^(input|textarea|select)$/i.test((document.activeElement || {}).tagName || '')) return;
      if (e.key === ' ' && !e.target.closest('button')) { e.preventDefault(); cmd('toggle'); }
    });

    // ---------- player bar ----------
    $('bar').addEventListener('click', e => { const b = e.target.closest('[data-c]'); if (b) cmd(b.dataset.c); });
    $('b-now').onclick = () => { if (st.track) openSong(); };
    $('b-lyr').onclick = () => { if (mu.classList.contains('song-open')) closeSong(); else if (st.track) openSong(); };
    $('b-q').onclick = () => { const q = $('qp'); q.classList.toggle('open'); if (q.classList.contains('open')) renderQueue(); };
    $('qp-x').onclick = () => $('qp').classList.remove('open');
    const seek = $('seek'), vol = $('vol'); let seeking = false, lastVol = 1;
    const setP = (el, f) => el.style.setProperty('--p', (Math.max(0, Math.min(1, f)) * 100) + '%');
    seek.addEventListener('input', () => { seeking = true; setP(seek, seek.value / 1000); $('b-cur').textContent = fmt(seek.value / 1000 * st.dur); });
    seek.addEventListener('change', () => { const t = seek.value / 1000 * st.dur; st.t = t; st.at = Date.now(); cmd('seek', { t }); seeking = false; });
    vol.addEventListener('input', () => { setP(vol, vol.value / 100); cmd('vol', { v: vol.value / 100 }); });
    $('b-mute').onclick = () => { if (st.vol > 0) { lastVol = st.vol; cmd('vol', { v: 0 }); } else cmd('vol', { v: lastVol || 1 }); };
    function renderQueue() {
      const q = st.queue || [], i = st.i;
      if (!q.length) { $('qp-l').innerHTML = '<div class="empty">the queue is empty</div>'; return; }
      $('qp-l').innerHTML = '<div class="qp-lbl">now playing, then up next</div>' + trackRows(q, { queue: true });
      const on = $('qp-l').querySelectorAll('.tr')[i]; if (on) on.scrollIntoView({ block: 'nearest' });
    }

    // ---------- song view ----------
    let lyrKey = '', lyr = null, lyrIdx = -1, lyrUserScroll = 0;
    function openSong() { mu.classList.add('song-open'); $('qp').classList.remove('open'); fillSong(); }
    function closeSong() { mu.classList.remove('song-open'); }
    $('song-close').onclick = closeSong;
    $('song-add').onclick = e => { if (st.track) playlistMenu(e.currentTarget, st.track); };
    $('song-q').onclick = () => { $('qp').classList.add('open'); renderQueue(); };
    function fillSong() {
      const t = st.track; if (!t) return;
      $('song-cov').innerHTML = img(t.cover); $('song-t').textContent = t.title; $('song-a').textContent = t.artist || '';
      $('song-bg').style.backgroundImage = t.cover ? `url("${t.cover.replace(/"/g, '')}")` : '';
      if (lyrKey === key(t)) return;
      lyrKey = key(t); lyr = null; lyrIdx = -1;
      const box = $('lyr'), k = lyrKey;
      box.innerHTML = '<div class="ly-msg">finding lyrics...</div>';
      api('lyrics', { track: t }).then(l => {
        if (k !== lyrKey) return; lyr = l;
        if (!l || (!l.synced && !l.plain)) { box.innerHTML = '<div class="ly-msg">no lyrics found for this one</div>'; return; }
        if (l.synced) { timeWords(l.synced); markRhymes(l.synced); box.innerHTML = l.synced.map((x, i) => `<button class="ly" type="button" data-t="${x.t}" data-n="${i}">${x.ws.length ? x.ws.map(w => `<span class="w${w.r ? ' rh' : ''}">${esc(w.w)}</span>`).join(' ') : '♪'}</button>`).join('') + `<div class="ly-src">lyrics from ${esc(l.source)}</div>`; }
        else box.innerHTML = `<div class="ly-plain">${esc(l.plain)}</div><div class="ly-src">lyrics from ${esc(l.source)}</div>`;
        box.style.paddingTop = box.style.paddingBottom = l.synced ? '' : '24px';
        box.scrollTop = 0; syncLyrics(true);
      }, () => { if (k === lyrKey) box.innerHTML = '<div class="ly-msg">couldn\'t load lyrics</div>'; });
    }
    $('lyr').addEventListener('click', e => { const b = e.target.closest('.ly[data-t]'); if (b) { const t = +b.dataset.t; st.t = t; st.at = Date.now(); cmd('seek', { t }); lyrUserScroll = 0; syncLyrics(true); } });
    $('lyr').addEventListener('wheel', () => { lyrUserScroll = Date.now(); }, { passive: true });
    $('lyr').addEventListener('touchmove', () => { lyrUserScroll = Date.now(); }, { passive: true });
    // when each word is sung. sources that time words are used as is, otherwise the line's time is shared out by
    // word length, capped so a long gap after a line (a solo, a pause) doesn't stretch the words across it
    function timeWords(lines) {
      lines.forEach((x, i) => {
        const words = String(x.text || '').split(/\s+/).filter(Boolean), next = lines[i + 1] ? lines[i + 1].t : x.t + 6;
        if (x.words && x.words.length) { x.ws = x.words.map((w, j) => ({ w: w.w, a: w.t, b: x.words[j + 1] ? x.words[j + 1].t : Math.min(x.end || next, w.t + 1.2) })); return; }
        if (!words.length) { x.ws = []; return; }
        const gap = Math.max(.4, (x.end > x.t ? Math.min(x.end, next) : next) - x.t), chars = words.reduce((n, w) => n + w.length + 1, 0);
        const dur = Math.min(gap * .95, Math.max(1, chars * .085));
        let at = x.t; x.ws = words.map(w => { const d = dur * (w.length + 1) / chars, o = { w, a: at, b: at + d }; at += d; return o; });
      });
    }
    // words that rhyme with another word nearby (same sound at the end, a different word) get r:true and glow from the moment they're sung until the line ends
    const RH_SKIP = new Set('the and you your that this with for but not are was were have has had can will just all got get its it\'s i\'m you\'re they them then than there here when what who how why out our one now yeah oh ooh uh hey gonna wanna from into over like'.split(' '));
    function rhymeKey(w) {
      w = w.toLowerCase().replace(/[^a-z]/g, '').replace(/y/g, 'i');
      if (w.length < 3 || RH_SKIP.has(w)) return '';
      w = w.replace(/([^aeiou])e$/, '$1').replace(/([aeiou][^aeiou]+)s$/, '$1').replace(/(.)\1$/, '$1');
      const m = w.match(/[aeiou]+[^aeiou]*$/); return m && (m[0].length > 1 || m[0] === 'i') ? m[0] : '';
    }
    function markRhymes(lines) {
      const by = {};
      lines.forEach((x, i) => (x.ws || []).forEach(o => { const k = rhymeKey(o.w); if (k) (by[k] = by[k] || []).push({ o, i, w: o.w.toLowerCase().replace(/[^a-z]/g, '') }); }));
      Object.values(by).forEach(g => g.forEach(e => { e.o.r = g.some(f => f !== e && f.w !== e.w && Math.abs(f.i - e.i) <= 4); }));
    }
    function syncLyrics(force) {
      if (!lyr || !lyr.synced || !mu.classList.contains('song-open')) return;
      const t = now() + .15; let i = -1;
      for (let j = 0; j < lyr.synced.length; j++) { if (lyr.synced[j].t <= t) i = j; else break; }
      const lines = $('lyr').querySelectorAll('.ly');
      if (i !== lyrIdx || force) {
        if (lines[lyrIdx]) lines[lyrIdx].querySelectorAll('.w').forEach(w => { w.style.removeProperty('--p'); w.classList.remove('glow'); });
        lyrIdx = i;
        lines.forEach((el, j) => { el.classList.toggle('on', j === i); el.classList.toggle('done', j < i); });
        if (lines[i] && Date.now() - lyrUserScroll > 3000) { const box = $('lyr'); box.scrollTop = lines[i].offsetTop - box.clientHeight * .4; }
      }
      // the white fill runs across the words of the current line
      const L = lyr.synced[i], ws = lines[i] ? lines[i].querySelectorAll('.w') : [];
      if (L && L.ws) L.ws.forEach((w, j) => { if (ws[j]) { ws[j].style.setProperty('--p', (t <= w.a ? 0 : t >= w.b ? 108 : (t - w.a) / (w.b - w.a) * 108).toFixed(1) + '%'); ws[j].classList.toggle('glow', !!w.r && t > w.a); } });
    }
    // smooth fill while the song view is open and playing, the 200ms tick covers the rest
    let lyrRaf = 0;
    function lyrLoop() { lyrRaf = 0; syncLyrics(); if (st.playing && lyr && lyr.synced && mu.classList.contains('song-open') && !document.hidden) lyrRaf = requestAnimationFrame(lyrLoop); }

    // ---------- state from the parent ----------
    let lastKey = null;
    function apply(s) {
      const prevKey = key(st.track);
      st = Object.assign({}, st, s, { queue: s.queue || st.queue });
      const t = st.track, k = key(t);
      $('bar').classList.toggle('none', !t); $('bar').classList.toggle('b-loading', !!st.loading);
      $('bar').querySelector('.b-ctl').classList.toggle('is-playing', !!st.playing);
      if (k !== lastKey) {
        lastKey = k;
        $('b-cov').innerHTML = t ? img(t.cover) : ''; $('b-t').textContent = t ? t.title : 'nothing playing';
        if (mu.classList.contains('song-open')) fillSong();
      }
      $('b-a').textContent = !t ? 'pick a song to start' : st.loading ? 'loading...' : st.error ? st.error : (t.artist || '');
      document.querySelector('[data-c=shuffle]').classList.toggle('on', !!st.shuffle);
      const rp = document.querySelector('[data-c=repeat]'); rp.classList.toggle('on', st.repeat !== 'off'); rp.querySelector('.one').hidden = st.repeat !== 'one';
      rp.title = 'repeat: ' + (st.repeat || 'off');
      if (document.activeElement !== vol) { vol.value = Math.round((st.vol || 0) * 100); setP(vol, st.vol || 0); }
      $('b-mute').innerHTML = (st.vol || 0) > 0 ? cfg.icons.volume : cfg.icons.mute;
      if (prevKey !== k || s.playing !== undefined) markPlaying();
      if ($('qp').classList.contains('open') && (s.queue || prevKey !== k)) renderQueue();
      tick();
    }
    function tick() {
      const d = st.dur || (st.track && st.track.dur) || 0, t = now();
      if (!seeking) { $('b-cur').textContent = fmt(t); seek.value = d ? Math.round(t / d * 1000) : 0; setP(seek, d ? t / d : 0); }
      $('b-dur').textContent = fmt(d);
      if (!lyrRaf) lyrLoop();
    }
    setInterval(tick, 200);
    window.addEventListener('message', e => {
      const m = e.data; if (!m) return;
      if (m.type === 'GHOSTLINK_MUSIC_API' && wait[m.id]) { const w = wait[m.id]; delete wait[m.id]; if (m.error) w.rej(new Error(m.error)); else w.res(m.data); }
      if (m.type === 'GHOSTLINK_NT_MUSIC' && m.state) apply(m.state);
      if (m.type === 'GHOSTLINK_NT_ACCOUNT') loadPls().then(() => { if (view.v === 'library' || view.v === 'pl' || view.v === 'list') render(); });
    });

    // ---------- start ----------
    (async () => {
      api('state').then(apply, () => {});
      await loadPls();
      const route = await api('route').catch(() => '');
      if (/^pl\//.test(route)) go({ v: 'pl', id: route.slice(3) }, false);
      else { go({ v: 'browse' }, false); if (route === 'now') setTimeout(() => { if (st.track) openSong(); }, 50); }
    })();
  };
  return pageShell(Object.assign({}, cfg, { icons }), 'music', body, script, css);
}

