  <script>/* p/js/app/pages/build.js */
// turns the internal pages into blob urls

async function buildInternalPages() {
  window.__fontHead = await getFontHead();
  const abs = p => new URL(p, __loc.href).href;
  const cfg = {
    brand: BRAND_PILL,
    // the svg build bundles the chatroom (jsdelivr serves .html as plain text), so it runs from a blob instead
    chatUrl: window.__chatHtml ? URL.createObjectURL(new Blob([window.__chatHtml], { type: 'text/html' })) : abs(CHAT_PAGE),
    libBase: abs(getBasePath() + 'p/js/lib/'),
    ai: {
      url: abs('/api/ai'),
      // where supabase keeps the session in localStorage, so the page can tell straight away if someone is signed in
      authKey: runtimeConfig.supabaseUrl ? 'sb-' + new URL(runtimeConfig.supabaseUrl).hostname.split('.')[0] + '-auth-token' : '',
      models: GROQ_MODELS
    },
    bookmarks: DEFAULT_BOOKMARKS,
    noAi: !!window.__noAi
  };
  const html = { home: pageHome(cfg), games: pageGames(cfg), chat: pageChat(cfg), music: pageMusic(cfg) };
  if (!cfg.noAi) html.ai = pageAi(cfg);
  window.__pageURLs = {};
  for (const [name, src] of Object.entries(html)) window.__pageURLs[name] = URL.createObjectURL(new Blob([src], { type: 'text/html' }));
}

