  <script>/* p/js/app/extensions.js */
// extension storage, installing from the chrome web store or a zip / folder, the marketplace and the toolbar.
// the chrome api the extensions run against is in ext-runtime.js and p/js/ext/api.js

const EXTENSION_DB_NAME='mochiiExtensions', EXTENSION_DB_VERSION=3;
const EXT_STORE_PROD='141.0';
let EXTENSIONS=[];
let extensionDbPromise=null, extBareClient=null;
const extTextCache=new Map();

// storage. extensions: one record each (manifest and state, no files). files: a blob per "<id>/<path>". kv: chrome.storage
function openExtensionDb(){
  if(extensionDbPromise)return extensionDbPromise;
  extensionDbPromise=new Promise((resolve,reject)=>{
    if(!('indexedDB'in window)){reject(new Error('indexeddb unavailable'));return}
    const req=indexedDB.open(EXTENSION_DB_NAME,EXTENSION_DB_VERSION);
    req.onupgradeneeded=()=>{const db=req.result;for(const s of ['extensions','files','kv'])if(!db.objectStoreNames.contains(s))db.createObjectStore(s,s==='extensions'?{keyPath:'id'}:undefined)};
    req.onsuccess=()=>{const db=req.result;db.onversionchange=()=>{db.close();extensionDbPromise=null};resolve(db)};
    req.onerror=()=>reject(req.error||new Error('could not open extension storage'));
    req.onblocked=()=>console.warn('extension storage upgrade is waiting for another tab');
  });
  return extensionDbPromise;
}
async function extTx(store,mode,fn){
  const db=await openExtensionDb();
  return new Promise((resolve,reject)=>{const tx=db.transaction(store,mode),os=tx.objectStore(store);let out;const r=fn(os);if(r&&'onsuccess'in r)r.onsuccess=()=>{out=r.result};tx.oncomplete=()=>resolve(out);tx.onerror=tx.onabort=()=>reject(tx.error||new Error('storage error'))});
}
const extAll=()=>extTx('extensions','readonly',os=>os.getAll()).then(x=>x||[]).catch(()=>[]);
async function extPut(rec){const clean=JSON.parse(JSON.stringify(rec));await extTx('extensions','readwrite',os=>os.put(clean));EXTENSIONS=EXTENSIONS.filter(x=>x.id!==clean.id).concat(clean);return clean}
async function extPatch(id,patch){const rec=EXTENSIONS.find(x=>x.id===id);if(!rec)return null;Object.assign(rec,patch);return extPut(rec)}
async function extWriteFiles(id,files){
  const db=await openExtensionDb();
  await new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite'),os=tx.objectStore('files');os.delete(IDBKeyRange.bound(id+'/',id+'/￿'));for(const [p,b] of files)os.put(b,id+'/'+p);tx.oncomplete=resolve;tx.onerror=tx.onabort=()=>reject(tx.error||new Error('could not save the extension files'))});
  for(const k of [...extTextCache.keys()])if(k.startsWith(id+'/'))extTextCache.delete(k);
}
const extReadFile=(id,path)=>extTx('files','readonly',os=>os.get(id+'/'+normalizeExtensionPath(path))).catch(()=>null);
async function extReadText(id,path){
  const key=id+'/'+normalizeExtensionPath(path);
  if(extTextCache.has(key))return extTextCache.get(key);
  const blob=await extReadFile(id,path),text=blob?await blob.text():null;
  extTextCache.set(key,text);return text;
}
const extKvGet=(id,area)=>extTx('kv','readonly',os=>os.get(id+':'+area)).then(x=>x||{}).catch(()=>({}));
const extKvSet=(id,area,obj)=>extTx('kv','readwrite',os=>os.put(obj,id+':'+area));
async function extRemoveAll(id){
  const db=await openExtensionDb();
  await new Promise(resolve=>{const tx=db.transaction(['extensions','files','kv'],'readwrite');tx.objectStore('extensions').delete(id);tx.objectStore('files').delete(IDBKeyRange.bound(id+'/',id+'/￿'));tx.objectStore('kv').delete(IDBKeyRange.bound(id+':',id+':￿'));tx.oncomplete=tx.onerror=tx.onabort=resolve});
  for(const k of [...extTextCache.keys()])if(k.startsWith(id+'/'))extTextCache.delete(k);
  EXTENSIONS=EXTENSIONS.filter(x=>x.id!==id);
}

function normalizeExtensionPath(path){return String(path||'').replace(/\\/g,'/').replace(/^\/+/, '').replace(/[?#].*$/,'')}
function resolveExtensionPath(base,file){
  const parts=(String(base||'')+'/'+normalizeExtensionPath(file)).split('/'),out=[];
  for(const part of parts){if(!part||part==='.')continue;if(part==='..')out.pop();else out.push(part)}
  return out.join('/');
}
function extensionMime(path){
  const ext=String(path||'').split('.').pop().toLowerCase();
  return ({html:'text/html',htm:'text/html',js:'text/javascript',mjs:'text/javascript',css:'text/css',json:'application/json',svg:'image/svg+xml',xml:'application/xml',txt:'text/plain',png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',webp:'image/webp',gif:'image/gif',ico:'image/x-icon',woff:'font/woff',woff2:'font/woff2',ttf:'font/ttf',otf:'font/otf',wasm:'application/wasm',mp3:'audio/mpeg',mp4:'video/mp4'})[ext]||'application/octet-stream';
}
const extBaseUrl=id=>__loc.origin+getBasePath()+'ext/'+id+'/';
// paths are from the extension root, and ".." can't climb above it (as with chrome-extension://<id>/)
const extFileUrl=(id,path)=>{if(!path)return '';const m=String(path).match(/^([^?#]*)(.*)$/);return extBaseUrl(id)+resolveExtensionPath('',m[1])+m[2]};

function extensionMatchPattern(pattern,url){
  if(pattern==='<all_urls>')return /^(https?|wss?|file|ftp):/i.test(url||'');
  try{
    const u=new URL(url),m=String(pattern||'').match(/^(\*|https?|wss?|file|ftp|urn):\/\/([^/]*)(\/.*)?$/i);if(!m)return false;
    const scheme=m[1].toLowerCase(),host=m[2].toLowerCase().replace(/:\d+$|:\*$/,''),path=m[3]||'/',h=u.hostname.toLowerCase();
    if(scheme==='*'?!/^(https?|wss?):$/.test(u.protocol):scheme!==u.protocol.slice(0,-1))return false;
    if(host!=='*'&&host!==h&&!(host.startsWith('*.')&&(h===host.slice(2)||h.endsWith('.'+host.slice(2)))))return false;
    return new RegExp('^'+path.replace(/[.+?^${}()|[\]\\]/g,'\\$&').replace(/\*/g,'.*')+'$').test(u.pathname+u.search);
  }catch{return false}
}
const extGlob=(g,url)=>new RegExp('^'+String(g).replace(/[.+^${}()|[\]\\]/g,'\\$&').replace(/\*/g,'.*').replace(/\?/g,'.')+'$').test(url);

// manifest helpers
function extManifestIcon(m){
  const c=m?.icons||m?.action?.default_icon||m?.browser_action?.default_icon||m?.page_action?.default_icon;
  if(typeof c==='string')return normalizeExtensionPath(c);
  if(c&&typeof c==='object'){const k=Object.keys(c).sort((a,b)=>Math.abs(a-48)-Math.abs(b-48))[0];if(k)return normalizeExtensionPath(c[k])}
  return '';
}
const extAction=m=>m?.action||m?.browser_action||m?.page_action||null;
const extPopupPath=m=>normalizeExtensionPath(extAction(m)?.default_popup||'');
const extOptionsPath=m=>normalizeExtensionPath(m?.options_ui?.page||m?.options_page||'');
const extSidePath=m=>normalizeExtensionPath(m?.side_panel?.default_path||'');
async function extLocalize(id,manifest,files){
  // messages for the ui language, falling back to default_locale
  const read=async loc=>{try{const raw=files?files.get('_locales/'+loc+'/messages.json'):await extReadFile(id,'_locales/'+loc+'/messages.json');return raw?JSON.parse((await raw.text()).replace(/^﻿/,'')):null}catch{return null}};
  const ui=(navigator.language||'en').replace('-','_'),def=manifest.default_locale||'en',out={};
  for(const loc of [...new Set([def,ui.split('_')[0],ui])]){const m=await read(loc);if(m)for(const [k,v] of Object.entries(m))out[k.toLowerCase()]=v}
  return out;
}
const extMsg=(text,messages)=>String(text||'').replace(/__MSG_([A-Za-z0-9_@]+)__/g,(x,k)=>messages?.[k.toLowerCase()]?.message??x);
// chrome's own id for a package with a "key": the first 128 bits of sha256(public key), written with a-p
async function extIdFromKey(key){
  try{const bin=Uint8Array.from(atob(String(key).replace(/\s+/g,'')),c=>c.charCodeAt(0)),h=new Uint8Array(await crypto.subtle.digest('SHA-256',bin));return [...h.slice(0,16)].map(b=>String.fromCharCode(97+(b>>4),97+(b&15))).join('')}catch{return ''}
}
const extRandomId=()=>[...crypto.getRandomValues(new Uint8Array(16))].map(b=>String.fromCharCode(97+(b>>4),97+(b&15))).join('');

// packages: a crx is a short header in front of a zip
function crxToZip(buf){
  const b=new Uint8Array(buf),v=new DataView(buf);
  if(b[0]===0x43&&b[1]===0x72&&b[2]===0x32&&b[3]===0x34){
    const ver=v.getUint32(4,true);
    if(ver===3)return buf.slice(12+v.getUint32(8,true));
    if(ver===2)return buf.slice(16+v.getUint32(8,true)+v.getUint32(12,true));
    throw new Error('unknown crx version '+ver);
  }
  return buf;
}
async function loadJsZip(){
  if(window.JSZip)return window.JSZip;
  await new Promise((res,rej)=>{const s=document.createElement('script');s.src=getBasePath()+'p/js/lib/jszip.min.js';s.onload=res;s.onerror=()=>rej(new Error('could not load jszip'));document.head.appendChild(s)});
  return window.JSZip;
}
async function readZipPackage(data){
  const zip=await (await loadJsZip()).loadAsync(data),names=Object.keys(zip.files).filter(n=>!zip.files[n].dir);
  const mf=names.filter(n=>/(^|\/)manifest\.json$/i.test(n)).sort((a,b)=>a.length-b.length)[0];if(!mf)throw new Error('manifest.json was not found in the package');
  const base=mf.slice(0,mf.lastIndexOf('/')+1),files=new Map();
  for(const n of names){if(!n.startsWith(base))continue;const p=normalizeExtensionPath(n.slice(base.length));files.set(p,new Blob([await zip.file(n).async('arraybuffer')],{type:extensionMime(p)}))}
  return files;
}
async function readFolderPackage(list){
  const arr=[...list],mf=arr.filter(f=>/(^|\/)manifest\.json$/i.test(f.webkitRelativePath||f.name)).sort((a,b)=>(a.webkitRelativePath||a.name).length-(b.webkitRelativePath||b.name).length)[0];
  if(!mf)throw new Error('manifest.json was not found in the folder');
  const rel=normalizeExtensionPath(mf.webkitRelativePath||mf.name),base=rel.slice(0,rel.lastIndexOf('/')+1),files=new Map();
  for(const f of arr){const p=normalizeExtensionPath(f.webkitRelativePath||f.name);if(p.startsWith(base))files.set(p.slice(base.length),new Blob([await f.arrayBuffer()],{type:extensionMime(p)}))}
  return files;
}

async function installExtensionFiles(files,{id='',source='custom',enabled=true,pinned}={}){
  const raw=files.get('manifest.json');if(!raw)throw new Error('manifest.json is missing');
  let manifest;try{manifest=JSON.parse((await raw.text()).replace(/^﻿/,''))}catch{throw new Error('manifest.json is not valid json')}
  if(manifest.manifest_version!==2&&manifest.manifest_version!==3)throw new Error('only manifest v2 and v3 extensions are supported');
  if(!id)id=(manifest.key&&await extIdFromKey(manifest.key))||extRandomId();
  const messages=await extLocalize(id,manifest,files),old=EXTENSIONS.find(x=>x.id===id);
  if(old)await extensionStop(id);
  await extWriteFiles(id,files);
  let size=0;for(const b of files.values())size+=b.size;
  const rec=await extPut({
    id,source,manifest,size,
    name:extMsg(manifest.name,messages)||id,short:extMsg(manifest.short_name||'',messages),
    version:String(manifest.version||''),description:extMsg(manifest.description||'',messages),
    icon:extManifestIcon(manifest),enabled:old?old.enabled:enabled,pinned:old?old.pinned:(pinned??EXTENSIONS.filter(x=>x.pinned).length<4),
    installedAt:old?.installedAt||Date.now(),updatedAt:Date.now(),
    dnr:old?.dnr||{},scripts:old?.scripts||[],installReason:old?(old.version===String(manifest.version)?'':'update'):'install',previousVersion:old?.version||''
  });
  extTextCache.clear();
  await extensionStart(rec.id);
  renderExtensionControls();updateExtensionToolbar();
  return rec;
}

// the store, through the proxy, so it works wherever mochii does
async function extProxyFetch(url,init){
  const BM=await ensureBareMuxLoaded();await getSharedConnection();
  if(!extBareClient)extBareClient=new BM.BareClient();
  return extBareClient.fetch(url,init);
}
const extStoreCrxUrl=id=>`https://clients2.google.com/service/update2/crx?response=redirect&prodversion=${EXT_STORE_PROD}&acceptformat=crx2,crx3&x=id%3D${id}%26uc`;
const extInstalling=new Map();
async function installFromStore(id,{quiet=false,pinned}={}){
  id=String(id||'').toLowerCase();
  if(!/^[a-p]{32}$/.test(id))throw new Error('that is not a chrome web store id');
  if(extInstalling.has(id))return extInstalling.get(id).promise;
  const job={progress:0,promise:null};extInstalling.set(id,job);renderExtensionControls();
  job.promise=(async()=>{
    try{
      const res=await extProxyFetch(extStoreCrxUrl(id));
      if(res.status===204||!res.ok)throw new Error(res.status===204?'the web store has no download for it (it may be removed or not for chrome)':'the web store answered '+res.status);
      const total=Number(res.headers.get('content-length'))||0,parts=[];let got=0;
      // a download that stops moving for 30s is given up on, so a stuck connection can't hold the install forever
      if(res.body?.getReader){const rd=res.body.getReader();for(;;){let t;const {done,value}=await Promise.race([rd.read(),new Promise((_,rej)=>t=setTimeout(()=>rej(new Error('the download stalled')),30000))]).finally(()=>clearTimeout(t)).catch(e=>{rd.cancel().catch(()=>{});throw e});if(done)break;parts.push(value);got+=value.length;if(total){job.progress=got/total;extProgressPaint(id)}}}
      else parts.push(new Uint8Array(await res.arrayBuffer()));
      const buf=await new Blob(parts).arrayBuffer();if(!buf.byteLength)throw new Error('the download was empty');
      const files=await readZipPackage(crxToZip(buf));
      const rec=await installExtensionFiles(files,{id,source:'store',pinned});
      if(!quiet)extToast(`${rec.name} added`,rec);
      return rec;
    }finally{extInstalling.delete(id);renderExtensionControls()}
  })();
  return job.promise;
}
function extProgressPaint(id){const job=extInstalling.get(id);document.querySelectorAll(`[data-ext-progress="${id}"]`).forEach(el=>el.textContent=job?`${Math.round(job.progress*100)}%`:'')}

async function handleExtensionZip(file){try{const files=await readZipPackage(crxToZip(await file.arrayBuffer()));const rec=await installExtensionFiles(files,{source:'custom'});extToast(`${rec.name} added`,rec)}catch(e){alert(`could not install extension: ${e?.message||'invalid package'}`)}}
async function handleExtensionFolder(list){try{const rec=await installExtensionFiles(await readFolderPackage(list),{source:'custom'});extToast(`${rec.name} added`,rec)}catch(e){alert(`could not install extension: ${e?.message||'invalid folder'}`)}}
async function toggleExtension(id,on){
  const rec=EXTENSIONS.find(x=>x.id===id);if(!rec)return;
  on=on??!rec.enabled;if(on===rec.enabled)return;
  await extPatch(id,{enabled:on});
  if(on)await extensionStart(id);else await extensionStop(id);
  renderExtensionControls();updateExtensionToolbar();
  const tab=getActiveTab();if(tab&&!tab.page&&tab.url)reloadTab(tab);
}
async function uninstallExtension(id){
  const rec=EXTENSIONS.find(x=>x.id===id);if(!rec)return;
  if(!confirm(`remove ${rec.name}?`))return;
  await extensionStop(id);await extRemoveAll(id);await extSyncWorker();
  renderExtensionControls();updateExtensionToolbar();
}
async function extTogglePin(id){const rec=EXTENSIONS.find(x=>x.id===id);if(rec){await extPatch(id,{pinned:!rec.pinned});updateExtensionToolbar();renderExtensionControls()}}

async function initializeExtensions(){
  try{await openExtensionDb()}catch{EXTENSIONS=[];return}
  EXTENSIONS=await extAll();
  // the old format kept files inside the record, and nothing reads that any more
  for(const old of EXTENSIONS.filter(x=>x.files||x.source==='builtin'||x.source==='library'))await extRemoveAll(old.id);
}
// ublock origin lite goes in on the first run. a failure is retried on the next start
async function installDefaultExtensions(){
  let done={};try{done=JSON.parse(localStorage.getItem('mochiiExtDefaults')||'{}')}catch{}
  for(const id of EXT_DEFAULTS){
    if(done[id]||EXTENSIONS.some(x=>x.id===id))continue;
    try{await installFromStore(id,{quiet:true,pinned:true});done[id]=1;try{localStorage.setItem('mochiiExtDefaults',JSON.stringify(done))}catch{}}
    catch(e){console.warn('could not install the default extension',id,e)}
  }
}

// marketplace. store details (name, icon, rating) are read from the web store page once and cached for a week
const extStoreCache={};
function extStoreInfoCached(id){
  if(extStoreCache[id])return extStoreCache[id];
  try{const o=JSON.parse(localStorage.getItem('mochiiExtStore:'+id)||'null');if(o&&Date.now()-o.t<7*864e5)return extStoreCache[id]=o}catch{}
  return null;
}
let extStoreQueue=Promise.resolve();
function extStoreInfo(id){
  const cached=extStoreInfoCached(id);if(cached)return Promise.resolve(cached);
  const p=extStoreQueue.then(async()=>{
    if(extStoreInfoCached(id))return extStoreInfoCached(id);
    try{
      const html=await (await extProxyFetch('https://chromewebstore.google.com/detail/'+id)).text(),doc=new DOMParser().parseFromString(html,'text/html');
      const meta=k=>doc.querySelector(`meta[property="og:${k}"]`)?.getAttribute('content')||'';
      const users=(html.match(/>([\d,.]+\+?\s*(?:k|m)?\+?)\s*users</i)||[])[1]||'',rating=(html.match(/Average rating ([\d.]+) out of 5/i)||[])[1]||'';
      const o={t:Date.now(),name:meta('title').replace(/\s*-\s*Chrome Web Store$/,''),desc:meta('description'),icon:meta('image'),users,rating};
      try{localStorage.setItem('mochiiExtStore:'+id,JSON.stringify(o))}catch{}
      return extStoreCache[id]=o;
    }catch{return null}
  });
  extStoreQueue=p.catch(()=>{});
  return p;
}
async function extStoreSearch(q){
  const html=await (await extProxyFetch('https://chromewebstore.google.com/search/'+encodeURIComponent(q))).text(),doc=new DOMParser().parseFromString(html,'text/html'),out=[],seen=new Set();
  for(const el of doc.querySelectorAll('[data-item-id]')){
    const id=el.getAttribute('data-item-id');if(!/^[a-p]{32}$/.test(id)||seen.has(id))continue;seen.add(id);
    const name=el.querySelector('h2')?.textContent?.trim()||'',rating=(el.querySelector('[aria-label*="rating"]')?.getAttribute('aria-label')||'').match(/([\d.]+) out of/)?.[1]||'';
    const img=[...el.querySelectorAll('img')].map(i=>i.getAttribute('src')||'').find(s=>/googleusercontent/.test(s))||'';
    const desc=[...el.querySelectorAll('p,div')].map(x=>x.childElementCount?'':x.textContent.trim()).filter(t=>t.length>30).sort((a,b)=>b.length-a.length)[0]||'';
    out.push({id,name,rating,img,blurb:desc.slice(0,140)});
  }
  return out;
}
const extIdFromInput=v=>{const m=String(v||'').trim().match(/(?:^|\/|id=)([a-p]{32})(?:$|[/?#&])/i);return m?m[1].toLowerCase():''};

let extMarketCat='all',extMarketQuery='',extMarketResults=null,extMarketBusy=false;
function extIconHtml(rec,storeIcon,label){
  const src=rec?.icon?extFileUrl(rec.id,rec.icon):storeIcon;
  return src?`<img src="${escapeHtml(src)}" alt="" loading="lazy">`:`<span>${escapeHtml(String(label||'?').trim().slice(0,1).toUpperCase())}</span>`;
}
function extMarketCard(item){
  const rec=EXTENSIONS.find(x=>x.id===item.id),info=extStoreInfoCached(item.id),job=extInstalling.get(item.id);
  const name=rec?.name||info?.name||item.name||item.id,blurb=item.blurb||info?.desc||'';
  const meta=[info?.rating||item.rating?`★ ${escapeHtml(info?.rating||item.rating)}`:'',info?.users?escapeHtml(info.users)+' users':''].filter(Boolean).join(' · ');
  const btn=job?`<button class="btn" disabled>adding <span data-ext-progress="${item.id}">${Math.round(job.progress*100)}%</span></button>`:rec?`<button class="btn" data-ext-manage="${item.id}">added</button>`:`<button class="btn primary" data-ext-add="${item.id}">add</button>`;
  return `<div class="ext-store-card" data-ext-card="${item.id}"><div class="ext-icon">${extIconHtml(rec,info?.icon||item.img,name)}</div><div class="ext-store-info"><div class="ext-name">${escapeHtml(name)}</div>${meta?`<div class="ext-meta">${meta}</div>`:''}<div class="ext-desc">${escapeHtml(blurb)}</div></div><div class="ext-store-action">${btn}</div></div>`;
}
function renderExtensionMarket(){
  const box=document.getElementById('ext-market');if(!box)return;
  const chips=document.getElementById('ext-market-cats');
  if(chips)chips.innerHTML=EXT_CATEGORIES.map(c=>`<button type="button" class="ext-chip ${extMarketCat===c.key&&!extMarketResults?'active':''}" data-ext-cat="${c.key}">${escapeHtml(c.label)}</button>`).join('');
  let items,head='';
  if(extMarketResults){items=extMarketResults;head=`<div class="ext-market-head"><span>${extMarketBusy?'searching the web store…':`${items.length} results for "${escapeHtml(extMarketQuery)}" from the chrome web store`}</span><button class="btn" type="button" data-ext-clear>back to featured</button></div>`}
  else items=EXTENSION_CATALOG.filter(x=>extMarketCat==='all'||x.cat===extMarketCat);
  box.innerHTML=head+(items.length?`<div class="ext-store-grid">${items.map(extMarketCard).join('')}</div>`:extMarketBusy?'':'<div class="ext-empty">nothing found. try another search, or paste a chrome web store link</div>');
