  const open=!document.getElementById('wisp-settings-modal')?.classList.contains('hidden')&&!box.closest('.settings-pane')?.classList.contains('hidden');
  if(open&&!extMarketResults)for(const it of items)if(!extStoreInfoCached(it.id))extStoreInfo(it.id).then(o=>{if(!o)return;const el=box.querySelector(`[data-ext-card="${it.id}"]`);if(el)el.outerHTML=extMarketCard(it)});
}
async function extMarketSearch(q){
