  if(id){extMarketResults=[{id,name:'',blurb:'from the chrome web store'}];renderExtensionMarket();extStoreInfo(id).then(()=>renderExtensionMarket());return}
  const local=EXTENSION_CATALOG.filter(x=>(x.name+' '+x.blurb).toLowerCase().includes(q.toLowerCase()));
  extMarketResults=local;extMarketBusy=true;renderExtensionMarket();
  try{const found=await extStoreSearch(q);if(extMarketQuery!==q)return;const ids=new Set(local.map(x=>x.id));extMarketResults=local.concat(found.filter(x=>!ids.has(x.id)))}
