  if(m.background)p.push(m.background.service_worker?'service worker':'background page');
  if((m.content_scripts||[]).length||(rec.scripts||[]).length)p.push('content scripts');
  if(extPopupPath(m))p.push('popup');if(extOptionsPath(m))p.push('options');if(extSidePath(m))p.push('side panel');
  if(m.declarative_net_request)p.push('network rules');
