}
function renderInstalledExtensions(){
  const box=document.getElementById('ext-installed');if(!box)return;
  const list=EXTENSIONS.slice().sort((a,b)=>a.name.localeCompare(b.name));
  if(!list.length){box.innerHTML='<div class="ext-empty">no extensions yet. add one from the marketplace below</div>';return}
