      ${extOptionsPath(m)&&rec.enabled?`<button class="btn" data-ext-options="${rec.id}">options</button>`:''}
      <button class="btn ext-pin ${rec.pinned?'active':''}" data-ext-pin="${rec.id}" title="${rec.pinned?'unpin from toolbar':'pin to toolbar'}">${rec.pinned?'pinned':'pin'}</button>
      ${rec.source==='store'?`<button class="btn" data-ext-update="${rec.id}">${extInstalling.has(rec.id)?'updating…':'update'}</button>`:''}
      <button class="btn" data-ext-remove="${rec.id}">remove</button>
      <button type="button" class="switch ${rec.enabled?'active':''}" data-ext-toggle="${rec.id}" aria-label="${rec.enabled?'turn off':'turn on'} ${escapeHtml(rec.name)}"><i></i></button></div></div>`;
  }).join('');
