function renderExtensionControls(){renderInstalledExtensions();renderExtensionMarket()}
function bindExtensionPane(){
  const pane=document.querySelector('[data-settings-pane="extensions"]');if(!pane||pane._bound)return;pane._bound=true;
  const input=document.getElementById('ext-market-search');
  if(input){let t=0;input.addEventListener('keydown',e=>{if(e.key==='Enter'){clearTimeout(t);extMarketSearch(input.value)}});input.addEventListener('input',()=>{clearTimeout(t);if(!input.value.trim())extMarketSearch('');else if(extIdFromInput(input.value))extMarketSearch(input.value);else t=setTimeout(()=>extMarketSearch(input.value),600)})}
