    const b=e.target.closest('button');if(!b)return;const d=b.dataset;
    if(d.extCat){extMarketCat=d.extCat;extMarketResults=null;if(input)input.value='';renderExtensionMarket()}
    else if(d.extClear!==undefined){extMarketResults=null;if(input)input.value='';renderExtensionMarket()}
    else if(d.extAdd){try{await installFromStore(d.extAdd)}catch(err){alert(`could not add it: ${err?.message||err}`)}}
    else if(d.extManage){document.getElementById('ext-installed')?.scrollIntoView({behavior:'smooth',block:'start'})}
