    else if(d.extPin)extTogglePin(d.extPin);
    else if(d.extRemove)uninstallExtension(d.extRemove);
    else if(d.extUpdate){try{await installFromStore(d.extUpdate,{quiet:true});extToast('updated')}catch(err){alert(`could not update: ${err?.message||err}`)}}
