    const st=extActionState?.(rec.id,tab.id)||{},icon=extIconFor(rec,tab.id),badge=st.text?`<b class="ext-badge" style="${st.color?`background:${escapeHtml(st.color)};`:''}${st.textColor?`color:${escapeHtml(st.textColor)};`:''}">${escapeHtml(String(st.text).slice(0,4))}</b>`:'';
    return `<button type="button" class="extension-toolbar-button ${st.enabled===false?'dim':''}" data-ext-action="${rec.id}" title="${escapeHtml(st.title||rec.name)}">${icon?`<img src="${escapeHtml(icon)}" alt="">`:`<span>${escapeHtml(rec.name.slice(0,1).toUpperCase())}</span>`}${badge}</button>`;
