}
const EXT_PUZZLE='<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"><path d="M10 4a2 2 0 1 1 4 0v2h4v4h-1.5a2 2 0 1 0 0 4H18v4h-4v-1.5a2 2 0 1 0-4 0V18H6v-4h1.5a2 2 0 1 0 0-4H6V6h4z"/></svg>';
function extToolbarClick(e){
  const b=e.target.closest('button');if(!b)return;
  if(b.dataset.extAction)extActionClick(b.dataset.extAction,b);
  else if(b.dataset.extMenu!==undefined)openExtensionMenu(b);
}
function openExtensionMenu(anchor){
