  pop.innerHTML=`<div class="ext-menu-title">extensions</div>${on.length?on.map(rec=>`<div class="ext-menu-row"><button type="button" class="ext-menu-main" data-m-act="${rec.id}"><span class="ext-icon sm">${extIconHtml(rec,'',rec.name)}</span><span>${escapeHtml(rec.name)}</span></button><button type="button" class="ext-menu-pin ${rec.pinned?'active':''}" data-m-pin="${rec.id}" title="${rec.pinned?'unpin':'pin'}"><svg viewBox="0 0 24 24" width="14" height="14" fill="${rec.pinned?'currentColor':'none'}" stroke="currentColor" stroke-width="1.8"><path d="M9 3h6l-1 6 3 3v2H7v-2l3-3zM12 14v7"/></svg></button></div>`).join(''):'<div class="ext-empty">no extensions turned on</div>'}<button type="button" class="ext-menu-manage" data-m-manage>manage extensions</button>`;
  pop.onclick=e=>{const b=e.target.closest('button');if(!b)return;
    if(b.dataset.mAct){closeExtPopup();extActionClick(b.dataset.mAct,document.querySelector(`[data-ext-action="${b.dataset.mAct}"]`)||anchor)}
    else if(b.dataset.mPin){extTogglePin(b.dataset.mPin).then(()=>openExtensionMenu(document.querySelector('[data-ext-menu]')||anchor))}
