  el.innerHTML=`${rec||opts.icon?`<span class="ext-icon sm">${opts.icon?`<img src="${escapeHtml(opts.icon)}" alt="">`:extIconHtml(rec,'',rec.name)}</span>`:''}<div class="ext-toast-text">${opts.title?`<b>${escapeHtml(opts.title)}</b>`:''}<span>${escapeHtml(text)}</span>${(opts.buttons||[]).map((b,i)=>`<button type="button" class="btn" data-i="${i}">${escapeHtml(b.title||'')}</button>`).join('')}</div><button type="button" class="ext-toast-x" aria-label="dismiss">&times;</button>`;
