// messaging
async function extWaitBg(extId){const b=extBg.get(extId);if(b)await Promise.race([b.ready,new Promise(r=>setTimeout(r,8000))])}
async function extSend(c,target,msg){
  const sender=extSender(c);let recv,ev='runtime.onMessage';
  if(target.tab!=null){recv=extContentOf(c.extId,target.tab,target.frameId??null);if(target.documentId)recv=recv.filter(x=>x.frame?.docId===target.documentId)}
  else{
    const ext=target.ext||c.extId;if(ext!==c.extId)ev='runtime.onMessageExternal';
    if(!extOn(ext))extErr('Could not establish connection. Receiving end does not exist.');
    await extWaitBg(ext);recv=extPagesOf(ext,c.id);
  }
  const json=JSON.stringify([msg,sender]);
  return new Promise((resolve,reject)=>{
    let left=recv.length,none=false,done=false;
    const settle=()=>{if(done||left>0)return;done=true;none?resolve(undefined):reject(new Error('Could not establish connection. Receiving end does not exist.'))};
    if(!left)return settle();
    for(const r of recv){
      Promise.resolve().then(()=>r.rt?.dispatch(ev,json)).then(out=>{left--;if(done)return;if(out&&'r' in out){done=true;resolve(out.r)}else{if(out)none=true;settle()}},e=>{left--;console.error(e);settle()});
    }
  });
}
function extPortOpen(ctxId,portId,info){
  const c=extCtx.get(ctxId);if(!c)return;
  const t=info.target||{};let recv,ev='runtime.onConnect';
  if(t.tab!=null)recv=extContentOf(c.extId,t.tab,info.frameId??null);
  else{const ext=t.ext||c.extId;if(ext!==c.extId)ev='runtime.onConnectExternal';recv=extPagesOf(ext,c.id)}
  const p={a:ctxId,b:new Set()};extPorts.set(portId,p);
  const json=JSON.stringify([portId,info.name||'',extSender(c)]);
  const go=()=>{for(const r of recv){try{if(r.rt?.dispatch(ev,json))p.b.add(r.id)}catch(e){console.error(e)}}if(!p.b.size)extPortClose(-1,portId,'Could not establish connection. Receiving end does not exist.')};
  if(t.tab==null)extWaitBg(t.ext||c.extId).then(()=>{recv=extPagesOf(t.ext||c.extId,c.id);go()});else go();
}
function extPortClose(fromId,portId,err){
  const p=extPorts.get(portId);if(!p)return;
  const tell=id=>{const x=extCtx.get(id);if(x?.rt&&extLive(x)&&id!==fromId)setTimeout(()=>{try{x.rt.portClosed(portId,err||'')}catch{}},0)};
  if(fromId===p.a||fromId===-1){extPorts.delete(portId);p.b.forEach(tell);tell(p.a)}
  else{p.b.delete(fromId);if(!p.b.size){extPorts.delete(portId);tell(p.a)}}
}

// storage. local and sync persist in indexeddb, session lives as long as the app does, managed is always empty
async function extArea(id,area){
