    [p+'get']:async(c,keys)=>{const obj=await extArea(c.extId,area),out={};if(keys&&typeof keys==='object'&&!Array.isArray(keys))Object.assign(out,keys);for(const k of extKeysOf(keys,obj))if(k in obj)out[k]=obj[k];return out},
    [p+'getKeys']:async c=>Object.keys(await extArea(c.extId,area)),
    [p+'set']:(c,items)=>extStorageChange(c,area,(o,ch)=>{for(const [k,v] of Object.entries(items||{})){if(v===undefined)continue;const nv=extJson(v);ch(k,o[k],nv);o[k]=nv}}),
    [p+'remove']:(c,keys)=>extStorageChange(c,area,(o,ch)=>{for(const k of extKeysOf(keys,o)){if(k in o){ch(k,o[k],undefined);delete o[k]}}}),
    [p+'clear']:c=>extStorageChange(c,area,(o,ch)=>{for(const k of Object.keys(o)){ch(k,o[k],undefined);delete o[k]}}),
    [p+'getBytesInUse']:async(c,keys)=>{const o=await extArea(c.extId,area);let n=0;for(const k of extKeysOf(keys,o))if(k in o)n+=k.length+JSON.stringify(o[k]).length;return n},
    [p+'setAccessLevel']:()=>undefined
