  const win=extApiFactory(fr.win);
  c=extNewCtx({extId:rec.id,kind:'content',win,tabId:fr.tabId,frameId:fr.frameId,frame:fr,url:fr.url});
  c.rt=win.__mochiiApi(window.__mochiiExt,extCtxInfo(c));c.world=win.__mochiiWorld(win,c.rt.chrome);
