    const c=extContentCtx(fr,rec);
    if(value)return new win.Function('chrome','self','globalThis','__c','return eval(__c)').call(c.world,c.rt.chrome,c.world,c.world,src);
    return new win.Function('chrome','self','globalThis',src).call(c.world,c.rt.chrome,c.world,c.world);
