  const fr=extFrameRecord(win,tab,top);if(!fr)return;
  const nav={tabId:fr.tabId,frameId:fr.frameId,parentFrameId:fr.parentFrameId,url:fr.url,timeStamp:Date.now(),documentId:fr.docId,documentLifecycle:'active',frameType:fr.frameId?'sub_frame':'outermost_frame'};
