function extTargetFrames(target){
  const tab=extTab(target?.tabId);if(!tab)extErr(`No tab with id: ${target?.tabId}.`);
  if(tab.page)extErr('Cannot access contents of the page. Extension manifest must request permission to access the respective host.');
  try{const w=tab.frame.frame.contentWindow;if(w&&!extFrames.has(w))extFrameRecord(w,tab,w)}catch{}
  let list=[...extFrames.values()].filter(f=>f.tabId===tab.id&&extLive({win:f.win}));
