// context menus, shown on right click in pages that have any (shift + right click gives the normal menu)
function extMenuItems(contexts){
  const out=[];
  for(const [extId,items] of extMenus){if(!extOn(extId))continue;for(const it of items){if(it.visible===false)continue;const cs=it.contexts||['page'];if(cs.includes('all')&&!contexts.includes('action')||cs.some(x=>contexts.includes(x)))out.push({extId,it})}}
  return out;
