function extPageMenu(fr,e){
  if(e.shiftKey||!extMenus.size)return;
  const t=e.target,ctxs=['page','frame'],info={frameId:fr.frameId,pageUrl:extTabObj(fr.tab).url,frameUrl:fr.url,editable:false};
  const sel=String(fr.win.getSelection?.()||'');if(sel){ctxs.push('selection');info.selectionText=sel}
  const a=t.closest?.('a[href]');if(a){ctxs.push('link');info.linkUrl=extRealUrl(a.href);info.linkText=a.textContent}
  const media=t.closest?.('img,video,audio');if(media){const k=media.tagName.toLowerCase()==='img'?'image':media.tagName.toLowerCase();ctxs.push(k);info.mediaType=k;info.srcUrl=extRealUrl(media.currentSrc||media.src)}
  if(t.closest?.('input,textarea,[contenteditable=""],[contenteditable="true"]')){ctxs.push('editable');info.editable=true}
  const items=extMenuItems(ctxs).filter(({it})=>(!it.documentUrlPatterns||it.documentUrlPatterns.some(p=>extensionMatchPattern(p,info.pageUrl)))&&(!it.targetUrlPatterns||!(info.linkUrl||info.srcUrl)||it.targetUrlPatterns.some(p=>extensionMatchPattern(p,info.linkUrl||info.srcUrl))));
