  extShowMenu(x,y,items,info,fr.tab);
}
function extShowMenu(x,y,items,info,tab,extra=[]){
  closeExtPopup();
  const el=document.createElement('div');el.className='ext-popup ext-ctx';document.body.appendChild(extPopupEl=el);
  const byExt=new Map();for(const x of items){if(!byExt.has(x.extId))byExt.set(x.extId,[]);byExt.get(x.extId).push(x.it)}
  const label=(it,sel)=>escapeHtml(String(it.title||'').replace(/%s/g,sel||''));
  let html='';
  for(const [extId,list] of byExt){
    const rec=extRec(extId),top=list.filter(i=>!i.parentId),kids=id=>list.filter(i=>i.parentId===id);
    const row=(it,depth)=>it.type==='separator'?'<div class="ext-ctx-sep"></div>':`<button type="button" class="ext-ctx-item" style="padding-left:${12+depth*14}px" data-e="${extId}" data-i="${escapeHtml(String(it.id))}" ${it.enabled===false?'disabled':''}>${it.type==='checkbox'||it.type==='radio'?(it.checked?'✓ ':'<span class="ext-ctx-gap"></span>'):''}${label(it,info.selectionText)}</button>`+kids(it.id).map(k=>row(k,depth+1)).join('');
    html+=byExt.size>1||top.length>1?`<div class="ext-ctx-head">${escapeHtml(rec?.name||'')}</div>`:'';
    html+=top.map(it=>row(it,0)).join('');
  }
  html+=extra.map((b,i)=>`<button type="button" class="ext-ctx-item" data-x="${i}">${escapeHtml(b.label)}</button>`).join('');
  el.innerHTML=html;
  const r=el.getBoundingClientRect();el.style.left=Math.min(x,innerWidth-r.width-8)+'px';el.style.top=Math.min(y,innerHeight-r.height-8)+'px';
  setTimeout(()=>{document.addEventListener('mousedown',extPopupOutside,true);window.addEventListener('blur',extPopupBlur)},0);
  el.onclick=e=>{const b=e.target.closest('button');if(!b)return;closeExtPopup();
    if(b.dataset.x!=null)return extra[Number(b.dataset.x)].run();
    const list=extMenus.get(b.dataset.e)||[],it=list.find(i=>String(i.id)===b.dataset.i);if(!it)return;
    const was=it.checked;if(it.type==='checkbox')it.checked=!it.checked;if(it.type==='radio'){list.filter(i=>i.type==='radio'&&i.parentId===it.parentId).forEach(i=>i.checked=false);it.checked=true}
    extFire(b.dataset.e,'contextMenus.onClicked',[Object.assign({menuItemId:it.id,parentMenuItemId:it.parentId,checked:it.checked,wasChecked:was},info),extTabObj(tab)]);
  };
}
function extToolbarMenu(e){
  const b=e.target.closest('[data-ext-action]');if(!b)return;e.preventDefault();
  const id=b.dataset.extAction,rec=extRec(id),tab=getActiveTab();
  const extra=[...(extOptionsPath(rec.manifest)?[{label:'options',run:()=>openExtensionSurface(id,'options')}]:[]),{label:'unpin',run:()=>extTogglePin(id)},{label:'manage extensions',run:()=>{openSettings();setSettingsSection('extensions')}}];
  const items=extMenuItems(['action','browser_action','page_action']).filter(x=>x.extId===id);
