// alarms
function extAlarmSet(id,name,info){
  const m=extAlarms.get(id)||new Map();extAlarms.set(id,m);
  const old=m.get(name);if(old){clearTimeout(old.t);clearInterval(old.i)}
  const when=info.when||Date.now()+(info.delayInMinutes??info.periodInMinutes??0)*6e4,period=info.periodInMinutes;
