  <script>/* p/js/app/tabs.js */
// tab state, kept internal pages and the tab strip

let tabs = [];
let activeTabId = null;
let nextTabId = 1;
let _dragSrcTabId = null;

const getActiveTab = () => tabs.find(t => t.id === activeTabId);
function reloadTab(tab) {
  if (!tab) return;
  clearTimeout(tab.skipTimeout);
  clearTimeout(tab.loadFallbackTimeout);
  // only real urls go through beginLoad. internal pages have no loading state to clear later
  if (tab.page || !tab.url) cancelLoad(tab);
  if (tab.page && window.__pageURLs?.[tab.page]) {
    if (tab.keptShown && tab.kept?.[tab.keptShown]) tab.kept[tab.keptShown].src = window.__pageURLs[tab.page];
    else tab.frame.frame.src = window.__pageURLs[tab.page];
  } else if (tab.url) {
    beginLoad(tab, true);
    tab.frame.go(tab.url);
  } else {
    tab.frame.frame.src = 'about:blank';
  }
  if (tab.id === activeTabId) {
    setBrowserMode(tab.forceChrome || (!tab.page && Boolean(tab.url)));
    if (tab.page) showIframeLoading(false);
  }
  updateTabsUI();
  updateAddressBar();
}

function ensureKept(tab, name) {
  tab.kept = tab.kept || {};
  if (!tab.kept[name]) {
    const el = document.createElement('iframe');
    el.className = 'hidden';
    el.setAttribute('referrerpolicy', 'no-referrer');
    el.setAttribute('allow', 'autoplay; fullscreen; clipboard-write; microphone; camera; display-capture');
    el.src = window.__pageURLs[name];
    document.getElementById('iframe-container').appendChild(el);
    tab.kept[name] = el;
  }
  return tab.kept[name];
}

function syncFrames() {
  tabs.forEach(t => {
    t.frame.frame.classList.toggle('hidden', t.id !== activeTabId || !!t.keptShown);
    Object.entries(t.kept || {}).forEach(([name, el]) => el.classList.toggle('hidden', t.id !== activeTabId || t.keptShown !== name));
  });
}

function internalWindows() {
  const list = [];
  tabs.forEach(t => {
    if (t.page && t.frame?.frame?.contentWindow && !t.keptShown) list.push(t.frame.frame.contentWindow);
    Object.values(t.kept || {}).forEach(el => { if (el.contentWindow) list.push(el.contentWindow); });
  });
  return list;
}

function tabOfWindow(w) {
  return tabs.find(t => t.frame?.frame?.contentWindow === w || Object.values(t.kept || {}).some(el => el.contentWindow === w));
}

function openPage(name, tab = getActiveTab(), push = true) {
  if (!tab || !window.__pageURLs?.[name]) return;
  cancelLoad(tab);
  tab.page = name; tab.url = ''; tab.title = PAGE_TITLES[name] || name; tab.favicon = null; tab.loading = false;
  tab.forceChrome = false;
  if (push && !tab._navigating) {
    tab.historyStack = tab.historyStack.slice(0, tab.historyIndex + 1);
    tab.historyStack.push('page:' + name);
    tab.historyIndex = tab.historyStack.length - 1;
  }
  if (KEPT_PAGES.includes(name)) {
    ensureKept(tab, name);
    tab.keptShown = name;
    // unload the site behind it, or it keeps playing audio and its url changes pull the tab back
    tab.frame.frame.src = 'about:blank';
  } else {
    tab.keptShown = null;
    tab.frame.frame.src = window.__pageURLs[name];
  }
  syncFrames();
  if (tab.id === activeTabId) showIframeLoading(false);

  updateTabsUI(); updateAddressBar();
  setBrowserMode(false);
  window.dispatchEvent(new CustomEvent('page-switched', {
    detail: { page: name, tabId: tab.id }
  }));
}
function createTab(makeActive=true, page=NEW_TAB_PAGE, options={}) {
  if (tabs.length >= 12) return null;
  const frame = activeProxy === 'ultraviolet' ? createUvFrame() : sharedScramjet.createFrame();
  frame.frame.setAttribute('allow', 'display-capture; microphone; clipboard-write; fullscreen; autoplay');
  const forceChrome = options.forceChrome ?? false;
  const tab = {
    id:nextTabId++, title:PAGE_TITLES[page] || page, url:'', page, forceChrome, frame, loading:false, favicon:null,
    skipTimeout:null, loadFallbackTimeout:null, loadStartTime:null,
    historyStack:['page:'+page], historyIndex:0, _navigating:false, _erudaOpen:false
  };
  if (!KEPT_PAGES.includes(page)) frame.frame.src = window.__pageURLs[page];
  frame.addEventListener('urlchange', e => {
    tab.page = null;
    tab.keptShown = null;
    syncFrames();
    tab.url = e.url;
    if (!tab._navigating) {
      tab.historyStack = tab.historyStack.slice(0, tab.historyIndex + 1);
      if (tab.historyStack[tab.historyIndex] !== e.url) tab.historyStack.push(e.url);
      tab.historyIndex = tab.historyStack.length - 1;
    }
    if (!tab.loading) beginLoad(tab, false);
    try {
      const u = new URL(e.url);
      tab.title = u.hostname || 'browsing';
      tab.favicon = `https://www.google.com/s2/favicons?domain=${encodeURIComponent(u.hostname)}&sz=32`;
    } catch { tab.title='browsing'; tab.favicon=null; }
    updateTabsUI(); updateAddressBar();
    extTabEvent('updated', tab, { url: e.url });
  });
  frame.frame.addEventListener('load', () => {
    if (tab.page && !tab._cover) {
      cancelLoad(tab);
      if (tab.id === activeTabId) setBrowserMode(tab.forceChrome || (!tab.page && Boolean(tab.url)));
    }
    try {
      const cw = frame.frame.contentWindow;
      if (cw && cw.open && !cw.__glOpenPatched) {
        const orig = cw.open.bind(cw);
        cw.open = function(url, target, features) {
          if (typeof url === 'string' && url && url !== 'about:blank') {
            let target = url;
            try { target = new URL(url, tab.url || undefined).href; } catch {}
            openUrlInNewTab(target); return null;
          }
          return orig(url, target, features);
        };
        cw.__glOpenPatched = true;
      }
    } catch {}
    try {
      const title = frame.frame.contentWindow.document.title;
      if (title && !tab.page) tab.title = title;
    } catch {}
    updateTabsUI(); updateAddressBar();
    if(!tab.page&&tab.url)runExtensionsForTab(tab,true).catch(err=>console.warn('extension runtime error',err));
    updateExtensionToolbar();
    extTabEvent('updated', tab, { status: 'complete', title: tab.title });
  });
  tabs.push(tab);
  frame.frame.classList.add('hidden');
  frame.frame.setAttribute('referrerpolicy','no-referrer');
  document.getElementById('iframe-container').appendChild(frame.frame);
  if (KEPT_PAGES.includes(page)) { ensureKept(tab, page); tab.keptShown = page; }
  extTabEvent('created', tab);
  if (makeActive) switchTab(tab.id);
  syncFrames();
  updateTabsUI();
  return tab;
}

function openUrlInNewTab(url) {
  const t = createTab(true, 'home', { forceChrome: true });
  if (t) handleSubmit(url, t);
}

function switchTab(tabId) {
  activeTabId = tabId;
  const active = getActiveTab();
  syncFrames();
  if (active) {
    showIframeLoading(active.loading, active.url);
    setBrowserMode(active.forceChrome || (!active.page && Boolean(active.url)));
  } else {
    setBrowserMode(false);
  }
  updateTabsUI(); updateAddressBar(); updateExtensionToolbar();
  if (active) extTabEvent('activated', active);
  window.dispatchEvent(new CustomEvent('tab-switched', {
    detail: { tabId: tabId, page: active?.page || null }
  }));
}

function closeTab(tabId) {
  const idx = tabs.findIndex(t => t.id === tabId);
  if (idx === -1) return;
  const tab = tabs[idx];
  clearTimeout(tab.skipTimeout); clearTimeout(tab.loadFallbackTimeout); clearInterval(tab._poll);
  try { tab.frame.frame.src='about:blank'; } catch {}
  Object.values(tab.kept || {}).forEach(el => el.remove());
  tab.frame.frame.remove(); tabs.splice(idx,1);
  extTabEvent('removed', tab);
  if (activeTabId === tabId) {
    if (tabs.length) switchTab(tabs[Math.max(0, idx - 1)].id); else createTab(true, 'home');
  } else updateTabsUI();
  updateExtensionToolbar();
}

function updateTabsUI() {
  const container = document.getElementById('tabs-container');
  if (!container) return;
  container.innerHTML='';
  tabs.forEach(tab => {
    const el = document.createElement('div');
    el.className = `tab ${tab.id === activeTabId ? 'active' : ''}`;
    el.draggable = true; el.dataset.tabId = tab.id;
    const iconHtml = tab.loading ? `<div class="tab-spinner"></div>` : tab.favicon ? `<img class="tab-favicon" src="${tab.favicon}" alt="">` : `${icon('search',16)}`;
    el.innerHTML = `${iconHtml}<span class="tab-title">${escapeHtml(tab.title)}</span><span class="tab-close">×</span>`;
    el.onclick = () => switchTab(tab.id);
    el.querySelector('.tab-close').onclick = e => { e.stopPropagation(); closeTab(tab.id); };
    el.addEventListener('dragstart', e => { _dragSrcTabId=tab.id; e.dataTransfer.effectAllowed='move'; });
    el.addEventListener('dragover', e => { e.preventDefault(); if (tab.id !== _dragSrcTabId) el.classList.add('drag-over'); });
    el.addEventListener('dragleave', () => el.classList.remove('drag-over'));
    el.addEventListener('dragend', () => { _dragSrcTabId = null; container.querySelectorAll('.drag-over').forEach(x => x.classList.remove('drag-over')); });
    el.addEventListener('drop', e => {
      e.preventDefault(); el.classList.remove('drag-over');
      if (_dragSrcTabId === null || _dragSrcTabId === tab.id) return;
      const from=tabs.findIndex(t=>t.id===_dragSrcTabId), to=tabs.findIndex(t=>t.id===tab.id);
      if (from<0 || to<0) return;
      const [moved]=tabs.splice(from,1); tabs.splice(to,0,moved); _dragSrcTabId=null; updateTabsUI();
    });
    container.appendChild(el);
  });
}

