              <button class="nm-btn" type="button" data-nm="toggle" aria-label="play or pause" title="play / pause"><span class="i-play">${pgIcon('playo', 15)}</span><span class="i-pause">${pgIcon('pauseo', 15)}</span></button>
              <button class="nm-btn" type="button" data-nm="next" aria-label="next" title="next">${pgIcon('nexto', 15)}</button>
