          <div class="window-controls">
            <button class="proxy-action" id="home-btn-nav" title="home">${icon('home')}</button>
            <button class="proxy-action" id="devtools-btn" title="devtools">${icon('dev')}</button>
            <button class="proxy-action" id="wisp-settings-btn" title="pr0xy settings">${icon('settings')}</button>
          </div>
        </nav>

        <div class="tabbar" id="tabbar">
          <div class="tabs-container" id="tabs-container"></div>
          <button class="new-tab-btn" id="new-tab-btn" title="new tab">${icon('plus')}</button>
        </div>

        <div class="iframe-container" id="iframe-container">
          <div class="loading-bar-container"><div class="loading-bar" id="loading-bar"></div></div>
          <div class="page-loading" id="page-loading"><div class="spinner"></div><span>loading</span></div>
          <div id="error" class="message-container" style="display:none">
            <div class="message-content"><h1>connection error</h1><p id="error-message">an error occurred.</p></div>
          </div>
        </div>
      </section>
    </div>`;

  const addr = document.getElementById('address-bar');

  renderExtensionControls(); updateExtensionToolbar();
  { const bar = document.getElementById('extension-toolbar'); bar.onclick = extToolbarClick; bar.oncontextmenu = extToolbarMenu; }

  document.getElementById('back-btn').onclick = () => navigateHistory(-1);
  document.getElementById('fwd-btn').onclick = () => navigateHistory(1);
  document.getElementById('reload-btn').onclick = () => reloadTab(getActiveTab());
  document.getElementById('home-btn-nav').onclick = () => goHome();
  document.getElementById('devtools-btn').onclick = toggleDevTools;
  const settingsBtn = document.getElementById('wisp-settings-btn');
  if (settingsBtn) settingsBtn.onclick = openSettings;
  let lastNewTabAt = 0;
  document.getElementById('new-tab-btn').onclick = () => {
    const now = Date.now();
    if (now - lastNewTabAt < 400) return;
    lastNewTabAt = now;
    createTab(true, 'home', { forceChrome: true });
  };
  document.getElementById('nav-music').onclick = e => {
    const b = e.target.closest('[data-nm]');
    if (b) musicCommand({ cmd: b.dataset.nm });
    else if (e.target.closest('#nm-now')) openMusicRoute(mTrack() ? 'now' : '', getActiveTab());
  };
  updateNavMusic();
  attachSuggest(addr, v => { addr.value = v; handleSubmit(); });
  addr.addEventListener('keydown', e => { if (e.key === 'Enter') handleSubmit(); });
  addr.addEventListener('focus', () => addr.select());
  window.addEventListener('message', e => {
    const sourceTab = tabOfWindow(e.source);
    const fromInternal = !!sourceTab?.page;
    if (fromInternal && e.data?.type === 'navigate' && e.data.url) handleSubmit(e.data.url, sourceTab);
    if (fromInternal && e.data?.type === 'gl_open_tab' && e.data.url) openUrlInNewTab(String(e.data.url));
    if (fromInternal && e.data?.type === 'gl_page') {
      const page = e.data.page;
      if (page === 'music' && e.data.route) openMusicRoute(e.data.route, sourceTab); else openPage(page, sourceTab);
    }
    if (fromInternal && e.data?.type === 'gl_settings') { openSettings(); if (e.data.section) setSettingsSection(e.data.section); }
    if (fromInternal && e.data?.type === 'gl_palette') togglePalette();
    if (fromInternal && e.data?.type === 'gl_ai_token') { const src = e.source, id = e.data.id; accountAccessToken().then(token => { try { src.postMessage({ type: 'GHOSTLINK_AI_TOKEN', id, token }, '*'); } catch {} }); }
    if (fromInternal && e.data?.type === 'gl_activity') setActivity(e.data.game, e.source);
    if (fromInternal && e.data?.type === 'gl_discord') handleSubmit(DISCORD_URL, sourceTab);
    if (fromInternal && e.data?.type === 'gl_music') musicCommand(e.data);
    if (fromInternal && e.data?.type === 'gl_music_api') handleMusicApi(e);
  });
  createTab(true, 'home');
  checkHashParameters();
  window.addEventListener('hashchange', checkHashParameters);
}

function setBrowserMode(showChrome) {
  const shell = document.getElementById('browser-container');
  if (!shell) return;
  const browsing = Boolean(showChrome);
  shell.classList.toggle('landing-mode', !browsing);
  shell.classList.toggle('browsing-mode', browsing);
  updateTabsUI(); updateExtensionToolbar();
}

function navigateHistory(direction) {
  const tab = getActiveTab();
  if (!tab) return;
  const next = tab.historyIndex + direction;
  if (next < 0 || next >= tab.historyStack.length) return;
  tab._navigating = true;
  tab.historyIndex = next;
  const target = tab.historyStack[next];
  if (typeof target === 'string' && target.startsWith('page:')) {
    openPage(target.slice(5), tab, false);
  } else {
    setBrowserMode(true);
    leaveKept(tab);
    beginLoad(tab, true);
    tab._pendingUrl = target;
    tab.frame.go(target);
  }
  clearTimeout(tab._navTimer);
  tab._navTimer = setTimeout(() => { tab._navigating = false; }, 2500);
}

function goHome() {
  const tab = getActiveTab();
  if (!tab) return;
  cancelLoad(tab);
  tab.forceChrome = false; openPage('home', tab, true);
  setBrowserMode(false);
}
function updateAddressBar() {
  const bar=document.getElementById('address-bar'); const tab=getActiveTab();
  if (!bar || !tab) return;
  bar.value = (!tab.page && tab.url) ? tab.url : '';
}

function resolveInput(raw) {
  const input = String(raw).trim();
  if (/^https?:\/\//i.test(input)) return input;
  if (/\s/.test(input)) return getSearchUrl(input);
  if (/^(\d{1,3}\.){3}\d{1,3}(:\d+)?([/?#].*)?$/.test(input)) return `http://${input}`;
  if (/^([a-z0-9-]+\.)+[a-z]{2,}(:\d+)?([/?#].*)?$/i.test(input)) return `https://${input}`;
  return getSearchUrl(input);
}

function leaveKept(tab) {
  if (!tab || !tab.keptShown) return;
  tab.keptShown = null;
  syncFrames();
}

function handleSubmit(url, targetTab) {
  const tab=targetTab || getActiveTab();
  if (!tab) return;
  const raw = (url ?? document.getElementById('address-bar').value);
  if (!String(raw).trim()) return;
  const input = resolveInput(raw);
  if (input === getSearchUrl(String(raw).trim())) recordSearch(String(raw).trim());
  if (tab.id === activeTabId) setBrowserMode(true);
  tab.forceChrome = true;
  leaveKept(tab);
  beginLoad(tab, true);
  tab._pendingUrl = input;
  tab.frame.go(input);
}
function hideErudaEntryBtn(win) {
  const attempt=tries=>{ try { const c=win.document.getElementById('eruda'); if(!c){if(tries) setTimeout(()=>attempt(tries-1),80);return;} const root=c.shadowRoot||c; const btn=root.querySelector('.eruda-entry-btn'); if(btn) btn.style.cssText+='display:none!important;visibility:hidden!important;pointer-events:none!important;'; else if(tries) setTimeout(()=>attempt(tries-1),80); } catch {} };
  attempt(10);
}

async function toggleDevTools() {
  const tab=getActiveTab(); const win=tab?.frame.frame.contentWindow; if(!win) return;
  try {
    if(win.eruda) {
      if(tab._erudaOpen){win.eruda.hide();tab._erudaOpen=false;} else {win.eruda.show();hideErudaEntryBtn(win);tab._erudaOpen=true;}
      return;
    }
    const script=win.document.createElement('script'); script.textContent=await (await fetch(getBasePath()+'p/js/lib/eruda.js')).text();
    win.document.body.appendChild(script);
    win.eruda.init();win.eruda.show();hideErudaEntryBtn(win);tab._erudaOpen=true;
  } catch(e) { console.warn('devtools unavailable',e); }
}

function checkHashParameters() {
  if (!__loc.hash) return;
  let hash='';
  try { hash=decodeURIComponent(__loc.hash.slice(1)); } catch { hash=__loc.hash.slice(1); }
  // #music/pl/<id> is a shared playlist, everything else is a url to open
  if(/^music\//.test(hash)) openMusicRoute(hash.slice(6)); else if(hash) handleSubmit(hash);
  __hist.replaceState(null,'',__loc.pathname + __loc.search);
}

