// stored preferences and the settings modal

const SETTINGS_DEFAULTS = { motion:'full', grid:true, glow:false, hover:true, compact:false, engine:'duckduckgo', font:'lexend', proxy:'scramjet', transport:'epoxy', blockStats:true, shareActivity:true };
function getSetting(key) {
  try { const raw=localStorage.getItem('mochiiSetting:'+key); if(raw===null) return SETTINGS_DEFAULTS[key]; return raw==='true'?true:raw==='false'?false:raw; } catch { return SETTINGS_DEFAULTS[key]; }
}
function setSetting(key, value) { try { localStorage.setItem('mochiiSetting:'+key, String(value)); } catch {} queueSettingsSync(); }
function applyStoredSettings() {
  const root=document.documentElement;
  root.classList.remove('motion-subtle','motion-off');
  if(getSetting('motion')==='subtle') root.classList.add('motion-subtle');
  if(getSetting('motion')==='off') root.classList.add('motion-off');
  root.classList.toggle('grid-off', !getSetting('grid'));
  root.classList.toggle('glow-on', !!getSetting('glow'));
  root.classList.toggle('no-hover', !getSetting('hover'));
  root.classList.toggle('compact-ui', !!getSetting('compact'));
  const font=FONTS.find(f=>f.key===getSetting('font')) || FONTS[0];
  root.style.setProperty('--font', font.css);
  root.style.setProperty('--font-weight', font.key === 'lexend' ? '450' : '400');
  root.classList.toggle('block-stats-off', !getSetting('blockStats'));
  if (typeof syncActivity === 'function') syncActivity();
}
function getSearchUrl(query) {
  const q=encodeURIComponent(query);
  const engine=getSetting('engine');
  return engine==='google'?`https://www.google.com/search?q=${q}`:
    engine==='bing'?`https://www.bing.com/search?q=${q}`:
    engine==='brave'?`https://search.brave.com/search?q=${q}`:
    `https://duckduckgo.com/?q=${q}`;
}
function setSettingsSection(section){
  const available=[...document.querySelectorAll('[data-settings-pane]')].map(pane=>pane.dataset.settingsPane);
  const target=available.includes(section)?section:'preferences';
  try{localStorage.setItem('mochiiSettingsSection',target)}catch{}
  document.querySelectorAll('[data-settings-section]').forEach(btn=>btn.classList.toggle('active',btn.dataset.settingsSection===target));
  document.querySelectorAll('[data-settings-pane]').forEach(pane=>pane.classList.toggle('hidden',pane.dataset.settingsPane!==target));
  if(target==='extensions') { bindExtensionPane(); renderExtensionControls(); }
}

function renderSettingsControls() {
  document.querySelectorAll('[data-setting-select]').forEach(btn=>{
    const key=btn.dataset.settingSelect, value=btn.dataset.value;
    btn.classList.toggle('active', getSetting(key)===value);
    btn.onclick=()=>{ setSetting(key,value); applyStoredSettings(); renderSettingsControls(); };
  });
  document.querySelectorAll('[data-setting-toggle]').forEach(btn=>{
    const key=btn.dataset.settingToggle, on=!!getSetting(key);
    btn.classList.toggle('active',on);
    btn.onclick=()=>{ setSetting(key,!getSetting(key)); applyStoredSettings(); renderSettingsControls(); };
  });
  const engine=document.getElementById('search-engine-setting');
  if(engine){ engine.value=getSetting('engine'); engine.onchange=()=>{setSetting('engine',engine.value);}; }
  const fontSel=document.getElementById('font-setting');
  if(fontSel){
    if(!fontSel.options.length) FONTS.forEach(f=>{ const o=document.createElement('option'); o.value=f.key; o.textContent=f.label; fontSel.appendChild(o); });
    fontSel.value=getSetting('font');
    fontSel.onchange=()=>{ setSetting('font',fontSel.value); applyStoredSettings(); sendThemeToNtTabs(); };
  }
  const proxySel=document.getElementById('proxy-setting');
  if(proxySel){
    proxySel.value=getSetting('proxy');
    proxySel.onchange=async()=>{
      setSetting('proxy',proxySel.value);
      if(sb && sbUser) await pushSettings();
      __loc.reload();
    };
  }
  const transportSel=document.getElementById('transport-setting');
  if(transportSel){ transportSel.value=getSetting('transport'); transportSel.onchange=()=>{ setSetting('transport',transportSel.value); __loc.reload(); }; }
  const clearHist=document.getElementById('clear-history');
  if(clearHist) clearHist.onclick=clearSearchHistory;
  const resetBlocks=document.getElementById('reset-block-stats');
  if(resetBlocks) resetBlocks.onclick=resetBlockStats;
  renderBlockStats();
}

function resetAppearanceSettings() {
  ['motion','grid','glow','hover','compact','engine','font'].forEach(key=>{ try{localStorage.removeItem('mochiiSetting:'+key);}catch{} });
  try{localStorage.removeItem('mochiiTheme');}catch{}
  try{localStorage.setItem('mochiiBackground', DEFAULT_WALLPAPER);}catch{}
  applyTheme(getTheme());
  applyStoredSettings(); renderThemeList(); renderSettingsControls(); sendThemeToNtTabs(); sendBackgroundToNtTabs();
  queueSettingsSync();
}
function openSettings() {
  const modal=document.getElementById('wisp-settings-modal');
  if(!modal) return;
  modal.classList.remove('hidden');
  const closeBtn = document.getElementById('close-wisp-modal');
  const saveWispBtn = document.getElementById('save-custom-wisp');
  const resetBtn = document.getElementById('reset-settings');
  if (closeBtn) closeBtn.onclick=()=>modal.classList.add('hidden');
  modal.querySelectorAll('[data-settings-pane="about"] a').forEach(a=>{
    a.removeAttribute('target');
    a.onclick=e=>{ e.preventDefault(); modal.classList.add('hidden'); handleSubmit(a.href); };
  });
  if (saveWispBtn) saveWispBtn.onclick=saveCustomWisp;
  if (resetBtn) resetBtn.onclick=resetAppearanceSettings;
  const tourBtn=document.getElementById('replay-tour');
  if (tourBtn) tourBtn.onclick=()=>{ modal.classList.add('hidden'); startTour(); };
  const backgroundUploadBtn=document.getElementById('background-upload-btn');
  const backgroundRemoveBtn=document.getElementById('background-remove-btn');
  const backgroundFileInput=document.getElementById('background-file-input');
  if(backgroundUploadBtn && backgroundFileInput) backgroundUploadBtn.onclick=()=>backgroundFileInput.click();
  if(backgroundRemoveBtn) backgroundRemoveBtn.onclick=()=>setCustomBackground('');
  if(backgroundFileInput) backgroundFileInput.onchange=e=>{
    const file=e.target.files?.[0];
    if(file && file.type.startsWith('image/')) {
      const reader=new FileReader();
