  <script>/* p/js/app/theme.js */
// themes, and pushing theme vars into internal pages

const THEMES = [
  { key:'default', label:'onyx', dot:'#ffffff' },
  { key:'catppuccin', label:'mocha', dot:'#cba6f7' },
  { key:'tokyo night', label:'midnight', dot:'#7aa2f7' },
  { key:'everforest', label:'moss', dot:'#a7c080' },
  { key:'kanagawa', label:'tide', dot:'#7e9cd8' },
  { key:'sakura', label:'blossom', dot:'#ff69b4' },
  { key:'halloween', label:'halloween', dot:'#ff7518' },
  { key:'auto', label:'wallpaper', dot:'conic-gradient(#ff69b4,#a7c080,#7aa2f7,#cba6f7,#ff69b4)' }
];
function getTheme() {
  let stored='auto';
  try { stored=localStorage.getItem('mochiiTheme') || 'auto'; } catch {}
  return THEMES.some(theme=>theme.key===stored) ? stored : 'auto';
}
function applyTheme(key) {
  if (key === 'default') document.documentElement.removeAttribute('data-theme');
  else document.documentElement.setAttribute('data-theme', key);
  try { localStorage.setItem('mochiiTheme', key); } catch {}
  if (key === 'auto') applyAutoTheme(); else clearAutoTheme();
  queueSettingsSync();

  renderThemeList();
  applyStoredSettings();
  sendThemeToNtTabs();
}

function renderThemeList() {
  const list=document.getElementById('theme-list'); if(!list) return; list.innerHTML='';
  const current=getTheme();
  const name=document.getElementById('settings-theme-name'); if(name) name.textContent=(THEMES.find(t=>t.key===current)||THEMES[0]).label;
  THEMES.forEach(theme=>{
    const el=document.createElement('button');
    el.type='button';
    el.className=`theme-swatch ${theme.key===current?'active':''}`;
    el.innerHTML=`<span class="theme-dot" style="background:${theme.dot}"></span>${escapeHtml(theme.label)}`;
    el.onclick=()=>applyTheme(theme.key);
    list.appendChild(el);
  });
}
function sendThemeToNtTabs() {
  const vars = readThemeVars();
  const background = getCustomBackground();
  internalWindows().forEach(w => {
    try { w.postMessage({type:'GHOSTLINK_NT_THEME', vars}, '*'); } catch {}
    try { w.postMessage({type:'GHOSTLINK_NT_BACKGROUND', background}, '*'); } catch {}
  });
}

// 'auto' theme: build the palette from the wallpaper's main colour, set as inline vars on <html>
const AUTO_THEME_VARS = ['--bg-body','--bg-body-translucent','--bg-grid','--surface-0','--surface-1','--surface-2','--surface-3','--surface-4',
  '--surface-5','--surface-hover','--surface-active','--text-primary','--text-secondary','--text-muted','--text-faint','--accent',
  '--accent-soft','--accent-active','--input','--search-inset','--search-inset-focus','--search-glow','--border-faint','--border-medium'];
let autoThemeReq = 0;
function clearAutoTheme() {
  autoThemeReq++;
  AUTO_THEME_VARS.forEach(k=>document.documentElement.style.removeProperty(k));
}
function setAutoThemeVars(vars) {
  const r=document.documentElement.style;
  AUTO_THEME_VARS.forEach(k=>{ if(vars[k]) r.setProperty(k,vars[k]); else r.removeProperty(k); });
}
function hslHex(h, s, l) {
  s=Math.max(0,Math.min(1,s)); l=Math.max(0,Math.min(1,l));
  const f=n=>{ const k=(n+h/30)%12, c=l-s*Math.min(l,1-l)*Math.max(-1,Math.min(k-3,9-k,1)); return Math.round(c*255).toString(16).padStart(2,'0'); };
  return '#'+f(0)+f(8)+f(4);
}
// strongest colour in the image: hue buckets weighted by saturation, ignoring near-black and near-white
function wallpaperColour(img) {
  const size=48, c=document.createElement('canvas'); c.width=c.height=size;
  const ctx=c.getContext('2d',{willReadFrequently:true}); ctx.drawImage(img,0,0,size,size);
  const px=ctx.getImageData(0,0,size,size).data, bins=Array.from({length:24},()=>({w:0,x:0,y:0,s:0}));
  let total=0, hx=0, hy=0;
  for(let i=0;i<px.length;i+=4){
    const r=px[i]/255, g=px[i+1]/255, b=px[i+2]/255, max=Math.max(r,g,b), min=Math.min(r,g,b), l=(max+min)/2, d=max-min;
    if(l<.06 || l>.96) continue;
    const s=d ? d/(1-Math.abs(2*l-1)) : 0;
    let h=0; if(d) h=max===r ? ((g-b)/d+6)%6 : max===g ? (b-r)/d+2 : (r-g)/d+4; h*=60;
    const a=h*Math.PI/180, w=s*s*(1-Math.abs(l-.5)), bin=bins[Math.floor(h/15)%24];
    bin.w+=w; bin.x+=Math.cos(a)*w; bin.y+=Math.sin(a)*w; bin.s+=s*w;
    total++; hx+=Math.cos(a); hy+=Math.sin(a);
  }
  const best=bins.reduce((a,b)=>b.w>a.w?b:a);
  if(!total) return { h:0, s:0 };
  if(best.w/total<.003) return { h:(Math.atan2(hy,hx)*180/Math.PI+360)%360, s:.06 };
  return { h:(Math.atan2(best.y,best.x)*180/Math.PI+360)%360, s:best.s/best.w };
}
function autoThemeVars({h, s}) {
  const t=Math.min(s*.45,.22), L=l=>hslHex(h,t,l), bg=L(.075);
  const accent = s<.12 ? hslHex(h,s,.86) : hslHex(h,Math.max(.5,Math.min(s*1.15,.85)),.72);
  const n=parseInt(bg.slice(1),16);
  return {
    '--bg-body':bg, '--bg-body-translucent':`rgba(${n>>16},${n>>8&255},${n&255},.79)`, '--bg-grid':L(.15),
    '--surface-0':L(.08), '--surface-1':L(.09), '--surface-2':L(.1), '--surface-3':L(.11), '--surface-4':L(.13), '--surface-5':L(.16),
    '--surface-hover':L(.24), '--surface-active':L(.3),
    '--text-primary':hslHex(h,t*.6,.92), '--text-secondary':hslHex(h,t*.6,.8), '--text-muted':hslHex(h,t*.5,.57), '--text-faint':hslHex(h,t*.5,.44),
    '--accent':accent, '--accent-soft':accent+'18', '--accent-active':accent+'33', '--search-glow':accent+'40',
    '--input':L(.17), '--search-inset':L(.105), '--search-inset-focus':L(.135), '--border-faint':L(.26)+'88', '--border-medium':L(.26)
  };
}
function applyAutoTheme() {
  const req=++autoThemeReq, bg=getCustomBackground(), key=bg.length>2000 ? bg.length+':'+bg.slice(-200) : bg;
  if(!bg) { AUTO_THEME_VARS.forEach(k=>document.documentElement.style.removeProperty(k)); sendThemeToNtTabs(); return; }
  let cached=null; try { cached=JSON.parse(localStorage.getItem('mochiiAutoTheme')||'null'); } catch {}
  if(cached?.bg===key && cached.vars) { setAutoThemeVars(cached.vars); sendThemeToNtTabs(); return; }
  const img=new Image();
  img.onload=()=>{
    if(req!==autoThemeReq) return;
    try {
      const vars=autoThemeVars(wallpaperColour(img));
      setAutoThemeVars(vars);
      try { localStorage.setItem('mochiiAutoTheme', JSON.stringify({ bg:key, vars })); } catch {}
    } catch { AUTO_THEME_VARS.forEach(k=>document.documentElement.style.removeProperty(k)); }
    sendThemeToNtTabs();
  };
  img.src=bg;
}

