// command palette (ctrl/cmd+k): jump to pages, tabs, bookmarks, themes, servers and actions

const PALETTE_KEY = /mac|iphone|ipad/i.test(navigator.platform) ? '⌘k' : 'ctrl k';
let paletteEl = null, paletteShown = [], paletteIndex = 0;

function paletteHost(url) { try { return new URL(url).hostname.replace(/^www\./, ''); } catch { return ''; } }
function paletteFavicon(url) { const h = paletteHost(url); return h ? `<img src="https://www.google.com/s2/favicons?domain=${encodeURIComponent(h)}&sz=32" alt="">` : icon('search', 16); }

function paletteCommands() {
  const cmds = [], add = (group, label, run, o = {}) => cmds.push({ group, label, run, ...o });
  const tab = getActiveTab(), browsing = !!(tab && !tab.page && tab.url);
  if (tabs.length > 1) tabs.forEach(t => add('tabs', t.title || 'new tab', () => switchTab(t.id), {
    hint: t.id === activeTabId ? 'current' : t.url ? paletteHost(t.url) : '',
    icon: t.favicon ? `<img src="${escapeHtml(t.favicon)}" alt="">` : t.page ? pgIcon(t.page, 16) : icon('search', 16) }));
  Object.entries(PAGE_TITLES).forEach(([p, t]) => add('pages', t, () => { const a = getActiveTab(); if (a) { a.forceChrome = false; openPage(p, a); } }, { icon: pgIcon(p, 16), hint: tab?.page === p ? 'current' : '' }));
  add('actions', 'new tab', () => createTab(true, 'home', { forceChrome: true }), { icon: icon('plus', 16) });
  add('actions', 'close tab', () => closeTab(activeTabId), { icon: pgIcon('close', 16) });
  add('actions', 'reload', () => reloadTab(getActiveTab()), { icon: icon('reload', 16) });
  if (tab && tab.historyIndex > 0) add('actions', 'go back', () => navigateHistory(-1), { icon: icon('back', 16) });
  if (tab && tab.historyIndex < tab.historyStack.length - 1) add('actions', 'go forward', () => navigateHistory(1), { icon: icon('forward', 16) });
  if (browsing) add('actions', 'devtools', toggleDevTools, { icon: icon('dev', 16) });
  add('actions', 'settings', () => { openSettings(); setSettingsSection('preferences'); }, { icon: icon('settings', 16) });
  add('actions', 'appearance', () => { openSettings(); setSettingsSection('appearance'); }, { icon: icon('settings', 16), keys: 'wallpaper font' });
  add('actions', 'account', () => { openSettings(); setSettingsSection('account'); }, { icon: pgIcon('account', 16) });
  add('actions', 'take the tour', startTour, { icon: icon('home', 16), keys: 'help tutorial guide' });
  add('actions', 'discord', () => handleSubmit(DISCORD_URL), { icon: pgIcon('discord', 16) });
  let marks = DEFAULT_BOOKMARKS;
  try { marks = JSON.parse(localStorage.getItem('gl_shortcuts') || 'null') || DEFAULT_BOOKMARKS; } catch {}
  marks.forEach(b => add('bookmarks', b.label, () => handleSubmit(b.url), { hint: paletteHost(b.url), icon: paletteFavicon(b.url) }));
  const theme = getTheme();
  THEMES.forEach(t => add('themes', 'theme: ' + t.label, () => applyTheme(t.key), { hint: t.key === theme ? 'current' : '', icon: `<span class="palette-dot" style="background:${t.dot}"></span>` }));
  const server = localStorage.getItem('proxServer') || DEFAULT_WISP;
  getAllWispServers().forEach(s => add('servers', 'server: ' + s.name, () => setWisp(s.url), { hint: s.url === server ? 'current' : 'reloads', keys: s.url, icon: icon('reload', 16) }));
  return cmds;
}

function paletteScore(q, text) {
  const s = text.toLowerCase(), i = s.indexOf(q);
  if (i === 0) return 4;
  if (i > 0) return /[\s:.\-]/.test(s[i - 1]) ? 3 : 2;
  let j = 0;
  for (const c of s) if (c === q[j]) j++;
  return j === q.length ? 1 : 0;
}

function renderPalette() {
  const input = document.getElementById('palette-input'), list = document.getElementById('palette-list');
  const raw = input.value.trim(), q = raw.toLowerCase();
  let shown = paletteCommands();
  if (q) {
    shown = shown.map((c, n) => ({ c, n, s: Math.max(paletteScore(q, c.label), paletteScore(q, c.keys || '') > 1 ? 1 : 0, paletteScore(q, c.group) > 1 ? 1 : 0) }))
      .filter(x => x.s).sort((a, b) => b.s - a.s || a.n - b.n).map(x => x.c);
    const isSearch = resolveInput(raw) === getSearchUrl(raw);
    shown.unshift({ group: 'go', label: isSearch ? `search "${raw}"` : `go to ${raw}`, run: () => handleSubmit(raw), icon: isSearch ? icon('search', 16) : paletteFavicon(resolveInput(raw)), hint: 'enter' },
      { group: 'go', label: `${isSearch ? 'search' : 'open'} in new tab`, run: () => openUrlInNewTab(raw), icon: icon('plus', 16) });
  }
  paletteShown = shown;
  paletteIndex = Math.min(paletteIndex, Math.max(0, shown.length - 1));
  let html = '', last = '';
  shown.forEach((c, i) => {
    if (!q && c.group !== last) html += `<div class="palette-group">${c.group}</div>`;
    last = c.group;
    const hint = q && c.group !== 'go' ? (c.hint && c.hint !== 'reloads' ? c.hint : c.group) : (c.hint || '');
    html += `<div class="palette-item${i === paletteIndex ? ' active' : ''}" role="option" id="palette-opt-${i}" data-i="${i}" aria-selected="${i === paletteIndex}"><span class="palette-icon">${c.icon || ''}</span><span class="palette-label">${escapeHtml(c.label)}</span>${hint ? `<span class="palette-hint${hint === 'current' ? ' current' : ''}">${escapeHtml(hint)}</span>` : ''}</div>`;
  });
  list.innerHTML = html || '<div class="palette-empty">nothing found</div>';
  input.setAttribute('aria-activedescendant', shown.length ? 'palette-opt-' + paletteIndex : '');
}

function movePalette(i) {
  const list = document.getElementById('palette-list');
  list.querySelector('.palette-item.active')?.classList.remove('active');
  paletteIndex = (i + paletteShown.length) % paletteShown.length;
  const el = list.querySelector(`[data-i="${paletteIndex}"]`);
  if (!el) return;
  el.classList.add('active'); el.scrollIntoView({ block: 'nearest' });
  document.getElementById('palette-input').setAttribute('aria-activedescendant', el.id);
}

function runPalette(i) {
  const cmd = paletteShown[i];
  if (!cmd) return;
  closePalette();
  try { cmd.run(); } catch (e) { console.warn('palette command failed', e); }
}

function buildPalette() {
  paletteEl = document.createElement('div');
  paletteEl.className = 'palette hidden';
  paletteEl.innerHTML = `<div class="palette-card" role="dialog" aria-modal="true" aria-label="command palette">
    <div class="palette-search">${icon('search', 18)}<input id="palette-input" type="text" autocomplete="off" spellcheck="false" placeholder="search, jump to a page or run a command" role="combobox" aria-expanded="true" aria-controls="palette-list"><kbd>esc</kbd></div>
    <div class="palette-list" id="palette-list" role="listbox"></div>
    <div class="palette-foot"><span><kbd>↑</kbd><kbd>↓</kbd> move</span><span><kbd>enter</kbd> open</span><span class="grow"></span><span><kbd>${PALETTE_KEY}</kbd> toggle</span></div></div>`;
  document.body.appendChild(paletteEl);
  const input = paletteEl.querySelector('input'), list = paletteEl.querySelector('.palette-list');
  input.addEventListener('input', () => { paletteIndex = 0; renderPalette(); list.scrollTop = 0; });
  input.addEventListener('keydown', e => {
    if (e.key === 'ArrowDown' || (e.key === 'Tab' && !e.shiftKey)) { e.preventDefault(); movePalette(paletteIndex + 1); }
    else if (e.key === 'ArrowUp' || (e.key === 'Tab' && e.shiftKey)) { e.preventDefault(); movePalette(paletteIndex - 1); }
    else if (e.key === 'Enter') { e.preventDefault(); runPalette(paletteIndex); }
    else if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); closePalette(); }
  });
  list.addEventListener('mousemove', e => { const it = e.target.closest('.palette-item'); if (it && +it.dataset.i !== paletteIndex) movePalette(+it.dataset.i); });
  list.addEventListener('click', e => { const it = e.target.closest('.palette-item'); if (it) runPalette(+it.dataset.i); });
  paletteEl.addEventListener('mousedown', e => { if (e.target === paletteEl) closePalette(); });
}

function openPalette() {
  if (!tabs.length) return;
  if (!paletteEl) buildPalette();
  const input = document.getElementById('palette-input');
  input.value = ''; paletteIndex = 0;
  renderPalette();
  paletteEl.classList.remove('hidden');
  input.focus();
}
function closePalette() { paletteEl?.classList.add('hidden'); }
function togglePalette() { if (paletteEl && !paletteEl.classList.contains('hidden')) closePalette(); else openPalette(); }

window.addEventListener('keydown', e => {
  if ((e.ctrlKey || e.metaKey) && !e.altKey && !e.shiftKey && e.key.toLowerCase() === 'k') { e.preventDefault(); togglePalette(); }
});

</script>
  <script>/* p/js/app/main.js */
// startup. loaded last, after every other file has defined its functions

async function proxyInit() {
  const root=document.getElementById('proxy-app');
  root.innerHTML=`<div style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:var(--bg-body)"><div style="display:flex;flex-direction:column;align-items:center;gap:12px;color:var(--text-muted);font-size:12px"><div class="spinner" style="margin:0"></div><div>starting mochii...</div></div></div>`;

  await initializeExtensions();
  await buildInternalPages();

  try {
    await fetchWispServers();
    await initializeWithBestServer();
    await initProxyEngine();
    try { await getSharedConnection(); } catch (e) { const alt = getAllWispServers().find(s => s.url !== localStorage.getItem('proxServer')); if (!alt) throw e; localStorage.setItem('proxServer', alt.url); sharedConnectionReady = false; await getSharedConnection(); }

    if ('serviceWorker' in navigator) {
      const reg=await navigator.serviceWorker.register(getBasePath()+'sw.js',{scope:getBasePath()});
      await navigator.serviceWorker.ready;
      const wispUrl=localStorage.getItem('proxServer') || DEFAULT_WISP;
      const config={type:'config',wispurl:wispUrl,servers:getAllWispServers(),autoswitch:localStorage.getItem('wispAutoswitch')!=='false'};
      navigator.serviceWorker.addEventListener('message', async ({ data }) => { if (data?.type === 'blocked') return recordBlocked(data); if (data?.type !== 'wispChanged' || !data.url) return; localStorage.setItem('proxServer', data.url); try { await sharedConnection.setTransport(TRANSPORT_URL, [{ wisp: data.url }]); } catch {} });
      const send=()=>{const sw=reg.active||navigator.serviceWorker.controller;if(sw)sw.postMessage(config);};
      send(); setTimeout(send,500); setTimeout(send,1500); reg.update();
    }
    // extensions start once the service worker can serve their files
    try { await initExtensionRuntime(); } catch (e) { console.warn('extensions failed to start', e); }

    await initializeBrowser();
    maybeStartTour();
    installDefaultExtensions();
  } catch(err) {
    console.error('proxy initialization error:',err);
    root.innerHTML=`<div style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:var(--bg-body)"><div class="message-content"><h1>init error</h1><p>${escapeHtml(err?.message || 'unknown error')}</p><button class="message-button" onclick="__loc.reload()">retry</button></div></div>`;
  }
}

window.addEventListener('message', event => {
  if(event.data?.type==='GHOSTLINK_NT_READY') { sendThemeToNtTabs(); sendAccountToNtTabs(); sendMusicToNtTabs(true); }
});

try {
  const savedTheme = getTheme();
  if (savedTheme !== 'default') document.documentElement.setAttribute('data-theme', savedTheme);
  if (savedTheme === 'auto') applyAutoTheme();
} catch {}
applyStoredSettings();
initAccount();
initWizard();
window.addEventListener('keydown', e => {
  if (e.key !== 'Escape') return;
  const modal = document.getElementById('wisp-settings-modal');
  if (modal && !modal.classList.contains('hidden')) modal.classList.add('hidden');
});
proxyInit();

</script>
  <script>/* p/js/alerts.js */
(function () {
    "use strict";
    var SUPABASE_URL = "https://qizflqwaxghaisoydwmj.supabase.co";
    var SUPABASE_ANON_KEY = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InFpemZscXdheGdoYWlzb3lkd21qIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODc2NzgxMTMsImV4cCI6MjEwMzI1NDExM30.sFhWpgOb77RueP9Se-i2ixyx8TD62tHNZi0ipZ5pMds";

    if (window.__mochiiAlertsLoaded) return;
    window.__mochiiAlertsLoaded = true;

    var DISMISS_KEY = "mochii_dismissed_alerts";
    function dismissed() {
        try { return JSON.parse(localStorage.getItem(DISMISS_KEY)) || []; }
        catch (e) { return []; }
    }

    var css = document.createElement("style");
    css.textContent = [
        "#alert-popup-bg{position:fixed;inset:0;z-index:999999;display:none;align-items:center;justify-content:center;background:rgba(0,0,0,.55);backdrop-filter:blur(4px)}",
        "#alert-popup-bg.open{display:flex}",
        "#alert-popup{position:relative;width:min(420px,90vw);background:#131313;color:#c2c2c2;border:1px solid rgba(224,224,224,.18);border-radius:14px;padding:26px 26px 22px;box-shadow:0 20px 60px rgba(0,0,0,.6);font-family:Geist,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;animation:mochiiAlertPop .35s cubic-bezier(.34,1.56,.64,1);max-height:80vh;overflow:auto}",
        "@keyframes mochiiAlertPop{from{opacity:0;transform:scale(.92)}}",
        "#alert-popup h2{color:#fff;font-size:19px;margin:0 28px 8px 0;line-height:1.25}",
        "#alert-popup p{font-size:14px;line-height:1.55;margin:0 0 6px;white-space:pre-wrap;word-break:break-word}",
        "#alert-close-x{position:absolute;top:10px;right:10px;width:28px;height:28px;border:none;border-radius:50%;background:rgba(255,255,255,.08);color:#fff;font-size:14px;line-height:1;cursor:pointer;transition:background .15s;display:flex;align-items:center;justify-content:center}",
        "#alert-close-x:hover{background:rgba(255,255,255,.2)}",
        ".alert-links{margin-top:14px;display:flex;flex-direction:column;gap:8px}",
        ".alert-link{display:block;text-align:center;padding:9px 12px;border-radius:9px;background:#fff;color:#000;font-weight:600;font-size:13.5px;text-decoration:none;transition:opacity .15s}",
        ".alert-link:hover{opacity:.85}",
        ".alert-link.secondary{background:rgba(255,255,255,.09);color:#fff}"
    ].join("\n");
    document.head.appendChild(css);

    var bg = document.createElement("div");
    bg.id = "alert-popup-bg";
    bg.innerHTML = '<div id="alert-popup">' +
        '<button id="alert-close-x" title="Dismiss" aria-label="Close">✕</button>' +
        '<h2 id="alert-title"></h2><p id="alert-desc"></p><div class="alert-links" id="alert-links"></div></div>';
    document.body.appendChild(bg);

    function esc(s) {
        return String(s == null ? "" : s).replace(/[&<>"']/g, function (c) {
            return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
        });
    }

    function closePopup() { bg.classList.remove("open"); }

    var currentId = null;

    function showAlert(a) {
        currentId = a.id;
        document.getElementById("alert-title").textContent = a.title;
        document.getElementById("alert-desc").textContent = a.description || "";
        var links = [];
        try { links = typeof a.links === "string" ? JSON.parse(a.links) : (a.links || []); } catch (e) {}
        links = links.filter(function (l) { return l && l.url; });
        var box = document.getElementById("alert-links");
        box.innerHTML = links.map(function (l, i) {
            return '<a class="alert-link' + (i > 0 ? " secondary" : "") + '" href="' + esc(l.url) +
                '" target="_blank" rel="noopener noreferrer">' + esc(l.label || l.url) + "</a>";
        }).join("");
        box.style.display = links.length ? "" : "none";
        bg.classList.add("open");
    }

    function dismissAndClose() {
        if (currentId) {
            var seen = dismissed();
            seen.push(currentId);
            try { localStorage.setItem(DISMISS_KEY, JSON.stringify(seen.slice(-30))); } catch (e) {}
        }
        closePopup();
    }

    document.getElementById("alert-close-x").addEventListener("click", dismissAndClose);
    bg.addEventListener("click", function (e) { if (e.target === bg) closePopup(); });

    async function checkAlerts() {
        try {
            var r = await fetch(SUPABASE_URL + "/rest/v1/alerts?select=*&active=eq.true&order=created_at.desc&limit=1", {
                headers: { apikey: SUPABASE_ANON_KEY, Authorization: "Bearer " + SUPABASE_ANON_KEY }
            });
            var rows = await r.json();
            if (!rows || !rows.length) return;
            var a = rows[0];
            if (dismissed().indexOf(a.id) !== -1) return;
            showAlert(a);
        } catch (e) { /* silent */ }
    }

    try {
        var sb = supabase.createClient(SUPABASE_URL, SUPABASE_ANON_KEY);
        sb.channel("site-alerts")
            .on("postgres_changes", { event: "INSERT", schema: "public", table: "alerts" }, function (p) {
                if (p.new && p.new.active && dismissed().indexOf(p.new.id) === -1) showAlert(p.new);
            })
            .subscribe();
    } catch (e) { /* polling still works */ }

    setTimeout(checkAlerts, 1200);
    setInterval(checkAlerts, 60000);
})();
</script>
